    #[derive(Debug, Clone)]
    pub struct StreamingSha256 {
        state: [u32; 8],
        buffer: [u8; 64],
        buffer_length: usize,
        total_length: u64,
    }

    impl Default for StreamingSha256 {
        fn default() -> Self {
            Self {
                state: SHA256_INITIAL_STATE,
                buffer: [0; 64],
                buffer_length: 0,
                total_length: 0,
            }
        }
    }

    impl StreamingSha256 {
        pub fn new() -> Self {
            Self::default()
        }

        fn compress(&mut self, block: &[u8; 64]) {
            let mut schedule = [0u32; 64];
            for (index, word) in block
                .as_chunks::<4>()
                .0
                .iter()
                .take(16)
                .enumerate()
            {
                schedule[index] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
            }
            for index in 16..64 {
                let previous_15 = schedule[index - 15];
                let previous_2 = schedule[index - 2];
                let small_sigma_0 = previous_15.rotate_right(7)
                    ^ previous_15.rotate_right(18)
                    ^ (previous_15 >> 3);
                let small_sigma_1 = previous_2.rotate_right(17)
                    ^ previous_2.rotate_right(19)
                    ^ (previous_2 >> 10);
                schedule[index] = schedule[index - 16]
                    .wrapping_add(small_sigma_0)
                    .wrapping_add(schedule[index - 7])
                    .wrapping_add(small_sigma_1);
            }

            let mut state_a = self.state[0];
            let mut state_b = self.state[1];
            let mut state_c = self.state[2];
            let mut state_d = self.state[3];
            let mut state_e = self.state[4];
            let mut state_f = self.state[5];
            let mut state_g = self.state[6];
            let mut state_h = self.state[7];

            for index in 0..64 {
                let big_sigma_1 = state_e.rotate_right(6)
                    ^ state_e.rotate_right(11)
                    ^ state_e.rotate_right(25);
                let choice = (state_e & state_f) ^ ((!state_e) & state_g);
                let temporary_1 = state_h
                    .wrapping_add(big_sigma_1)
                    .wrapping_add(choice)
                    .wrapping_add(SHA256_ROUND_CONSTANTS[index])
                    .wrapping_add(schedule[index]);
                let big_sigma_0 = state_a.rotate_right(2)
                    ^ state_a.rotate_right(13)
                    ^ state_a.rotate_right(22);
                let majority = (state_a & state_b)
                    ^ (state_a & state_c)
                    ^ (state_b & state_c);
                let temporary_2 = big_sigma_0.wrapping_add(majority);

                state_h = state_g;
                state_g = state_f;
                state_f = state_e;
                state_e = state_d.wrapping_add(temporary_1);
                state_d = state_c;
                state_c = state_b;
                state_b = state_a;
                state_a = temporary_1.wrapping_add(temporary_2);
            }

            self.state[0] = self.state[0].wrapping_add(state_a);
            self.state[1] = self.state[1].wrapping_add(state_b);
            self.state[2] = self.state[2].wrapping_add(state_c);
            self.state[3] = self.state[3].wrapping_add(state_d);
            self.state[4] = self.state[4].wrapping_add(state_e);
            self.state[5] = self.state[5].wrapping_add(state_f);
            self.state[6] = self.state[6].wrapping_add(state_g);
            self.state[7] = self.state[7].wrapping_add(state_h);
        }

        pub fn update(&mut self, mut bytes: &[u8]) -> TrustResult<()> {
            let additional = u64::try_from(bytes.len()).map_err(|_| {
                TrustError::new("E_SHA256_LENGTH", "input length does not fit u64")
            })?;
            let total_length = self.total_length.checked_add(additional).ok_or_else(|| {
                TrustError::new("E_SHA256_LENGTH", "input length overflow")
            })?;
            if total_length > u64::MAX / 8 {
                return Err(TrustError::new(
                    "E_SHA256_LENGTH",
                    "SHA-256 bit length overflow",
                ));
            }
            self.total_length = total_length;

            if self.buffer_length != 0 {
                let needed = 64 - self.buffer_length;
                let copied = needed.min(bytes.len());
                self.buffer[self.buffer_length..self.buffer_length + copied]
                    .copy_from_slice(&bytes[..copied]);
                self.buffer_length += copied;
                bytes = &bytes[copied..];
                if self.buffer_length == 64 {
                    let block = self.buffer;
                    self.compress(&block);
                    self.buffer_length = 0;
                }
            }

            while bytes.len() >= 64 {
                let block = <&[u8; 64]>::try_from(&bytes[..64]).map_err(|_| {
                    TrustError::new("E_SHA256_INTERNAL", "full block conversion")
                })?;
                self.compress(block);
                bytes = &bytes[64..];
            }
            if !bytes.is_empty() {
                self.buffer[..bytes.len()].copy_from_slice(bytes);
                self.buffer_length = bytes.len();
            }
            Ok(())
        }

        pub fn finalize(mut self) -> TrustResult<[u8; 32]> {
            let bit_length = self.total_length.checked_mul(8).ok_or_else(|| {
                TrustError::new("E_SHA256_LENGTH", "SHA-256 bit length overflow")
            })?;
            self.buffer[self.buffer_length] = 0x80;
            self.buffer_length += 1;
            if self.buffer_length > 56 {
                self.buffer[self.buffer_length..].fill(0);
                let block = self.buffer;
                self.compress(&block);
                self.buffer = [0; 64];
                self.buffer_length = 0;
            }
            self.buffer[self.buffer_length..56].fill(0);
            self.buffer[56..64].copy_from_slice(&bit_length.to_be_bytes());
            let block = self.buffer;
            self.compress(&block);

            let mut digest = [0u8; 32];
            for (destination, word) in digest
                .as_chunks_mut::<4>()
                .0
                .iter_mut()
                .zip(self.state)
            {
                destination.copy_from_slice(&word.to_be_bytes());
            }
            Ok(digest)
        }
    }

    pub fn sha256(bytes: &[u8]) -> TrustResult<[u8; 32]> {
        let mut hasher = StreamingSha256::new();
        hasher.update(bytes)?;
        hasher.finalize()
    }

