    pub fn compiled_native_tool_registry_identity(
    ) -> TrustResult<(usize, usize, [u8; 32])> {
        const PREFIX: &[u8] = b"FND01BOOTSTRAPNATIVETOOLSv1\0";

        fn append_u32_bytes(
            output: &mut Vec<u8>,
            bytes: &[u8],
            subject: &'static str,
        ) -> TrustResult<()> {
            let length = u32::try_from(bytes.len()).map_err(|_| {
                TrustError::new(
                    "E_NATIVE_TOOL_REGISTRY",
                    format!("{subject} length exceeds u32"),
                )
            })?;
            output
                .try_reserve(4usize.saturating_add(bytes.len()))
                .map_err(|_| {
                    TrustError::new(
                        "E_NATIVE_TOOL_REGISTRY",
                        format!("cannot reserve {subject} bytes"),
                    )
                })?;
            output.extend_from_slice(&length.to_be_bytes());
            output.extend_from_slice(bytes);
            Ok(())
        }

        let count = u32::try_from(NATIVE_TOOL_DESCRIPTORS.len()).map_err(|_| {
            TrustError::new("E_NATIVE_TOOL_REGISTRY", "tool count exceeds u32")
        })?;
        let mut registry = Vec::new();
        registry.extend_from_slice(PREFIX);
        registry.extend_from_slice(&count.to_be_bytes());
        for (ordinal, row) in NATIVE_TOOL_DESCRIPTORS.iter().enumerate() {
            let ordinal = u32::try_from(ordinal).map_err(|_| {
                TrustError::new("E_NATIVE_TOOL_REGISTRY", "tool ordinal exceeds u32")
            })?;
            registry.extend_from_slice(&ordinal.to_be_bytes());
            append_u32_bytes(&mut registry, row.id.as_bytes(), "native tool id")?;
            let candidate_count = u32::try_from(row.candidates.len()).map_err(|_| {
                TrustError::new("E_NATIVE_TOOL_REGISTRY", "candidate count exceeds u32")
            })?;
            registry.extend_from_slice(&candidate_count.to_be_bytes());
            for candidate in row.candidates {
                append_u32_bytes(&mut registry, candidate.as_bytes(), "tool candidate")?;
            }
            let argv_count = u32::try_from(row.version_argv.len()).map_err(|_| {
                TrustError::new("E_NATIVE_TOOL_REGISTRY", "argv count exceeds u32")
            })?;
            registry.extend_from_slice(&argv_count.to_be_bytes());
            for argument in row.version_argv {
                append_u32_bytes(&mut registry, argument.as_bytes(), "version argv")?;
            }
            append_u32_bytes(&mut registry, row.stream.as_bytes(), "version stream")?;
            append_u32_bytes(&mut registry, row.parser.as_bytes(), "version parser")?;
            append_u32_bytes(
                &mut registry,
                b"selected-executable-and-raw-version",
                "tool identity",
            )?;
        }
        Ok((
            NATIVE_TOOL_DESCRIPTORS.len(),
            registry.len(),
            sha256(&registry)?,
        ))
    }

    #[allow(clippy::struct_field_names)]
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct BootstrapLockLexicalLimits {
        pub max_bytes: u64,
        pub max_packages: usize,
        pub max_dependencies_per_package: usize,
        pub max_string_bytes: usize,
    }

    pub const BOOTSTRAP_LOCK_LEXICAL_LIMITS: BootstrapLockLexicalLimits =
        BootstrapLockLexicalLimits {
            max_bytes: MAX_SOURCE_FILE_BYTES,
            max_packages: 2_000_000,
            max_dependencies_per_package: 2_000_000,
            max_string_bytes: MAX_SOURCE_FILE_BYTES as usize,
        };

    fn bootstrap_lock_lexical_string<'a>(
        line: &'a str,
        prefix: &str,
        limits: BootstrapLockLexicalLimits,
        subject: &str,
    ) -> TrustResult<&'a str> {
        let value = line
            .strip_prefix(prefix)
            .and_then(|value| value.strip_suffix('"'))
            .ok_or_else(|| {
                TrustError::new(
                    "E_BOOTSTRAP_LOCK_SCHEMA",
                    format!("{subject}: exact quoted assignment required"),
                )
            })?;
        if value.is_empty()
            || value.len() > limits.max_string_bytes
            || value.contains('"')
            || value.contains('\\')
            || value.bytes().any(|byte| byte.is_ascii_control())
        {
            return Err(TrustError::new(
                "E_BOOTSTRAP_LOCK_SCHEMA",
                format!("{subject}: invalid quoted value"),
            ));
        }
        Ok(value)
    }

    fn bootstrap_lock_lexical_dependency<'a>(
        line: &'a str,
        limits: BootstrapLockLexicalLimits,
        subject: &str,
    ) -> TrustResult<&'a str> {
        let value = line
            .strip_prefix(" \"")
            .and_then(|value| value.strip_suffix("\","))
            .ok_or_else(|| {
                TrustError::new(
                    "E_BOOTSTRAP_LOCK_DEPENDENCY",
                    format!("{subject}: exact dependency row required"),
                )
            })?;
        if value.is_empty()
            || value.len() > limits.max_string_bytes
            || value.contains('"')
            || value.contains('\\')
            || value.bytes().any(|byte| byte.is_ascii_control())
        {
            return Err(TrustError::new(
                "E_BOOTSTRAP_LOCK_DEPENDENCY",
                format!("{subject}: invalid dependency value"),
            ));
        }
        Ok(value)
    }

    pub fn validate_bootstrap_cargo_lock_v4_lexical_with_limits(
        bytes: &[u8],
        limits: BootstrapLockLexicalLimits,
    ) -> TrustResult<()> {
        const HEADER: &str = concat!(
            "# This file is automatically @generated by Cargo.\n",
            "# It is not intended for manual editing.\n",
            "version = 4\n\n",
        );
        let length = u64::try_from(bytes.len()).map_err(|_| {
            TrustError::new(
                "E_BOOTSTRAP_LOCK_BOUND",
                "bootstrap Cargo.lock length conversion",
            )
        })?;
        if limits.max_bytes == 0
            || limits.max_packages == 0
            || limits.max_dependencies_per_package == 0
            || limits.max_string_bytes == 0
            || bytes.is_empty()
            || length > limits.max_bytes
        {
            return Err(TrustError::new(
                "E_BOOTSTRAP_LOCK_BOUND",
                "bootstrap Cargo.lock or lexical limit is outside its bound",
            ));
        }
        if !bytes.ends_with(b"\n")
            || bytes.starts_with(&[0xef, 0xbb, 0xbf])
            || bytes.contains(&0)
            || bytes.contains(&b'\r')
        {
            return Err(TrustError::new(
                "E_BOOTSTRAP_LOCK_FRAMING",
                "strict UTF-8 LF framing without BOM, NUL, or CR is required",
            ));
        }
        let text = std::str::from_utf8(bytes).map_err(|_| {
            TrustError::new(
                "E_BOOTSTRAP_LOCK_FRAMING",
                "bootstrap Cargo.lock must be strict UTF-8",
            )
        })?;
        let body = text.strip_suffix('\n').ok_or_else(|| {
            TrustError::new(
                "E_BOOTSTRAP_LOCK_FRAMING",
                "one terminal LF is required",
            )
        })?;
        if body.ends_with('\n') {
            return Err(TrustError::new(
                "E_BOOTSTRAP_LOCK_FRAMING",
                "exactly one terminal LF is required",
            ));
        }
        let package_text = body.strip_prefix(HEADER).ok_or_else(|| {
            TrustError::new(
                "E_BOOTSTRAP_LOCK_SCHEMA",
                "exact Cargo v4 generated header is required",
            )
        })?;
        if package_text.is_empty() {
            return Err(TrustError::new(
                "E_BOOTSTRAP_LOCK_SCHEMA",
                "at least one package block is required",
            ));
        }
        let mut lines = package_text.split('\n').peekable();
        let mut package_count = 0usize;
        loop {
            if lines.next() != Some("[[package]]") {
                return Err(TrustError::new(
                    "E_BOOTSTRAP_LOCK_SCHEMA",
                    "exact [[package]] block start is required",
                ));
            }
            if package_count >= limits.max_packages {
                return Err(TrustError::new(
                    "E_BOOTSTRAP_LOCK_BOUND",
                    "bootstrap Cargo.lock package count exceeds its bound",
                ));
            }
            package_count += 1;
            let subject = format!("bootstrap Cargo.lock package[{package_count}]");
            let name = lines.next().ok_or_else(|| {
                TrustError::new(
                    "E_BOOTSTRAP_LOCK_SCHEMA",
                    format!("{subject}: missing name"),
                )
            })?;
            bootstrap_lock_lexical_string(
                name,
                "name = \"",
                limits,
                &subject,
            )?;
            let version = lines.next().ok_or_else(|| {
                TrustError::new(
                    "E_BOOTSTRAP_LOCK_SCHEMA",
                    format!("{subject}: missing version"),
                )
            })?;
            bootstrap_lock_lexical_string(
                version,
                "version = \"",
                limits,
                &subject,
            )?;
            if lines
                .peek()
                .is_some_and(|line| line.starts_with("source = "))
            {
                let source = lines.next().ok_or_else(|| {
                    TrustError::new(
                        "E_BOOTSTRAP_LOCK_SCHEMA",
                        format!("{subject}: missing source"),
                    )
                })?;
                bootstrap_lock_lexical_string(
                    source,
                    "source = \"",
                    limits,
                    &subject,
                )?;
                let checksum = lines.next().ok_or_else(|| {
                    TrustError::new(
                        "E_BOOTSTRAP_LOCK_SCHEMA",
                        format!("{subject}: missing checksum"),
                    )
                })?;
                bootstrap_lock_lexical_string(
                    checksum,
                    "checksum = \"",
                    limits,
                    &subject,
                )?;
            }
            if lines.peek().copied() == Some("dependencies = [") {
                lines.next();
                let mut dependency_count = 0usize;
                let mut previous = None::<&str>;
                loop {
                    let line = lines.next().ok_or_else(|| {
                        TrustError::new(
                            "E_BOOTSTRAP_LOCK_SCHEMA",
                            format!("{subject}: unterminated dependencies"),
                        )
                    })?;
                    if line == "]" {
                        if dependency_count == 0 {
                            return Err(TrustError::new(
                                "E_BOOTSTRAP_LOCK_DEPENDENCY",
                                format!("{subject}: empty dependency array"),
                            ));
                        }
                        break;
                    }
                    if dependency_count
                        >= limits.max_dependencies_per_package
                    {
                        return Err(TrustError::new(
                            "E_BOOTSTRAP_LOCK_BOUND",
                            format!("{subject}: dependency count exceeds its bound"),
                        ));
                    }
                    let dependency = bootstrap_lock_lexical_dependency(
                        line,
                        limits,
                        &subject,
                    )?;
                    if previous.is_some_and(|prior| {
                        prior.as_bytes() >= dependency.as_bytes()
                    }) {
                        return Err(TrustError::new(
                            "E_BOOTSTRAP_LOCK_DEPENDENCY",
                            format!(
                                "{subject}: dependencies must be raw-sorted unique"
                            ),
                        ));
                    }
                    previous = Some(dependency);
                    dependency_count += 1;
                }
            }
            match lines.next() {
                None => break,
                Some("") => {
                    if lines.peek().is_none()
                        || lines.peek().copied() == Some("")
                    {
                        return Err(TrustError::new(
                            "E_BOOTSTRAP_LOCK_SCHEMA",
                            "exactly one blank line must separate package blocks",
                        ));
                    }
                }
                Some(_) => {
                    return Err(TrustError::new(
                        "E_BOOTSTRAP_LOCK_SCHEMA",
                        format!("{subject}: unknown, misplaced, or reordered field"),
                    ));
                }
            }
        }
        Ok(())
    }

    pub fn validate_bootstrap_cargo_lock_v4_lexical(
        bytes: &[u8],
    ) -> TrustResult<()> {
        validate_bootstrap_cargo_lock_v4_lexical_with_limits(
            bytes,
            BOOTSTRAP_LOCK_LEXICAL_LIMITS,
        )
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
    pub struct FileBinding {
        pub byte_length: u64,
        pub sha256: [u8; 32],
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct AuthoringMarker {
        pub policy: FileBinding,
        pub verifier: FileBinding,
        pub harness: FileBinding,
        pub closure_sha256: [u8; 32],
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct IntegrationSeal {
        pub run_id: [u8; 16],
        pub records: [FileBinding; 5],
        pub outer_transport: FileBinding,
        pub authoring_closure_sha256: [u8; 32],
        pub seal_sha256: [u8; 32],
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct FinalGateSeal {
        pub run_id: [u8; 16],
        pub final_attestation: FileBinding,
        pub producer_outer_transport: FileBinding,
        pub attester_outer_transport: FileBinding,
        pub gate_executable: FileBinding,
        pub gate_input: FileBinding,
        pub authoring_closure_sha256: [u8; 32],
        pub integration_seal_sha256: [u8; 32],
        pub seal_sha256: [u8; 32],
    }

    fn split_exact<'a, const N: usize>(
        value: &'a str,
        subject: &str,
    ) -> TrustResult<[&'a str; N]> {
        let mut parts = [""; N];
        let mut iterator = value.split(':');
        for part in &mut parts {
            *part = iterator.next().ok_or_else(|| {
                TrustError::new("E_MARKER_GRAMMAR", format!("{subject}: missing field"))
            })?;
        }
        if iterator.next().is_some() {
            return Err(TrustError::new(
                "E_MARKER_GRAMMAR",
                format!("{subject}: trailing field"),
            ));
        }
        Ok(parts)
    }

    fn reserve_preimage(preimage: &mut Vec<u8>, additional: usize) -> TrustResult<()> {
        preimage.try_reserve_exact(additional).map_err(|_| {
            TrustError::new(
                "E_PREIMAGE_ALLOCATION",
                format!("cannot reserve {additional} preimage bytes"),
            )
        })
    }

    fn append_bound_record(
        preimage: &mut Vec<u8>,
        path: &str,
        binding: FileBinding,
    ) -> TrustResult<()> {
        let path_length = u32::try_from(path.len()).map_err(|_| {
            TrustError::new(
                "E_PREIMAGE_BOUND",
                format!("binding path exceeds u32 encoding: {path:?}"),
            )
        })?;
        let encoded_length = 4usize
            .checked_add(path.len())
            .and_then(|length| length.checked_add(8 + 32))
            .ok_or_else(|| {
                TrustError::new("E_PREIMAGE_BOUND", "binding record length overflow")
            })?;
        reserve_preimage(preimage, encoded_length)?;
        preimage.extend_from_slice(&path_length.to_be_bytes());
        preimage.extend_from_slice(path.as_bytes());
        preimage.extend_from_slice(&binding.byte_length.to_be_bytes());
        preimage.extend_from_slice(&binding.sha256);
        Ok(())
    }

    pub fn authoring_closure_preimage(marker: &AuthoringMarker) -> TrustResult<Vec<u8>> {
        let mut preimage = Vec::new();
        reserve_preimage(&mut preimage, b"FND01AUTHORv2\0".len() + 4)?;
        preimage.extend_from_slice(b"FND01AUTHORv2\0");
        preimage.extend_from_slice(&3u32.to_be_bytes());
        append_bound_record(&mut preimage, AUTHORING_PATHS[0], marker.policy)?;
        append_bound_record(&mut preimage, AUTHORING_PATHS[1], marker.verifier)?;
        append_bound_record(&mut preimage, AUTHORING_PATHS[2], marker.harness)?;
        Ok(preimage)
    }

    pub fn parse_authoring_marker(value: &str) -> TrustResult<AuthoringMarker> {
        if value.len() > MAX_AUTHORING_MARKER_TEXT_BYTES {
            return Err(TrustError::new(
                "E_AUTHORING_MARKER",
                "marker exceeds bounded grammar size",
            ));
        }
        let fields = split_exact::<8>(value, AUTHORING_MARKER_ENV)?;
        if fields[0] != "FND01AUTHORv2" {
            return Err(TrustError::new(
                "E_AUTHORING_MARKER",
                "wrong marker prefix",
            ));
        }
        let marker = AuthoringMarker {
            policy: FileBinding {
                byte_length: parse_canonical_nonzero_u64(
                    fields[1],
                    MAX_POLICY_BYTES,
                    "policy length",
                )?,
                sha256: decode_lower_hex(fields[2], "policy SHA-256")?,
            },
            verifier: FileBinding {
                byte_length: parse_canonical_nonzero_u64(
                    fields[3],
                    MAX_VERIFIER_BYTES,
                    "verifier length",
                )?,
                sha256: decode_lower_hex(fields[4], "verifier SHA-256")?,
            },
            harness: FileBinding {
                byte_length: parse_canonical_nonzero_u64(
                    fields[5],
                    MAX_HARNESS_BYTES,
                    "harness length",
                )?,
                sha256: decode_lower_hex(fields[6], "harness SHA-256")?,
            },
            closure_sha256: decode_lower_hex(fields[7], "authoring closure SHA-256")?,
        };
        let actual = sha256(&authoring_closure_preimage(&marker)?)?;
        if actual != marker.closure_sha256 {
            return Err(TrustError::new(
                "E_AUTHORING_CLOSURE",
                "authoring closure digest mismatch",
            ));
        }
        Ok(marker)
    }

    pub fn integration_seal_preimage(seal: &IntegrationSeal) -> TrustResult<Vec<u8>> {
        let mut preimage = Vec::new();
        reserve_preimage(
            &mut preimage,
            b"FND01INTEGRATIONv1\0".len() + seal.run_id.len(),
        )?;
        preimage.extend_from_slice(b"FND01INTEGRATIONv1\0");
        preimage.extend_from_slice(&seal.run_id);
        for (path, binding) in INTEGRATION_SEAL_PATHS.iter().zip(seal.records) {
            append_bound_record(&mut preimage, path, binding)?;
        }
        reserve_preimage(&mut preimage, 8 + 32 + 32)?;
        preimage.extend_from_slice(&seal.outer_transport.byte_length.to_be_bytes());
        preimage.extend_from_slice(&seal.outer_transport.sha256);
        preimage.extend_from_slice(&seal.authoring_closure_sha256);
        Ok(preimage)
    }

    pub fn parse_integration_seal(
        value: &str,
        expected_authoring_closure: &[u8; 32],
    ) -> TrustResult<IntegrationSeal> {
        if value.len() > MAX_INTEGRATION_SEAL_TEXT_BYTES {
            return Err(TrustError::new(
                "E_INTEGRATION_SEAL",
                "seal exceeds bounded grammar size",
            ));
        }
        let fields = split_exact::<16>(value, INTEGRATION_SEAL_ENV)?;
        if fields[0] != "FND01INTEGRATIONv1" {
            return Err(TrustError::new(
                "E_INTEGRATION_SEAL",
                "wrong seal prefix",
            ));
        }
        let run_id = decode_lower_hex::<16>(fields[1], "integration run ID")?;
        if run_id.iter().all(|byte| *byte == 0) {
            return Err(TrustError::new(
                "E_INTEGRATION_RUN_ID",
                "all-zero run ID is forbidden",
            ));
        }
        let mut records = [FileBinding {
            byte_length: 0,
            sha256: [0; 32],
        }; 5];
        for (index, record) in records.iter_mut().enumerate() {
            *record = FileBinding {
                byte_length: parse_canonical_nonzero_u64(
                    fields[2 + index * 2],
                    INTEGRATION_SEAL_LIMITS[index],
                    INTEGRATION_SEAL_PATHS[index],
                )?,
                sha256: decode_lower_hex(
                    fields[3 + index * 2],
                    INTEGRATION_SEAL_PATHS[index],
                )?,
            };
        }
        let seal = IntegrationSeal {
            run_id,
            records,
            outer_transport: FileBinding {
                byte_length: parse_canonical_nonzero_u64(
                    fields[12],
                    MAX_OUTER_TRANSPORT_RECORD_BYTES,
                    "outer transport record length",
                )?,
                sha256: decode_lower_hex(fields[13], "outer transport record SHA-256")?,
            },
            authoring_closure_sha256: decode_lower_hex(
                fields[14],
                "seal authoring closure",
            )?,
            seal_sha256: decode_lower_hex(fields[15], "integration seal SHA-256")?,
        };
        if seal.authoring_closure_sha256 != *expected_authoring_closure {
            return Err(TrustError::new(
                "E_INTEGRATION_AUTHORING_CLOSURE",
                "seal and authoring marker disagree",
            ));
        }
        let actual = sha256(&integration_seal_preimage(&seal)?)?;
        if actual != seal.seal_sha256 {
            return Err(TrustError::new(
                "E_INTEGRATION_SEAL",
                "integration seal digest mismatch",
            ));
        }
        Ok(seal)
    }

    fn append_final_gate_binding(
        preimage: &mut Vec<u8>,
        path: &str,
        binding: FileBinding,
    ) -> TrustResult<()> {
        append_bound_record(preimage, path, binding)
    }

    pub fn final_gate_seal_preimage(
        seal: &FinalGateSeal,
        run_id: &str,
    ) -> TrustResult<Vec<u8>> {
        let producer_outer_path =
            format!(".fnd01-run/controller/{run_id}/producer-outer.bin");
        let attester_outer_path =
            format!(".fnd01-run/controller/{run_id}/attester-outer.bin");
        let gate_executable_path =
            format!(".fnd01-run/controller/{run_id}/final-gate");
        let gate_input_path =
            format!(".fnd01-run/controller/{run_id}/final-gate-input.bin");
        let mut preimage = Vec::new();
        reserve_preimage(
            &mut preimage,
            b"FND01FINALGATEv1\0".len()
                .checked_add(seal.run_id.len())
                .ok_or_else(|| {
                    TrustError::new(
                        "E_FINAL_GATE_BOUND",
                        "seal preimage length overflow",
                    )
                })?,
        )?;
        preimage.extend_from_slice(b"FND01FINALGATEv1\0");
        preimage.extend_from_slice(&seal.run_id);
        append_final_gate_binding(
            &mut preimage,
            "evidence/fnd-01/final-attestation.toml",
            seal.final_attestation,
        )?;
        append_final_gate_binding(
            &mut preimage,
            &producer_outer_path,
            seal.producer_outer_transport,
        )?;
        append_final_gate_binding(
            &mut preimage,
            &attester_outer_path,
            seal.attester_outer_transport,
        )?;
        append_final_gate_binding(
            &mut preimage,
            &gate_executable_path,
            seal.gate_executable,
        )?;
        append_final_gate_binding(
            &mut preimage,
            &gate_input_path,
            seal.gate_input,
        )?;
        reserve_preimage(&mut preimage, 64)?;
        preimage.extend_from_slice(&seal.authoring_closure_sha256);
        preimage.extend_from_slice(&seal.integration_seal_sha256);
        Ok(preimage)
    }

    pub fn parse_final_gate_seal(
        value: &str,
        expected_run_id: &[u8; 16],
        run_id: &str,
        expected_authoring_closure: &[u8; 32],
    ) -> TrustResult<FinalGateSeal> {
        if value.len() > 2048 {
            return Err(TrustError::new(
                "E_FINAL_GATE_SEAL",
                "marker exceeds bounded grammar size",
            ));
        }
        let fields = split_exact::<15>(value, FINAL_GATE_SEAL_ENV)?;
        if fields[0] != "FND01FINALGATEv1" {
            return Err(TrustError::new(
                "E_FINAL_GATE_SEAL",
                "wrong marker prefix",
            ));
        }
        let decoded_run_id = decode_lower_hex::<16>(fields[1], "final gate run ID")?;
        if decoded_run_id != *expected_run_id {
            return Err(TrustError::new(
                "E_FINAL_GATE_RUN_ID",
                "final gate marker and argv run IDs disagree",
            ));
        }
        let binding = |length: &str,
                       digest: &str,
                       maximum: u64,
                       subject: &str|
         -> TrustResult<FileBinding> {
            Ok(FileBinding {
                byte_length: parse_canonical_nonzero_u64(
                    length, maximum, subject,
                )?,
                sha256: decode_lower_hex(digest, subject)?,
            })
        };
        let seal = FinalGateSeal {
            run_id: decoded_run_id,
            final_attestation: binding(
                fields[2],
                fields[3],
                MAX_FINAL_ATTESTATION_BYTES,
                "final attestation",
            )?,
            producer_outer_transport: binding(
                fields[4],
                fields[5],
                MAX_OUTER_TRANSPORT_RECORD_BYTES,
                "producer outer record",
            )?,
            attester_outer_transport: binding(
                fields[6],
                fields[7],
                MAX_OUTER_TRANSPORT_RECORD_BYTES,
                "attester outer record",
            )?,
            gate_executable: binding(
                fields[8],
                fields[9],
                MAX_GATE_EXECUTABLE_BYTES,
                "gate executable",
            )?,
            gate_input: binding(
                fields[10],
                fields[11],
                MAX_FINAL_GATE_INPUT_BYTES,
                "gate input",
            )?,
            authoring_closure_sha256: decode_lower_hex(
                fields[12],
                "final gate authoring closure",
            )?,
            integration_seal_sha256: decode_lower_hex(
                fields[13],
                "final gate integration seal",
            )?,
            seal_sha256: decode_lower_hex(fields[14], "final gate seal")?,
        };
        if seal.authoring_closure_sha256 != *expected_authoring_closure
            || sha256(&final_gate_seal_preimage(&seal, run_id)?)?
                != seal.seal_sha256
        {
            return Err(TrustError::new(
                "E_FINAL_GATE_SEAL",
                "marker closure or digest mismatch",
            ));
        }
        Ok(seal)
    }

    pub fn read_unique_environment(name: &str) -> TrustResult<String> {
        let mut found = None::<OsString>;
        for (key, value) in std::env::vars_os() {
            if key == OsStr::new(name) {
                if found.replace(value).is_some() {
                    return Err(TrustError::new(
                        "E_ENV_DUPLICATE",
                        format!("{name}: duplicate environment entry"),
                    ));
                }
            }
        }
        let value = found.ok_or_else(|| {
            TrustError::new("E_ENV_MISSING", format!("{name}: required external value"))
        })?;
        value.into_string().map_err(|_| {
            TrustError::new("E_ENV_ENCODING", format!("{name}: UTF-8 required"))
        })
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct LinuxFileIdentity {
        pub device: u64,
        pub inode: u64,
        pub link_count: u64,
        pub file_type: u32,
        pub mode: u32,
        pub byte_length: u64,
        pub modification_seconds: i64,
        pub modification_nanoseconds: i64,
        pub change_seconds: i64,
        pub change_nanoseconds: i64,
    }

    #[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
    pub struct FilesystemUsage {
        pub entry_count: u64,
        pub regular_file_bytes: u64,
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct FilesystemUsageCap {
        pub max_entry_count: u64,
        pub max_regular_file_bytes: u64,
    }

    impl FilesystemUsageCap {
        pub fn validate(self, subject: &str) -> TrustResult<Self> {
            if self.max_entry_count == 0 || self.max_regular_file_bytes == 0 {
                return Err(TrustError::new(
                    "E_SPACE_CONFIGURATION",
                    format!("{subject}: aggregate caps must be nonzero"),
                ));
            }
            Ok(self)
        }
    }

    impl FilesystemUsage {
        pub const ZERO: Self = Self {
            entry_count: 0,
            regular_file_bytes: 0,
        };

        pub fn checked_add(
            self,
            additional: Self,
            subject: &str,
        ) -> TrustResult<Self> {
            Ok(Self {
                entry_count: self.entry_count.checked_add(additional.entry_count)
                    .ok_or_else(|| TrustError::new(
                        "E_SPACE_OVERFLOW",
                        format!("{subject}: entry-count overflow"),
                    ))?,
                regular_file_bytes: self.regular_file_bytes
                    .checked_add(additional.regular_file_bytes)
                    .ok_or_else(|| TrustError::new(
                        "E_SPACE_OVERFLOW",
                        format!("{subject}: regular-file-byte overflow"),
                    ))?,
            })
        }

        pub fn require_at_most(
            self,
            cap: FilesystemUsageCap,
            subject: &str,
        ) -> TrustResult<()> {
            let cap = cap.validate(subject)?;
            if self.entry_count > cap.max_entry_count
                || self.regular_file_bytes > cap.max_regular_file_bytes
            {
                return Err(TrustError::new(
                    "E_SPACE_BOUND",
                    format!(
                        "{subject}: usage entries={} bytes={} exceeds entries={} bytes={}",
                        self.entry_count,
                        self.regular_file_bytes,
                        cap.max_entry_count,
                        cap.max_regular_file_bytes,
                    ),
                ));
            }
            Ok(())
        }

        pub fn checked_projected(
            self,
            additional: Self,
            cap: FilesystemUsageCap,
            subject: &str,
        ) -> TrustResult<Self> {
            let projected = self.checked_add(additional, subject)?;
            projected.require_at_most(cap, subject)?;
            Ok(projected)
        }
    }

    #[allow(clippy::struct_field_names)]
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct PhaseBSpaceBudget {
        pub max_tree_entry_count: u64,
        pub max_run_scratch_total_bytes: u64,
        pub max_fallback_target_total_bytes: u64,
        pub max_execution_footprint_total_bytes: u64,
        pub max_control_plane_total_bytes: u64,
        pub max_bootstrap_scratch_total_bytes: u64,
        pub max_materialization_total_bytes: u64,
    }

    impl PhaseBSpaceBudget {
        pub fn validate(self, subject: &str) -> TrustResult<Self> {
            if self.max_tree_entry_count == 0
                || self.max_run_scratch_total_bytes == 0
                || self.max_fallback_target_total_bytes == 0
                || self.max_execution_footprint_total_bytes == 0
                || self.max_control_plane_total_bytes == 0
                || self.max_bootstrap_scratch_total_bytes == 0
                || self.max_materialization_total_bytes == 0
            {
                return Err(TrustError::new(
                    "E_SPACE_CONFIGURATION",
                    format!("{subject}: Phase-B space caps must be nonzero"),
                ));
            }
            let execution = self.max_run_scratch_total_bytes
                .checked_add(self.max_fallback_target_total_bytes)
                .ok_or_else(|| TrustError::new(
                    "E_SPACE_OVERFLOW",
                    format!("{subject}: execution-footprint authority overflow"),
                ))?;
            if execution != self.max_execution_footprint_total_bytes {
                return Err(TrustError::new(
                    "E_SPACE_CONFIGURATION",
                    format!(
                        "{subject}: execution footprint must equal run plus fallback"
                    ),
                ));
            }
            Ok(self)
        }

        pub fn cap(
            self,
            max_regular_file_bytes: u64,
        ) -> FilesystemUsageCap {
            FilesystemUsageCap {
                max_entry_count: self.max_tree_entry_count,
                max_regular_file_bytes,
            }
        }
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct FilesystemRootUsage {
        pub root: PathBuf,
        pub root_identity: LinuxFileIdentity,
        pub usage: FilesystemUsage,
    }

    pub fn normalize_outermost_usage_roots(
        candidate_roots: &[PathBuf],
        subject: &str,
    ) -> TrustResult<Vec<PathBuf>> {
        let mut sorted = Vec::new();
        sorted.try_reserve_exact(candidate_roots.len()).map_err(|_| {
            TrustError::new(
                "E_SPACE_ALLOCATION",
                format!("{subject}: root registry allocation"),
            )
        })?;
        let mut unique = BTreeSet::new();
        for candidate in candidate_roots {
            let text = candidate.to_str().ok_or_else(|| {
                TrustError::new(
                    "E_SPACE_ROOT",
                    format!("{subject}: usage root must be UTF-8"),
                )
            })?;
            let validated = validate_absolute_lexical_path(text, subject)?;
            if &validated != candidate || !unique.insert(validated.clone()) {
                return Err(TrustError::new(
                    "E_SPACE_ROOT",
                    format!("{subject}: duplicate or noncanonical usage root"),
                ));
            }
            sorted.push(validated);
        }
        sorted.sort_by(|left, right| {
            left.components().count().cmp(&right.components().count())
                .then_with(|| {
                    left.as_os_str().as_encoded_bytes()
                        .cmp(right.as_os_str().as_encoded_bytes())
                })
        });
        let mut outermost = Vec::<PathBuf>::new();
        for candidate in sorted {
            if outermost.iter().any(|root| candidate.starts_with(root)) {
                continue;
            }
            outermost.push(candidate);
        }
        outermost.sort_by(|left, right| {
            left.as_os_str().as_encoded_bytes()
                .cmp(right.as_os_str().as_encoded_bytes())
        });
        Ok(outermost)
    }

    pub fn checked_disjoint_usage(
        roots: &[FilesystemRootUsage],
        cap: FilesystemUsageCap,
        subject: &str,
    ) -> TrustResult<FilesystemUsage> {
        cap.validate(subject)?;
        let mut total = FilesystemUsage::ZERO;
        for (index, root) in roots.iter().enumerate() {
            for prior in &roots[..index] {
                if root.root == prior.root
                    || root.root.starts_with(&prior.root)
                    || prior.root.starts_with(&root.root)
                    || (root.root_identity.device == prior.root_identity.device
                        && root.root_identity.inode == prior.root_identity.inode)
                {
                    return Err(TrustError::new(
                        "E_SPACE_ROOT_ALIAS",
                        format!("{subject}: overlapping or physically aliased roots"),
                    ));
                }
            }
            total = total.checked_add(root.usage, subject)?;
        }
        total.require_at_most(cap, subject)?;
        Ok(total)
    }

    fn walk_usage_directory_nofollow(
        current: &Path,
        cap: FilesystemUsageCap,
        subject: &str,
        depth: usize,
        usage: &mut FilesystemUsage,
    ) -> TrustResult<()> {
        if depth == 0 || depth > MAX_ABSOLUTE_PATH_DEPTH {
            return Err(TrustError::new(
                "E_SPACE_DEPTH",
                format!("{subject}: filesystem traversal depth exceeded"),
            ));
        }
        let before_metadata = fs::symlink_metadata(current).map_err(|error| {
            TrustError::new(
                "E_SPACE_SCAN",
                format!("{subject}: {}: {error}", current.display()),
            )
        })?;
        if before_metadata.file_type().is_symlink() || !before_metadata.is_dir() {
            return Err(TrustError::new(
                "E_SPACE_FILE_TYPE",
                format!("{subject}: {} is not a no-follow directory", current.display()),
            ));
        }
        let before = linux_identity(&before_metadata, subject)?;
        for entry in fs::read_dir(current).map_err(|error| {
            TrustError::new(
                "E_SPACE_SCAN",
                format!("{subject}: {}: {error}", current.display()),
            )
        })? {
            let entry = entry.map_err(|error| {
                TrustError::new(
                    "E_SPACE_SCAN",
                    format!("{subject}: {}: {error}", current.display()),
                )
            })?;
            let name = entry.file_name().into_string().map_err(|_| {
                TrustError::new(
                    "E_SPACE_ROOT",
                    format!("{subject}: non-UTF-8 filesystem entry"),
                )
            })?;
            if name.is_empty() || name == "." || name == ".." || name.contains('/') {
                return Err(TrustError::new(
                    "E_SPACE_ROOT",
                    format!("{subject}: invalid filesystem entry {name:?}"),
                ));
            }
            let path = entry.path();
            let metadata = fs::symlink_metadata(&path).map_err(|error| {
                TrustError::new(
                    "E_SPACE_SCAN",
                    format!("{subject}: {}: {error}", path.display()),
                )
            })?;
            let file_type = metadata.file_type();
            *usage = usage.checked_projected(
                FilesystemUsage {
                    entry_count: 1,
                    regular_file_bytes: 0,
                },
                cap,
                subject,
            )?;
            if file_type.is_symlink() {
                // No-follow accounting charges the directory entry but never
                // follows or charges the target.  Separate typed tree
                // contracts decide whether this exact link is admissible.
            } else if metadata.is_dir() {
                let next_depth = depth.checked_add(1).ok_or_else(|| {
                    TrustError::new(
                        "E_SPACE_DEPTH",
                        format!("{subject}: filesystem traversal depth overflow"),
                    )
                })?;
                walk_usage_directory_nofollow(
                    &path,
                    cap,
                    subject,
                    next_depth,
                    usage,
                )?;
            } else if metadata.is_file() {
                let identity = linux_identity(&metadata, subject)?;
                if identity.link_count != 1 {
                    return Err(TrustError::new(
                        "E_SPACE_FILE_TYPE",
                        format!("{subject}: hardlink forbidden at {}", path.display()),
                    ));
                }
                *usage = usage.checked_projected(
                    FilesystemUsage {
                        entry_count: 0,
                        regular_file_bytes: identity.byte_length,
                    },
                    cap,
                    subject,
                )?;
                let after_metadata =
                    fs::symlink_metadata(&path).map_err(|error| {
                        TrustError::new(
                            "E_SPACE_RACE",
                            format!("{subject}: {}: {error}", path.display()),
                        )
                    })?;
                if linux_identity(&after_metadata, subject)? != identity {
                    return Err(TrustError::new(
                        "E_SPACE_RACE",
                        format!(
                            "{subject}: regular-file identity drift at {}",
                            path.display(),
                        ),
                    ));
                }
            } else {
                return Err(TrustError::new(
                    "E_SPACE_FILE_TYPE",
                    format!("{subject}: special file forbidden at {}", path.display()),
                ));
            }
        }
        let after_metadata = fs::symlink_metadata(current).map_err(|error| {
            TrustError::new(
                "E_SPACE_RACE",
                format!("{subject}: {}: {error}", current.display()),
            )
        })?;
        if linux_identity(&after_metadata, subject)? != before {
            return Err(TrustError::new(
                "E_SPACE_RACE",
                format!("{subject}: directory identity drift at {}", current.display()),
            ));
        }
        Ok(())
    }

    fn snapshot_missing_usage_parent(
        missing: &Path,
        subject: &str,
    ) -> TrustResult<(PathBuf, LinuxFileIdentity)> {
        let mut candidate = missing.parent().ok_or_else(|| {
            TrustError::new(
                "E_SPACE_ROOT",
                format!("{subject}: missing root has no parent"),
            )
        })?;
        loop {
            match fs::symlink_metadata(candidate) {
                Ok(metadata) => {
                    if metadata.file_type().is_symlink() || !metadata.is_dir() {
                        return Err(TrustError::new(
                            "E_SPACE_FILE_TYPE",
                            format!(
                                "{subject}: missing-root ancestor is not a no-follow directory"
                            ),
                        ));
                    }
                    return Ok((
                        candidate.to_path_buf(),
                        linux_identity(&metadata, subject)?,
                    ));
                }
                Err(error) if error.kind() == io::ErrorKind::NotFound => {
                    candidate = candidate.parent().ok_or_else(|| {
                        TrustError::new(
                            "E_SPACE_ROOT",
                            format!("{subject}: no existing missing-root ancestor"),
                        )
                    })?;
                }
                Err(error) => {
                    return Err(TrustError::new(
                        "E_SPACE_SCAN",
                        format!("{subject}: {}: {error}", candidate.display()),
                    ));
                }
            }
        }
    }

    pub fn snapshot_usage_roots_nofollow(
        candidate_roots: &[PathBuf],
        cap: FilesystemUsageCap,
        subject: &str,
    ) -> TrustResult<Vec<FilesystemRootUsage>> {
        let cap = cap.validate(subject)?;
        let normalized =
            normalize_outermost_usage_roots(candidate_roots, subject)?;
        let mut snapshots = Vec::new();
        let mut missing_parents = Vec::new();
        for root in normalized {
            match fs::symlink_metadata(&root) {
                Ok(metadata) => {
                    if metadata.file_type().is_symlink() {
                        return Err(TrustError::new(
                            "E_SPACE_FILE_TYPE",
                            format!("{subject}: root is a symlink"),
                        ));
                    }
                    let root_identity = linux_identity(&metadata, subject)?;
                    let usage = if metadata.is_dir() {
                        let mut usage = FilesystemUsage::ZERO;
                        walk_usage_directory_nofollow(
                            &root,
                            cap,
                            subject,
                            1,
                            &mut usage,
                        )?;
                        usage
                    } else if metadata.is_file() {
                        if root_identity.link_count != 1 {
                            return Err(TrustError::new(
                                "E_SPACE_FILE_TYPE",
                                format!("{subject}: file root is a hardlink"),
                            ));
                        }
                        let usage = FilesystemUsage {
                            entry_count: 1,
                            regular_file_bytes: root_identity.byte_length,
                        };
                        usage.require_at_most(cap, subject)?;
                        usage
                    } else {
                        return Err(TrustError::new(
                            "E_SPACE_FILE_TYPE",
                            format!("{subject}: root is a special file"),
                        ));
                    };
                    let after_root =
                        fs::symlink_metadata(&root).map_err(|error| {
                            TrustError::new(
                                "E_SPACE_RACE",
                                format!(
                                    "{subject}: {}: {error}",
                                    root.display(),
                                ),
                            )
                        })?;
                    if linux_identity(&after_root, subject)? != root_identity {
                        return Err(TrustError::new(
                            "E_SPACE_RACE",
                            format!(
                                "{subject}: root identity drift at {}",
                                root.display(),
                            ),
                        ));
                    }
                    snapshots.try_reserve(1).map_err(|_| {
                        TrustError::new(
                            "E_SPACE_ALLOCATION",
                            format!("{subject}: root snapshot allocation"),
                        )
                    })?;
                    snapshots.push(FilesystemRootUsage {
                        root,
                        root_identity,
                        usage,
                    });
                }
                Err(error) if error.kind() == io::ErrorKind::NotFound => {
                    missing_parents.try_reserve(1).map_err(|_| {
                        TrustError::new(
                            "E_SPACE_ALLOCATION",
                            format!("{subject}: missing-parent allocation"),
                        )
                    })?;
                    missing_parents.push(
                        snapshot_missing_usage_parent(&root, subject)?,
                    );
                }
                Err(error) => {
                    return Err(TrustError::new(
                        "E_SPACE_SCAN",
                        format!("{subject}: {}: {error}", root.display()),
                    ));
                }
            }
        }
        checked_disjoint_usage(&snapshots, cap, subject)?;
        for (path, expected) in missing_parents {
            let metadata = fs::symlink_metadata(&path).map_err(|error| {
                TrustError::new(
                    "E_SPACE_RACE",
                    format!("{subject}: {}: {error}", path.display()),
                )
            })?;
            if linux_identity(&metadata, subject)? != expected {
                return Err(TrustError::new(
                    "E_SPACE_RACE",
                    format!(
                        "{subject}: missing-root ancestor drift at {}",
                        path.display(),
                    ),
                ));
            }
        }
        for snapshot in &snapshots {
            let metadata =
                fs::symlink_metadata(&snapshot.root).map_err(|error| {
                    TrustError::new(
                        "E_SPACE_RACE",
                        format!(
                            "{subject}: final root bookend {}: {error}",
                            snapshot.root.display(),
                        ),
                    )
                })?;
            if linux_identity(&metadata, subject)?
                != snapshot.root_identity
            {
                return Err(TrustError::new(
                    "E_SPACE_RACE",
                    format!(
                        "{subject}: final root identity drift at {}",
                        snapshot.root.display(),
                    ),
                ));
            }
        }
        Ok(snapshots)
    }

    #[cfg(test)]
    mod filesystem_usage_tests {
        use super::*;

        fn identity(device: u64, inode: u64) -> LinuxFileIdentity {
            LinuxFileIdentity {
                device,
                inode,
                link_count: 1,
                file_type: 0o040_000,
                mode: 0o040_700,
                byte_length: 0,
                modification_seconds: 0,
                modification_nanoseconds: 0,
                change_seconds: 0,
                change_nanoseconds: 0,
            }
        }

        #[test]
        fn aggregate_usage_is_checked_at_exact_bound_and_overflow() {
            let cap = FilesystemUsageCap {
                max_entry_count: 3,
                max_regular_file_bytes: 10,
            };
            FilesystemUsage {
                entry_count: 3,
                regular_file_bytes: 10,
            }
            .require_at_most(cap, "exact aggregate cap")
            .expect("the exact cap is admitted");
            for usage in [
                FilesystemUsage {
                    entry_count: 4,
                    regular_file_bytes: 10,
                },
                FilesystemUsage {
                    entry_count: 3,
                    regular_file_bytes: 11,
                },
            ] {
                assert_eq!(
                    usage
                        .require_at_most(cap, "cap plus one")
                        .expect_err("either cap plus one must fail")
                        .code(),
                    "E_SPACE_BOUND",
                );
            }
            assert_eq!(
                FilesystemUsage {
                    entry_count: u64::MAX,
                    regular_file_bytes: 0,
                }
                .checked_add(
                    FilesystemUsage {
                        entry_count: 1,
                        regular_file_bytes: 0,
                    },
                    "entry overflow",
                )
                .expect_err("entry overflow must fail")
                .code(),
                "E_SPACE_OVERFLOW",
            );
            assert_eq!(
                FilesystemUsage {
                    entry_count: 0,
                    regular_file_bytes: u64::MAX,
                }
                .checked_add(
                    FilesystemUsage {
                        entry_count: 0,
                        regular_file_bytes: 1,
                    },
                    "byte overflow",
                )
                .expect_err("byte overflow must fail")
                .code(),
                "E_SPACE_OVERFLOW",
            );
        }

        #[test]
        fn phase_b_space_budget_requires_exact_execution_sum() {
            let exact = PhaseBSpaceBudget {
                max_tree_entry_count: 100,
                max_run_scratch_total_bytes: 64,
                max_fallback_target_total_bytes: 8,
                max_execution_footprint_total_bytes: 72,
                max_control_plane_total_bytes: 4,
                max_bootstrap_scratch_total_bytes: 5,
                max_materialization_total_bytes: 6,
            };
            exact.validate("exact budget").expect("64 + 8 = 72");
            assert_eq!(
                PhaseBSpaceBudget {
                    max_execution_footprint_total_bytes: 71,
                    ..exact
                }
                .validate("wrong execution sum")
                .expect_err("a nonexact execution sum must fail")
                .code(),
                "E_SPACE_CONFIGURATION",
            );
            assert_eq!(
                PhaseBSpaceBudget {
                    max_run_scratch_total_bytes: u64::MAX,
                    max_fallback_target_total_bytes: 1,
                    max_execution_footprint_total_bytes: u64::MAX,
                    ..exact
                }
                .validate("overflowing execution sum")
                .expect_err("the authority sum must not wrap")
                .code(),
                "E_SPACE_OVERFLOW",
            );
        }

        #[test]
        fn root_normalization_deduplicates_only_nested_coverage() {
            let normalized = normalize_outermost_usage_roots(
                &[
                    PathBuf::from("/run/producer"),
                    PathBuf::from("/run"),
                    PathBuf::from("/fallback"),
                ],
                "nested roots",
            )
            .expect("nested roots normalize");
            assert_eq!(
                normalized,
                vec![PathBuf::from("/fallback"), PathBuf::from("/run")],
            );
            assert_eq!(
                normalize_outermost_usage_roots(
                    &[PathBuf::from("/run"), PathBuf::from("/run")],
                    "duplicate roots",
                )
                .expect_err("duplicate configured roots must fail")
                .code(),
                "E_SPACE_ROOT",
            );
        }

        #[test]
        fn phase_b_relative_roots_reject_non_normal_paths_before_scanning() {
            // PhaseBSpaceGuard lives in the cfg(fnd01_bootstrap) phase_b_std
            // module; ordinary offline compilation only exercises the shared
            // relative-path grammar that the guard reuses before any FS walk.
            for relative in [
                "../escape",
                "target/../debug",
                "./target",
                "target//debug",
            ] {
                assert!(
                    validate_relative_path(relative, "synthetic invalid root").is_err(),
                    "non-normal root {relative:?} must fail before I/O",
                );
            }
            assert!(
                validate_relative_path(
                    ".fnd01-run/integration-producer/0123456789abcdef0123456789abcdef",
                    "synthetic valid root",
                )
                .is_ok(),
                "role-run relative root must be admitted by the shared grammar",
            );
        }

        #[test]
        fn disjoint_usage_is_collective_and_rejects_aliases() {
            let cap = FilesystemUsageCap {
                max_entry_count: 10,
                max_regular_file_bytes: 100,
            };
            let roots = [
                FilesystemRootUsage {
                    root: PathBuf::from("/run/a"),
                    root_identity: identity(1, 10),
                    usage: FilesystemUsage {
                        entry_count: 2,
                        regular_file_bytes: 60,
                    },
                },
                FilesystemRootUsage {
                    root: PathBuf::from("/run/b"),
                    root_identity: identity(1, 11),
                    usage: FilesystemUsage {
                        entry_count: 2,
                        regular_file_bytes: 41,
                    },
                },
            ];
            assert_eq!(
                checked_disjoint_usage(&roots, cap, "two sibling roots")
                    .expect_err("siblings share one collective allowance")
                    .code(),
                "E_SPACE_BOUND",
            );
            let aliased = [
                FilesystemRootUsage {
                    root: PathBuf::from("/run/a"),
                    root_identity: identity(2, 20),
                    usage: FilesystemUsage::ZERO,
                },
                FilesystemRootUsage {
                    root: PathBuf::from("/elsewhere"),
                    root_identity: identity(2, 20),
                    usage: FilesystemUsage::ZERO,
                },
            ];
            assert_eq!(
                checked_disjoint_usage(&aliased, cap, "physical aliases")
                    .expect_err("physical root aliases must fail")
                    .code(),
                "E_SPACE_ROOT_ALIAS",
            );
        }

        #[test]
        fn projected_usage_fails_before_mutating_state() {
            let current = FilesystemUsage {
                entry_count: 2,
                regular_file_bytes: 90,
            };
            let cap = FilesystemUsageCap {
                max_entry_count: 3,
                max_regular_file_bytes: 100,
            };
            assert_eq!(
                current
                    .checked_projected(
                        FilesystemUsage {
                            entry_count: 1,
                            regular_file_bytes: 11,
                        },
                        cap,
                        "projected file",
                    )
                    .expect_err("the projection must fail before a write")
                    .code(),
                "E_SPACE_BOUND",
            );
            assert_eq!(
                current,
                FilesystemUsage {
                    entry_count: 2,
                    regular_file_bytes: 90,
                },
            );
            assert_eq!(
                FilesystemUsage::ZERO
                    .require_at_most(
                        FilesystemUsageCap {
                            max_entry_count: 0,
                            max_regular_file_bytes: 1,
                        },
                        "zero cap",
                    )
                    .expect_err("zero caps are configuration errors")
                    .code(),
                "E_SPACE_CONFIGURATION",
            );
        }

        #[cfg(target_os = "linux")]
        #[test]
        fn nofollow_scanner_is_bounded_and_rejects_special_roots() {
            let executable =
                std::env::current_exe().expect("current executable path");
            let metadata = fs::symlink_metadata(&executable)
                .expect("current executable metadata");
            assert!(metadata.is_file());
            assert_eq!(metadata.nlink(), 1);
            assert!(metadata.len() > 0);
            let exact_cap = FilesystemUsageCap {
                max_entry_count: 1,
                max_regular_file_bytes: metadata.len(),
            };
            let snapshots = snapshot_usage_roots_nofollow(
                std::slice::from_ref(&executable),
                exact_cap,
                "current executable exact cap",
            )
            .expect("an exact file-root cap is admitted");
            assert_eq!(snapshots.len(), 1);
            assert_eq!(
                snapshots[0].usage,
                FilesystemUsage {
                    entry_count: 1,
                    regular_file_bytes: metadata.len(),
                },
            );
            assert_eq!(
                snapshot_usage_roots_nofollow(
                    std::slice::from_ref(&executable),
                    FilesystemUsageCap {
                        max_entry_count: 1,
                        max_regular_file_bytes: metadata.len() - 1,
                    },
                    "current executable cap minus one",
                )
                .expect_err("one byte above the cap must fail")
                .code(),
                "E_SPACE_BOUND",
            );

            let missing = PathBuf::from(format!(
                "/proc/{}/fnd01-space-missing",
                std::process::id(),
            ));
            assert!(snapshot_usage_roots_nofollow(
                &[missing],
                FilesystemUsageCap {
                    max_entry_count: 1,
                    max_regular_file_bytes: 1,
                },
                "missing no-follow root",
            )
            .expect("a bookended missing root is zero usage")
            .is_empty());

            for (path, subject) in [
                (PathBuf::from("/dev/null"), "special root"),
                (PathBuf::from("/proc/self/exe"), "symlink root"),
            ] {
                assert_eq!(
                    snapshot_usage_roots_nofollow(
                        &[path],
                        FilesystemUsageCap {
                            max_entry_count: 1024,
                            max_regular_file_bytes: 1024,
                        },
                        subject,
                    )
                    .expect_err("special and symlink roots must fail")
                    .code(),
                    "E_SPACE_FILE_TYPE",
                );
            }

            let descriptor_snapshots = snapshot_usage_roots_nofollow(
                &[PathBuf::from("/proc/self/fd")],
                FilesystemUsageCap {
                    max_entry_count: 1_000_000,
                    max_regular_file_bytes: 1,
                },
                "no-follow descriptor symlinks",
            )
            .expect("descriptor symlinks are counted but not followed");
            assert_eq!(descriptor_snapshots.len(), 1);
            assert!(descriptor_snapshots[0].usage.entry_count > 0);
            assert_eq!(
                descriptor_snapshots[0].usage.regular_file_bytes,
                0,
            );

            let mut usage = FilesystemUsage::ZERO;
            assert_eq!(
                walk_usage_directory_nofollow(
                    Path::new("/"),
                    FilesystemUsageCap {
                        max_entry_count: 1,
                        max_regular_file_bytes: 1,
                    },
                    "depth cap",
                    MAX_ABSOLUTE_PATH_DEPTH + 1,
                    &mut usage,
                )
                .expect_err("excessive traversal depth must fail before I/O")
                .code(),
                "E_SPACE_DEPTH",
            );
            assert_eq!(usage, FilesystemUsage::ZERO);
        }
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct EmptyDirectorySnapshot {
        pub path: PathBuf,
        pub identity: LinuxFileIdentity,
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    struct CargoDiscoveryIdentity {
        device: u64,
        inode: u64,
        mode: u32,
        link_count: u64,
        byte_length: u64,
        modification_seconds: i64,
        modification_nanoseconds: i64,
        change_seconds: i64,
        change_nanoseconds: i64,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    struct CargoDiscoveryAncestor {
        path: PathBuf,
        identity: CargoDiscoveryIdentity,
        cargo_directory: Option<CargoDiscoveryIdentity>,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct CargoConfigDiscoverySnapshot {
        working_directory: PathBuf,
        cargo_home: PathBuf,
        ancestors: Vec<CargoDiscoveryAncestor>,
    }

    impl CargoConfigDiscoverySnapshot {
        pub fn require_same_working_directory_discovery(
            &self,
            other: &Self,
        ) -> TrustResult<()> {
            if self.working_directory != other.working_directory
                || self.cargo_home != other.cargo_home
                || self.ancestors != other.ancestors
            {
                return Err(TrustError::new(
                    "E_CARGO_CONFIG_DISCOVERY",
                    "working-directory ancestry or .cargo directory identity drifted",
                ));
            }
            Ok(())
        }
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct CheckedSnapshot {
        pub logical_path: String,
        pub byte_length: u64,
        pub sha256: [u8; 32],
        pub identity: LinuxFileIdentity,
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub enum SnapshotStage {
        PreOpen,
        PostOpenPreRead,
        PostReadPreFinalMetadata,
    }

    pub trait SnapshotHook {
        fn at(&mut self, stage: SnapshotStage, path: &Path) -> TrustResult<()>;
    }

    impl<F> SnapshotHook for F
    where
        F: FnMut(SnapshotStage, &Path) -> TrustResult<()>,
    {
        fn at(&mut self, stage: SnapshotStage, path: &Path) -> TrustResult<()> {
            self(stage, path)
        }
    }

    struct NoopSnapshotHook;

    impl SnapshotHook for NoopSnapshotHook {
        fn at(&mut self, _stage: SnapshotStage, _path: &Path) -> TrustResult<()> {
            Ok(())
        }
    }

    fn require_qualified_platform() -> TrustResult<()> {
        if std::env::consts::OS == "linux" && std::env::consts::ARCH == "x86_64" {
            Ok(())
        } else {
            Err(TrustError::new(
                "E_UNQUALIFIED_PLATFORM",
                "retained evidence requires Linux x86_64",
            ))
        }
    }

    fn linux_identity(metadata: &Metadata, _subject: &str) -> TrustResult<LinuxFileIdentity> {
        require_qualified_platform()?;
        #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
        {
            Ok(LinuxFileIdentity {
                device: metadata.dev(),
                inode: metadata.ino(),
                link_count: metadata.nlink(),
                file_type: metadata.mode() & 0o170_000,
                mode: metadata.mode(),
                byte_length: metadata.len(),
                modification_seconds: metadata.mtime(),
                modification_nanoseconds: metadata.mtime_nsec(),
                change_seconds: metadata.ctime(),
                change_nanoseconds: metadata.ctime_nsec(),
            })
        }
        #[cfg(not(all(target_os = "linux", target_arch = "x86_64")))]
        {
            let _ = metadata;
            Err(TrustError::new("E_UNQUALIFIED_PLATFORM", _subject))
        }
    }

    pub(super) fn validate_absolute_lexical_path(
        value: &str,
        subject: &str,
    ) -> TrustResult<PathBuf> {
        if value.len() > MAX_ABSOLUTE_PATH_BYTES
            || !value.starts_with('/')
            || value == "/"
            || value.ends_with('/')
            || value.contains("//")
            || value.contains('\\')
            || value.as_bytes().iter().any(|byte| byte.is_ascii_control())
        {
            return Err(TrustError::new(
                "E_ROOT_PATH",
                format!("{subject}: invalid absolute lexical path"),
            ));
        }
        let mut depth = 0usize;
        for component in value.split('/').skip(1) {
            depth = depth.checked_add(1).ok_or_else(|| {
                TrustError::new("E_ROOT_PATH", format!("{subject}: depth overflow"))
            })?;
            if component.is_empty()
                || component == "."
                || component == ".."
                || component.len() > MAX_ABSOLUTE_PATH_COMPONENT_BYTES
            {
                return Err(TrustError::new(
                    "E_ROOT_PATH",
                    format!("{subject}: invalid component"),
                ));
            }
        }
        if depth == 0 || depth > MAX_ABSOLUTE_PATH_DEPTH {
            return Err(TrustError::new(
                "E_ROOT_PATH",
                format!("{subject}: depth {depth}"),
            ));
        }
        let path = PathBuf::from(value);
        if path
            .components()
            .any(|component| !matches!(component, Component::RootDir | Component::Normal(_)))
        {
            return Err(TrustError::new(
                "E_ROOT_PATH",
                format!("{subject}: non-lexical component"),
            ));
        }
        Ok(path)
    }

    fn validate_existing_directory_root(root: &Path, subject: &str) -> TrustResult<()> {
        require_qualified_platform()?;
        if !root.is_absolute() {
            return Err(TrustError::new(
                "E_ROOT_PATH",
                format!("{subject}: absolute path required"),
            ));
        }
        let mut current = PathBuf::from("/");
        for component in root.components() {
            match component {
                Component::RootDir => {}
                Component::Normal(part) => {
                    current.push(part);
                    let metadata = fs::symlink_metadata(&current)
                        .map_err(|error| io_error("E_ROOT_METADATA", subject, &error))?;
                    if metadata.file_type().is_symlink() || !metadata.is_dir() {
                        return Err(TrustError::new(
                            "E_ROOT_TYPE",
                            format!("{subject}: {}", current.display()),
                        ));
                    }
                }
                _ => {
                    return Err(TrustError::new(
                        "E_ROOT_PATH",
                        format!("{subject}: non-lexical component"),
                    ));
                }
            }
        }
        Ok(())
    }

    #[cfg(unix)]
    fn cargo_discovery_identity(metadata: &Metadata) -> CargoDiscoveryIdentity {
        CargoDiscoveryIdentity {
            device: metadata.dev(),
            inode: metadata.ino(),
            mode: metadata.mode(),
            link_count: metadata.nlink(),
            byte_length: metadata.len(),
            modification_seconds: metadata.mtime(),
            modification_nanoseconds: metadata.mtime_nsec(),
            change_seconds: metadata.ctime(),
            change_nanoseconds: metadata.ctime_nsec(),
        }
    }

    #[cfg(unix)]
    fn cargo_discovery_directory(
        path: &Path,
        subject: &str,
    ) -> TrustResult<CargoDiscoveryIdentity> {
        let metadata = fs::symlink_metadata(path)
            .map_err(|error| io_error("E_CARGO_CONFIG_DISCOVERY", subject, &error))?;
        if metadata.file_type().is_symlink() || !metadata.is_dir() {
            return Err(TrustError::new(
                "E_CARGO_CONFIG_DISCOVERY",
                format!("{subject}: physical non-symlink directory required"),
            ));
        }
        Ok(cargo_discovery_identity(&metadata))
    }

    #[cfg(unix)]
    fn cargo_discovery_optional_directory(
        path: &Path,
        subject: &str,
    ) -> TrustResult<Option<CargoDiscoveryIdentity>> {
        match fs::symlink_metadata(path) {
            Ok(metadata) => {
                if metadata.file_type().is_symlink() || !metadata.is_dir() {
                    return Err(TrustError::new(
                        "E_CARGO_CONFIG_DISCOVERY",
                        format!(
                            "{subject}: .cargo must be absent or a physical directory"
                        ),
                    ));
                }
                Ok(Some(cargo_discovery_identity(&metadata)))
            }
            Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(None),
            Err(error) => Err(io_error(
                "E_CARGO_CONFIG_DISCOVERY",
                subject,
                &error,
            )),
        }
    }

    #[cfg(unix)]
    fn require_cargo_config_absent(
        path: &Path,
        subject: &str,
    ) -> TrustResult<()> {
        match fs::symlink_metadata(path) {
            Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
            Ok(metadata) => Err(TrustError::new(
                "E_CARGO_CONFIG_DISCOVERY",
                format!(
                    "{subject}: discovered forbidden node {} with mode {:o}",
                    path.display(),
                    metadata.mode(),
                ),
            )),
            Err(error) => Err(io_error(
                "E_CARGO_CONFIG_DISCOVERY",
                subject,
                &error,
            )),
        }
    }

    #[cfg(unix)]
    fn cargo_discovery_ancestor(
        path: &Path,
    ) -> TrustResult<CargoDiscoveryAncestor> {
        let subject = format!("Cargo discovery ancestor {}", path.display());
        let before = cargo_discovery_directory(path, &subject)?;
        let cargo_directory_path = path.join(".cargo");
        let cargo_directory_before = cargo_discovery_optional_directory(
            &cargo_directory_path,
            &subject,
        )?;
        for name in ["config.toml", "config"] {
            require_cargo_config_absent(
                &cargo_directory_path.join(name),
                &subject,
            )?;
        }
        let cargo_directory_after = cargo_discovery_optional_directory(
            &cargo_directory_path,
            &subject,
        )?;
        let after = cargo_discovery_directory(path, &subject)?;
        if before != after || cargo_directory_before != cargo_directory_after {
            return Err(TrustError::new(
                "E_CARGO_CONFIG_DISCOVERY",
                format!("{subject}: identity drift during checked absence scan"),
            ));
        }
        Ok(CargoDiscoveryAncestor {
            path: path.to_path_buf(),
            identity: before,
            cargo_directory: cargo_directory_before,
        })
    }

    #[cfg(unix)]
    fn validate_cargo_home_config_absence(cargo_home: &Path) -> TrustResult<()> {
        let subject = format!("fresh CARGO_HOME {}", cargo_home.display());
        let before = cargo_discovery_directory(cargo_home, &subject)?;
        for name in ["config.toml", "config"] {
            require_cargo_config_absent(&cargo_home.join(name), &subject)?;
        }
        let after = cargo_discovery_directory(cargo_home, &subject)?;
        if before != after {
            return Err(TrustError::new(
                "E_CARGO_CONFIG_DISCOVERY",
                format!("{subject}: identity drift during checked absence scan"),
            ));
        }
        Ok(())
    }

    #[cfg(unix)]
    pub fn validate_cargo_config_discovery(
        working_directory: &Path,
        cargo_home: &Path,
    ) -> TrustResult<CargoConfigDiscoverySnapshot> {
        let working_directory_text = working_directory.to_str().ok_or_else(|| {
            TrustError::new(
                "E_CARGO_CONFIG_DISCOVERY",
                "Cargo working directory must be UTF-8",
            )
        })?;
        let cargo_home_text = cargo_home.to_str().ok_or_else(|| {
            TrustError::new(
                "E_CARGO_CONFIG_DISCOVERY",
                "CARGO_HOME must be UTF-8",
            )
        })?;
        let working_directory = validate_absolute_lexical_path(
            working_directory_text,
            "Cargo working directory",
        )?;
        let cargo_home =
            validate_absolute_lexical_path(cargo_home_text, "CARGO_HOME")?;
        validate_existing_directory_root(
            &working_directory,
            "Cargo working directory",
        )?;
        validate_existing_directory_root(&cargo_home, "CARGO_HOME")?;

        let ancestor_count = working_directory.components().count();
        let mut ancestors = Vec::new();
        ancestors.try_reserve_exact(ancestor_count).map_err(|_| {
            TrustError::new(
                "E_CARGO_CONFIG_DISCOVERY",
                "cannot reserve Cargo discovery ancestor snapshot",
            )
        })?;
        let mut current = working_directory.clone();
        loop {
            ancestors.push(cargo_discovery_ancestor(&current)?);
            if current == Path::new("/") {
                break;
            }
            current = current.parent().ok_or_else(|| {
                TrustError::new(
                    "E_CARGO_CONFIG_DISCOVERY",
                    "Cargo working-directory ancestry did not terminate at /",
                )
            })?
            .to_path_buf();
        }
        for expected in &ancestors {
            if cargo_discovery_ancestor(&expected.path)? != *expected {
                return Err(TrustError::new(
                    "E_CARGO_CONFIG_DISCOVERY",
                    "Cargo discovery ancestry drifted across the full scan",
                ));
            }
        }
        validate_cargo_home_config_absence(&cargo_home)?;
        Ok(CargoConfigDiscoverySnapshot {
            working_directory,
            cargo_home,
            ancestors,
        })
    }

    #[cfg(not(unix))]
    pub fn validate_cargo_config_discovery(
        working_directory: &Path,
        cargo_home: &Path,
    ) -> TrustResult<CargoConfigDiscoverySnapshot> {
        let _ = (working_directory, cargo_home);
        Err(TrustError::new(
            "E_CARGO_CONFIG_DISCOVERY",
            "Cargo discovery identity validation requires Unix",
        ))
    }

    pub fn validate_empty_lookup_directory(
        value: &str,
    ) -> TrustResult<EmptyDirectorySnapshot> {
        let path = validate_absolute_lexical_path(value, "empty lookup directory")?;
        validate_existing_directory_root(&path, "empty lookup directory")?;
        let before = fs::symlink_metadata(&path).map_err(|error| {
            io_error(
                "E_EMPTY_LOOKUP_METADATA",
                "empty lookup directory",
                &error,
            )
        })?;
        if before.file_type().is_symlink() || !before.is_dir() {
            return Err(TrustError::new(
                "E_EMPTY_LOOKUP_TYPE",
                "empty lookup directory must be a real directory",
            ));
        }
        let before_identity = linux_identity(&before, "empty lookup directory")?;
        let mut entries = fs::read_dir(&path).map_err(|error| {
            io_error(
                "E_EMPTY_LOOKUP_READ",
                "empty lookup directory",
                &error,
            )
        })?;
        if entries
            .next()
            .transpose()
            .map_err(|error| {
                io_error(
                    "E_EMPTY_LOOKUP_READ",
                    "empty lookup directory",
                    &error,
                )
            })?
            .is_some()
        {
            return Err(TrustError::new(
                "E_EMPTY_LOOKUP_NOT_EMPTY",
                path.display().to_string(),
            ));
        }
        let after = fs::symlink_metadata(&path).map_err(|error| {
            io_error(
                "E_EMPTY_LOOKUP_METADATA",
                "empty lookup directory",
                &error,
            )
        })?;
        if linux_identity(&after, "empty lookup directory")? != before_identity {
            return Err(TrustError::new(
                "E_EMPTY_LOOKUP_RACE",
                path.display().to_string(),
            ));
        }
        Ok(EmptyDirectorySnapshot {
            path,
            identity: before_identity,
        })
    }

    pub fn validate_exact_integration_namespace(
        repository_root: &Path,
    ) -> TrustResult<LinuxFileIdentity> {
        const EXPECTED_NAMES: [&str; 14] = [
            "source-snapshot.toml",
            "producer-environment.toml",
            "advisory-database.bin",
            "supply-bundle.bin",
            "supply-receipt.toml",
            "command-streams.bin.gz",
            "command-results.toml",
            "dependency-receipt.toml",
            "workspace-receipt.toml",
            "mutation-receipt.toml",
            "package-artifacts.bin",
            "package-receipt.toml",
            "consumer-receipt.toml",
            "integration-index.toml",
        ];
        let logical_root = "evidence/fnd-01/integration";
        validate_relative_path(logical_root, "integration namespace")?;
        let root = repository_root.join(logical_root);
        validate_existing_directory_root(&root, "integration namespace")?;
        let before_metadata = fs::symlink_metadata(&root).map_err(|error| {
            io_error("E_INTEGRATION_NAMESPACE", "integration root", &error)
        })?;
        let before = linux_identity(&before_metadata, "integration root")?;
        if before.file_type != 0o040_000 || before.link_count == 0 {
            return Err(TrustError::new(
                "E_INTEGRATION_NAMESPACE",
                "integration root identity",
            ));
        }
        let mut names = Vec::new();
        names.try_reserve_exact(EXPECTED_NAMES.len()).map_err(|_| {
            TrustError::new(
                "E_INTEGRATION_NAMESPACE",
                "cannot reserve namespace entries",
            )
        })?;
        let entries = fs::read_dir(&root).map_err(|error| {
            io_error("E_INTEGRATION_NAMESPACE", "integration read_dir", &error)
        })?;
        for entry in entries {
            let entry = entry.map_err(|error| {
                io_error("E_INTEGRATION_NAMESPACE", "integration entry", &error)
            })?;
            if names.len() >= EXPECTED_NAMES.len() {
                return Err(TrustError::new(
                    "E_INTEGRATION_NAMESPACE",
                    "extra integration entry",
                ));
            }
            let name = entry.file_name().into_string().map_err(|_| {
                TrustError::new(
                    "E_INTEGRATION_NAMESPACE",
                    "non-UTF-8 integration entry",
                )
            })?;
            if name.is_empty()
                || name == "."
                || name == ".."
                || name.contains('/')
                || name.contains('\\')
            {
                return Err(TrustError::new(
                    "E_INTEGRATION_NAMESPACE",
                    "invalid integration entry name",
                ));
            }
            let metadata = fs::symlink_metadata(entry.path()).map_err(|error| {
                io_error(
                    "E_INTEGRATION_NAMESPACE",
                    "integration entry metadata",
                    &error,
                )
            })?;
            let identity = linux_identity(&metadata, "integration entry")?;
            if metadata.file_type().is_symlink()
                || !metadata.is_file()
                || identity.file_type != 0o100_000
                || identity.link_count != 1
            {
                return Err(TrustError::new(
                    "E_INTEGRATION_NAMESPACE",
                    format!("{name}: regular nlink-one file required"),
                ));
            }
            names.push(name);
        }
        names.sort_unstable();
        let mut expected = EXPECTED_NAMES;
        expected.sort_unstable();
        if names
            .iter()
            .map(String::as_str)
            .ne(expected.iter().copied())
        {
            return Err(TrustError::new(
                "E_INTEGRATION_NAMESPACE",
                "missing, extra, or renamed integration entry",
            ));
        }
        let after_metadata = fs::symlink_metadata(&root).map_err(|error| {
            io_error("E_INTEGRATION_NAMESPACE", "integration root recheck", &error)
        })?;
        let after = linux_identity(&after_metadata, "integration root recheck")?;
        if before != after {
            return Err(TrustError::new(
                "E_INTEGRATION_NAMESPACE",
                "integration root changed during enumeration",
            ));
        }
        Ok(before)
    }

    fn read_system_file(path: &str, maximum: usize) -> TrustResult<Vec<u8>> {
        let mut file = File::open(path)
            .map_err(|error| io_error("E_GATE_OBSERVATION", path, &error))?;
        let mut bytes = Vec::new();
        let limit = u64::try_from(maximum)
            .ok()
            .and_then(|value| value.checked_add(1))
            .ok_or_else(|| TrustError::new("E_GATE_OBSERVATION", path))?;
        Read::by_ref(&mut file)
            .take(limit)
            .read_to_end(&mut bytes)
            .map_err(|error| io_error("E_GATE_OBSERVATION", path, &error))?;
        if bytes.len() > maximum || bytes.contains(&0) {
            return Err(TrustError::new("E_GATE_OBSERVATION", path));
        }
        Ok(bytes)
    }

    fn observed_text(path: &str, maximum: usize) -> TrustResult<String> {
        let read_maximum = maximum
            .checked_add(1)
            .ok_or_else(|| TrustError::new("E_GATE_OBSERVATION", path))?;
        let bytes = read_system_file(path, read_maximum)?;
        let text = std::str::from_utf8(&bytes)
            .map_err(|_| TrustError::new("E_GATE_OBSERVATION", path))?;
        let text = text.strip_suffix('\n').unwrap_or(text);
        if text.is_empty()
            || text.len() > maximum
            || text.contains('\n')
            || text.contains('\r')
            || text.chars().any(char::is_control)
        {
            return Err(TrustError::new("E_GATE_OBSERVATION", path));
        }
        Ok(text.to_owned())
    }

    fn observed_parent_process_id() -> TrustResult<u64> {
        let bytes = read_system_file("/proc/self/stat", 4096)?;
        let text = std::str::from_utf8(&bytes).map_err(|_| {
            TrustError::new("E_GATE_OBSERVATION", "/proc/self/stat")
        })?;
        let close = text.rfind(')').ok_or_else(|| {
            TrustError::new("E_GATE_OBSERVATION", "/proc/self/stat")
        })?;
        let mut fields = text
            .get(close + 1..)
            .ok_or_else(|| {
                TrustError::new("E_GATE_OBSERVATION", "/proc/self/stat")
            })?
            .split_whitespace();
        let state = fields.next().ok_or_else(|| {
            TrustError::new("E_GATE_OBSERVATION", "/proc/self/stat")
        })?;
        let parent = fields.next().ok_or_else(|| {
            TrustError::new("E_GATE_OBSERVATION", "/proc/self/stat")
        })?;
        if state.len() != 1
            || !state.bytes().all(|byte| byte.is_ascii_alphabetic())
        {
            return Err(TrustError::new(
                "E_GATE_OBSERVATION",
                "/proc/self/stat",
            ));
        }
        canonical_toml_u64(parent, "/proc/self/stat parent PID")
    }

    fn append_handshake_string(
        output: &mut Vec<u8>,
        value: &str,
        maximum: usize,
        subject: &str,
    ) -> TrustResult<()> {
        if value.is_empty()
            || value.len() > maximum
            || value.contains('\r')
            || value.contains('\n')
            || value.chars().any(char::is_control)
        {
            return Err(TrustError::new("E_GATE_HANDSHAKE", subject));
        }
        let length = u32::try_from(value.len())
            .map_err(|_| TrustError::new("E_GATE_HANDSHAKE", subject))?;
        output.extend_from_slice(&length.to_be_bytes());
        output.extend_from_slice(value.as_bytes());
        Ok(())
    }

    pub fn build_gate_handshake(
        repository_root: &Path,
        gate_input_sha256: [u8; 32],
    ) -> TrustResult<Vec<u8>> {
        require_qualified_platform()?;
        let hostname = observed_text(
            "/etc/hostname",
            MAX_GATE_OBSERVATION_TEXT_BYTES,
        )?;
        let kernel_release = observed_text(
            "/proc/sys/kernel/osrelease",
            MAX_GATE_OBSERVATION_TEXT_BYTES,
        )?;
        let machine_id = read_system_file("/etc/machine-id", 4096)?;
        if machine_id.is_empty() {
            return Err(TrustError::new(
                "E_GATE_OBSERVATION",
                "/etc/machine-id",
            ));
        }
        let repository_root = repository_root.to_str().ok_or_else(|| {
            TrustError::new("E_GATE_HANDSHAKE", "UTF-8 repository root")
        })?;
        let mut output = b"FND01GATEPASSv1\0".to_vec();
        for (subject, value) in [
            ("worker ID", hostname.as_str()),
            ("OS", "linux"),
            ("architecture", "x86_64"),
            ("kernel release", kernel_release.as_str()),
            ("hostname", hostname.as_str()),
        ] {
            let maximum = match subject {
                "worker ID" => MAX_GATE_WORKER_ID_BYTES,
                "OS" | "architecture" => MAX_GATE_PLATFORM_BYTES,
                "kernel release" | "hostname" => {
                    MAX_GATE_OBSERVATION_TEXT_BYTES
                }
                _ => unreachable!("closed Gate handshake field set"),
            };
            append_handshake_string(&mut output, value, maximum, subject)?;
        }
        output.extend_from_slice(&sha256(&machine_id)?);
        let process_id = u64::from(std::process::id());
        let parent_process_id = observed_parent_process_id()?;
        if process_id == 0 || parent_process_id == 0 {
            return Err(TrustError::new(
                "E_GATE_OBSERVATION",
                "nonzero process and parent process IDs required",
            ));
        }
        output.extend_from_slice(&process_id.to_be_bytes());
        output.extend_from_slice(&parent_process_id.to_be_bytes());
        append_handshake_string(
            &mut output,
            repository_root,
            MAX_ABSOLUTE_PATH_BYTES,
            "remote repository root",
        )?;
        output.extend_from_slice(&gate_input_sha256);
        if output.len() > MAX_FINAL_GATE_STDOUT_BYTES {
            return Err(TrustError::new(
                "E_GATE_HANDSHAKE",
                "stdout bound",
            ));
        }
        Ok(output)
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct GateWorkerObservation {
        pub worker_id: String,
        pub os: String,
        pub architecture: String,
        pub kernel_release: String,
        pub hostname: String,
        pub machine_id_sha256: [u8; 32],
        pub process_id: u64,
        pub parent_process_id: u64,
        pub remote_repository_root: String,
        pub gate_input_sha256: [u8; 32],
    }

    fn parse_gate_handshake_string(
        cursor: &mut BinaryCursor<'_>,
        maximum: usize,
        subject: &str,
    ) -> TrustResult<String> {
        let value = cursor.utf8(maximum)?;
        if value.is_empty()
            || value.contains('\r')
            || value.contains('\n')
            || value.chars().any(char::is_control)
        {
            return Err(TrustError::new("E_GATE_HANDSHAKE", subject));
        }
        Ok(value)
    }

    pub fn parse_gate_handshake(
        bytes: &[u8],
        subject: &str,
    ) -> TrustResult<GateWorkerObservation> {
        if bytes.is_empty() || bytes.len() > MAX_FINAL_GATE_STDOUT_BYTES {
            return Err(TrustError::new("E_GATE_HANDSHAKE", "stdout bound"));
        }
        let mut cursor = BinaryCursor::new(bytes, subject);
        if cursor.exact(b"FND01GATEPASSv1\0".len())?
            != b"FND01GATEPASSv1\0"
        {
            return Err(TrustError::new("E_GATE_HANDSHAKE", "format"));
        }
        let worker_id = parse_gate_handshake_string(
            &mut cursor,
            MAX_GATE_WORKER_ID_BYTES,
            "worker ID",
        )?;
        let os = parse_gate_handshake_string(
            &mut cursor,
            MAX_GATE_PLATFORM_BYTES,
            "OS",
        )?;
        let architecture = parse_gate_handshake_string(
            &mut cursor,
            MAX_GATE_PLATFORM_BYTES,
            "architecture",
        )?;
        let kernel_release = parse_gate_handshake_string(
            &mut cursor,
            MAX_GATE_OBSERVATION_TEXT_BYTES,
            "kernel release",
        )?;
        let hostname = parse_gate_handshake_string(
            &mut cursor,
            MAX_GATE_OBSERVATION_TEXT_BYTES,
            "hostname",
        )?;
        let machine_id_sha256: [u8; 32] =
            cursor.exact(32)?.try_into().map_err(|_| {
                TrustError::new("E_GATE_HANDSHAKE", "machine-id SHA-256")
            })?;
        let process_id = cursor.u64()?;
        let parent_process_id = cursor.u64()?;
        let remote_repository_root = parse_gate_handshake_string(
            &mut cursor,
            MAX_ABSOLUTE_PATH_BYTES,
            "remote repository root",
        )?;
        validate_absolute_lexical_path(
            &remote_repository_root,
            "remote repository root",
        )?;
        let gate_input_sha256: [u8; 32] =
            cursor.exact(32)?.try_into().map_err(|_| {
                TrustError::new("E_GATE_HANDSHAKE", "gate-input SHA-256")
            })?;
        cursor.finish()?;
        if os != "linux"
            || architecture != "x86_64"
            || process_id == 0
            || parent_process_id == 0
        {
            return Err(TrustError::new(
                "E_GATE_HANDSHAKE",
                "worker platform or process identity",
            ));
        }
        Ok(GateWorkerObservation {
            worker_id,
            os,
            architecture,
            kernel_release,
            hostname,
            machine_id_sha256,
            process_id,
            parent_process_id,
            remote_repository_root,
            gate_input_sha256,
        })
    }

    pub fn write_gate_handshake<W: Write>(
        writer: &mut W,
        bytes: &[u8],
    ) -> TrustResult<()> {
        if bytes.is_empty() || bytes.len() > MAX_FINAL_GATE_STDOUT_BYTES {
            return Err(TrustError::new(
                "E_GATE_HANDSHAKE",
                "stdout bound",
            ));
        }
        writer
            .write_all(bytes)
            .map_err(|error| io_error("E_GATE_HANDSHAKE", "stdout", &error))?;
        writer
            .flush()
            .map_err(|error| io_error("E_GATE_HANDSHAKE", "stdout", &error))
    }

    pub fn emit_gate_handshake(bytes: &[u8]) -> TrustResult<()> {
        let mut stdout = io::stdout().lock();
        write_gate_handshake(&mut stdout, bytes)
    }

    pub fn has_exact_gate_intent(arguments: &[OsString]) -> bool {
        arguments
            .get(1)
            .is_some_and(|value| value.as_os_str() == OsStr::new("gate"))
    }

    #[cfg(test)]
    mod gate_handshake_tests {
        use super::*;

        #[derive(Default)]
        struct RecordingWriter {
            bytes: Vec<u8>,
            flushes: usize,
            fail_after: Option<usize>,
            fail_flush: bool,
        }

        impl Write for RecordingWriter {
            fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
                if self
                    .fail_after
                    .is_some_and(|maximum| self.bytes.len() >= maximum)
                {
                    return Err(io::Error::other("injected Gate stdout failure"));
                }
                let accepted = self.fail_after.map_or(bytes.len(), |maximum| {
                    bytes.len().min(maximum.saturating_sub(self.bytes.len()))
                });
                self.bytes.extend_from_slice(&bytes[..accepted]);
                Ok(accepted)
            }

            fn flush(&mut self) -> io::Result<()> {
                self.flushes += 1;
                if self.fail_flush {
                    Err(io::Error::other("injected Gate stdout flush failure"))
                } else {
                    Ok(())
                }
            }
        }

        #[test]
        fn gate_intent_precedes_all_later_argument_validation() {
            let malformed_gate = ["binary", "gate", "not-dot", "not-a-run-id"]
                .into_iter()
                .map(OsString::from)
                .collect::<Vec<_>>();
            assert!(has_exact_gate_intent(&malformed_gate));

            for selector in ["Gate", "gate ", "produce", "attest", ""] {
                let arguments = ["binary", selector]
                    .into_iter()
                    .map(OsString::from)
                    .collect::<Vec<_>>();
                assert!(!has_exact_gate_intent(&arguments));
            }
            assert!(!has_exact_gate_intent(&[OsString::from("binary")]));
        }

        #[test]
        fn gate_handshake_string_encoder_enforces_decoder_bounds() {
            let mut output = Vec::new();
            append_handshake_string(
                &mut output,
                &"x".repeat(MAX_GATE_OBSERVATION_TEXT_BYTES),
                MAX_GATE_OBSERVATION_TEXT_BYTES,
                "bounded",
            )
            .expect("maximum-sized Gate text");
            let before = output.clone();
            for value in [
                String::new(),
                "x".repeat(MAX_GATE_OBSERVATION_TEXT_BYTES + 1),
                "line\nbreak".to_owned(),
            ] {
                assert!(
                    append_handshake_string(
                        &mut output,
                        &value,
                        MAX_GATE_OBSERVATION_TEXT_BYTES,
                        "bounded",
                    )
                    .is_err()
                );
                assert_eq!(output, before);
            }
        }

        #[test]
        fn gate_handshake_writer_flushes_only_after_complete_write() {
            let handshake = b"FND01GATEPASSv1\0bounded";
            let mut success = RecordingWriter::default();
            write_gate_handshake(&mut success, handshake)
                .expect("complete Gate stdout write");
            assert_eq!(success.bytes, handshake);
            assert_eq!(success.flushes, 1);

            let mut partial = RecordingWriter {
                fail_after: Some(7),
                ..RecordingWriter::default()
            };
            assert!(write_gate_handshake(&mut partial, handshake).is_err());
            assert_eq!(partial.bytes, handshake[..7]);
            assert_eq!(partial.flushes, 0);

            let mut flush_failure = RecordingWriter {
                fail_flush: true,
                ..RecordingWriter::default()
            };
            assert!(
                write_gate_handshake(&mut flush_failure, handshake).is_err()
            );
            assert_eq!(flush_failure.bytes, handshake);
            assert_eq!(flush_failure.flushes, 1);
        }

        #[test]
        fn gate_handshake_writer_rejects_bounds_before_output() {
            for bytes in [
                Vec::new(),
                vec![b'x'; MAX_FINAL_GATE_STDOUT_BYTES + 1],
            ] {
                let mut writer = RecordingWriter::default();
                assert!(write_gate_handshake(&mut writer, &bytes).is_err());
                assert!(writer.bytes.is_empty());
                assert_eq!(writer.flushes, 0);
            }
        }
    }

    fn validate_relative_path(relative: &str, subject: &str) -> TrustResult<()> {
        if relative.is_empty()
            || relative.len() > MAX_RELATIVE_PATH_BYTES
            || relative.starts_with('/')
            || relative.ends_with('/')
            || relative.contains("//")
            || relative.contains('\\')
            || relative.contains(':')
            || relative
                .as_bytes()
                .iter()
                .any(|byte| byte.is_ascii_control())
        {
            return Err(TrustError::new(
                "E_PATH_GRAMMAR",
                format!("{subject}: {relative:?}"),
            ));
        }
        let mut depth = 0usize;
        for component in relative.split('/') {
            depth = depth.checked_add(1).ok_or_else(|| {
                TrustError::new("E_PATH_GRAMMAR", format!("{subject}: depth overflow"))
            })?;
            if component.is_empty()
                || component == "."
                || component == ".."
                || component.len() > MAX_RELATIVE_PATH_COMPONENT_BYTES
            {
                return Err(TrustError::new(
                    "E_PATH_GRAMMAR",
                    format!("{subject}: invalid component"),
                ));
            }
        }
        if depth > MAX_RELATIVE_PATH_DEPTH {
            return Err(TrustError::new(
                "E_PATH_GRAMMAR",
                format!("{subject}: depth {depth}"),
            ));
        }
        Ok(())
    }

    fn precheck_leaf(
        root: &Path,
        relative: &str,
        subject: &str,
    ) -> TrustResult<(PathBuf, Metadata, LinuxFileIdentity)> {
        validate_existing_directory_root(root, "repository root")?;
        validate_relative_path(relative, subject)?;
        let mut current = root.to_path_buf();
        let component_count = relative.split('/').count();
        for (index, component) in relative.split('/').enumerate() {
            current.push(component);
            let metadata = fs::symlink_metadata(&current)
                .map_err(|error| io_error("E_PATH_METADATA", subject, &error))?;
            if metadata.file_type().is_symlink() {
                return Err(TrustError::new(
                    "E_PATH_SYMLINK",
                    format!("{subject}: {relative}"),
                ));
            }
            if index + 1 == component_count {
                if !metadata.is_file() {
                    return Err(TrustError::new(
                        "E_FILE_TYPE",
                        format!("{subject}: regular file required"),
                    ));
                }
                let identity = linux_identity(&metadata, subject)?;
                if identity.link_count != 1 {
                    return Err(TrustError::new(
                        "E_FILE_HARDLINK",
                        format!("{subject}: nlink={}", identity.link_count),
                    ));
                }
                return Ok((current, metadata, identity));
            }
            if !metadata.is_dir() {
                return Err(TrustError::new(
                    "E_PATH_COMPONENT",
                    format!("{subject}: intermediate directory required"),
                ));
            }
        }
        Err(TrustError::new(
            "E_PATH_GRAMMAR",
            format!("{subject}: missing leaf"),
        ))
    }

    fn checked_stream_with_hook<H, F>(
        root: &Path,
        relative: &str,
        maximum_bytes: u64,
        expected: Option<FileBinding>,
        hook: &mut H,
        mut observe: F,
    ) -> TrustResult<CheckedSnapshot>
    where
        H: SnapshotHook,
        F: FnMut(&[u8]) -> TrustResult<()>,
    {
        let subject = relative;
        let (path, pre_metadata, pre_identity) = precheck_leaf(root, relative, subject)?;
        if pre_metadata.len() > maximum_bytes {
            return Err(TrustError::new(
                "E_FILE_BOUND",
                format!("{subject}: {} > {maximum_bytes}", pre_metadata.len()),
            ));
        }
        if expected.is_some_and(|binding| binding.byte_length != pre_metadata.len()) {
            return Err(TrustError::new(
                "E_FILE_LENGTH",
                format!("{subject}: marker length mismatch"),
            ));
        }

        hook.at(SnapshotStage::PreOpen, &path)?;
        let mut file =
            File::open(&path).map_err(|error| io_error("E_FILE_OPEN", subject, &error))?;
        let opened_metadata = file
            .metadata()
            .map_err(|error| io_error("E_FILE_METADATA", subject, &error))?;
        let opened_identity = linux_identity(&opened_metadata, subject)?;
        if opened_identity != pre_identity {
            return Err(TrustError::new(
                "E_FILE_RACE",
                format!("{subject}: pre-open identity changed"),
            ));
        }

        hook.at(SnapshotStage::PostOpenPreRead, &path)?;
        let mut hasher = StreamingSha256::new();
        let mut byte_length = 0u64;
        let mut buffer = [0u8; 16 * 1024];
        loop {
            let read = file
                .read(&mut buffer)
                .map_err(|error| io_error("E_FILE_READ", subject, &error))?;
            if read == 0 {
                break;
            }
            byte_length = byte_length
                .checked_add(u64::try_from(read).map_err(|_| {
                    TrustError::new("E_FILE_LENGTH", format!("{subject}: read length overflow"))
                })?)
                .ok_or_else(|| {
                    TrustError::new("E_FILE_LENGTH", format!("{subject}: length overflow"))
                })?;
            if byte_length > maximum_bytes {
                return Err(TrustError::new(
                    "E_FILE_BOUND",
                    format!("{subject}: stream exceeded {maximum_bytes}"),
                ));
            }
            hasher.update(&buffer[..read])?;
            observe(&buffer[..read])?;
        }
        if byte_length != pre_identity.byte_length {
            return Err(TrustError::new(
                "E_FILE_RACE",
                format!("{subject}: length changed during read"),
            ));
        }
        let digest = hasher.finalize()?;

        let after_handle_metadata = file
            .metadata()
            .map_err(|error| io_error("E_FILE_METADATA", subject, &error))?;
        let after_handle_identity = linux_identity(&after_handle_metadata, subject)?;
        if after_handle_identity != pre_identity {
            return Err(TrustError::new(
                "E_FILE_RACE",
                format!("{subject}: opened handle identity changed"),
            ));
        }
        hook.at(SnapshotStage::PostReadPreFinalMetadata, &path)?;
        let (post_path, _post_metadata, post_identity) = precheck_leaf(root, relative, subject)?;
        if post_path != path || post_identity != pre_identity {
            return Err(TrustError::new(
                "E_FILE_RACE",
                format!("{subject}: post-read path identity changed"),
            ));
        }
        if let Some(binding) = expected {
            if digest != binding.sha256 {
                return Err(TrustError::new(
                    "E_FILE_DIGEST",
                    format!("{subject}: marker digest mismatch"),
                ));
            }
        }
        Ok(CheckedSnapshot {
            logical_path: relative.to_owned(),
            byte_length,
            sha256: digest,
            identity: pre_identity,
        })
    }

    pub fn checked_snapshot(
        root: &Path,
        relative: &str,
        maximum_bytes: u64,
        expected: Option<FileBinding>,
    ) -> TrustResult<CheckedSnapshot> {
        let mut hook = NoopSnapshotHook;
        checked_stream_with_hook(
            root,
            relative,
            maximum_bytes,
            expected,
            &mut hook,
            |_| Ok(()),
        )
    }

    pub fn checked_snapshot_with_hook<H>(
        root: &Path,
        relative: &str,
        maximum_bytes: u64,
        expected: Option<FileBinding>,
        hook: &mut H,
    ) -> TrustResult<CheckedSnapshot>
    where
        H: SnapshotHook,
    {
        checked_stream_with_hook(
            root,
            relative,
            maximum_bytes,
            expected,
            hook,
            |_| Ok(()),
        )
    }

    pub fn checked_read(
        root: &Path,
        relative: &str,
        maximum_bytes: u64,
        expected: Option<FileBinding>,
    ) -> TrustResult<(CheckedSnapshot, Vec<u8>)> {
        let mut bytes = Vec::new();
        let mut hook = NoopSnapshotHook;
        let snapshot = checked_stream_with_hook(
            root,
            relative,
            maximum_bytes,
            expected,
            &mut hook,
            |chunk| {
                bytes.try_reserve(chunk.len()).map_err(|_| {
                    TrustError::new("E_FILE_ALLOCATION", format!("{relative}: allocation failed"))
                })?;
                bytes.extend_from_slice(chunk);
                Ok(())
            },
        )?;
        Ok((snapshot, bytes))
    }

    struct BinaryCursor<'a> {
        bytes: &'a [u8],
        offset: usize,
        subject: &'a str,
    }

    impl<'a> BinaryCursor<'a> {
        fn new(bytes: &'a [u8], subject: &'a str) -> Self {
            Self {
                bytes,
                offset: 0,
                subject,
            }
        }

        fn position(&self) -> usize {
            self.offset
        }

        fn remaining(&self) -> usize {
            self.bytes.len().saturating_sub(self.offset)
        }

        fn exact(&mut self, length: usize) -> TrustResult<&'a [u8]> {
            let end = self.offset.checked_add(length).ok_or_else(|| {
                TrustError::new(
                    "E_BINARY_BOUND",
                    format!("{}: offset overflow", self.subject),
                )
            })?;
            let value = self.bytes.get(self.offset..end).ok_or_else(|| {
                TrustError::new(
                    "E_BINARY_TRUNCATED",
                    format!("{}: need {length} bytes", self.subject),
                )
            })?;
            self.offset = end;
            Ok(value)
        }

        fn byte(&mut self) -> TrustResult<u8> {
            Ok(self.exact(1)?[0])
        }

        fn u32(&mut self) -> TrustResult<u32> {
            let bytes: [u8; 4] = self.exact(4)?.try_into().map_err(|_| {
                TrustError::new("E_BINARY_INTERNAL", self.subject)
            })?;
            Ok(u32::from_be_bytes(bytes))
        }

        fn u64(&mut self) -> TrustResult<u64> {
            let bytes: [u8; 8] = self.exact(8)?.try_into().map_err(|_| {
                TrustError::new("E_BINARY_INTERNAL", self.subject)
            })?;
            Ok(u64::from_be_bytes(bytes))
        }

        fn i32(&mut self) -> TrustResult<i32> {
            let bytes: [u8; 4] = self.exact(4)?.try_into().map_err(|_| {
                TrustError::new("E_BINARY_INTERNAL", self.subject)
            })?;
            Ok(i32::from_be_bytes(bytes))
        }

        fn i64(&mut self) -> TrustResult<i64> {
            let bytes: [u8; 8] = self.exact(8)?.try_into().map_err(|_| {
                TrustError::new("E_BINARY_INTERNAL", self.subject)
            })?;
            Ok(i64::from_be_bytes(bytes))
        }

        fn u32_slice(&mut self, maximum: usize) -> TrustResult<&'a [u8]> {
            let length = usize::try_from(self.u32()?).map_err(|_| {
                TrustError::new("E_BINARY_BOUND", self.subject)
            })?;
            if length > maximum {
                return Err(TrustError::new(
                    "E_BINARY_BOUND",
                    format!("{}: {length} > {maximum}", self.subject),
                ));
            }
            self.exact(length)
        }

        fn u32_bytes(&mut self, maximum: usize) -> TrustResult<Vec<u8>> {
            Ok(self.u32_slice(maximum)?.to_vec())
        }

        fn u64_bytes(&mut self, maximum: u64) -> TrustResult<Vec<u8>> {
            Ok(self.u64_slice(maximum)?.to_vec())
        }

        fn u64_slice(&mut self, maximum: u64) -> TrustResult<&'a [u8]> {
            let length = self.u64()?;
            if length > maximum {
                return Err(TrustError::new(
                    "E_BINARY_BOUND",
                    format!("{}: {length} > {maximum}", self.subject),
                ));
            }
            let length = usize::try_from(length).map_err(|_| {
                TrustError::new("E_BINARY_BOUND", self.subject)
            })?;
            self.exact(length)
        }

        fn utf8(&mut self, maximum: usize) -> TrustResult<String> {
            let bytes = self.u32_bytes(maximum)?;
            if bytes.contains(&0) {
                return Err(TrustError::new(
                    "E_BINARY_STRING",
                    format!("{}: NUL is forbidden", self.subject),
                ));
            }
            String::from_utf8(bytes).map_err(|_| {
                TrustError::new(
                    "E_BINARY_STRING",
                    format!("{}: UTF-8 required", self.subject),
                )
            })
        }

        fn finish(self) -> TrustResult<()> {
            if self.offset != self.bytes.len() {
                return Err(TrustError::new(
                    "E_BINARY_TRAILING",
                    format!("{}: {} trailing bytes", self.subject, self.remaining()),
                ));
            }
            Ok(())
        }
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct OuterTransportRecord {
        pub argv: Vec<Vec<u8>>,
        pub assignments: Vec<(Vec<u8>, Vec<u8>)>,
        pub exit_code: i32,
        pub stdout: Vec<u8>,
        pub stderr: Vec<u8>,
        pub final_argv: Vec<Vec<u8>>,
        pub rustc_cfg: Vec<(Vec<u8>, Option<Vec<u8>>)>,
        pub lifecycle: CanonicalRecord,
    }

    fn validate_rustc_cfg_row(
        key: &[u8],
        value: Option<&[u8]>,
        subject: &str,
    ) -> TrustResult<()> {
        if key.is_empty()
            || key.len() > MAX_OUTER_CFG_KEY_BYTES
            || key.iter().any(|byte| {
                !byte.is_ascii_lowercase()
                    && !byte.is_ascii_digit()
                    && *byte != b'_'
            })
            || value.is_some_and(|value| {
                value.len() > MAX_OUTER_CFG_VALUE_BYTES
                    || value.iter().any(|byte| {
                        *byte == b'"'
                            || *byte == b'\\'
                            || byte.is_ascii_control()
                    })
            })
        {
            return Err(TrustError::new(
                "E_OUTER_CFG",
                format!("{subject}: noncanonical rustc cfg row"),
            ));
        }
        Ok(())
    }

    fn parse_bounded_byte_vector(
        cursor: &mut BinaryCursor<'_>,
        count_maximum: usize,
        item_maximum: usize,
    ) -> TrustResult<Vec<Vec<u8>>> {
        let count = usize::try_from(cursor.u32()?).map_err(|_| {
            TrustError::new("E_OUTER_BOUND", cursor.subject)
        })?;
        if count > count_maximum {
            return Err(TrustError::new(
                "E_OUTER_BOUND",
                format!("{}: item count {count}", cursor.subject),
            ));
        }
        let mut values = Vec::new();
        values.try_reserve_exact(count).map_err(|_| {
            TrustError::new("E_OUTER_ALLOCATION", cursor.subject)
        })?;
        for _ in 0..count {
            values.push(cursor.u32_bytes(item_maximum)?);
        }
        Ok(values)
    }

    pub fn parse_outer_transport_record(
        bytes: &[u8],
        subject: &str,
    ) -> TrustResult<OuterTransportRecord> {
        if bytes.is_empty()
            || u64::try_from(bytes.len()).unwrap_or(u64::MAX)
                > MAX_OUTER_TRANSPORT_RECORD_BYTES
        {
            return Err(TrustError::new("E_OUTER_BOUND", subject));
        }
        let mut cursor = BinaryCursor::new(bytes, subject);
        if cursor.exact(b"FND01OUTERv2\0".len())? != b"FND01OUTERv2\0" {
            return Err(TrustError::new("E_OUTER_FORMAT", subject));
        }
        let argv = parse_bounded_byte_vector(
            &mut cursor,
            MAX_OUTER_ARGV_ITEMS,
            MAX_OUTER_ARGUMENT_BYTES,
        )?;
        let assignment_count = usize::try_from(cursor.u32()?).map_err(|_| {
            TrustError::new("E_OUTER_BOUND", subject)
        })?;
        if assignment_count > MAX_OUTER_ASSIGNMENTS {
            return Err(TrustError::new("E_OUTER_BOUND", subject));
        }
        let mut assignments = Vec::new();
        assignments.try_reserve_exact(assignment_count).map_err(|_| {
            TrustError::new("E_OUTER_ALLOCATION", subject)
        })?;
        for _ in 0..assignment_count {
            let key = cursor.u32_bytes(MAX_OUTER_ASSIGNMENT_KEY_BYTES)?;
            let value =
                cursor.u32_bytes(MAX_OUTER_ASSIGNMENT_VALUE_BYTES)?;
            if key.is_empty()
                || key.contains(&0)
                || key.iter().any(|byte| {
                    !byte.is_ascii_uppercase()
                        && !byte.is_ascii_digit()
                        && *byte != b'_'
                })
                || value.contains(&0)
            {
                return Err(TrustError::new("E_OUTER_ASSIGNMENT", subject));
            }
            assignments.push((key, value));
        }
        if assignments
            .windows(2)
            .any(|pair| pair[0].0 >= pair[1].0)
        {
            return Err(TrustError::new("E_OUTER_ASSIGNMENT_ORDER", subject));
        }
        let exit_code = cursor.i32()?;
        let stdout = cursor.u64_bytes(MAX_OUTER_STREAM_BYTES)?;
        let stderr = cursor.u64_bytes(MAX_OUTER_STREAM_BYTES)?;
        let final_argv = parse_bounded_byte_vector(
            &mut cursor,
            MAX_OUTER_FINAL_ARGV_ITEMS,
            MAX_OUTER_ARGUMENT_BYTES,
        )?;
        let cfg_count = usize::try_from(cursor.u32()?).map_err(|_| {
            TrustError::new("E_OUTER_BOUND", subject)
        })?;
        if cfg_count > MAX_OUTER_CFG_ENTRIES {
            return Err(TrustError::new("E_OUTER_BOUND", subject));
        }
        let mut rustc_cfg = Vec::new();
        let mut cfg_bytes = 4usize;
        rustc_cfg.try_reserve_exact(cfg_count).map_err(|_| {
            TrustError::new("E_OUTER_ALLOCATION", subject)
        })?;
        for _ in 0..cfg_count {
            let key = cursor.u32_slice(MAX_OUTER_CFG_KEY_BYTES)?;
            let value = match cursor.byte()? {
                0 => None,
                1 => Some(cursor.u32_slice(MAX_OUTER_CFG_VALUE_BYTES)?),
                _ => return Err(TrustError::new("E_OUTER_CFG_TAG", subject)),
            };
            cfg_bytes = cfg_bytes
                .checked_add(4)
                .and_then(|total| total.checked_add(key.len()))
                .and_then(|total| total.checked_add(1))
                .and_then(|total| {
                    value.map_or(Some(total), |bytes| {
                        total
                            .checked_add(4)
                            .and_then(|next| next.checked_add(bytes.len()))
                    })
                })
                .ok_or_else(|| TrustError::new("E_OUTER_BOUND", subject))?;
            if cfg_bytes > MAX_OUTER_CFG_BYTES {
                return Err(TrustError::new("E_OUTER_BOUND", subject));
            }
            validate_rustc_cfg_row(key, value, subject)?;
            rustc_cfg.push((key.to_vec(), value.map(|bytes| bytes.to_vec())));
        }
        if rustc_cfg.windows(2).any(|pair| pair[0] >= pair[1]) {
            return Err(TrustError::new("E_OUTER_CFG_ORDER", subject));
        }
        let lifecycle = {
            let lifecycle_bytes =
                cursor.u64_slice(MAX_OUTER_TRANSPORT_RECORD_BYTES)?;
            if lifecycle_bytes.is_empty() {
                return Err(TrustError::new(
                    "E_OUTER_LIFECYCLE",
                    format!("{subject}: empty lifecycle tail"),
                ));
            }
            let mut lifecycle_cursor =
                BinaryCursor::new(lifecycle_bytes, "outer lifecycle");
            let lifecycle =
                parse_tagged_record(&mut lifecycle_cursor, "outer-lifecycle", 0)?;
            lifecycle_cursor.finish()?;
            lifecycle
        };
        cursor.finish()?;
        Ok(OuterTransportRecord {
            argv,
            assignments,
            exit_code,
            stdout,
            stderr,
            final_argv,
            rustc_cfg,
            lifecycle,
        })
    }

    fn append_outer_byte_vector(
        output: &mut Vec<u8>,
        values: &[Vec<u8>],
        count_maximum: usize,
        item_maximum: usize,
        subject: &str,
    ) -> TrustResult<()> {
        if values.len() > count_maximum {
            return Err(TrustError::new("E_OUTER_BOUND", subject));
        }
        append_u32_length(output, values.len(), subject)?;
        for value in values {
            if value.len() > item_maximum {
                return Err(TrustError::new("E_OUTER_BOUND", subject));
            }
            append_u32_length(output, value.len(), subject)?;
            output.extend_from_slice(value);
        }
        Ok(())
    }

    pub fn encode_outer_transport_record(
        record: &OuterTransportRecord,
        subject: &str,
    ) -> TrustResult<Vec<u8>> {
        let mut output = b"FND01OUTERv2\0".to_vec();
        append_outer_byte_vector(
            &mut output,
            &record.argv,
            MAX_OUTER_ARGV_ITEMS,
            MAX_OUTER_ARGUMENT_BYTES,
            subject,
        )?;
        if record.assignments.len() > MAX_OUTER_ASSIGNMENTS
            || record.assignments.windows(2).any(|pair| pair[0].0 >= pair[1].0)
        {
            return Err(TrustError::new("E_OUTER_ASSIGNMENT_ORDER", subject));
        }
        append_u32_length(&mut output, record.assignments.len(), subject)?;
        for (key, value) in &record.assignments {
            if key.is_empty()
                || key.len() > MAX_OUTER_ASSIGNMENT_KEY_BYTES
                || value.len() > MAX_OUTER_ASSIGNMENT_VALUE_BYTES
                || key.iter().any(|byte| {
                    !byte.is_ascii_uppercase()
                        && !byte.is_ascii_digit()
                        && *byte != b'_'
                })
                || value.contains(&0)
            {
                return Err(TrustError::new("E_OUTER_ASSIGNMENT", subject));
            }
            append_u32_length(&mut output, key.len(), subject)?;
            output.extend_from_slice(key);
            append_u32_length(&mut output, value.len(), subject)?;
            output.extend_from_slice(value);
        }
        output.extend_from_slice(&record.exit_code.to_be_bytes());
        for stream in [&record.stdout, &record.stderr] {
            if u64::try_from(stream.len()).unwrap_or(u64::MAX)
                > MAX_OUTER_STREAM_BYTES
            {
                return Err(TrustError::new("E_OUTER_BOUND", subject));
            }
            let length = u64::try_from(stream.len())
                .map_err(|_| TrustError::new("E_OUTER_BOUND", subject))?;
            output.extend_from_slice(&length.to_be_bytes());
            output.extend_from_slice(stream);
        }
        append_outer_byte_vector(
            &mut output,
            &record.final_argv,
            MAX_OUTER_FINAL_ARGV_ITEMS,
            MAX_OUTER_ARGUMENT_BYTES,
            subject,
        )?;
        if record.rustc_cfg.len() > MAX_OUTER_CFG_ENTRIES
            || record.rustc_cfg.windows(2).any(|pair| pair[0] >= pair[1])
        {
            return Err(TrustError::new("E_OUTER_CFG_ORDER", subject));
        }
        let cfg_start = output.len();
        append_u32_length(&mut output, record.rustc_cfg.len(), subject)?;
        for (key, value) in &record.rustc_cfg {
            validate_rustc_cfg_row(key, value.as_deref(), subject)?;
            append_u32_length(&mut output, key.len(), subject)?;
            output.extend_from_slice(key);
            output.push(u8::from(value.is_some()));
            if let Some(value) = value {
                append_u32_length(&mut output, value.len(), subject)?;
                output.extend_from_slice(value);
            }
        }
        if output.len().saturating_sub(cfg_start) > MAX_OUTER_CFG_BYTES {
            return Err(TrustError::new("E_OUTER_BOUND", subject));
        }
        let lifecycle = encode_canonical_record(&record.lifecycle, subject)?;
        if lifecycle.is_empty() {
            return Err(TrustError::new("E_OUTER_LIFECYCLE", subject));
        }
        let lifecycle_length = u64::try_from(lifecycle.len())
            .map_err(|_| TrustError::new("E_OUTER_BOUND", subject))?;
        output.extend_from_slice(&lifecycle_length.to_be_bytes());
        output.extend_from_slice(&lifecycle);
        if u64::try_from(output.len()).unwrap_or(u64::MAX)
            > MAX_OUTER_TRANSPORT_RECORD_BYTES
        {
            return Err(TrustError::new("E_OUTER_BOUND", subject));
        }
        let parsed = parse_outer_transport_record(&output, subject)?;
        if parsed.argv != record.argv
            || parsed.assignments != record.assignments
            || parsed.exit_code != record.exit_code
            || parsed.stdout != record.stdout
            || parsed.stderr != record.stderr
            || parsed.final_argv != record.final_argv
            || parsed.rustc_cfg != record.rustc_cfg
            || !canonical_record_semantic_eq(
                &parsed.lifecycle,
                &record.lifecycle,
            )
        {
            return Err(TrustError::new("E_OUTER_ROUND_TRIP", subject));
        }
        Ok(output)
    }

    pub fn integration_seal_marker(seal: &IntegrationSeal) -> String {
        let mut fields = vec![
            "FND01INTEGRATIONv1".to_owned(),
            encode_lower_hex(&seal.run_id),
        ];
        for binding in seal.records {
            fields.push(binding.byte_length.to_string());
            fields.push(encode_lower_hex(&binding.sha256));
        }
        fields.push(seal.outer_transport.byte_length.to_string());
        fields.push(encode_lower_hex(&seal.outer_transport.sha256));
        fields.push(encode_lower_hex(&seal.authoring_closure_sha256));
        fields.push(encode_lower_hex(&seal.seal_sha256));
        fields.join(":")
    }

    fn expected_outer_shell(
        mode: BootstrapMode,
        run_id: &str,
        authoring_marker: &str,
        integration_marker: Option<&str>,
    ) -> TrustResult<String> {
        let prefix = format!(
            "fnd01_tool_bin=\"$(rustup run nightly-2026-07-11 rustc --print sysroot)/bin\" && \
             rustup run nightly-2026-07-11 rustc \
             crates/fastmcp/tests/fnd_01_dependency_evidence.rs --edition=2024 \
             --cfg fnd01_bootstrap -o target/debug/fnd-01/{run_id}/bootstrap && \
             /usr/bin/env -i FASTMCP_FND01_AUTHORING_CLOSURE={authoring_marker} "
        );
        let role = match mode {
            BootstrapMode::Produce => {
                format!("FASTMCP_FND01_RUN_ID={run_id} ")
            }
            BootstrapMode::Attest => {
                let integration_marker = integration_marker.ok_or_else(|| {
                    TrustError::new(
                        "E_OUTER_ROLE",
                        "attester integration marker required",
                    )
                })?;
                format!(
                    "FASTMCP_FND01_INTEGRATION_SEAL={integration_marker} \
                     FASTMCP_FND01_PRODUCER_OUTER_RECORD_PATH=.fnd01-run/controller/{run_id}/producer-outer.bin \
                     FASTMCP_FND01_RUN_ID={run_id} "
                )
            }
            BootstrapMode::Gate => {
                return Err(TrustError::new(
                    "E_OUTER_ROLE",
                    "gate has no bootstrap compile shell",
                ));
            }
        };
        let invocation = match mode {
            BootstrapMode::Produce => format!(
                "target/debug/fnd-01/{run_id}/bootstrap produce . {run_id}"
            ),
            BootstrapMode::Attest => format!(
                "target/debug/fnd-01/{run_id}/bootstrap attest . {run_id} \
                 .fnd01-run/controller/{run_id}/producer-outer.bin"
            ),
            BootstrapMode::Gate => {
                return Err(TrustError::new("E_OUTER_ROLE", "gate bootstrap invocation"));
            }
        };
        Ok(format!(
            "{prefix}{role}LANG=C LC_ALL=C PATH=\"$fnd01_tool_bin:/usr/bin:/bin\" TZ=UTC \
             {invocation} && RUSTUP_TOOLCHAIN=nightly-2026-07-11 rustc --print cfg"
        ))
    }

    fn parse_rustc_cfg_stdout(
        stdout: &[u8],
        subject: &str,
    ) -> TrustResult<Vec<(Vec<u8>, Option<Vec<u8>>)>> {
        if stdout.is_empty()
            || !stdout.ends_with(b"\n")
            || stdout.contains(&0)
            || stdout.contains(&b'\r')
        {
            return Err(TrustError::new(
                "E_OUTER_CFG_STDOUT",
                format!("{subject}: exact LF-terminated rustc cfg output required"),
            ));
        }
        let mut rows = Vec::new();
        for line in stdout[..stdout.len() - 1].split(|byte| *byte == b'\n') {
            if line.is_empty() || line.len() > 4096 {
                return Err(TrustError::new(
                    "E_OUTER_CFG_STDOUT",
                    format!("{subject}: empty or oversized cfg row"),
                ));
            }
            let (key, value) = match line.iter().position(|byte| *byte == b'=') {
                None => (line, None),
                Some(equals) => {
                    let key = &line[..equals];
                    let quoted = &line[equals + 1..];
                    if quoted.len() < 2
                        || quoted.first() != Some(&b'"')
                        || quoted.last() != Some(&b'"')
                        || quoted[1..quoted.len() - 1].iter().any(|byte| {
                            *byte == b'"'
                                || *byte == b'\\'
                                || byte.is_ascii_control()
                        })
                    {
                        return Err(TrustError::new(
                            "E_OUTER_CFG_STDOUT",
                            format!("{subject}: noncanonical cfg value"),
                        ));
                    }
                    (key, Some(quoted[1..quoted.len() - 1].to_vec()))
                }
            };
            validate_rustc_cfg_row(key, value.as_deref(), subject).map_err(
                |_| {
                    TrustError::new(
                        "E_OUTER_CFG_STDOUT",
                        format!("{subject}: noncanonical cfg row"),
                    )
                },
            )?;
            rows.push((key.to_vec(), value));
        }
        if rows.is_empty() || rows.windows(2).any(|pair| pair[0] >= pair[1]) {
            return Err(TrustError::new(
                "E_OUTER_CFG_STDOUT",
                format!("{subject}: cfg rows must be unique and sorted"),
            ));
        }
        Ok(rows)
    }

    pub fn validate_outer_role_record(
        record: &OuterTransportRecord,
        mode: BootstrapMode,
        run_id: &str,
        authoring_marker: &str,
        integration_marker: Option<&str>,
    ) -> TrustResult<ValidatedOuterLifecycle> {
        if record.exit_code != 0 {
            return Err(TrustError::new("E_OUTER_EXIT", "nonzero outer exit"));
        }
        let phase = match mode {
            BootstrapMode::Produce => "producer",
            BootstrapMode::Attest => "attester",
            BootstrapMode::Gate => {
                return Err(TrustError::new(
                    "E_OUTER_ROLE",
                    "gate has no bootstrap outer record",
                ));
            }
        };
        if record.lifecycle.schema_id != "outer-lifecycle"
            || record.lifecycle.string("phase")? != phase
        {
            return Err(TrustError::new(
                "E_OUTER_LIFECYCLE",
                "outer selector and lifecycle phase differ",
            ));
        }
        let controller = validate_controller_rch_binding(
            record.lifecycle.record("controller_rch")?,
        )?;
        let invocation = validate_controller_invocation_plan(
            record.lifecycle.record("controller_invocation")?,
            &controller,
        )?;
        if invocation
            .argv
            .iter()
            .map(|value| value.as_bytes())
            .ne(record.argv.iter().map(Vec::as_slice))
            || invocation
                .controller_environment
                .iter()
                .map(|(key, value)| (key.as_bytes(), value.as_bytes()))
                .ne(record
                    .assignments
                    .iter()
                    .map(|(key, value)| (key.as_slice(), value.as_slice())))
        {
            return Err(TrustError::new(
                "E_OUTER_LIFECYCLE",
                "outer bytes and invocation plan differ",
            ));
        }
        let phase_code = match mode {
            BootstrapMode::Produce => "p",
            BootstrapMode::Attest => "a",
            BootstrapMode::Gate => unreachable!("Gate rejected above"),
        };
        // Short socket path under .fnd01-run/s/ keeps sockaddr_un.sun_path within
        // 104 bytes on macOS (path max 103 + NUL). Long rch-daemon/* paths are
        // evidence-only and must never be used as Unix domain sockets.
        let expected_socket_suffix = format!(
            "/fnd01/{run_id}/s/{phase_code}/rch.sock"
        );
        if !invocation.socket_path.ends_with(&expected_socket_suffix)
        {
            return Err(TrustError::new(
                "E_OUTER_ASSIGNMENT",
                "role-scoped short RCH socket path",
            ));
        }
        let shell =
            expected_outer_shell(mode, run_id, authoring_marker, integration_marker)?;
        let expected_argv = [
            controller.executable.path.as_bytes(),
            b"exec".as_slice(),
            b"--".as_slice(),
            b"sh".as_slice(),
            b"-c".as_slice(),
            shell.as_bytes(),
        ];
        if record
            .argv
            .iter()
            .map(Vec::as_slice)
            .ne(expected_argv)
            || record
                .final_argv
                .iter()
                .map(Vec::as_slice)
                .ne([
                    b"rustc".as_slice(),
                    b"--print".as_slice(),
                    b"cfg".as_slice(),
                ])
            || shell.contains("cargo")
        {
            return Err(TrustError::new("E_OUTER_ARGV", "role outer argv"));
        }
        let expected_remote_environment = match mode {
            BootstrapMode::Produce => vec![
                (
                    AUTHORING_MARKER_ENV.to_owned(),
                    authoring_marker.to_owned(),
                ),
                (RUN_ID_ENV.to_owned(), run_id.to_owned()),
                ("LANG".to_owned(), "C".to_owned()),
                ("LC_ALL".to_owned(), "C".to_owned()),
                (
                    "PATH".to_owned(),
                    "$fnd01_tool_bin:/usr/bin:/bin".to_owned(),
                ),
                ("TZ".to_owned(), "UTC".to_owned()),
            ],
            BootstrapMode::Attest => vec![
                (
                    AUTHORING_MARKER_ENV.to_owned(),
                    authoring_marker.to_owned(),
                ),
                (
                    INTEGRATION_SEAL_ENV.to_owned(),
                    integration_marker
                        .ok_or_else(|| {
                            TrustError::new(
                                "E_OUTER_ROLE",
                                "attester integration marker required",
                            )
                        })?
                        .to_owned(),
                ),
                (
                    PRODUCER_OUTER_RECORD_PATH_ENV.to_owned(),
                    format!(
                        ".fnd01-run/controller/{run_id}/producer-outer.bin"
                    ),
                ),
                (RUN_ID_ENV.to_owned(), run_id.to_owned()),
                ("LANG".to_owned(), "C".to_owned()),
                ("LC_ALL".to_owned(), "C".to_owned()),
                (
                    "PATH".to_owned(),
                    "$fnd01_tool_bin:/usr/bin:/bin".to_owned(),
                ),
                ("TZ".to_owned(), "UTC".to_owned()),
            ],
            BootstrapMode::Gate => unreachable!("Gate rejected above"),
        };
        if invocation.remote_environment != expected_remote_environment {
            return Err(TrustError::new(
                "E_OUTER_ENVIRONMENT",
                "role remote environment plan",
            ));
        }
        let daemon_pre = validate_rch_daemon_pre(
            record.lifecycle.record("daemon_pre")?,
            phase,
            run_id,
            &controller,
            &invocation,
        )?;
        let daemon_post = validate_rch_daemon_post(
            record.lifecycle.record("daemon_post")?,
            &daemon_pre,
            &controller,
        )?;
        if parse_rustc_cfg_stdout(&record.stdout, "outer stdout")?
            != record.rustc_cfg
        {
            return Err(TrustError::new(
                "E_OUTER_CFG_STDOUT",
                "parsed cfg rows do not derive from raw outer stdout",
            ));
        }
        let target_os = record
            .rustc_cfg
            .iter()
            .filter(|(key, _)| key.as_slice() == b"target_os")
            .collect::<Vec<_>>();
        let target_arch = record
            .rustc_cfg
            .iter()
            .filter(|(key, _)| key.as_slice() == b"target_arch")
            .collect::<Vec<_>>();
        if target_os.len() != 1
            || target_arch.len() != 1
            || target_os[0].1.as_deref() != Some(b"linux".as_slice())
            || target_arch[0].1.as_deref() != Some(b"x86_64".as_slice())
        {
            return Err(TrustError::new(
                "E_OUTER_PLATFORM",
                "Linux x86_64 rustc cfg required",
            ));
        }
        Ok(ValidatedOuterLifecycle {
            phase: phase.to_owned(),
            controller,
            invocation,
            daemon_pre,
            daemon_post,
        })
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub enum CanonicalValue {
        String(String),
        Unsigned(u64),
        Signed(i64),
        Boolean(bool),
        RawBytes(Vec<u8>),
        StringArray(Vec<String>),
        EnvironmentPairs(Vec<(String, String)>),
        Record(Box<CanonicalRecord>),
        RecordArray(Vec<CanonicalRecord>),
        OptionalString(Option<String>),
        OptionalUnsigned(Option<u64>),
        OptionalBoolean(Option<bool>),
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct CanonicalRecord {
        pub schema_id: &'static str,
        pub fields: Vec<CanonicalValue>,
        pub field_offsets: Vec<usize>,
    }

    struct CanonicalSchema {
        id: &'static str,
        fields: &'static [&'static str],
        mask: &'static str,
    }

