    fn canonical_schema(id: &str) -> TrustResult<CanonicalSchema> {
        let schema = match id {
            "file-binding" => CanonicalSchema {
                id: "file-binding",
                fields: FILE_BINDING_FIELDS,
                mask: "sus",
            },
            "directory-tree-binding" => CanonicalSchema {
                id: "directory-tree-binding",
                fields: DIRECTORY_TREE_BINDING_FIELDS,
                mask: "ssuuuuuus",
            },
            "producer-outer-record-file-binding" => CanonicalSchema {
                id: "producer-outer-record-file-binding",
                fields: OUTER_BINDING_FIELDS,
                mask: "susss",
            },
            "attester-outer-record-file-binding" => CanonicalSchema {
                id: "attester-outer-record-file-binding",
                fields: OUTER_BINDING_FIELDS,
                mask: "susss",
            },
            "controller-rch-binding" => CanonicalSchema {
                id: "controller-rch-binding",
                fields: CONTROLLER_RCH_FIELDS,
                mask: "rssbbb",
            },
            "unix-file-identity" => CanonicalSchema {
                id: "unix-file-identity",
                fields: UNIX_FILE_IDENTITY_FIELDS,
                mask: "suuuuuuuuus",
            },
            "unix-directory-identity" => CanonicalSchema {
                id: "unix-directory-identity",
                fields: UNIX_NODE_IDENTITY_FIELDS,
                mask: "suuuuuuuu",
            },
            "unix-socket-identity" => CanonicalSchema {
                id: "unix-socket-identity",
                fields: UNIX_NODE_IDENTITY_FIELDS,
                mask: "suuuuuuuu",
            },
            "rch-status-observation" => CanonicalSchema {
                id: "rch-status-observation",
                fields: RCH_STATUS_FIELDS,
                mask: "aeirrbsu",
            },
            "rch-daemon-pre" => CanonicalSchema {
                id: "rch-daemon-pre",
                fields: RCH_DAEMON_PRE_FIELDS,
                mask: "srraebrbsbsbsburrs",
            },
            "rch-daemon-post" => CanonicalSchema {
                id: "rch-daemon-post",
                fields: RCH_DAEMON_POST_FIELDS,
                mask: "srrrrubsbbbrrrs",
            },
            "outer-lifecycle" => CanonicalSchema {
                id: "outer-lifecycle",
                fields: OUTER_LIFECYCLE_FIELDS,
                mask: "srrrr",
            },
            "controller-invocation-plan" => CanonicalSchema {
                id: "controller-invocation-plan",
                fields: CONTROLLER_INVOCATION_FIELDS,
                mask: "reaessuS",
            },
            "cargo-compiler-artifact" => CanonicalSchema {
                id: "cargo-compiler-artifact",
                fields: COMPILER_ARTIFACT_FIELDS,
                mask: "ssssaassabbas",
            },
            "cargo-build-finished" => CanonicalSchema {
                id: "cargo-build-finished",
                fields: BUILD_FINISHED_FIELDS,
                mask: "sbu",
            },
            "target-snapshot" => CanonicalSchema {
                id: "target-snapshot",
                fields: TARGET_SNAPSHOT_FIELDS,
                mask: "suus",
            },
            "raw-stream-blob" => CanonicalSchema {
                id: "raw-stream-blob",
                fields: RAW_STREAM_FIELDS,
                mask: "usx",
            },
            "optional-file-binding" => CanonicalSchema {
                id: "optional-file-binding",
                fields: OPTIONAL_FILE_BINDING_FIELDS,
                mask: "bSUS",
            },
            "control-ledger" => CanonicalSchema {
                id: "control-ledger",
                fields: CONTROL_LEDGER_FIELDS,
                mask: "sussussuqrrssaesirrusrrrraers",
            },
            "acquisition-spool-command" => CanonicalSchema {
                id: "acquisition-spool-command",
                fields: ACQUISITION_COMMAND_FIELDS,
                mask: "suaesirrsss",
            },
            "acquisition-spool" => CanonicalSchema {
                id: "acquisition-spool",
                fields: ACQUISITION_SPOOL_FIELDS,
                mask: "sussuqrs",
            },
            "final-gate-input" => CanonicalSchema {
                id: "final-gate-input",
                fields: FINAL_GATE_INPUT_FIELDS,
                mask: "susrrrraserrsss",
            },
            "gate-worker-observation" => CanonicalSchema {
                id: "gate-worker-observation",
                fields: GATE_WORKER_FIELDS,
                mask: "ssssssuuss",
            },
            "gate-input-recheck" => CanonicalSchema {
                id: "gate-input-recheck",
                fields: GATE_INPUT_RECHECK_FIELDS,
                mask: "srrb",
            },
            "gate-fallback-residue" => CanonicalSchema {
                id: "gate-fallback-residue",
                fields: GATE_FALLBACK_RESIDUE_FIELDS,
                mask: "ssssUSb",
            },
            "final-gate-result" => CanonicalSchema {
                id: "final-gate-result",
                fields: FINAL_GATE_RESULT_FIELDS,
                mask: "sussrirrruquqss",
            },
            _ => {
                return Err(TrustError::new(
                    "E_RECORD_SCHEMA",
                    format!("unknown canonical schema {id:?}"),
                ));
            }
        };
        if schema.fields.len() != schema.mask.len() {
            return Err(TrustError::new(
                "E_RECORD_SCHEMA",
                format!("{} field/type cardinality mismatch", schema.id),
            ));
        }
        Ok(schema)
    }

    fn child_schema(parent: &str, ordinal: usize) -> Option<&'static str> {
        match (parent, ordinal) {
            ("controller-rch-binding", 0) => Some("unix-file-identity"),
            ("controller-invocation-plan", 0) => {
                Some("unix-file-identity")
            }
            ("rch-status-observation", 3 | 4) => Some("raw-stream-blob"),
            ("rch-daemon-pre", 1 | 2) => Some("unix-file-identity"),
            ("rch-daemon-pre", 6) => Some("unix-directory-identity"),
            ("rch-daemon-pre", 15) => Some("unix-socket-identity"),
            ("rch-daemon-pre", 16) => Some("rch-status-observation"),
            ("rch-daemon-post", 1 | 11 | 12 | 13) => {
                Some("unix-file-identity")
            }
            ("rch-daemon-post", 2) => Some("unix-directory-identity"),
            ("rch-daemon-post", 3) => Some("unix-socket-identity"),
            ("rch-daemon-post", 4) => Some("rch-status-observation"),
            ("outer-lifecycle", 1) => Some("controller-rch-binding"),
            ("outer-lifecycle", 2) => Some("controller-invocation-plan"),
            ("outer-lifecycle", 3) => Some("rch-daemon-pre"),
            ("outer-lifecycle", 4) => Some("rch-daemon-post"),
            ("control-ledger", 8) => Some("file-binding"),
            ("control-ledger", 9) => Some("directory-tree-binding"),
            ("control-ledger", 10 | 24) => Some("file-binding"),
            ("control-ledger", 17 | 18) => Some("raw-stream-blob"),
            ("control-ledger", 21) => Some("cargo-compiler-artifact"),
            ("control-ledger", 22) => Some("cargo-build-finished"),
            ("control-ledger", 23) => Some("target-snapshot"),
            ("control-ledger", 27) => Some("optional-file-binding"),
            ("acquisition-spool-command", 6 | 7) => Some("raw-stream-blob"),
            ("acquisition-spool", 5) => Some("acquisition-spool-command"),
            ("acquisition-spool", 6) => Some("file-binding"),
            ("final-gate-input", 3) => Some("controller-rch-binding"),
            ("final-gate-input", 4) => Some("controller-invocation-plan"),
            ("final-gate-input", 5) => Some("rch-daemon-pre"),
            ("final-gate-input", 6 | 10) => Some("file-binding"),
            ("final-gate-input", 11) => {
                Some("attester-outer-record-file-binding")
            }
            ("final-gate-result", 4) => Some("gate-worker-observation"),
            ("final-gate-result", 6 | 7) => Some("raw-stream-blob"),
            ("final-gate-result", 8) => Some("rch-daemon-post"),
            ("final-gate-result", 10) => Some("gate-input-recheck"),
            ("final-gate-result", 12) => Some("gate-fallback-residue"),
            ("gate-input-recheck", 1 | 2) => Some("file-binding"),
            _ => None,
        }
    }

    fn parse_tagged_string_with_maximum(
        cursor: &mut BinaryCursor<'_>,
        maximum: usize,
    ) -> TrustResult<String> {
        if cursor.byte()? != 0x01 {
            return Err(TrustError::new("E_RECORD_TAG", cursor.subject));
        }
        cursor.utf8(maximum)
    }

    fn parse_tagged_string(cursor: &mut BinaryCursor<'_>) -> TrustResult<String> {
        parse_tagged_string_with_maximum(cursor, 1024 * 1024)
    }

    fn parse_tagged_unsigned(cursor: &mut BinaryCursor<'_>) -> TrustResult<u64> {
        if cursor.byte()? != 0x02 {
            return Err(TrustError::new("E_RECORD_TAG", cursor.subject));
        }
        cursor.u64()
    }

    fn parse_tagged_signed(cursor: &mut BinaryCursor<'_>) -> TrustResult<i64> {
        if cursor.byte()? != 0x0a {
            return Err(TrustError::new("E_RECORD_TAG", cursor.subject));
        }
        cursor.i64()
    }

    fn parse_tagged_boolean(cursor: &mut BinaryCursor<'_>) -> TrustResult<bool> {
        if cursor.byte()? != 0x03 {
            return Err(TrustError::new("E_RECORD_TAG", cursor.subject));
        }
        match cursor.byte()? {
            0 => Ok(false),
            1 => Ok(true),
            _ => Err(TrustError::new("E_RECORD_BOOLEAN", cursor.subject)),
        }
    }

    fn parse_tagged_string_array(
        cursor: &mut BinaryCursor<'_>,
    ) -> TrustResult<Vec<String>> {
        if cursor.byte()? != 0x05 {
            return Err(TrustError::new("E_RECORD_TAG", cursor.subject));
        }
        let count = usize::try_from(cursor.u32()?).map_err(|_| {
            TrustError::new("E_RECORD_BOUND", cursor.subject)
        })?;
        if count > 1_000_000 {
            return Err(TrustError::new("E_RECORD_BOUND", cursor.subject));
        }
        let mut values = Vec::new();
        values.try_reserve_exact(count).map_err(|_| {
            TrustError::new("E_RECORD_ALLOCATION", cursor.subject)
        })?;
        for _ in 0..count {
            values.push(parse_tagged_string(cursor)?);
        }
        Ok(values)
    }

    fn parse_tagged_environment(
        cursor: &mut BinaryCursor<'_>,
    ) -> TrustResult<Vec<(String, String)>> {
        if cursor.byte()? != 0x05 {
            return Err(TrustError::new("E_RECORD_TAG", cursor.subject));
        }
        let count = usize::try_from(cursor.u32()?).map_err(|_| {
            TrustError::new("E_RECORD_BOUND", cursor.subject)
        })?;
        if count > 64 {
            return Err(TrustError::new("E_RECORD_BOUND", cursor.subject));
        }
        let mut values = Vec::new();
        for _ in 0..count {
            if cursor.byte()? != 0x05 || cursor.u32()? != 2 {
                return Err(TrustError::new(
                    "E_RECORD_ENVIRONMENT",
                    cursor.subject,
                ));
            }
            let key = parse_tagged_string_with_maximum(cursor, 128)?;
            let value = parse_tagged_string_with_maximum(cursor, 4096)?;
            if key.is_empty()
                || key.len() > 128
                || value.len() > 4096
                || key.contains('=')
                || values.iter().any(|(prior, _)| prior == &key)
            {
                return Err(TrustError::new(
                    "E_RECORD_ENVIRONMENT",
                    cursor.subject,
                ));
            }
            values.push((key, value));
        }
        Ok(values)
    }

    fn parse_tagged_record(
        cursor: &mut BinaryCursor<'_>,
        expected_schema: &str,
        depth: usize,
    ) -> TrustResult<CanonicalRecord> {
        if depth > 32 || cursor.byte()? != 0x06 {
            return Err(TrustError::new("E_RECORD_DEPTH_OR_TAG", cursor.subject));
        }
        let encoded_schema = cursor.utf8(128)?;
        if encoded_schema != expected_schema {
            return Err(TrustError::new(
                "E_RECORD_SCHEMA",
                format!(
                    "{}: expected {expected_schema}, found {encoded_schema}",
                    cursor.subject
                ),
            ));
        }
        let schema = canonical_schema(expected_schema)?;
        let mut fields = Vec::new();
        let mut offsets = Vec::new();
        fields.try_reserve_exact(schema.fields.len()).map_err(|_| {
            TrustError::new("E_RECORD_ALLOCATION", cursor.subject)
        })?;
        offsets.try_reserve_exact(schema.fields.len()).map_err(|_| {
            TrustError::new("E_RECORD_ALLOCATION", cursor.subject)
        })?;
        for (ordinal, kind) in schema.mask.bytes().enumerate() {
            offsets.push(cursor.position());
            let child = child_schema(expected_schema, ordinal);
            let value = match kind {
                b's' => CanonicalValue::String(parse_tagged_string(cursor)?),
                b'u' => {
                    CanonicalValue::Unsigned(parse_tagged_unsigned(cursor)?)
                }
                b'i' => CanonicalValue::Signed(parse_tagged_signed(cursor)?),
                b'b' => {
                    CanonicalValue::Boolean(parse_tagged_boolean(cursor)?)
                }
                b'x' => {
                    if cursor.byte()? != 0x04 {
                        return Err(TrustError::new(
                            "E_RECORD_TAG",
                            cursor.subject,
                        ));
                    }
                    CanonicalValue::RawBytes(
                        cursor.u64_bytes(1024 * 1024 * 1024)?,
                    )
                }
                b'a' => CanonicalValue::StringArray(
                    parse_tagged_string_array(cursor)?,
                ),
                b'e' => CanonicalValue::EnvironmentPairs(
                    parse_tagged_environment(cursor)?,
                ),
                b'r' => CanonicalValue::Record(Box::new(
                    parse_tagged_record(
                        cursor,
                        child.ok_or_else(|| {
                            TrustError::new(
                                "E_RECORD_CHILD",
                                format!("{expected_schema}[{ordinal}]"),
                            )
                        })?,
                        depth + 1,
                    )?,
                )),
                b'q' => {
                    if cursor.byte()? != 0x07 {
                        return Err(TrustError::new(
                            "E_RECORD_TAG",
                            cursor.subject,
                        ));
                    }
                    let count = usize::try_from(cursor.u32()?).map_err(|_| {
                        TrustError::new("E_RECORD_BOUND", cursor.subject)
                    })?;
                    if count > 1_000_000 {
                        return Err(TrustError::new(
                            "E_RECORD_BOUND",
                            cursor.subject,
                        ));
                    }
                    let child = child.ok_or_else(|| {
                        TrustError::new(
                            "E_RECORD_CHILD",
                            format!("{expected_schema}[{ordinal}]"),
                        )
                    })?;
                    let mut records = Vec::new();
                    records.try_reserve_exact(count).map_err(|_| {
                        TrustError::new("E_RECORD_ALLOCATION", cursor.subject)
                    })?;
                    for _ in 0..count {
                        records.push(parse_tagged_record(
                            cursor,
                            child,
                            depth + 1,
                        )?);
                    }
                    CanonicalValue::RecordArray(records)
                }
                b'S' | b'U' | b'B' => {
                    if cursor.byte()? != 0x08 {
                        return Err(TrustError::new(
                            "E_RECORD_TAG",
                            cursor.subject,
                        ));
                    }
                    let present = match cursor.byte()? {
                        0 => false,
                        1 => true,
                        _ => {
                            return Err(TrustError::new(
                                "E_RECORD_OPTION",
                                cursor.subject,
                            ));
                        }
                    };
                    match kind {
                        b'S' => CanonicalValue::OptionalString(
                            present.then(|| parse_tagged_string(cursor)).transpose()?,
                        ),
                        b'U' => CanonicalValue::OptionalUnsigned(
                            present
                                .then(|| parse_tagged_unsigned(cursor))
                                .transpose()?,
                        ),
                        b'B' => CanonicalValue::OptionalBoolean(
                            present
                                .then(|| parse_tagged_boolean(cursor))
                                .transpose()?,
                        ),
                        _ => {
                            return Err(TrustError::new(
                                "E_RECORD_SCHEMA",
                                format!("{expected_schema}: invalid optional type {kind:#x}"),
                            ));
                        }
                    }
                }
                _ => {
                    return Err(TrustError::new(
                        "E_RECORD_SCHEMA",
                        format!("{expected_schema}: unknown type {kind:#x}"),
                    ));
                }
            };
            fields.push(value);
        }
        Ok(CanonicalRecord {
            schema_id: schema.id,
            fields,
            field_offsets: offsets,
        })
    }

    pub fn parse_canonical_record_file(
        bytes: &[u8],
        prefix: &[u8],
        schema: &str,
        maximum: u64,
        subject: &str,
    ) -> TrustResult<CanonicalRecord> {
        if bytes.is_empty()
            || u64::try_from(bytes.len()).unwrap_or(u64::MAX) > maximum
        {
            return Err(TrustError::new("E_RECORD_BOUND", subject));
        }
        let mut cursor = BinaryCursor::new(bytes, subject);
        if cursor.exact(prefix.len())? != prefix {
            return Err(TrustError::new("E_RECORD_FORMAT", subject));
        }
        let record = parse_tagged_record(&mut cursor, schema, 0)?;
        cursor.finish()?;
        Ok(record)
    }

    pub fn parse_canonical_record_file_with_final_self_digest(
        bytes: &[u8],
        prefix: &[u8],
        schema: &str,
        final_self_digest_field: &str,
        maximum: u64,
        subject: &str,
    ) -> TrustResult<CanonicalRecord> {
        let record =
            parse_canonical_record_file(bytes, prefix, schema, maximum, subject)?;
        let digest_index = record.ordinal(final_self_digest_field)?;
        if digest_index.checked_add(1) != Some(record.fields.len()) {
            return Err(TrustError::new(
                "E_RECORD_DIGEST",
                format!(
                    "{subject}: {final_self_digest_field} is not the final field"
                ),
            ));
        }
        let claimed =
            decode_lower_hex::<32>(record.string(final_self_digest_field)?, subject)?;
        let preimage_end = *record
            .field_offsets
            .get(digest_index)
            .ok_or_else(|| TrustError::new("E_RECORD_DIGEST", subject))?;
        if sha256(bytes.get(..preimage_end).ok_or_else(|| {
            TrustError::new("E_RECORD_DIGEST", subject)
        })?)? != claimed
        {
            return Err(TrustError::new("E_RECORD_DIGEST", subject));
        }
        Ok(record)
    }

    fn append_u32_length(
        output: &mut Vec<u8>,
        length: usize,
        subject: &str,
    ) -> TrustResult<()> {
        let length = u32::try_from(length).map_err(|_| {
            TrustError::new("E_RECORD_BOUND", format!("{subject}: u32 length"))
        })?;
        output.extend_from_slice(&length.to_be_bytes());
        Ok(())
    }

    fn append_tagged_string_value(
        output: &mut Vec<u8>,
        value: &str,
        subject: &str,
    ) -> TrustResult<()> {
        if value.len() > 1024 * 1024 || value.as_bytes().contains(&0) {
            return Err(TrustError::new("E_RECORD_BOUND", subject));
        }
        output.push(0x01);
        append_u32_length(output, value.len(), subject)?;
        output.extend_from_slice(value.as_bytes());
        Ok(())
    }

    fn encode_tagged_record_into(
        output: &mut Vec<u8>,
        record: &CanonicalRecord,
        depth: usize,
        subject: &str,
    ) -> TrustResult<()> {
        if depth > 32 {
            return Err(TrustError::new("E_RECORD_DEPTH_OR_TAG", subject));
        }
        let schema = canonical_schema(record.schema_id)?;
        if record.fields.len() != schema.fields.len() {
            return Err(TrustError::new(
                "E_RECORD_SCHEMA",
                format!("{subject}: {} field cardinality", record.schema_id),
            ));
        }
        output.push(0x06);
        append_u32_length(output, record.schema_id.len(), subject)?;
        output.extend_from_slice(record.schema_id.as_bytes());
        for (ordinal, (kind, value)) in schema
            .mask
            .bytes()
            .zip(record.fields.iter())
            .enumerate()
        {
            let child = child_schema(record.schema_id, ordinal);
            match (kind, value) {
                (b's', CanonicalValue::String(value)) => {
                    append_tagged_string_value(output, value, subject)?;
                }
                (b'u', CanonicalValue::Unsigned(value)) => {
                    output.push(0x02);
                    output.extend_from_slice(&value.to_be_bytes());
                }
                (b'i', CanonicalValue::Signed(value)) => {
                    output.push(0x0a);
                    output.extend_from_slice(&value.to_be_bytes());
                }
                (b'b', CanonicalValue::Boolean(value)) => {
                    output.extend_from_slice(&[0x03, u8::from(*value)]);
                }
                (b'x', CanonicalValue::RawBytes(value)) => {
                    let length = u64::try_from(value.len()).map_err(|_| {
                        TrustError::new("E_RECORD_BOUND", subject)
                    })?;
                    if length > 1024 * 1024 * 1024 {
                        return Err(TrustError::new("E_RECORD_BOUND", subject));
                    }
                    output.push(0x04);
                    output.extend_from_slice(&length.to_be_bytes());
                    output.extend_from_slice(value);
                }
                (b'a', CanonicalValue::StringArray(values)) => {
                    if values.len() > 1_000_000 {
                        return Err(TrustError::new("E_RECORD_BOUND", subject));
                    }
                    output.push(0x05);
                    append_u32_length(output, values.len(), subject)?;
                    for value in values {
                        append_tagged_string_value(output, value, subject)?;
                    }
                }
                (b'e', CanonicalValue::EnvironmentPairs(values)) => {
                    if values.len() > 64 {
                        return Err(TrustError::new("E_RECORD_BOUND", subject));
                    }
                    output.push(0x05);
                    append_u32_length(output, values.len(), subject)?;
                    for (index, (key, value)) in values.iter().enumerate() {
                        if key.is_empty()
                            || key.len() > 128
                            || key.contains('=')
                            || value.len() > 4096
                            || values[..index]
                                .iter()
                                .any(|(prior, _)| prior == key)
                        {
                            return Err(TrustError::new(
                                "E_RECORD_ENVIRONMENT",
                                subject,
                            ));
                        }
                        output.push(0x05);
                        output.extend_from_slice(&2_u32.to_be_bytes());
                        append_tagged_string_value(output, key, subject)?;
                        append_tagged_string_value(output, value, subject)?;
                    }
                }
                (b'r', CanonicalValue::Record(value)) => {
                    let expected = child.ok_or_else(|| {
                        TrustError::new(
                            "E_RECORD_CHILD",
                            format!("{}[{ordinal}]", record.schema_id),
                        )
                    })?;
                    if value.schema_id != expected {
                        return Err(TrustError::new(
                            "E_RECORD_CHILD",
                            format!(
                                "{}[{ordinal}]: expected {expected}, found {}",
                                record.schema_id, value.schema_id
                            ),
                        ));
                    }
                    encode_tagged_record_into(output, value, depth + 1, subject)?;
                }
                (b'q', CanonicalValue::RecordArray(values)) => {
                    let expected = child.ok_or_else(|| {
                        TrustError::new(
                            "E_RECORD_CHILD",
                            format!("{}[{ordinal}]", record.schema_id),
                        )
                    })?;
                    if values.len() > 1_000_000 {
                        return Err(TrustError::new("E_RECORD_BOUND", subject));
                    }
                    output.push(0x07);
                    append_u32_length(output, values.len(), subject)?;
                    for value in values {
                        if value.schema_id != expected {
                            return Err(TrustError::new(
                                "E_RECORD_CHILD",
                                format!(
                                    "{}[{ordinal}]: expected {expected}, found {}",
                                    record.schema_id, value.schema_id
                                ),
                            ));
                        }
                        encode_tagged_record_into(
                            output,
                            value,
                            depth + 1,
                            subject,
                        )?;
                    }
                }
                (b'S', CanonicalValue::OptionalString(value)) => {
                    output.extend_from_slice(&[0x08, u8::from(value.is_some())]);
                    if let Some(value) = value {
                        append_tagged_string_value(output, value, subject)?;
                    }
                }
                (b'U', CanonicalValue::OptionalUnsigned(value)) => {
                    output.extend_from_slice(&[0x08, u8::from(value.is_some())]);
                    if let Some(value) = value {
                        output.push(0x02);
                        output.extend_from_slice(&value.to_be_bytes());
                    }
                }
                (b'B', CanonicalValue::OptionalBoolean(value)) => {
                    output.extend_from_slice(&[0x08, u8::from(value.is_some())]);
                    if let Some(value) = value {
                        output.extend_from_slice(&[0x03, u8::from(*value)]);
                    }
                }
                _ => {
                    return Err(TrustError::new(
                        "E_RECORD_TYPE",
                        format!("{}[{ordinal}]", record.schema_id),
                    ));
                }
            }
            if output.len() > 1024 * 1024 * 1024 {
                return Err(TrustError::new("E_RECORD_BOUND", subject));
            }
        }
        Ok(())
    }

    fn canonical_value_semantic_eq(
        left: &CanonicalValue,
        right: &CanonicalValue,
    ) -> bool {
        match (left, right) {
            (CanonicalValue::String(left), CanonicalValue::String(right)) => {
                left == right
            }
            (
                CanonicalValue::Unsigned(left),
                CanonicalValue::Unsigned(right),
            ) => left == right,
            (CanonicalValue::Signed(left), CanonicalValue::Signed(right)) => {
                left == right
            }
            (CanonicalValue::Boolean(left), CanonicalValue::Boolean(right)) => {
                left == right
            }
            (
                CanonicalValue::RawBytes(left),
                CanonicalValue::RawBytes(right),
            ) => left == right,
            (
                CanonicalValue::StringArray(left),
                CanonicalValue::StringArray(right),
            ) => left == right,
            (
                CanonicalValue::EnvironmentPairs(left),
                CanonicalValue::EnvironmentPairs(right),
            ) => left == right,
            (CanonicalValue::Record(left), CanonicalValue::Record(right)) => {
                canonical_record_semantic_eq(left, right)
            }
            (
                CanonicalValue::RecordArray(left),
                CanonicalValue::RecordArray(right),
            ) => {
                left.len() == right.len()
                    && left.iter().zip(right).all(|(left, right)| {
                        canonical_record_semantic_eq(left, right)
                    })
            }
            (
                CanonicalValue::OptionalString(left),
                CanonicalValue::OptionalString(right),
            ) => left == right,
            (
                CanonicalValue::OptionalUnsigned(left),
                CanonicalValue::OptionalUnsigned(right),
            ) => left == right,
            (
                CanonicalValue::OptionalBoolean(left),
                CanonicalValue::OptionalBoolean(right),
            ) => left == right,
            _ => false,
        }
    }

    pub fn canonical_record_semantic_eq(
        left: &CanonicalRecord,
        right: &CanonicalRecord,
    ) -> bool {
        left.schema_id == right.schema_id
            && left.fields.len() == right.fields.len()
            && left
                .fields
                .iter()
                .zip(&right.fields)
                .all(|(left, right)| canonical_value_semantic_eq(left, right))
    }

    pub fn encode_canonical_record(
        record: &CanonicalRecord,
        subject: &str,
    ) -> TrustResult<Vec<u8>> {
        let mut output = Vec::new();
        encode_tagged_record_into(&mut output, record, 0, subject)?;
        let mut cursor = BinaryCursor::new(&output, subject);
        let parsed = parse_tagged_record(&mut cursor, record.schema_id, 0)?;
        cursor.finish()?;
        if !canonical_record_semantic_eq(&parsed, record) {
            return Err(TrustError::new(
                "E_RECORD_ROUND_TRIP",
                subject,
            ));
        }
        Ok(output)
    }

    impl CanonicalRecord {
        fn ordinal(&self, field: &str) -> TrustResult<usize> {
            canonical_schema(self.schema_id)?
                .fields
                .iter()
                .position(|candidate| *candidate == field)
                .ok_or_else(|| {
                    TrustError::new(
                        "E_RECORD_FIELD",
                        format!("{}: {field}", self.schema_id),
                    )
                })
        }

        pub fn field(&self, field: &str) -> TrustResult<&CanonicalValue> {
            self.fields.get(self.ordinal(field)?).ok_or_else(|| {
                TrustError::new(
                    "E_RECORD_FIELD",
                    format!("{}: {field}", self.schema_id),
                )
            })
        }

        pub fn string(&self, field: &str) -> TrustResult<&str> {
            match self.field(field)? {
                CanonicalValue::String(value) => Ok(value),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn unsigned(&self, field: &str) -> TrustResult<u64> {
            match self.field(field)? {
                CanonicalValue::Unsigned(value) => Ok(*value),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn signed(&self, field: &str) -> TrustResult<i64> {
            match self.field(field)? {
                CanonicalValue::Signed(value) => Ok(*value),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn boolean(&self, field: &str) -> TrustResult<bool> {
            match self.field(field)? {
                CanonicalValue::Boolean(value) => Ok(*value),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn strings(&self, field: &str) -> TrustResult<&[String]> {
            match self.field(field)? {
                CanonicalValue::StringArray(values) => Ok(values),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn optional_string(&self, field: &str) -> TrustResult<Option<&str>> {
            match self.field(field)? {
                CanonicalValue::OptionalString(value) => Ok(value.as_deref()),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn optional_unsigned(&self, field: &str) -> TrustResult<Option<u64>> {
            match self.field(field)? {
                CanonicalValue::OptionalUnsigned(value) => Ok(*value),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn optional_boolean(&self, field: &str) -> TrustResult<Option<bool>> {
            match self.field(field)? {
                CanonicalValue::OptionalBoolean(value) => Ok(*value),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn raw_bytes(&self, field: &str) -> TrustResult<&[u8]> {
            match self.field(field)? {
                CanonicalValue::RawBytes(value) => Ok(value),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn environment(
            &self,
            field: &str,
        ) -> TrustResult<&[(String, String)]> {
            match self.field(field)? {
                CanonicalValue::EnvironmentPairs(values) => Ok(values),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn record(&self, field: &str) -> TrustResult<&CanonicalRecord> {
            match self.field(field)? {
                CanonicalValue::Record(value) => Ok(value),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }

        pub fn records(&self, field: &str) -> TrustResult<&[CanonicalRecord]> {
            match self.field(field)? {
                CanonicalValue::RecordArray(values) => Ok(values),
                _ => Err(TrustError::new(
                    "E_RECORD_TYPE",
                    format!("{}: {field}", self.schema_id),
                )),
            }
        }
    }

    pub fn canonical_file_binding(
        record: &CanonicalRecord,
        subject: &str,
    ) -> TrustResult<(String, FileBinding)> {
        if record.schema_id != "file-binding" {
            return Err(TrustError::new("E_FILE_BINDING_SCHEMA", subject));
        }
        let path = record.string("path")?.to_owned();
        if path.is_empty() {
            return Err(TrustError::new("E_FILE_BINDING_PATH", subject));
        }
        let byte_length = record.unsigned("byte_length")?;
        if byte_length == 0 {
            return Err(TrustError::new("E_FILE_BINDING_LENGTH", subject));
        }
        let sha256 = decode_lower_hex::<32>(record.string("sha256")?, subject)?;
        Ok((
            path,
            FileBinding {
                byte_length,
                sha256,
            },
        ))
    }

