    pub fn bootstrap_role_name(mode: BootstrapMode) -> TrustResult<&'static str> {
        match mode {
            BootstrapMode::Produce => Ok("integration-producer"),
            BootstrapMode::Attest => Ok("independent-attester"),
            BootstrapMode::Gate => Err(TrustError::new(
                "E_CONTROL_MODE",
                "Gate cannot enter the Produce/Attest control plane",
            )),
        }
    }

    fn bootstrap_mode_name(mode: BootstrapMode) -> TrustResult<&'static str> {
        match mode {
            BootstrapMode::Produce => Ok("produce"),
            BootstrapMode::Attest => Ok("attest"),
            BootstrapMode::Gate => Err(TrustError::new(
                "E_CONTROL_MODE",
                "Gate cannot enter the ordinary handoff",
            )),
        }
    }

    pub fn expected_ordinary_handoff_argv(
        mode: BootstrapMode,
        selected_executable: &str,
        run_id: &str,
    ) -> TrustResult<Vec<String>> {
        decode_run_id(run_id)?;
        validate_absolute_lexical_path(selected_executable, "handoff executable")?;
        let role = bootstrap_role_name(mode)?;
        Ok(vec![
            selected_executable.to_owned(),
            bootstrap_mode_name(mode)?.to_owned(),
            ".".to_owned(),
            run_id.to_owned(),
            format!(".fnd01-run/{role}/{run_id}/control-ledger.bin"),
        ])
    }

    pub fn validate_ordinary_handoff_argv(
        actual: &[String],
        mode: BootstrapMode,
        selected_executable: &str,
        run_id: &str,
        control_ledger_path: &str,
    ) -> TrustResult<()> {
        let expected =
            expected_ordinary_handoff_argv(mode, selected_executable, run_id)?;
        if expected.get(4).map(String::as_str) != Some(control_ledger_path)
            || actual != expected.as_slice()
        {
            return Err(TrustError::new(
                "E_CONTROL_HANDOFF",
                "handoff argv differs from exact live role/run invocation",
            ));
        }
        Ok(())
    }

    pub fn expected_ordinary_supply_relative_path(
        mode: BootstrapMode,
        run_id: &str,
    ) -> TrustResult<String> {
        decode_run_id(run_id)?;
        match mode {
            BootstrapMode::Produce => Ok(format!(
                ".fnd01-run/integration-producer/{run_id}/supply-bundle.bin"
            )),
            BootstrapMode::Attest => {
                Ok("evidence/fnd-01/integration/supply-bundle.bin".to_owned())
            }
            BootstrapMode::Gate => Err(TrustError::new(
                "E_CONTROL_MODE",
                "Gate has no ordinary handoff supply bundle",
            )),
        }
    }

    pub fn validate_ordinary_supply_path(
        actual: &str,
        repository_root: &Path,
        mode: BootstrapMode,
        run_id: &str,
    ) -> TrustResult<String> {
        let relative = expected_ordinary_supply_relative_path(mode, run_id)?;
        let expected = repository_root.join(&relative);
        let expected = expected.to_str().ok_or_else(|| {
            TrustError::new(
                "E_CONTROL_SUPPLY",
                "role-derived supply path must be UTF-8",
            )
        })?;
        validate_absolute_lexical_path(expected, "role-derived supply path")?;
        if actual != expected {
            return Err(TrustError::new(
                "E_CONTROL_SUPPLY",
                "supply path differs from exact role/run formula",
            ));
        }
        Ok(relative)
    }

    pub fn expected_ordinary_handoff_environment(
        mode: BootstrapMode,
        run_id: &str,
        environment: &BootstrapEnvironment,
    ) -> TrustResult<Vec<(String, String)>> {
        decode_run_id(run_id)?;
        if environment.authoring_marker.is_empty()
            || environment.closed_path.is_empty()
            || environment.attester_outer_record_path.is_some()
            || environment.final_gate_seal.is_some()
        {
            return Err(TrustError::new(
                "E_CONTROL_HANDOFF_ENVIRONMENT",
                "invalid common bootstrap environment",
            ));
        }
        let mut values = vec![(
            AUTHORING_MARKER_ENV.to_owned(),
            environment.authoring_marker.clone(),
        )];
        match mode {
            BootstrapMode::Produce => {
                if environment.integration_seal.is_some()
                    || environment.producer_outer_record_path.is_some()
                {
                    return Err(TrustError::new(
                        "E_CONTROL_HANDOFF_ENVIRONMENT",
                        "Produce received Attest-only environment",
                    ));
                }
            }
            BootstrapMode::Attest => {
                let integration_seal =
                    environment.integration_seal.clone().ok_or_else(|| {
                        TrustError::new(
                            "E_CONTROL_HANDOFF_ENVIRONMENT",
                            "Attest integration seal is missing",
                        )
                    })?;
                let expected_outer =
                    format!(".fnd01-run/controller/{run_id}/producer-outer.bin");
                let producer_outer_record_path = environment
                    .producer_outer_record_path
                    .clone()
                    .filter(|path| path == &expected_outer)
                    .ok_or_else(|| {
                        TrustError::new(
                            "E_CONTROL_HANDOFF_ENVIRONMENT",
                            "Attest producer outer-record path mismatch",
                        )
                    })?;
                values.push((INTEGRATION_SEAL_ENV.to_owned(), integration_seal));
                values.push((
                    PRODUCER_OUTER_RECORD_PATH_ENV.to_owned(),
                    producer_outer_record_path,
                ));
            }
            BootstrapMode::Gate => {
                return Err(TrustError::new(
                    "E_CONTROL_MODE",
                    "Gate cannot enter the ordinary handoff",
                ));
            }
        }
        values.extend([
            (RUN_ID_ENV.to_owned(), run_id.to_owned()),
            ("LANG".to_owned(), "C".to_owned()),
            ("LC_ALL".to_owned(), "C".to_owned()),
            ("PATH".to_owned(), environment.closed_path.clone()),
            ("TZ".to_owned(), "UTC".to_owned()),
        ]);
        validate_environment_array(&values, "ordinary handoff")?;
        Ok(values)
    }

    fn expected_absolute_role_path(
        repository_root: &Path,
        mode: BootstrapMode,
        run_id: &str,
        suffix: &str,
    ) -> TrustResult<String> {
        let root = repository_root.to_str().ok_or_else(|| {
            TrustError::new("E_CONTROL_PATH", "repository root must be UTF-8")
        })?;
        validate_absolute_lexical_path(root, "control repository root")?;
        let role = bootstrap_role_name(mode)?;
        let relative = if suffix.is_empty() {
            format!(".fnd01-run/{role}/{run_id}")
        } else {
            format!(".fnd01-run/{role}/{run_id}/{suffix}")
        };
        validate_relative_path(&relative, "control role path")?;
        repository_root
            .join(relative)
            .to_str()
            .map(str::to_owned)
            .ok_or_else(|| {
                TrustError::new("E_CONTROL_PATH", "role path must be UTF-8")
            })
    }

    fn validated_directory_tree_binding(
        record: &CanonicalRecord,
        subject: &str,
    ) -> TrustResult<ValidatedDirectoryTreeBinding> {
        if record.schema_id != "directory-tree-binding" {
            return Err(TrustError::new("E_CONTROL_TREE_SCHEMA", subject));
        }
        let mode = checked_u32(record.unsigned("mode")?, subject)?;
        let binding = ValidatedDirectoryTreeBinding {
            id: record.string("id")?.to_owned(),
            path: record.string("path")?.to_owned(),
            device: record.unsigned("device")?,
            inode: record.unsigned("inode")?,
            mode,
            nlink: record.unsigned("nlink")?,
            entry_count: record.unsigned("entry_count")?,
            total_regular_file_bytes: record.unsigned("total_regular_file_bytes")?,
            tree_sha256: decoded_digest(record.string("tree_sha256")?, subject)?,
        };
        if binding.id.is_empty()
            || binding.path.is_empty()
            || binding.nlink == 0
            || binding.mode & 0o170_000 != 0o040_000
            || binding.entry_count > 1_000_000
            || binding.total_regular_file_bytes > 4 * 1024 * 1024 * 1024
        {
            return Err(TrustError::new(
                "E_CONTROL_TREE",
                format!("{subject}: invalid directory-tree binding"),
            ));
        }
        Ok(binding)
    }

    fn validated_target_snapshot(
        record: &CanonicalRecord,
        subject: &str,
    ) -> TrustResult<ValidatedTargetSnapshot> {
        if record.schema_id != "target-snapshot" {
            return Err(TrustError::new("E_CONTROL_TARGET_SCHEMA", subject));
        }
        let snapshot = ValidatedTargetSnapshot {
            path: record.string("path")?.to_owned(),
            entry_count: record.unsigned("entry_count")?,
            total_regular_file_bytes: record.unsigned("total_regular_file_bytes")?,
            tree_sha256: decoded_digest(record.string("tree_sha256")?, subject)?,
        };
        if snapshot.path.is_empty()
            || snapshot.entry_count == 0
            || snapshot.entry_count > 1_000_000
            || snapshot.total_regular_file_bytes == 0
            || snapshot.total_regular_file_bytes > 4 * 1024 * 1024 * 1024
        {
            return Err(TrustError::new(
                "E_CONTROL_TARGET",
                format!("{subject}: invalid target snapshot"),
            ));
        }
        Ok(snapshot)
    }

    fn validated_compiler_artifact(
        record: &CanonicalRecord,
        package_root: &str,
        target_root: &str,
        selected_executable: &str,
    ) -> TrustResult<ValidatedCompilerArtifact> {
        if record.schema_id != "cargo-compiler-artifact" {
            return Err(TrustError::new(
                "E_CONTROL_ARTIFACT_SCHEMA",
                "control compiler artifact",
            ));
        }
        let artifact = ValidatedCompilerArtifact {
            reason: record.string("reason")?.to_owned(),
            package_id: record.string("package_id")?.to_owned(),
            manifest_path: record.string("manifest_path")?.to_owned(),
            target_name: record.string("target_name")?.to_owned(),
            target_kind: record.strings("target_kind")?.to_vec(),
            crate_types: record.strings("crate_types")?.to_vec(),
            src_path: record.string("src_path")?.to_owned(),
            edition: record.string("edition")?.to_owned(),
            features: record.strings("features")?.to_vec(),
            profile_test: record.boolean("profile_test")?,
            fresh: record.boolean("fresh")?,
            filenames: record.strings("filenames")?.to_vec(),
            executable: record.string("executable")?.to_owned(),
        };
        if !package_root.as_bytes().iter().all(|byte| {
            byte.is_ascii_alphanumeric() || matches!(byte, b'/' | b'-' | b'_' | b'.')
        }) {
            return Err(TrustError::new(
                "E_CONTROL_ARTIFACT",
                "package root cannot form the canonical Cargo file package ID",
            ));
        }
        let expected_package_id =
            format!("path+file://{package_root}#fastmcp-fnd01-bootstrap-control@0.0.0");
        let expected_manifest = format!("{package_root}/Cargo.toml");
        let expected_source = format!("{package_root}/src/main.rs");
        let expected_executable =
            format!("{target_root}/debug/fnd_01_evidence_harness");
        if artifact.reason != "compiler-artifact"
            || artifact.package_id != expected_package_id
            || artifact.manifest_path != expected_manifest
            || artifact.target_name != "fnd_01_evidence_harness"
            || artifact.target_kind != ["bin"]
            || artifact.crate_types != ["bin"]
            || artifact.src_path != expected_source
            || artifact.edition != "2024"
            || !artifact.features.is_empty()
            || artifact.profile_test
            || artifact.fresh
            || artifact.executable != expected_executable
            || artifact.executable != selected_executable
            || artifact
                .filenames
                .iter()
                .filter(|path| path.as_str() == selected_executable)
                .count()
                != 1
            || artifact.filenames.is_empty()
        {
            return Err(TrustError::new(
                "E_CONTROL_ARTIFACT",
                "control compiler artifact fields mismatch",
            ));
        }
        let target_root_path = Path::new(target_root);
        for (ordinal, filename) in artifact.filenames.iter().enumerate() {
            let relative = Path::new(filename)
                .strip_prefix(target_root_path)
                .map_err(|_| {
                    TrustError::new(
                        "E_CONTROL_ARTIFACT",
                        "artifact filename escapes target root",
                    )
                })?;
            if relative.as_os_str().is_empty()
                || relative.components().any(|component| {
                    !matches!(component, Component::Normal(_))
                })
                || artifact.filenames[..ordinal].contains(filename)
            {
                return Err(TrustError::new(
                    "E_CONTROL_ARTIFACT",
                    "artifact filename is empty, non-lexical, or duplicated",
                ));
            }
        }
        Ok(artifact)
    }

    fn validated_build_finished(
        record: &CanonicalRecord,
        message_count: u64,
    ) -> TrustResult<ValidatedBuildFinished> {
        if record.schema_id != "cargo-build-finished"
            || record.string("reason")? != "build-finished"
            || !record.boolean("success")?
            || record.unsigned("line_ordinal")? != message_count
        {
            return Err(TrustError::new(
                "E_CONTROL_BUILD_FINISHED",
                "final successful build-finished ordinal mismatch",
            ));
        }
        Ok(ValidatedBuildFinished {
            reason: "build-finished".to_owned(),
            success: true,
            line_ordinal: message_count,
        })
    }

    fn cargo_message_set(
        bytes: &[u8],
    ) -> TrustResult<(u64, [u8; 32])> {
        if bytes.is_empty()
            || !bytes.ends_with(b"\n")
            || bytes.contains(&b'\r')
        {
            return Err(TrustError::new(
                "E_CONTROL_CARGO_MESSAGES",
                "nonempty LF-terminated stdout required",
            ));
        }
        let lines = bytes[..bytes.len() - 1]
            .split(|byte| *byte == b'\n')
            .collect::<Vec<_>>();
        if lines.is_empty()
            || lines.len() > 1_000_000
            || lines.iter().any(|line| {
                line.is_empty() || std::str::from_utf8(line).is_err()
            })
        {
            return Err(TrustError::new(
                "E_CONTROL_CARGO_MESSAGES",
                "invalid UTF-8 line set",
            ));
        }
        let line_count = checked_usize_u64(lines.len(), "Cargo message count")?;
        let mut preimage = Vec::new();
        preimage.extend_from_slice(b"FND01CARGOMESSAGESv1\0");
        preimage.extend_from_slice(&checked_u32(line_count, "Cargo message count")?.to_be_bytes());
        for line in lines {
            reserve_preimage(
                &mut preimage,
                8usize
                    .checked_add(32)
                    .and_then(|length| length.checked_add(line.len()))
                    .ok_or_else(|| {
                        TrustError::new(
                            "E_CONTROL_BOUND",
                            "Cargo message preimage overflow",
                        )
                    })?,
            )?;
            preimage.extend_from_slice(
                &checked_usize_u64(line.len(), "Cargo message length")?.to_be_bytes(),
            );
            preimage.extend_from_slice(&sha256(line)?);
            preimage.extend_from_slice(line);
        }
        Ok((line_count, sha256(&preimage)?))
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct JoinedControlBuildStream {
        pub message_count: u64,
        pub message_set_sha256: [u8; 32],
        pub artifact: ValidatedCompilerArtifact,
        pub finished: ValidatedBuildFinished,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    enum ControlJson {
        Null,
        Bool(bool),
        Number(String),
        String(String),
        Array(Vec<ControlJson>),
        Object(Vec<(String, ControlJson)>),
    }

    struct ControlJsonParser<'a> {
        bytes: &'a [u8],
        offset: usize,
        nodes: usize,
    }

    impl<'a> ControlJsonParser<'a> {
        fn new(bytes: &'a [u8]) -> Self {
            Self {
                bytes,
                offset: 0,
                nodes: 0,
            }
        }

        fn err(&self, detail: &str) -> TrustError {
            TrustError::new(
                "E_CONTROL_JSON",
                format!("control Cargo JSON at byte {}: {detail}", self.offset),
            )
        }

        fn peek(&self) -> Option<u8> {
            self.bytes.get(self.offset).copied()
        }

        fn take(&mut self) -> TrustResult<u8> {
            let value = self.peek().ok_or_else(|| self.err("unexpected EOF"))?;
            self.offset += 1;
            Ok(value)
        }

        fn whitespace(&mut self) {
            while self
                .peek()
                .is_some_and(|byte| matches!(byte, b' ' | b'\t' | b'\r' | b'\n'))
            {
                self.offset += 1;
            }
        }

        fn literal(&mut self, suffix: &[u8], value: ControlJson) -> TrustResult<ControlJson> {
            let end = self
                .offset
                .checked_add(suffix.len())
                .ok_or_else(|| self.err("literal overflow"))?;
            if self.bytes.get(self.offset..end) != Some(suffix) {
                return Err(self.err("invalid literal"));
            }
            self.offset = end;
            Ok(value)
        }

        fn string(&mut self) -> TrustResult<String> {
            if self.take()? != b'"' {
                return Err(self.err("string quote required"));
            }
            let mut output = String::new();
            loop {
                let start = self.offset;
                while self
                    .peek()
                    .is_some_and(|byte| byte >= 0x20 && byte != b'"' && byte != b'\\')
                {
                    self.offset += 1;
                }
                if self.offset > start {
                    let chunk = std::str::from_utf8(&self.bytes[start..self.offset])
                        .map_err(|_| self.err("string is not UTF-8"))?;
                    output
                        .try_reserve(chunk.len())
                        .map_err(|_| TrustError::new("E_CONTROL_ALLOCATION", "JSON string"))?;
                    output.push_str(chunk);
                    if output.len() > 16 * 1024 * 1024 {
                        return Err(self.err("string bound exceeded"));
                    }
                }
                match self.take()? {
                    b'"' => return Ok(output),
                    b'\\' => {
                        let character = match self.take()? {
                            b'"' => '"',
                            b'\\' => '\\',
                            b'/' => '/',
                            b'b' => '\u{0008}',
                            b'f' => '\u{000c}',
                            b'n' => '\n',
                            b'r' => '\r',
                            b't' => '\t',
                            b'u' => {
                                let mut value = 0u16;
                                for _ in 0..4 {
                                    let digit = match self.take()? {
                                        byte @ b'0'..=b'9' => u16::from(byte - b'0'),
                                        byte @ b'a'..=b'f' => u16::from(byte - b'a' + 10),
                                        byte @ b'A'..=b'F' => u16::from(byte - b'A' + 10),
                                        _ => return Err(self.err("invalid Unicode escape")),
                                    };
                                    value = value
                                        .checked_mul(16)
                                        .and_then(|current| current.checked_add(digit))
                                        .ok_or_else(|| self.err("Unicode escape overflow"))?;
                                }
                                char::from_u32(u32::from(value))
                                    .ok_or_else(|| self.err("invalid Unicode scalar"))?
                            }
                            _ => return Err(self.err("invalid string escape")),
                        };
                        output.push(character);
                        if output.len() > 16 * 1024 * 1024 {
                            return Err(self.err("string bound exceeded"));
                        }
                    }
                    _ => return Err(self.err("control byte in string")),
                }
            }
        }

        fn number(&mut self) -> TrustResult<ControlJson> {
            let start = self.offset;
            if self.peek() == Some(b'-') {
                self.offset += 1;
            }
            match self.peek() {
                Some(b'0') => self.offset += 1,
                Some(b'1'..=b'9') => {
                    self.offset += 1;
                    while self.peek().is_some_and(|byte| byte.is_ascii_digit()) {
                        self.offset += 1;
                    }
                }
                _ => return Err(self.err("invalid number integer")),
            }
            if self.peek() == Some(b'.') {
                self.offset += 1;
                if !self.peek().is_some_and(|byte| byte.is_ascii_digit()) {
                    return Err(self.err("fraction digit required"));
                }
                while self.peek().is_some_and(|byte| byte.is_ascii_digit()) {
                    self.offset += 1;
                }
            }
            if self.peek().is_some_and(|byte| matches!(byte, b'e' | b'E')) {
                self.offset += 1;
                if self.peek().is_some_and(|byte| matches!(byte, b'+' | b'-')) {
                    self.offset += 1;
                }
                if !self.peek().is_some_and(|byte| byte.is_ascii_digit()) {
                    return Err(self.err("exponent digit required"));
                }
                while self.peek().is_some_and(|byte| byte.is_ascii_digit()) {
                    self.offset += 1;
                }
            }
            let value = std::str::from_utf8(&self.bytes[start..self.offset])
                .map_err(|_| self.err("number encoding"))?
                .to_owned();
            Ok(ControlJson::Number(value))
        }

        fn value(&mut self, depth: usize) -> TrustResult<ControlJson> {
            if depth > 128 || self.nodes >= 2_000_000 {
                return Err(self.err("JSON structural bound exceeded"));
            }
            self.nodes += 1;
            self.whitespace();
            match self.peek().ok_or_else(|| self.err("missing value"))? {
                b'n' => {
                    self.offset += 1;
                    self.literal(b"ull", ControlJson::Null)
                }
                b't' => {
                    self.offset += 1;
                    self.literal(b"rue", ControlJson::Bool(true))
                }
                b'f' => {
                    self.offset += 1;
                    self.literal(b"alse", ControlJson::Bool(false))
                }
                b'"' => self.string().map(ControlJson::String),
                b'-' | b'0'..=b'9' => self.number(),
                b'[' => {
                    self.offset += 1;
                    let mut values = Vec::new();
                    self.whitespace();
                    if self.peek() == Some(b']') {
                        self.offset += 1;
                        return Ok(ControlJson::Array(values));
                    }
                    loop {
                        values
                            .try_reserve(1)
                            .map_err(|_| TrustError::new("E_CONTROL_ALLOCATION", "JSON array"))?;
                        values.push(self.value(depth + 1)?);
                        self.whitespace();
                        match self.take()? {
                            b',' => self.whitespace(),
                            b']' => break,
                            _ => return Err(self.err("array separator")),
                        }
                    }
                    Ok(ControlJson::Array(values))
                }
                b'{' => {
                    self.offset += 1;
                    let mut values = Vec::new();
                    self.whitespace();
                    if self.peek() == Some(b'}') {
                        self.offset += 1;
                        return Ok(ControlJson::Object(values));
                    }
                    loop {
                        let name = self.string()?;
                        if values.iter().any(|(existing, _)| existing == &name) {
                            return Err(self.err("duplicate object key"));
                        }
                        self.whitespace();
                        if self.take()? != b':' {
                            return Err(self.err("object colon"));
                        }
                        let value = self.value(depth + 1)?;
                        values
                            .try_reserve(1)
                            .map_err(|_| TrustError::new("E_CONTROL_ALLOCATION", "JSON object"))?;
                        values.push((name, value));
                        self.whitespace();
                        match self.take()? {
                            b',' => self.whitespace(),
                            b'}' => break,
                            _ => return Err(self.err("object separator")),
                        }
                    }
                    Ok(ControlJson::Object(values))
                }
                _ => Err(self.err("unknown value token")),
            }
        }

        fn parse(mut self) -> TrustResult<ControlJson> {
            if self.bytes.is_empty() {
                return Err(self.err("empty JSON"));
            }
            let value = self.value(0)?;
            self.whitespace();
            if self.offset != self.bytes.len() {
                return Err(self.err("trailing JSON bytes"));
            }
            Ok(value)
        }
    }

    fn control_json_object<'a>(
        value: &'a ControlJson,
        subject: &str,
    ) -> TrustResult<&'a [(String, ControlJson)]> {
        match value {
            ControlJson::Object(fields) => Ok(fields),
            _ => Err(TrustError::new(
                "E_CONTROL_JSON_TYPE",
                format!("{subject}: object required"),
            )),
        }
    }

    fn control_json_field<'a>(
        object: &'a [(String, ControlJson)],
        name: &str,
        subject: &str,
    ) -> TrustResult<&'a ControlJson> {
        object
            .iter()
            .find(|(candidate, _)| candidate == name)
            .map(|(_, value)| value)
            .ok_or_else(|| {
                TrustError::new(
                    "E_CONTROL_JSON_FIELD",
                    format!("{subject}: missing {name:?}"),
                )
            })
    }

    fn control_json_string<'a>(value: &'a ControlJson, subject: &str) -> TrustResult<&'a str> {
        match value {
            ControlJson::String(value) => Ok(value),
            _ => Err(TrustError::new(
                "E_CONTROL_JSON_TYPE",
                format!("{subject}: string required"),
            )),
        }
    }

    fn control_json_bool(value: &ControlJson, subject: &str) -> TrustResult<bool> {
        match value {
            ControlJson::Bool(value) => Ok(*value),
            _ => Err(TrustError::new(
                "E_CONTROL_JSON_TYPE",
                format!("{subject}: boolean required"),
            )),
        }
    }

    fn control_json_number<'a>(value: &'a ControlJson, subject: &str) -> TrustResult<&'a str> {
        match value {
            ControlJson::Number(value) => Ok(value),
            _ => Err(TrustError::new(
                "E_CONTROL_JSON_TYPE",
                format!("{subject}: number required"),
            )),
        }
    }

    fn control_json_strings(value: &ControlJson, subject: &str) -> TrustResult<Vec<String>> {
        match value {
            ControlJson::Array(values) => {
                let mut output = Vec::new();
                output
                    .try_reserve_exact(values.len())
                    .map_err(|_| TrustError::new("E_CONTROL_ALLOCATION", subject))?;
                for (index, value) in values.iter().enumerate() {
                    let value = control_json_string(value, &format!("{subject}[{index}]"))?;
                    output.push(value.to_owned());
                }
                Ok(output)
            }
            _ => Err(TrustError::new(
                "E_CONTROL_JSON_TYPE",
                format!("{subject}: string array required"),
            )),
        }
    }

    fn control_json_exact_fields(
        object: &[(String, ControlJson)],
        required: &[&str],
        optional: &[&str],
    ) -> bool {
        object.len() >= required.len()
            && object.len() <= required.len() + optional.len()
            && required
                .iter()
                .all(|name| object.iter().any(|(field, _)| field == name))
            && object.iter().all(|(field, _)| {
                required.contains(&field.as_str()) || optional.contains(&field.as_str())
            })
    }

    fn parse_matching_control_compiler_artifact(
        value: &ControlJson,
        package_root: &str,
        target_root: &str,
        selected_executable: &str,
    ) -> TrustResult<Option<ValidatedCompilerArtifact>> {
        let object = control_json_object(value, "Cargo message")?;
        if control_json_string(control_json_field(object, "reason", "Cargo message")?, "reason")?
            != "compiler-artifact"
        {
            return Ok(None);
        }
        if !control_json_exact_fields(
            object,
            &[
                "reason",
                "package_id",
                "manifest_path",
                "target",
                "profile",
                "features",
                "filenames",
                "executable",
                "fresh",
            ],
            &[],
        ) {
            return Err(TrustError::new(
                "E_CONTROL_ARTIFACT",
                "unknown/missing artifact field",
            ));
        }
        let target = control_json_object(
            control_json_field(object, "target", "compiler-artifact")?,
            "compiler-artifact.target",
        )?;
        let profile = control_json_object(
            control_json_field(object, "profile", "compiler-artifact")?,
            "compiler-artifact.profile",
        )?;
        if !control_json_exact_fields(
            target,
            &[
                "kind",
                "crate_types",
                "name",
                "src_path",
                "edition",
                "doc",
                "doctest",
                "test",
            ],
            &[],
        ) || !control_json_exact_fields(
            profile,
            &["opt_level", "debuginfo", "debug_assertions", "overflow_checks", "test"],
            &[],
        ) {
            return Err(TrustError::new(
                "E_CONTROL_ARTIFACT",
                "unknown/missing target/profile field",
            ));
        }
        let executable_value = control_json_field(object, "executable", "compiler-artifact")?;
        let executable = match executable_value {
            ControlJson::String(value) => value.clone(),
            ControlJson::Null => return Ok(None),
            _ => {
                return Err(TrustError::new(
                    "E_CONTROL_ARTIFACT",
                    "executable must be string or null",
                ));
            }
        };
        if !package_root
            .as_bytes()
            .iter()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'/' | b'-' | b'_' | b'.'))
        {
            return Err(TrustError::new(
                "E_CONTROL_ARTIFACT",
                "package root cannot form the canonical Cargo file package ID",
            ));
        }
        let expected_package_id =
            format!("path+file://{package_root}#fastmcp-fnd01-bootstrap-control@0.0.0");
        let expected_manifest = format!("{package_root}/Cargo.toml");
        let expected_source = format!("{package_root}/src/main.rs");
        let expected_executable = format!("{target_root}/debug/fnd_01_evidence_harness");
        let target_name =
            control_json_string(control_json_field(target, "name", "target")?, "target.name")?
                .to_owned();
        let target_kind = control_json_strings(
            control_json_field(target, "kind", "target")?,
            "target.kind",
        )?;
        let crate_types = control_json_strings(
            control_json_field(target, "crate_types", "target")?,
            "target.crate_types",
        )?;
        let src_path = control_json_string(
            control_json_field(target, "src_path", "target")?,
            "target.src_path",
        )?
        .to_owned();
        let edition =
            control_json_string(control_json_field(target, "edition", "target")?, "target.edition")?
                .to_owned();
        let features = control_json_strings(
            control_json_field(object, "features", "compiler-artifact")?,
            "features",
        )?;
        let profile_test =
            control_json_bool(control_json_field(profile, "test", "profile")?, "profile.test")?;
        let fresh = control_json_bool(
            control_json_field(object, "fresh", "compiler-artifact")?,
            "fresh",
        )?;
        let filenames = control_json_strings(
            control_json_field(object, "filenames", "compiler-artifact")?,
            "filenames",
        )?;
        let package_id = control_json_string(
            control_json_field(object, "package_id", "compiler-artifact")?,
            "package_id",
        )?
        .to_owned();
        let manifest_path = control_json_string(
            control_json_field(object, "manifest_path", "compiler-artifact")?,
            "manifest_path",
        )?
        .to_owned();
        if package_id != expected_package_id
            || manifest_path != expected_manifest
            || target_name != "fnd_01_evidence_harness"
            || target_kind != ["bin"]
            || crate_types != ["bin"]
            || src_path != expected_source
            || edition != "2024"
            || !features.is_empty()
            || profile_test
            || fresh
            || control_json_bool(control_json_field(target, "doc", "target")?, "target.doc")?
            || control_json_bool(
                control_json_field(target, "doctest", "target")?,
                "target.doctest",
            )?
            || control_json_bool(control_json_field(target, "test", "target")?, "target.test")?
            || control_json_string(
                control_json_field(profile, "opt_level", "profile")?,
                "profile.opt_level",
            )? != "0"
            || control_json_number(
                control_json_field(profile, "debuginfo", "profile")?,
                "profile.debuginfo",
            )? != "2"
            || !control_json_bool(
                control_json_field(profile, "debug_assertions", "profile")?,
                "profile.debug_assertions",
            )?
            || !control_json_bool(
                control_json_field(profile, "overflow_checks", "profile")?,
                "profile.overflow_checks",
            )?
            || executable != expected_executable
            || executable != selected_executable
            || filenames
                .iter()
                .filter(|path| path.as_str() == selected_executable)
                .count()
                != 1
            || filenames.is_empty()
        {
            return Ok(None);
        }
        let target_root_path = Path::new(target_root);
        for (ordinal, filename) in filenames.iter().enumerate() {
            let relative = Path::new(filename)
                .strip_prefix(target_root_path)
                .map_err(|_| {
                    TrustError::new(
                        "E_CONTROL_ARTIFACT",
                        "artifact filename escapes target root",
                    )
                })?;
            if relative.as_os_str().is_empty()
                || relative
                    .components()
                    .any(|component| !matches!(component, Component::Normal(_)))
                || filenames[..ordinal].contains(filename)
            {
                return Err(TrustError::new(
                    "E_CONTROL_ARTIFACT",
                    "artifact filename is empty, non-lexical, or duplicated",
                ));
            }
        }
        Ok(Some(ValidatedCompilerArtifact {
            reason: "compiler-artifact".to_owned(),
            package_id,
            manifest_path,
            target_name,
            target_kind,
            crate_types,
            src_path,
            edition,
            features,
            profile_test,
            fresh,
            filenames,
            executable,
        }))
    }

    pub fn join_control_build_stream(
        stdout: &[u8],
        package_root: &str,
        target_root: &str,
        selected_executable: &str,
    ) -> TrustResult<JoinedControlBuildStream> {
        let (message_count, message_set_sha256) = cargo_message_set(stdout)?;
        if message_count < 2 {
            return Err(TrustError::new(
                "E_CONTROL_CARGO_MESSAGES",
                "control Cargo emitted fewer than two messages",
            ));
        }
        if stdout.is_empty() || !stdout.ends_with(b"\n") || stdout.contains(&b'\r') {
            return Err(TrustError::new(
                "E_CONTROL_CARGO_MESSAGES",
                "nonempty LF-terminated stdout required",
            ));
        }
        let lines = stdout[..stdout.len() - 1]
            .split(|byte| *byte == b'\n')
            .collect::<Vec<_>>();
        if checked_usize_u64(lines.len(), "Cargo message count")? != message_count {
            return Err(TrustError::new(
                "E_CONTROL_CARGO_MESSAGES",
                "joined line count desync",
            ));
        }
        let mut selected = Vec::new();
        for (ordinal, line) in lines.iter().enumerate() {
            let value = ControlJsonParser::new(line).parse()?;
            if let Some(artifact) = parse_matching_control_compiler_artifact(
                &value,
                package_root,
                target_root,
                selected_executable,
            )? {
                selected
                    .try_reserve(1)
                    .map_err(|_| TrustError::new("E_CONTROL_ALLOCATION", "selected artifacts"))?;
                selected.push((ordinal, artifact));
            }
        }
        let (artifact_ordinal, artifact) = selected.pop().ok_or_else(|| {
            TrustError::new(
                "E_CONTROL_ARTIFACT",
                "matching compiler-artifact is missing",
            )
        })?;
        if !selected.is_empty()
            || artifact_ordinal
                .checked_add(2)
                .ok_or_else(|| TrustError::new("E_CONTROL_BOUND", "artifact ordinal"))?
                != lines.len()
        {
            return Err(TrustError::new(
                "E_CONTROL_ARTIFACT",
                "matching artifact must be unique and immediately precede build-finished",
            ));
        }
        let finished_line = lines.last().ok_or_else(|| {
            TrustError::new("E_CONTROL_BUILD_FINISHED", "missing final message")
        })?;
        let finished_value = ControlJsonParser::new(finished_line).parse()?;
        let finished_object = control_json_object(&finished_value, "build-finished")?;
        if !control_json_exact_fields(finished_object, &["reason", "success"], &[])
            || control_json_string(
                control_json_field(finished_object, "reason", "build-finished")?,
                "build-finished.reason",
            )? != "build-finished"
            || !control_json_bool(
                control_json_field(finished_object, "success", "build-finished")?,
                "build-finished.success",
            )?
        {
            return Err(TrustError::new(
                "E_CONTROL_BUILD_FINISHED",
                "final build-finished success=true required",
            ));
        }
        Ok(JoinedControlBuildStream {
            message_count,
            message_set_sha256,
            artifact,
            finished: ValidatedBuildFinished {
                reason: "build-finished".to_owned(),
                success: true,
                line_ordinal: message_count,
            },
        })
    }

    fn expected_control_build_argv(
        expected: &ControlLedgerExpectation,
        package_root: &str,
        target_root: &str,
    ) -> Vec<String> {
        vec![
            expected.cargo_executable.clone(),
            "build".to_owned(),
            "--manifest-path".to_owned(),
            format!("{package_root}/Cargo.toml"),
            "--bin".to_owned(),
            "fnd_01_evidence_harness".to_owned(),
            "--locked".to_owned(),
            "--offline".to_owned(),
            "--message-format=json".to_owned(),
            "--target-dir".to_owned(),
            target_root.to_owned(),
            "--config".to_owned(),
            format!("{package_root}/cargo-config.toml"),
        ]
    }

    pub fn validate_control_ledger_bytes(
        bytes: &[u8],
        expected: &ControlLedgerExpectation,
    ) -> TrustResult<ValidatedControlLedger> {
        decode_run_id(&expected.run_id)?;
        if expected.process_id == 0 {
            return Err(TrustError::new(
                "E_CONTROL_PROCESS",
                "expected process ID must be nonzero",
            ));
        }
        let role = bootstrap_role_name(expected.mode)?;
        let package_root = expected_absolute_role_path(
            &expected.repository_root,
            expected.mode,
            &expected.run_id,
            "bootstrap-control-package",
        )?;
        let target_root = expected_absolute_role_path(
            &expected.repository_root,
            expected.mode,
            &expected.run_id,
            "bootstrap-control-target",
        )?;
        let local_registry_path = expected_absolute_role_path(
            &expected.repository_root,
            expected.mode,
            &expected.run_id,
            "local-registry",
        )?;
        let expected_scratch_paths = [
            format!("{package_root}/Cargo.toml"),
            format!("{package_root}/Cargo.lock"),
            format!("{package_root}/cargo-config.toml"),
            format!("{package_root}/src/main.rs"),
            format!("{package_root}/tests/fnd_01_dependency_evidence.rs"),
        ];
        if expected
            .scratch_bindings
            .iter()
            .map(|binding| binding.path.as_str())
            .ne(expected_scratch_paths.iter().map(String::as_str))
            || expected.local_registry.id != "sealed-local-registry"
            || expected.local_registry.path != local_registry_path
            || expected.target_snapshot.path != target_root
            || expected.selected_executable.path
                != format!("{target_root}/debug/fnd_01_evidence_harness")
            || expected.selected_executable.binding.byte_length == 0
        {
            return Err(TrustError::new(
                "E_CONTROL_EXPECTATION",
                "layout-derived expectation mismatch",
            ));
        }
        match expected.mode {
            BootstrapMode::Produce => {
                if expected.integration_seal_sha256 != [0; 32]
                    || expected.acquisition_spool_binding.is_none()
                {
                    return Err(TrustError::new(
                        "E_CONTROL_EXPECTATION",
                        "Produce integration/spool expectation mismatch",
                    ));
                }
            }
            BootstrapMode::Attest => {
                if expected.integration_seal_sha256 == [0; 32]
                    || expected.acquisition_spool_binding.is_some()
                {
                    return Err(TrustError::new(
                        "E_CONTROL_EXPECTATION",
                        "Attest integration/spool expectation mismatch",
                    ));
                }
            }
            BootstrapMode::Gate => {
                return Err(TrustError::new(
                    "E_CONTROL_MODE",
                    "Gate cannot carry a control ledger",
                ));
            }
        }
        validate_environment_array(
            &expected.build_environment,
            "control build expectation",
        )?;
        let expected_build_argv =
            expected_control_build_argv(expected, &package_root, &target_root);
        validate_argument_array(&expected_build_argv, "control build expectation")?;
        let expected_handoff_argv = expected_ordinary_handoff_argv(
            expected.mode,
            &expected.selected_executable.path,
            &expected.run_id,
        )?;
        let expected_handoff_environment =
            expected_ordinary_handoff_environment(
                expected.mode,
                &expected.run_id,
                &expected.bootstrap_environment,
            )?;

        let record = parse_canonical_record_file_with_final_self_digest(
            bytes,
            CONTROL_LEDGER_PREFIX,
            "control-ledger",
            "ledger_set_sha256",
            MAX_CONTROL_LEDGER_BYTES,
            "control ledger",
        )?;
        if record.string("format")? != "FND01CONTROLv2"
            || record.unsigned("schema_version")? != 2
            || record.string("role")? != role
            || record.string("run_id")? != expected.run_id.as_str()
            || record.unsigned("process_id")? != expected.process_id
            || record.unsigned("scratch_binding_count")? != 5
            || record.signed("build_exit_code")? != 0
        {
            return Err(TrustError::new(
                "E_CONTROL_LEDGER",
                "format/schema/role/run/PID/count/exit mismatch",
            ));
        }
        let authoring_closure_sha256 = decoded_digest(
            record.string("authoring_closure_sha256")?,
            "control authoring closure",
        )?;
        let integration_seal_sha256 = decoded_digest(
            record.string("integration_seal_sha256")?,
            "control integration seal",
        )?;
        let tool_set_sha256 =
            decoded_digest(record.string("tool_set_sha256")?, "control tool set")?;
        let environment_set_sha256 = decoded_digest(
            record.string("environment_set_sha256")?,
            "control environment set",
        )?;
        if authoring_closure_sha256 != expected.authoring_closure_sha256 {
            return Err(TrustError::new(
                "E_CONTROL_AUTHORITY",
                format!(
                    "authoring_closure_sha256 expected={} observed={}",
                    encode_lower_hex(&expected.authoring_closure_sha256),
                    encode_lower_hex(&authoring_closure_sha256),
                ),
            ));
        }
        if integration_seal_sha256 != expected.integration_seal_sha256 {
            return Err(TrustError::new(
                "E_CONTROL_AUTHORITY",
                format!(
                    "integration_seal_sha256 expected={} observed={}",
                    encode_lower_hex(&expected.integration_seal_sha256),
                    encode_lower_hex(&integration_seal_sha256),
                ),
            ));
        }
        if tool_set_sha256 != expected.tool_set_sha256 {
            return Err(TrustError::new(
                "E_CONTROL_AUTHORITY",
                format!(
                    "tool_set_sha256 expected={} observed={}",
                    encode_lower_hex(&expected.tool_set_sha256),
                    encode_lower_hex(&tool_set_sha256),
                ),
            ));
        }
        if environment_set_sha256 != expected.environment_set_sha256 {
            return Err(TrustError::new(
                "E_CONTROL_AUTHORITY",
                format!(
                    "environment_set_sha256 expected={} observed={}",
                    encode_lower_hex(&expected.environment_set_sha256),
                    encode_lower_hex(&environment_set_sha256),
                ),
            ));
        }

        let scratch_records = record.records("scratch_binding")?;
        if scratch_records.len() != 5 {
            return Err(TrustError::new(
                "E_CONTROL_SCRATCH",
                "scratch array cardinality mismatch",
            ));
        }
        let scratch_values = scratch_records
            .iter()
            .enumerate()
            .map(|(ordinal, record)| {
                validated_file_binding(
                    record,
                    &format!("control scratch binding {ordinal}"),
                )
            })
            .collect::<TrustResult<Vec<_>>>()?;
        let scratch_bindings: [ValidatedFileBinding; 5] =
            scratch_values.try_into().map_err(|_| {
                TrustError::new("E_CONTROL_SCRATCH", "scratch array conversion")
            })?;
        if scratch_bindings.as_slice() != expected.scratch_bindings.as_slice() {
            return Err(TrustError::new(
                "E_CONTROL_SCRATCH",
                "scratch binding order/path/digest mismatch",
            ));
        }

        let local_registry = validated_directory_tree_binding(
            record.record("local_registry")?,
            "control local registry",
        )?;
        let supply_bundle = validated_file_binding(
            record.record("supply_bundle")?,
            "control supply bundle",
        )?;
        if local_registry != expected.local_registry
            || supply_bundle != expected.supply_bundle
        {
            return Err(TrustError::new(
                "E_CONTROL_INPUT_BINDING",
                "local-registry or supply binding mismatch",
            ));
        }

        let build_argv = record.strings("build_argv")?;
        let build_environment = record.environment("build_environment")?;
        validate_argument_array(build_argv, "control build")?;
        validate_environment_array(build_environment, "control build")?;
        if build_argv != expected_build_argv.as_slice()
            || build_environment != expected.build_environment.as_slice()
            || record.string("build_working_directory")? != package_root.as_str()
        {
            return Err(TrustError::new(
                "E_CONTROL_BUILD_PLAN",
                "control build argv/environment/CWD mismatch",
            ));
        }
        let build_stdout = validated_raw_stream_blob(
            record.record("build_stdout")?,
            32 * 1024 * 1024,
            "control build stdout",
        )?;
        let build_stderr = validated_raw_stream_blob(
            record.record("build_stderr")?,
            32 * 1024 * 1024,
            "control build stderr",
        )?;
        let (cargo_message_count, cargo_message_set_sha256) =
            cargo_message_set(&build_stdout.bytes)?;
        if cargo_message_count < 2
            || record.unsigned("cargo_message_count")? != cargo_message_count
            || decoded_digest(
                record.string("cargo_message_set_sha256")?,
                "control Cargo message set",
            )? != cargo_message_set_sha256
        {
            return Err(TrustError::new(
                "E_CONTROL_CARGO_MESSAGES",
                "Cargo message count/digest mismatch",
            ));
        }

        let selected_executable = validated_file_binding(
            record.record("selected_executable")?,
            "control selected executable",
        )?;
        if selected_executable != expected.selected_executable {
            return Err(TrustError::new(
                "E_CONTROL_EXECUTABLE",
                "selected executable binding mismatch",
            ));
        }
        // build_stream_rule: penultimate matching compiler-artifact + terminal
        // build-finished must equal embedded ledger records (not digest-only).
        let joined = join_control_build_stream(
            &build_stdout.bytes,
            &package_root,
            &target_root,
            &selected_executable.path,
        )?;
        if joined.message_count != cargo_message_count
            || joined.message_set_sha256 != cargo_message_set_sha256
        {
            return Err(TrustError::new(
                "E_CONTROL_CARGO_MESSAGES",
                "joined Cargo stream count/digest mismatch",
            ));
        }
        let compiler_artifact = validated_compiler_artifact(
            record.record("compiler_artifact")?,
            &package_root,
            &target_root,
            &selected_executable.path,
        )?;
        let build_finished = validated_build_finished(
            record.record("build_finished")?,
            cargo_message_count,
        )?;
        if compiler_artifact != joined.artifact || build_finished != joined.finished {
            return Err(TrustError::new(
                "E_CONTROL_BUILD_STREAM_JOIN",
                "embedded compiler-artifact/build-finished desync from stdout JSON",
            ));
        }
        let target_snapshot = validated_target_snapshot(
            record.record("target_snapshot")?,
            "control target snapshot",
        )?;
        if target_snapshot != expected.target_snapshot {
            return Err(TrustError::new(
                "E_CONTROL_TARGET",
                "target snapshot mismatch",
            ));
        }

        let handoff_argv = record.strings("handoff_argv")?;
        let handoff_environment = record.environment("handoff_environment")?;
        if handoff_argv != expected_handoff_argv.as_slice()
            || handoff_environment != expected_handoff_environment.as_slice()
        {
            return Err(TrustError::new(
                "E_CONTROL_HANDOFF",
                "ordinary handoff argv/environment mismatch",
            ));
        }
        let acquisition_spool = validated_optional_file_binding(
            record.record("acquisition_spool")?,
            "control acquisition spool",
        )?;
        let expected_spool_path = expected
            .repository_root
            .join(".fnd01-run")
            .join("integration-producer")
            .join(&expected.run_id)
            .join("acquisition-spool.bin")
            .to_str()
            .map(str::to_owned)
            .ok_or_else(|| {
                TrustError::new("E_CONTROL_PATH", "spool path must be UTF-8")
            })?;
        match expected.acquisition_spool_binding {
            Some(binding)
                if acquisition_spool.present
                    && acquisition_spool.path.as_deref()
                        == Some(expected_spool_path.as_str())
                    && acquisition_spool.binding == Some(binding) => {}
            None
                if !acquisition_spool.present
                    && acquisition_spool.path.is_none()
                    && acquisition_spool.binding.is_none() => {}
            _ => {
                return Err(TrustError::new(
                    "E_CONTROL_SPOOL",
                    "role-specific acquisition spool mismatch",
                ));
            }
        }

        Ok(ValidatedControlLedger {
            role: role.to_owned(),
            run_id: expected.run_id.clone(),
            process_id: expected.process_id,
            authoring_closure_sha256,
            integration_seal_sha256,
            scratch_bindings,
            local_registry,
            supply_bundle,
            tool_set_sha256,
            environment_set_sha256,
            build_argv: build_argv.to_vec(),
            build_environment: build_environment.to_vec(),
            build_working_directory: package_root,
            build_exit_code: 0,
            build_stdout,
            build_stderr,
            cargo_message_count,
            cargo_message_set_sha256,
            compiler_artifact,
            build_finished,
            target_snapshot,
            selected_executable,
            handoff_argv: handoff_argv.to_vec(),
            handoff_environment: handoff_environment.to_vec(),
            acquisition_spool,
        })
    }

    fn rebind_absolute_file(
        repository_root: &Path,
        binding: &ValidatedFileBinding,
        maximum: u64,
        executable: bool,
        subject: &str,
    ) -> TrustResult<()> {
        let absolute = Path::new(&binding.path);
        let relative = absolute.strip_prefix(repository_root).map_err(|_| {
            TrustError::new(
                "E_CONTROL_REBIND_PATH",
                format!("{subject}: path is outside repository"),
            )
        })?;
        let relative = relative.to_str().ok_or_else(|| {
            TrustError::new(
                "E_CONTROL_REBIND_PATH",
                format!("{subject}: path must be UTF-8"),
            )
        })?;
        let snapshot =
            checked_snapshot(repository_root, relative, maximum, Some(binding.binding))?;
        if executable
            && (snapshot.identity.file_type != 0o100_000
                || snapshot.identity.link_count != 1
                || snapshot.identity.mode & 0o100 == 0)
        {
            return Err(TrustError::new(
                "E_CONTROL_REBIND_EXECUTABLE",
                format!("{subject}: regular nlink-one owner-executable required"),
            ));
        }
        Ok(())
    }

    pub fn rebind_control_ledger_regular_files(
        repository_root: &Path,
        ledger: &ValidatedControlLedger,
    ) -> TrustResult<()> {
        for (ordinal, (binding, maximum)) in ledger
            .scratch_bindings
            .iter()
            .zip(CONTROL_SCRATCH_MAXIMA)
            .enumerate()
        {
            rebind_absolute_file(
                repository_root,
                binding,
                maximum,
                false,
                &format!("control scratch binding {ordinal}"),
            )?;
        }
        rebind_absolute_file(
            repository_root,
            &ledger.supply_bundle,
            MAX_SUPPLY_BUNDLE_BYTES,
            false,
            "control supply bundle",
        )?;
        rebind_absolute_file(
            repository_root,
            &ledger.selected_executable,
            MAX_GATE_EXECUTABLE_BYTES,
            true,
            "control selected executable",
        )?;
        if let (Some(path), Some(binding)) = (
            ledger.acquisition_spool.path.as_ref(),
            ledger.acquisition_spool.binding,
        ) {
            rebind_absolute_file(
                repository_root,
                &ValidatedFileBinding {
                    path: path.clone(),
                    binding,
                },
                MAX_ACQUISITION_SPOOL_BYTES,
                false,
                "control acquisition spool",
            )?;
        }
        Ok(())
    }

    fn canonical_outer_binding(
        record: &CanonicalRecord,
        expected_schema: &str,
        expected_path: &str,
        expected_run_id: &str,
        subject: &str,
    ) -> TrustResult<FileBinding> {
        if record.schema_id != expected_schema
            || record.string("path")? != expected_path
            || record.string("format")? != "FND01OUTERv2"
            || record.string("run_id")? != expected_run_id
        {
            return Err(TrustError::new("E_OUTER_BINDING", subject));
        }
        let byte_length = record.unsigned("byte_length")?;
        if byte_length == 0
            || byte_length > MAX_OUTER_TRANSPORT_RECORD_BYTES
        {
            return Err(TrustError::new("E_OUTER_BINDING", subject));
        }
        Ok(FileBinding {
            byte_length,
            sha256: decode_lower_hex(record.string("sha256")?, subject)?,
        })
    }

