    fn checked_identity_mode(record: &CanonicalRecord, subject: &str) -> TrustResult<u32> {
        u32::try_from(record.unsigned("mode")?).map_err(|_| {
            TrustError::new(
                "E_UNIX_IDENTITY",
                format!("{subject}: mode exceeds u32"),
            )
        })
    }

    fn checked_identity_nanoseconds(
        record: &CanonicalRecord,
        field: &str,
        subject: &str,
    ) -> TrustResult<u32> {
        let value = u32::try_from(record.unsigned(field)?).map_err(|_| {
            TrustError::new(
                "E_UNIX_IDENTITY",
                format!("{subject}: {field} exceeds u32"),
            )
        })?;
        if value >= 1_000_000_000 {
            return Err(TrustError::new(
                "E_UNIX_IDENTITY",
                format!("{subject}: {field} is not a nanosecond remainder"),
            ));
        }
        Ok(value)
    }

    pub fn validate_unix_file_identity(
        record: &CanonicalRecord,
        maximum: u64,
        require_executable: bool,
        subject: &str,
    ) -> TrustResult<ValidatedUnixFileIdentity> {
        if record.schema_id != "unix-file-identity" {
            return Err(TrustError::new(
                "E_UNIX_IDENTITY",
                format!("{subject}: unix-file-identity required"),
            ));
        }
        let path = record.string("path")?.to_owned();
        validate_absolute_lexical_path(&path, subject)?;
        let mode = checked_identity_mode(record, subject)?;
        let nlink = record.unsigned("nlink")?;
        let byte_length = record.unsigned("byte_length")?;
        if mode & 0o170_000 != 0o100_000
            || nlink != 1
            || byte_length > maximum
            || require_executable && (byte_length == 0 || mode & 0o111 == 0)
        {
            return Err(TrustError::new(
                "E_UNIX_IDENTITY",
                format!("{subject}: regular nlink-one bounded file required"),
            ));
        }
        let inode = record.unsigned("inode")?;
        if inode == 0 {
            return Err(TrustError::new(
                "E_UNIX_IDENTITY",
                format!("{subject}: zero inode"),
            ));
        }
        Ok(ValidatedUnixFileIdentity {
            path,
            device: record.unsigned("device")?,
            inode,
            mode,
            nlink,
            byte_length,
            mtime_seconds: record.unsigned("mtime_seconds")?,
            mtime_nanoseconds: checked_identity_nanoseconds(
                record,
                "mtime_nanoseconds",
                subject,
            )?,
            ctime_seconds: record.unsigned("ctime_seconds")?,
            ctime_nanoseconds: checked_identity_nanoseconds(
                record,
                "ctime_nanoseconds",
                subject,
            )?,
            sha256: decode_lower_hex(record.string("sha256")?, subject)?,
        })
    }

    pub fn validate_unix_node_identity(
        record: &CanonicalRecord,
        expected_schema: &str,
        expected_file_type: u32,
        subject: &str,
    ) -> TrustResult<ValidatedUnixNodeIdentity> {
        if record.schema_id != expected_schema
            || !matches!(
                expected_schema,
                "unix-directory-identity" | "unix-socket-identity"
            )
        {
            return Err(TrustError::new(
                "E_UNIX_IDENTITY",
                format!("{subject}: wrong Unix node schema"),
            ));
        }
        let path = record.string("path")?.to_owned();
        validate_absolute_lexical_path(&path, subject)?;
        let mode = checked_identity_mode(record, subject)?;
        let nlink = record.unsigned("nlink")?;
        let inode = record.unsigned("inode")?;
        if mode & 0o170_000 != expected_file_type
            || nlink == 0
            || inode == 0
            || expected_file_type == 0o140_000 && nlink != 1
        {
            return Err(TrustError::new(
                "E_UNIX_IDENTITY",
                format!("{subject}: wrong node type or identity"),
            ));
        }
        Ok(ValidatedUnixNodeIdentity {
            path,
            device: record.unsigned("device")?,
            inode,
            mode,
            nlink,
            mtime_seconds: record.unsigned("mtime_seconds")?,
            mtime_nanoseconds: checked_identity_nanoseconds(
                record,
                "mtime_nanoseconds",
                subject,
            )?,
            ctime_seconds: record.unsigned("ctime_seconds")?,
            ctime_nanoseconds: checked_identity_nanoseconds(
                record,
                "ctime_nanoseconds",
                subject,
            )?,
        })
    }

    pub fn validate_controller_rch_binding(
        record: &CanonicalRecord,
    ) -> TrustResult<ValidatedControllerRch> {
        if record.schema_id != "controller-rch-binding" {
            return Err(TrustError::new(
                "E_CONTROLLER_RCH",
                "controller-rch-binding required",
            ));
        }
        let executable = validate_unix_file_identity(
            record.record("executable")?,
            MAX_GATE_EXECUTABLE_BYTES,
            true,
            "controller RCH executable",
        )?;
        if record.string("version")? != "1.0.49"
            || record.string("commit")? != "40beb520c1f3"
            || !record.boolean("require_remote")?
            || !record.boolean("no_self_healing")?
            || !record.boolean("quiet")?
        {
            return Err(TrustError::new(
                "E_CONTROLLER_RCH",
                "installed RCH version/commit/safety binding",
            ));
        }
        Ok(ValidatedControllerRch {
            executable,
            version: "1.0.49".to_owned(),
            commit: "40beb520c1f3".to_owned(),
        })
    }

    pub fn validate_controller_invocation_plan(
        record: &CanonicalRecord,
        controller: &ValidatedControllerRch,
    ) -> TrustResult<ValidatedControllerInvocation> {
        if record.schema_id != "controller-invocation-plan" {
            return Err(TrustError::new(
                "E_CONTROLLER_INVOCATION",
                "controller-invocation-plan required",
            ));
        }
        let executable = validate_unix_file_identity(
            record.record("executable")?,
            MAX_GATE_EXECUTABLE_BYTES,
            true,
            "controller invocation executable",
        )?;
        if executable != controller.executable {
            return Err(TrustError::new(
                "E_CONTROLLER_INVOCATION",
                "controller executable identity drift",
            ));
        }
        let controller_environment =
            record.environment("controller_environment")?.to_vec();
        let argv = record.strings("argv")?.to_vec();
        let remote_environment = record.environment("remote_environment")?.to_vec();
        validate_environment_array(
            &controller_environment,
            "controller RCH environment",
        )?;
        validate_argument_array(&argv, "controller RCH argv")?;
        validate_environment_array(
            &remote_environment,
            "controller remote environment",
        )?;
        let controller_working_directory =
            record.string("controller_working_directory")?.to_owned();
        validate_absolute_lexical_path(
            &controller_working_directory,
            "controller working directory",
        )?;
        let remote_working_directory_token =
            record.string("remote_working_directory_token")?.to_owned();
        let timeout_seconds = record.unsigned("timeout_seconds")?;
        let requested_worker =
            record.optional_string("requested_worker")?.map(str::to_owned);
        let socket_path = controller_environment
            .iter()
            .find_map(|(key, value)| {
                (key == "RCH_SOCKET_PATH").then_some(value.clone())
            })
            .ok_or_else(|| {
                TrustError::new(
                    "E_CONTROLLER_INVOCATION",
                    "missing RCH_SOCKET_PATH",
                )
            })?;
        validate_absolute_lexical_path(&socket_path, "private RCH socket")?;
        let mut expected_environment = vec![
            ("RCH_NO_SELF_HEALING".to_owned(), "1".to_owned()),
            ("RCH_QUIET".to_owned(), "1".to_owned()),
            ("RCH_REQUIRE_REMOTE".to_owned(), "1".to_owned()),
            ("RCH_SOCKET_PATH".to_owned(), socket_path.clone()),
        ];
        if let Some(worker) = &requested_worker {
            if worker.is_empty()
                || worker.as_bytes().contains(&0)
                || worker.chars().any(char::is_control)
            {
                return Err(TrustError::new(
                    "E_CONTROLLER_INVOCATION",
                    "invalid requested worker",
                ));
            }
            expected_environment.push(("RCH_WORKER".to_owned(), worker.clone()));
        }
        if controller_environment != expected_environment
            || argv.first() != Some(&controller.executable.path)
            || argv.get(1).map(String::as_str) != Some("exec")
            || argv.get(2).map(String::as_str) != Some("--")
            || remote_working_directory_token != "."
            || timeout_seconds != 86_400
            || socket_path.len() > 103
            || !socket_path.ends_with("/rch.sock")
        {
            return Err(TrustError::new(
                "E_CONTROLLER_INVOCATION",
                "controller environment/argv/CWD/timeout binding",
            ));
        }
        Ok(ValidatedControllerInvocation {
            executable,
            controller_environment,
            argv,
            remote_environment,
            controller_working_directory,
            remote_working_directory_token,
            timeout_seconds,
            requested_worker,
            socket_path,
        })
    }

    fn canonical_json_u64(value: &ControlJson, subject: &str) -> TrustResult<u64> {
        let text = control_json_number(value, subject)?;
        if text.is_empty()
            || text.len() > 1 && text.starts_with('0')
            || !text.bytes().all(|byte| byte.is_ascii_digit())
        {
            return Err(TrustError::new(
                "E_RCH_STATUS_JSON",
                format!("{subject}: canonical unsigned integer required"),
            ));
        }
        text.parse::<u64>().map_err(|_| {
            TrustError::new(
                "E_RCH_STATUS_JSON",
                format!("{subject}: unsigned integer overflow"),
            )
        })
    }

    pub fn validate_rch_status_observation(
        record: &CanonicalRecord,
        controller: &ValidatedControllerRch,
        expected_socket_path: &str,
    ) -> TrustResult<ValidatedRchStatus> {
        if record.schema_id != "rch-status-observation" {
            return Err(TrustError::new(
                "E_RCH_STATUS",
                "rch-status-observation required",
            ));
        }
        let expected_argv = vec![
            controller.executable.path.clone(),
            "--quiet".to_owned(),
            "--json".to_owned(),
            "--no-self-healing".to_owned(),
            "--no-hook-auto-start".to_owned(),
            "daemon".to_owned(),
            "status".to_owned(),
        ];
        let expected_environment = vec![
            ("LANG".to_owned(), "C".to_owned()),
            ("LC_ALL".to_owned(), "C".to_owned()),
            ("PATH".to_owned(), "/usr/bin:/bin".to_owned()),
            (
                "RCH_SOCKET_PATH".to_owned(),
                expected_socket_path.to_owned(),
            ),
            ("TZ".to_owned(), "UTC".to_owned()),
        ];
        let argv = record.strings("argv")?.to_vec();
        let environment = record.environment("environment")?.to_vec();
        let stdout = validated_raw_stream_blob(
            record.record("stdout")?,
            16 * 1024,
            "RCH status stdout",
        )?;
        let stderr = validated_raw_stream_blob(
            record.record("stderr")?,
            16 * 1024,
            "RCH status stderr",
        )?;
        if argv != expected_argv
            || environment != expected_environment
            || record.signed("exit_code")? != 0
            || !stderr.bytes.is_empty()
            || !record.boolean("running")?
            || record.string("socket_path")? != expected_socket_path
        {
            return Err(TrustError::new(
                "E_RCH_STATUS",
                "status invocation/result binding",
            ));
        }
        let json = ControlJsonParser::new(&stdout.bytes).parse()?;
        let object = control_json_object(&json, "RCH status response")?;
        if !control_json_exact_fields(
            object,
            &["api_version", "timestamp", "command", "success", "data"],
            &[],
        ) || control_json_string(
            control_json_field(object, "api_version", "RCH status response")?,
            "RCH status api_version",
        )? != "1.0"
            || control_json_string(
                control_json_field(object, "command", "RCH status response")?,
                "RCH status command",
            )? != "daemon status"
            || !control_json_bool(
                control_json_field(object, "success", "RCH status response")?,
                "RCH status success",
            )?
        {
            return Err(TrustError::new(
                "E_RCH_STATUS_JSON",
                "status response envelope",
            ));
        }
        canonical_json_u64(
            control_json_field(object, "timestamp", "RCH status response")?,
            "RCH status timestamp",
        )?;
        let data = control_json_object(
            control_json_field(object, "data", "RCH status response")?,
            "RCH status data",
        )?;
        if !control_json_exact_fields(
            data,
            &["running", "socket_path", "uptime_seconds"],
            &[],
        ) || !control_json_bool(
            control_json_field(data, "running", "RCH status data")?,
            "RCH status running",
        )?
            || control_json_string(
                control_json_field(data, "socket_path", "RCH status data")?,
                "RCH status socket_path",
            )? != expected_socket_path
        {
            return Err(TrustError::new(
                "E_RCH_STATUS_JSON",
                "status response data",
            ));
        }
        let uptime_seconds = canonical_json_u64(
            control_json_field(data, "uptime_seconds", "RCH status data")?,
            "RCH status uptime_seconds",
        )?;
        if record.unsigned("uptime_seconds")? != uptime_seconds {
            return Err(TrustError::new(
                "E_RCH_STATUS",
                "typed uptime and raw JSON disagree",
            ));
        }
        Ok(ValidatedRchStatus {
            argv,
            environment,
            stdout,
            stderr,
            socket_path: expected_socket_path.to_owned(),
            uptime_seconds,
        })
    }

    fn private_controller_temp_root(
        socket_path: &str,
        phase_code: &str,
        run_id: &str,
    ) -> TrustResult<&'static str> {
        // These records are controller-owned but are also parsed by Linux
        // Produce/Attest/Gate images.  The parser's compilation target is not
        // evidence of the controller's OS, so portable record validation must
        // admit either of the policy's two exact lexical controller roots.  The
        // local ordinary controller/audit separately joins the selected root to
        // CONTROLLER_OS_TEMP_ROOT and across all three serialized phases.
        for root in ["/private/tmp", "/tmp"] {
            if socket_path
                == format!("{root}/fnd01/{run_id}/s/{phase_code}/rch.sock")
            {
                return Ok(root);
            }
        }
        Err(TrustError::new(
            "E_RCH_DAEMON",
            "private socket does not match controller temp/run/phase formula",
        ))
    }

    pub fn validate_rch_daemon_pre(
        record: &CanonicalRecord,
        expected_phase: &str,
        run_id: &str,
        controller: &ValidatedControllerRch,
        invocation: &ValidatedControllerInvocation,
    ) -> TrustResult<ValidatedRchDaemonPre> {
        if record.schema_id != "rch-daemon-pre" {
            return Err(TrustError::new(
                "E_RCH_DAEMON",
                "rch-daemon-pre required",
            ));
        }
        let phase_code = match expected_phase {
            "producer" => "p",
            "attester" => "a",
            "gate" => "g",
            _ => {
                return Err(TrustError::new(
                    "E_RCH_DAEMON",
                    "unknown daemon phase",
                ));
            }
        };
        if record.string("phase")? != expected_phase {
            return Err(TrustError::new(
                "E_RCH_DAEMON",
                "daemon pre phase mismatch",
            ));
        }
        let temp_root = private_controller_temp_root(
            &invocation.socket_path,
            phase_code,
            run_id,
        )?;
        let run_directory_path =
            format!("{temp_root}/fnd01/{run_id}/ev/{expected_phase}");
        let socket_path =
            format!("{temp_root}/fnd01/{run_id}/s/{phase_code}/rch.sock");
        let history_path = format!("{run_directory_path}/history.jsonl");
        let stdout_path = format!("{run_directory_path}/rchd.stdout");
        let stderr_path = format!("{run_directory_path}/rchd.stderr");
        let expected_daemon_sha256 = decode_lower_hex::<32>(
            "4d1f57f6442e7f13846e51fcbdf5a8c52ae6a3d381d0fffdd6b97c55ee850735",
            "RCH daemon executable",
        )?;
        let executable = validate_unix_file_identity(
            record.record("executable")?,
            5_517_216,
            true,
            "RCH daemon executable",
        )?;
        let workers_config = validate_unix_file_identity(
            record.record("workers_config")?,
            MAX_FINAL_GATE_INPUT_BYTES,
            false,
            "RCH workers config",
        )?;
        let run_directory = validate_unix_node_identity(
            record.record("run_directory")?,
            "unix-directory-identity",
            0o040_000,
            "RCH daemon run directory",
        )?;
        let socket = validate_unix_node_identity(
            record.record("socket")?,
            "unix-socket-identity",
            0o140_000,
            "RCH daemon socket",
        )?;
        if executable.byte_length != 5_517_216
            || executable.sha256 != expected_daemon_sha256
            || executable == controller.executable
            || executable.path == controller.executable.path
            || run_directory.path != run_directory_path
            || run_directory.mode & 0o177_777 != 0o040_700
            || socket.path != socket_path
            || invocation.socket_path != socket_path
        {
            return Err(TrustError::new(
                "E_RCH_DAEMON",
                "daemon executable/directory/socket identity",
            ));
        }
        let launch_argv = vec![
            executable.path.clone(),
            "--foreground".to_owned(),
            "--socket".to_owned(),
            socket_path.clone(),
            "--workers-config".to_owned(),
            workers_config.path.clone(),
            "--history-file".to_owned(),
            history_path.clone(),
            "--history-capacity".to_owned(),
            "1".to_owned(),
            "--metrics-port".to_owned(),
            "0".to_owned(),
            "--no-hot-reload".to_owned(),
        ];
        let launch_environment = record.environment("launch_environment")?;
        let home = launch_environment
            .iter()
            .find_map(|(key, value)| (key == "HOME").then_some(value.as_str()))
            .ok_or_else(|| TrustError::new("E_RCH_DAEMON", "daemon HOME"))?;
        validate_absolute_lexical_path(home, "daemon HOME")?;
        let expected_launch_environment = [
            ("HOME", home),
            ("LANG", "C"),
            ("LC_ALL", "C"),
            ("PATH", "/usr/bin:/bin"),
            ("RCH_SOCKET_PATH", socket_path.as_str()),
            ("TZ", "UTC"),
        ];
        let child_pid = record.unsigned("child_pid")?;
        if record.strings("launch_argv")? != launch_argv
            || launch_environment
                .iter()
                .map(|(key, value)| (key.as_str(), value.as_str()))
                .ne(expected_launch_environment)
            || !record.boolean("run_directory_was_absent")?
            || !record.boolean("socket_was_absent")?
            || record.string("history_path")? != history_path
            || !record.boolean("history_was_absent")?
            || record.string("stdout_path")? != stdout_path
            || !record.boolean("stdout_was_absent")?
            || record.string("stderr_path")? != stderr_path
            || !record.boolean("stderr_was_absent")?
            || child_pid == 0
            || record.string("evidence_verdict")? != "Pass"
        {
            return Err(TrustError::new(
                "E_RCH_DAEMON",
                "daemon pre invocation/absence/PID binding",
            ));
        }
        let status = validate_rch_status_observation(
            record.record("status")?,
            controller,
            &socket_path,
        )?;
        Ok(ValidatedRchDaemonPre {
            phase: expected_phase.to_owned(),
            executable,
            workers_config,
            run_directory,
            socket,
            status,
            child_pid,
            history_path,
            stdout_path,
            stderr_path,
        })
    }

    fn validate_wait_status(value: &str) -> bool {
        let number = value
            .strip_prefix("exit:")
            .or_else(|| value.strip_prefix("signal:"));
        let Some(number) = number else {
            return false;
        };
        let unsigned = number.strip_prefix('-').unwrap_or(number);
        if unsigned.is_empty()
            || unsigned.len() > 1 && unsigned.starts_with('0')
            || number == "-0"
            || !unsigned.bytes().all(|byte| byte.is_ascii_digit())
        {
            return false;
        }
        number.parse::<i32>().is_ok()
    }

    pub fn validate_rch_daemon_post(
        record: &CanonicalRecord,
        pre: &ValidatedRchDaemonPre,
        controller: &ValidatedControllerRch,
    ) -> TrustResult<ValidatedRchDaemonPost> {
        if record.schema_id != "rch-daemon-post"
            || record.string("phase")? != pre.phase
        {
            return Err(TrustError::new(
                "E_RCH_DAEMON_POST",
                "rch-daemon-post phase/schema",
            ));
        }
        let executable = validate_unix_file_identity(
            record.record("executable")?,
            5_517_216,
            true,
            "post RCH daemon executable",
        )?;
        let run_directory = validate_unix_node_identity(
            record.record("run_directory")?,
            "unix-directory-identity",
            0o040_000,
            "post RCH daemon run directory",
        )?;
        let socket_before_stop = validate_unix_node_identity(
            record.record("socket_before_stop")?,
            "unix-socket-identity",
            0o140_000,
            "post RCH daemon socket",
        )?;
        let status_before_stop = validate_rch_status_observation(
            record.record("status_before_stop")?,
            controller,
            &pre.socket.path,
        )?;
        let history_file = validate_unix_file_identity(
            record.record("history_file")?,
            MAX_RECEIPT_BYTES,
            false,
            "RCH daemon history",
        )?;
        let daemon_stdout = validate_unix_file_identity(
            record.record("daemon_stdout")?,
            32 * 1024 * 1024,
            false,
            "RCH daemon stdout",
        )?;
        let daemon_stderr = validate_unix_file_identity(
            record.record("daemon_stderr")?,
            32 * 1024 * 1024,
            false,
            "RCH daemon stderr",
        )?;
        let child_pid = record.unsigned("child_pid")?;
        let child_wait_status = record.string("child_wait_status")?.to_owned();
        if executable != pre.executable
            || run_directory != pre.run_directory
            || socket_before_stop != pre.socket
            || child_pid != pre.child_pid
            || !validate_wait_status(&child_wait_status)
            || !record.boolean("child_reaped")?
            || !record.boolean("socket_absent_after")?
            || history_file.path != pre.history_path
            || daemon_stdout.path != pre.stdout_path
            || daemon_stderr.path != pre.stderr_path
            || record.string("evidence_verdict")? != "Pass"
        {
            return Err(TrustError::new(
                "E_RCH_DAEMON_POST",
                "daemon pre/post identity/PID/reap binding",
            ));
        }
        Ok(ValidatedRchDaemonPost {
            phase: pre.phase.clone(),
            executable,
            run_directory,
            socket_before_stop,
            status_before_stop,
            child_pid,
            kill_fallback_used: record.boolean("kill_fallback_used")?,
            child_wait_status,
            socket_unlink_performed: record.boolean(
                "socket_unlink_performed",
            )?,
            history_file,
            daemon_stdout,
            daemon_stderr,
        })
    }

