    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub enum GateFallbackNodeKind {
        Absent,
        RegularFile,
        Directory,
        Symlink,
        Special,
    }

    impl GateFallbackNodeKind {
        fn parse(value: &str) -> TrustResult<Self> {
            match value {
                "absent" => Ok(Self::Absent),
                "regular-file" => Ok(Self::RegularFile),
                "directory" => Ok(Self::Directory),
                "symlink" => Ok(Self::Symlink),
                "special" => Ok(Self::Special),
                _ => Err(TrustError::new(
                    "E_GATE_RESULT_RESIDUE",
                    format!("unknown fallback node kind {value:?}"),
                )),
            }
        }
    }

