    pub fn validate_gate_worker_observation(
        record: &CanonicalRecord,
        expected_gate_input_sha256: [u8; 32],
    ) -> TrustResult<GateWorkerObservation> {
        if record.schema_id != "gate-worker-observation" {
            return Err(TrustError::new(
                "E_GATE_RESULT_WORKER",
                "gate-worker-observation required",
            ));
        }
        let bounded_text = |field: &str, maximum: usize| -> TrustResult<String> {
            let value = record.string(field)?;
            if value.is_empty()
                || value.len() > maximum
                || value.contains('\r')
                || value.contains('\n')
                || value.chars().any(char::is_control)
            {
                return Err(TrustError::new(
                    "E_GATE_RESULT_WORKER",
                    format!("{field}: invalid worker text"),
                ));
            }
            Ok(value.to_owned())
        };
        let worker_id = bounded_text("worker_id", 1024)?;
        let os = bounded_text("os", 32)?;
        let architecture = bounded_text("arch", 32)?;
        let kernel_release = bounded_text("kernel_release", 1024)?;
        let hostname = bounded_text("hostname", 1024)?;
        let process_id = record.unsigned("process_id")?;
        let parent_process_id = record.unsigned("parent_process_id")?;
        let remote_repository_root =
            bounded_text("remote_repository_root", MAX_ABSOLUTE_PATH_BYTES)?;
        validate_absolute_lexical_path(
            &remote_repository_root,
            "gate worker remote repository root",
        )?;
        let gate_input_sha256 = decode_lower_hex::<32>(
            record.string("gate_input_sha256")?,
            "gate worker gate-input SHA-256",
        )?;
        if os != "linux"
            || architecture != "x86_64"
            || process_id == 0
            || parent_process_id == 0
            || gate_input_sha256 != expected_gate_input_sha256
        {
            return Err(TrustError::new(
                "E_GATE_RESULT_WORKER",
                "worker platform/process/gate-input binding",
            ));
        }
        Ok(GateWorkerObservation {
            worker_id,
            os,
            architecture,
            kernel_release,
            hostname,
            machine_id_sha256: decode_lower_hex::<32>(
                record.string("machine_id_sha256")?,
                "gate worker machine-id SHA-256",
            )?,
            process_id,
            parent_process_id,
            remote_repository_root,
            gate_input_sha256,
        })
    }

    fn validate_final_gate_input_rechecks(
        declared_count: u64,
        records: &[CanonicalRecord],
        expected_bindings: &[ValidatedFileBinding],
        run_id: &str,
        seal: &FinalGateSeal,
    ) -> TrustResult<Vec<ValidatedGateInputRecheck>> {
        let expected_paths = expected_final_gate_input_recheck_paths(run_id);
        if declared_count != 13
            || records.len() != expected_paths.len()
            || expected_bindings.len() != expected_paths.len()
        {
            return Err(TrustError::new(
                "E_GATE_RESULT_RECHECK",
                "exactly 13 rechecks and expected bindings required",
            ));
        }
        for (expected, path) in expected_bindings.iter().zip(&expected_paths) {
            if expected.path.as_str() != path.as_str()
                || expected.binding.byte_length == 0
            {
                return Err(TrustError::new(
                    "E_GATE_RESULT_RECHECK",
                    "expected input bindings must use canonical sorted paths",
                ));
            }
        }
        let known_sealed_bindings = [
            (
                format!(".fnd01-run/controller/{run_id}/producer-outer.bin"),
                seal.producer_outer_transport,
            ),
            (
                "evidence/fnd-01/final-attestation.toml".to_owned(),
                seal.final_attestation,
            ),
            (
                format!(".fnd01-run/controller/{run_id}/attester-outer.bin"),
                seal.attester_outer_transport,
            ),
            (
                format!(".fnd01-run/controller/{run_id}/final-gate"),
                seal.gate_executable,
            ),
            (
                format!(".fnd01-run/controller/{run_id}/final-gate-input.bin"),
                seal.gate_input,
            ),
        ];
        for (path, binding) in known_sealed_bindings {
            if !expected_bindings
                .iter()
                .any(|expected| expected.path == path && expected.binding == binding)
            {
                return Err(TrustError::new(
                    "E_GATE_RESULT_RECHECK",
                    format!("{path}: expected binding disagrees with external seal"),
                ));
            }
        }
        let mut validated = Vec::new();
        validated.try_reserve_exact(records.len()).map_err(|_| {
            TrustError::new(
                "E_GATE_RESULT_RECHECK",
                "cannot reserve validated rechecks",
            )
        })?;
        for ((record, expected), path) in records
            .iter()
            .zip(expected_bindings)
            .zip(expected_paths)
        {
            if record.schema_id != "gate-input-recheck"
                || record.string("id")? != path.as_str()
                || !record.boolean("byte_equal")?
            {
                return Err(TrustError::new(
                    "E_GATE_RESULT_RECHECK",
                    format!("{path}: schema/id/equality marker"),
                ));
            }
            let before = validated_file_binding(
                record.record("before")?,
                &format!("{path}: before"),
            )?;
            let after = validated_file_binding(
                record.record("after")?,
                &format!("{path}: after"),
            )?;
            if before.path.as_str() != path.as_str()
                || after.path.as_str() != path.as_str()
                || before.binding != expected.binding
                || after.binding != expected.binding
            {
                return Err(TrustError::new(
                    "E_GATE_RESULT_RECHECK",
                    format!("{path}: before/after/expected binding mismatch"),
                ));
            }
            validated.push(ValidatedGateInputRecheck {
                id: path,
                before,
                after,
                byte_equal: true,
            });
        }
        Ok(validated)
    }

    fn validate_final_gate_fallback_residues(
        declared_count: u64,
        records: &[CanonicalRecord],
    ) -> TrustResult<Vec<ValidatedGateFallbackResidue>> {
        if declared_count != 3
            || records.len() != FINAL_GATE_FALLBACK_CANDIDATE_PATHS.len()
        {
            return Err(TrustError::new(
                "E_GATE_RESULT_RESIDUE",
                "exactly three fallback residue rows required",
            ));
        }
        let mut validated = Vec::new();
        validated.try_reserve_exact(records.len()).map_err(|_| {
            TrustError::new(
                "E_GATE_RESULT_RESIDUE",
                "cannot reserve validated fallback residues",
            )
        })?;
        for (record, expected_path) in records
            .iter()
            .zip(FINAL_GATE_FALLBACK_CANDIDATE_PATHS)
        {
            if record.schema_id != "gate-fallback-residue"
                || record.string("path")? != expected_path
                || record.string("preexisting_disposition")?
                    != FINAL_GATE_FALLBACK_PREEXISTING_DISPOSITION
                || record.string("postreturn_disposition")?
                    != FINAL_GATE_FALLBACK_POSTRETURN_DISPOSITION
                || record.boolean("evidence_eligible")?
            {
                return Err(TrustError::new(
                    "E_GATE_RESULT_RESIDUE",
                    format!("{expected_path}: fixed residue fields"),
                ));
            }
            let node_kind =
                GateFallbackNodeKind::parse(record.string("node_kind")?)?;
            let byte_length = record.optional_unsigned("byte_length")?;
            let sha256_text = record.optional_string("sha256")?;
            let sha256 = sha256_text
                .map(|value| {
                    decode_lower_hex::<32>(
                        value,
                        &format!("{expected_path}: fallback SHA-256"),
                    )
                })
                .transpose()?;
            if node_kind == GateFallbackNodeKind::RegularFile {
                if byte_length.is_none() || sha256.is_none() {
                    return Err(TrustError::new(
                        "E_GATE_RESULT_RESIDUE",
                        format!("{expected_path}: regular-file options"),
                    ));
                }
            } else if byte_length.is_some() || sha256.is_some() {
                return Err(TrustError::new(
                    "E_GATE_RESULT_RESIDUE",
                    format!("{expected_path}: non-file options must be absent"),
                ));
            }
            validated.push(ValidatedGateFallbackResidue {
                path: expected_path.to_owned(),
                preexisting_disposition:
                    FINAL_GATE_FALLBACK_PREEXISTING_DISPOSITION.to_owned(),
                postreturn_disposition:
                    FINAL_GATE_FALLBACK_POSTRETURN_DISPOSITION.to_owned(),
                node_kind,
                byte_length,
                sha256,
                evidence_eligible: false,
            });
        }
        Ok(validated)
    }

    pub fn validate_final_gate_result(
        record: CanonicalRecord,
        run_id: &str,
        gate_input: &ValidatedGateInput,
        expected_input_rechecks: &[ValidatedFileBinding],
        seal: &FinalGateSeal,
    ) -> TrustResult<ValidatedFinalGateResult> {
        let decoded_run_id = decode_lower_hex::<16>(run_id, "final gate result run ID")?;
        if decoded_run_id.iter().all(|byte| *byte == 0)
            || decoded_run_id != seal.run_id
            || record.schema_id != "final-gate-result"
            || record.string("format")? != "FND01GATERESULTv3"
            || record.unsigned("schema_version")? != 2
            || record.string("run_id")? != run_id
            || gate_input.record.string("run_id")? != run_id
            || record.signed("rch_exit_code")? != 0
            || record.string("evidence_verdict")? != "Pass"
        {
            return Err(TrustError::new(
                "E_GATE_RESULT",
                "root/run/exit/verdict fields",
            ));
        }
        let gate_input_sha256 = decode_lower_hex::<32>(
            record.string("gate_input_sha256")?,
            "final gate result gate-input SHA-256",
        )?;
        if gate_input_sha256 != seal.gate_input.sha256 {
            return Err(TrustError::new(
                "E_GATE_RESULT",
                "gate-input digest disagrees with external seal",
            ));
        }
        let final_gate_seal_sha256 = decode_lower_hex::<32>(
            record.string("final_gate_seal_sha256")?,
            "final gate result external seal SHA-256",
        )?;
        if final_gate_seal_sha256 != seal.seal_sha256 {
            return Err(TrustError::new(
                "E_GATE_RESULT_SEAL",
                "result does not join the external final-gate seal",
            ));
        }
        let stdout = validated_raw_stream_blob(
            record.record("stdout")?,
            MAX_FINAL_GATE_STDOUT_BYTES as u64,
            "final gate stdout",
        )?;
        let stderr = validated_raw_stream_blob(
            record.record("stderr")?,
            MAX_FINAL_GATE_STDERR_BYTES,
            "final gate stderr",
        )?;
        if !stderr.bytes.is_empty() {
            return Err(TrustError::new(
                "E_GATE_RESULT_STREAM",
                "final gate stderr must be empty",
            ));
        }
        let handshake = parse_gate_handshake(&stdout.bytes, "final gate stdout")?;
        let actual_worker = validate_gate_worker_observation(
            record.record("actual_worker")?,
            gate_input_sha256,
        )?;
        if handshake != actual_worker
            || handshake.gate_input_sha256 != gate_input_sha256
        {
            return Err(TrustError::new(
                "E_GATE_RESULT_WORKER",
                "typed worker and raw stdout handshake disagree",
            ));
        }
        let daemon_post = validate_rch_daemon_post(
            record.record("daemon_post")?,
            &gate_input.daemon_pre,
            &gate_input.controller,
        )?;
        let input_rechecks = validate_final_gate_input_rechecks(
            record.unsigned("input_recheck_count")?,
            record.records("input_recheck")?,
            expected_input_rechecks,
            run_id,
            seal,
        )?;
        let fallback_residues = validate_final_gate_fallback_residues(
            record.unsigned("fallback_residue_count")?,
            record.records("fallback_residue")?,
        )?;
        Ok(ValidatedFinalGateResult {
            record,
            run_id: run_id.to_owned(),
            gate_input_sha256,
            actual_worker,
            rch_exit_code: 0,
            stdout,
            stderr,
            daemon_post,
            input_rechecks,
            fallback_residues,
            final_gate_seal_sha256,
            evidence_verdict: "Pass".to_owned(),
        })
    }

    // ---- End FND01GATERESULTv3 strict parser and semantic join ----

    #[cfg(test)]
    mod final_gate_result_tests {
        use super::*;

        fn zero_record(schema_id: &'static str) -> CanonicalRecord {
            let schema = canonical_schema(schema_id).expect("known test schema");
            let fields = schema
                .mask
                .bytes()
                .enumerate()
                .map(|(ordinal, kind)| match kind {
                    b's' => CanonicalValue::String(String::new()),
                    b'u' => CanonicalValue::Unsigned(0),
                    b'i' => CanonicalValue::Signed(0),
                    b'b' => CanonicalValue::Boolean(false),
                    b'x' => CanonicalValue::RawBytes(Vec::new()),
                    b'a' => CanonicalValue::StringArray(Vec::new()),
                    b'e' => CanonicalValue::EnvironmentPairs(Vec::new()),
                    b'r' => CanonicalValue::Record(Box::new(zero_record(
                        child_schema(schema_id, ordinal)
                            .expect("record child schema"),
                    ))),
                    b'q' => CanonicalValue::RecordArray(Vec::new()),
                    b'S' => CanonicalValue::OptionalString(None),
                    b'U' => CanonicalValue::OptionalUnsigned(None),
                    b'B' => CanonicalValue::OptionalBoolean(None),
                    _ => panic!("unexpected canonical kind {kind:#x}"),
                })
                .collect();
            CanonicalRecord {
                schema_id: schema.id,
                fields,
                field_offsets: Vec::new(),
            }
        }

        fn file_binding_record(
            path: &str,
            binding: FileBinding,
        ) -> CanonicalRecord {
            CanonicalRecord {
                schema_id: "file-binding",
                fields: vec![
                    CanonicalValue::String(path.to_owned()),
                    CanonicalValue::Unsigned(binding.byte_length),
                    CanonicalValue::String(encode_lower_hex(&binding.sha256)),
                ],
                field_offsets: Vec::new(),
            }
        }

        fn input_recheck_record(
            expected: &ValidatedFileBinding,
        ) -> CanonicalRecord {
            CanonicalRecord {
                schema_id: "gate-input-recheck",
                fields: vec![
                    CanonicalValue::String(expected.path.clone()),
                    CanonicalValue::Record(Box::new(file_binding_record(
                        &expected.path,
                        expected.binding,
                    ))),
                    CanonicalValue::Record(Box::new(file_binding_record(
                        &expected.path,
                        expected.binding,
                    ))),
                    CanonicalValue::Boolean(true),
                ],
                field_offsets: Vec::new(),
            }
        }

        fn fallback_residue_record(
            path: &str,
            node_kind: &str,
            byte_length: Option<u64>,
            sha256: Option<[u8; 32]>,
        ) -> CanonicalRecord {
            CanonicalRecord {
                schema_id: "gate-fallback-residue",
                fields: vec![
                    CanonicalValue::String(path.to_owned()),
                    CanonicalValue::String(
                        FINAL_GATE_FALLBACK_PREEXISTING_DISPOSITION.to_owned(),
                    ),
                    CanonicalValue::String(
                        FINAL_GATE_FALLBACK_POSTRETURN_DISPOSITION.to_owned(),
                    ),
                    CanonicalValue::String(node_kind.to_owned()),
                    CanonicalValue::OptionalUnsigned(byte_length),
                    CanonicalValue::OptionalString(
                        sha256.map(|digest| encode_lower_hex(&digest)),
                    ),
                    CanonicalValue::Boolean(false),
                ],
                field_offsets: Vec::new(),
            }
        }

        fn common_test_seal(run_id: [u8; 16], binding: FileBinding) -> FinalGateSeal {
            FinalGateSeal {
                run_id,
                final_attestation: binding,
                producer_outer_transport: binding,
                attester_outer_transport: binding,
                gate_executable: binding,
                gate_input: binding,
                authoring_closure_sha256: [2; 32],
                integration_seal_sha256: [3; 32],
                seal_sha256: [4; 32],
            }
        }

        #[test]
        fn final_gate_result_parser_requires_one_bounded_prefixed_record() {
            let encoded = encode_canonical_record(
                &zero_record("final-gate-result"),
                "final gate result parser fixture",
            )
            .expect("encode final-gate-result fixture");
            let mut bytes = FINAL_GATE_RESULT_PREFIX.to_vec();
            bytes.extend_from_slice(&encoded);
            assert_eq!(
                parse_final_gate_result(&bytes, "canonical final gate result")
                    .expect("one canonical result")
                    .schema_id,
                "final-gate-result",
            );

            let mut trailing_record = bytes.clone();
            trailing_record.extend_from_slice(&encoded);
            assert!(parse_final_gate_result(
                &trailing_record,
                "two final gate results",
            )
            .is_err());

            let mut wrong_prefix = bytes.clone();
            wrong_prefix[0] = b'X';
            assert!(parse_final_gate_result(&wrong_prefix, "wrong prefix").is_err());

            let oversized = vec![
                0;
                usize::try_from(MAX_FINAL_GATE_RESULT_BYTES)
                    .expect("test result bound")
                    + 1
            ];
            assert!(parse_final_gate_result(&oversized, "oversized result").is_err());
        }

        #[test]
        fn final_gate_rechecks_join_all_expected_sorted_bindings() {
            let run_id = "0123456789abcdef0123456789abcdef";
            let binding = FileBinding {
                byte_length: 17,
                sha256: [9; 32],
            };
            let expected = expected_final_gate_input_recheck_paths(run_id)
                .into_iter()
                .map(|path| ValidatedFileBinding { path, binding })
                .collect::<Vec<_>>();
            let records = expected
                .iter()
                .map(input_recheck_record)
                .collect::<Vec<_>>();
            let seal = common_test_seal([1; 16], binding);
            let validated = validate_final_gate_input_rechecks(
                13,
                &records,
                &expected,
                run_id,
                &seal,
            )
            .expect("exact sorted recheck binding join");
            assert_eq!(validated.len(), 13);

            let mut reordered = records;
            reordered.swap(0, 1);
            assert!(validate_final_gate_input_rechecks(
                13,
                &reordered,
                &expected,
                run_id,
                &seal,
            )
            .is_err());
        }

        #[test]
        fn fallback_residue_options_follow_node_kind_cardinality() {
            let records = vec![
                fallback_residue_record("target/debug", "absent", None, None),
                fallback_residue_record(
                    "target/doc",
                    "regular-file",
                    Some(0),
                    Some([7; 32]),
                ),
                fallback_residue_record(
                    "target/release",
                    "directory",
                    None,
                    None,
                ),
            ];
            let validated = validate_final_gate_fallback_residues(3, &records)
                .expect("canonical fallback residue set");
            assert_eq!(validated.len(), 3);
            assert_eq!(
                validated[1].node_kind,
                GateFallbackNodeKind::RegularFile,
            );
            assert_eq!(validated[1].byte_length, Some(0));

            let mut partial_file = records;
            partial_file[1] = fallback_residue_record(
                "target/doc",
                "regular-file",
                Some(1),
                None,
            );
            assert!(validate_final_gate_fallback_residues(3, &partial_file).is_err());
        }
    }

    #[derive(Debug, Clone)]
    struct ClosedTomlSection {
        path: String,
        array: bool,
        fields: BTreeMap<String, String>,
        field_order: Vec<String>,
    }

    fn strip_closed_toml_comment(value: &str) -> TrustResult<String> {
        let mut quoted = false;
        let mut escaped = false;
        for (index, character) in value.char_indices() {
            if escaped {
                escaped = false;
                continue;
            }
            if quoted && character == '\\' {
                escaped = true;
                continue;
            }
            if character == '"' {
                quoted = !quoted;
            } else if character == '#' && !quoted {
                return Err(TrustError::new(
                    "E_ATTESTATION_TOML",
                    format!("comment at byte {index} is noncanonical"),
                ));
            }
        }
        if quoted || escaped {
            return Err(TrustError::new(
                "E_ATTESTATION_TOML",
                "unterminated string",
            ));
        }
        Ok(value.to_owned())
    }

    fn valid_bare_toml_key(value: &str) -> bool {
        !value.is_empty()
            && value.bytes().all(|byte| {
                byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-')
            })
    }

    fn toml_value_is_complete(value: &str) -> TrustResult<bool> {
        let mut quoted = false;
        let mut escaped = false;
        let mut square = 0usize;
        let mut brace = 0usize;
        for character in value.chars() {
            if escaped {
                escaped = false;
                continue;
            }
            if quoted && character == '\\' {
                escaped = true;
                continue;
            }
            if character == '"' {
                quoted = !quoted;
                continue;
            }
            if quoted {
                continue;
            }
            match character {
                '[' => {
                    square = square.checked_add(1).ok_or_else(|| {
                        TrustError::new("E_ATTESTATION_TOML", "array depth")
                    })?;
                }
                ']' => {
                    square = square.checked_sub(1).ok_or_else(|| {
                        TrustError::new("E_ATTESTATION_TOML", "array close")
                    })?;
                }
                '{' => {
                    brace = brace.checked_add(1).ok_or_else(|| {
                        TrustError::new("E_ATTESTATION_TOML", "inline depth")
                    })?;
                }
                '}' => {
                    brace = brace.checked_sub(1).ok_or_else(|| {
                        TrustError::new("E_ATTESTATION_TOML", "inline close")
                    })?;
                }
                _ => {}
            }
        }
        if escaped {
            return Err(TrustError::new(
                "E_ATTESTATION_TOML",
                "dangling string escape",
            ));
        }
        Ok(!quoted && square == 0 && brace == 0)
    }

    fn parse_closed_toml(
        bytes: &[u8],
        maximum_bytes: u64,
        subject: &str,
    ) -> TrustResult<Vec<ClosedTomlSection>> {
        if bytes.is_empty()
            || u64::try_from(bytes.len()).unwrap_or(u64::MAX)
                > maximum_bytes
            || bytes.starts_with(&[0xef, 0xbb, 0xbf])
            || bytes.contains(&0)
            || bytes.contains(&b'\r')
            || !bytes.ends_with(b"\n")
        {
            return Err(TrustError::new(
                "E_ATTESTATION_TOML",
                format!("{subject}: noncanonical text envelope"),
            ));
        }
        let text = std::str::from_utf8(bytes).map_err(|_| {
            TrustError::new("E_ATTESTATION_TOML", "UTF-8 required")
        })?;
        let mut sections = vec![ClosedTomlSection {
            path: String::new(),
            array: false,
            fields: BTreeMap::new(),
            field_order: Vec::new(),
        }];
        let mut current = 0usize;
        for (line_index, raw) in text.lines().enumerate() {
            let line = strip_closed_toml_comment(raw)?;
            if line.is_empty() || line.trim() != line {
                return Err(TrustError::new(
                    "E_ATTESTATION_TOML",
                    format!("line {}: blank/edge whitespace is noncanonical", line_index + 1),
                ));
            }
            if line.starts_with('[') {
                let (array, inner) = line
                    .strip_prefix("[[")
                    .and_then(|value| value.strip_suffix("]]"))
                    .map(|inner| (true, inner))
                    .or_else(|| {
                        line.strip_prefix('[')
                            .and_then(|value| value.strip_suffix(']'))
                            .map(|inner| (false, inner))
                    })
                    .ok_or_else(|| {
                        TrustError::new(
                            "E_ATTESTATION_TOML",
                            format!("line {}: malformed table", line_index + 1),
                        )
                    })?;
                if inner.is_empty()
                    || inner.split('.').any(|part| !valid_bare_toml_key(part))
                    || sections.len() >= 1_000_000
                {
                    return Err(TrustError::new(
                        "E_ATTESTATION_TOML",
                        format!("line {}: table collision", line_index + 1),
                    ));
                }
                sections.push(ClosedTomlSection {
                    path: inner.to_owned(),
                    array,
                    fields: BTreeMap::new(),
                    field_order: Vec::new(),
                });
                current = sections.len() - 1;
                continue;
            }
            let (key, value) = line.split_once(" = ").ok_or_else(|| {
                TrustError::new(
                    "E_ATTESTATION_TOML",
                    format!("line {}: exact `key = value` required", line_index + 1),
                )
            })?;
            if !valid_bare_toml_key(key)
                || value.is_empty()
                || value.contains('{')
                || value.contains('}')
                || !toml_value_is_complete(value)?
                || sections[current].fields.len() >= 512
            {
                return Err(TrustError::new(
                    "E_ATTESTATION_TOML",
                    format!("line {}: invalid assignment", line_index + 1),
                ));
            }
            if sections[current]
                .fields
                .insert(key.to_owned(), value.to_owned())
                .is_some()
            {
                return Err(TrustError::new(
                    "E_ATTESTATION_TOML",
                    format!("line {}: duplicate key", line_index + 1),
                ));
            }
            sections[current].field_order.push(key.to_owned());
        }
        Ok(sections)
    }

    fn decode_toml_basic_string(value: &str, subject: &str) -> TrustResult<String> {
        let inner = value
            .strip_prefix('"')
            .and_then(|value| value.strip_suffix('"'))
            .ok_or_else(|| TrustError::new("E_ATTESTATION_VALUE", subject))?;
        let mut output = String::new();
        let mut characters = inner.chars();
        while let Some(character) = characters.next() {
            if character != '\\' {
                if character.is_control() {
                    return Err(TrustError::new("E_ATTESTATION_VALUE", subject));
                }
                output.push(character);
                continue;
            }
            let escaped = characters.next().ok_or_else(|| {
                TrustError::new("E_ATTESTATION_VALUE", subject)
            })?;
            output.push(match escaped {
                'b' => '\u{0008}',
                't' => '\t',
                'n' => '\n',
                'f' => '\u{000c}',
                'r' => '\r',
                '"' => '"',
                '\\' => '\\',
                _ => {
                    return Err(TrustError::new(
                        "E_ATTESTATION_VALUE",
                        subject,
                    ));
                }
            });
        }
        Ok(output)
    }

    fn canonical_toml_u64(value: &str, subject: &str) -> TrustResult<u64> {
        if value.is_empty()
            || (value.len() > 1 && value.starts_with('0'))
            || !value.bytes().all(|byte| byte.is_ascii_digit())
        {
            return Err(TrustError::new("E_ATTESTATION_VALUE", subject));
        }
        let parsed = value.parse::<u64>().map_err(|_| {
            TrustError::new("E_ATTESTATION_VALUE", subject)
        })?;
        if parsed > (u64::MAX >> 1) {
            return Err(TrustError::new("E_ATTESTATION_VALUE", subject));
        }
        Ok(parsed)
    }

    fn canonical_toml_i64(value: &str, subject: &str) -> TrustResult<i64> {
        let unsigned = value.strip_prefix('-').unwrap_or(value);
        if unsigned.is_empty()
            || (unsigned.len() > 1 && unsigned.starts_with('0'))
            || value == "-0"
            || !unsigned.bytes().all(|byte| byte.is_ascii_digit())
        {
            return Err(TrustError::new("E_ATTESTATION_VALUE", subject));
        }
        value.parse::<i64>().map_err(|_| {
            TrustError::new("E_ATTESTATION_VALUE", subject)
        })
    }

    fn canonical_toml_string(value: &str, subject: &str) -> TrustResult<String> {
        let decoded = decode_toml_basic_string(value, subject)?;
        let mut encoded = String::from("\"");
        for character in decoded.chars() {
            match character {
                '\u{0008}' => encoded.push_str("\\b"),
                '\t' => encoded.push_str("\\t"),
                '\n' => encoded.push_str("\\n"),
                '\u{000c}' => encoded.push_str("\\f"),
                '\r' => encoded.push_str("\\r"),
                '"' => encoded.push_str("\\\""),
                '\\' => encoded.push_str("\\\\"),
                character if character.is_control() => {
                    return Err(TrustError::new(
                        "E_ATTESTATION_VALUE",
                        subject,
                    ));
                }
                character => encoded.push(character),
            }
        }
        encoded.push('"');
        if encoded != value {
            return Err(TrustError::new(
                "E_ATTESTATION_VALUE",
                format!("{subject}: nonminimal string encoding"),
            ));
        }
        Ok(decoded)
    }

    fn canonical_toml_array_items<'a>(
        value: &'a str,
        subject: &str,
    ) -> TrustResult<Vec<&'a str>> {
        let inner = value
            .strip_prefix('[')
            .and_then(|value| value.strip_suffix(']'))
            .ok_or_else(|| TrustError::new("E_ATTESTATION_VALUE", subject))?;
        if inner.is_empty() {
            return Ok(Vec::new());
        }
        let mut quoted = false;
        let mut escaped = false;
        let mut depth = 0usize;
        let mut start = 0usize;
        let mut items = Vec::new();
        let bytes = inner.as_bytes();
        let mut index = 0usize;
        while index < bytes.len() {
            let byte = bytes[index];
            if escaped {
                escaped = false;
                index += 1;
                continue;
            }
            if quoted && byte == b'\\' {
                escaped = true;
                index += 1;
                continue;
            }
            if byte == b'"' {
                quoted = !quoted;
                index += 1;
                continue;
            }
            if !quoted {
                match byte {
                    b'[' => depth = depth.checked_add(1).ok_or_else(|| {
                        TrustError::new("E_ATTESTATION_VALUE", subject)
                    })?,
                    b']' => depth = depth.checked_sub(1).ok_or_else(|| {
                        TrustError::new("E_ATTESTATION_VALUE", subject)
                    })?,
                    b',' if depth == 0 => {
                        if bytes.get(index + 1) != Some(&b' ') {
                            return Err(TrustError::new(
                                "E_ATTESTATION_VALUE",
                                format!("{subject}: exact comma-space delimiter required"),
                            ));
                        }
                        let item = inner.get(start..index).ok_or_else(|| {
                            TrustError::new("E_ATTESTATION_VALUE", subject)
                        })?;
                        if item.is_empty() || item.trim() != item {
                            return Err(TrustError::new(
                                "E_ATTESTATION_VALUE",
                                subject,
                            ));
                        }
                        items.push(item);
                        index += 2;
                        start = index;
                        continue;
                    }
                    _ => {}
                }
            }
            index += 1;
        }
        if quoted || escaped || depth != 0 {
            return Err(TrustError::new("E_ATTESTATION_VALUE", subject));
        }
        let last = inner.get(start..).ok_or_else(|| {
            TrustError::new("E_ATTESTATION_VALUE", subject)
        })?;
        if last.is_empty() || last.trim() != last {
            return Err(TrustError::new("E_ATTESTATION_VALUE", subject));
        }
        items.push(last);
        Ok(items)
    }

    fn validate_canonical_toml_value(
        value: &str,
        kind: u8,
        subject: &str,
    ) -> TrustResult<()> {
        match kind {
            b's' => {
                let _ = canonical_toml_string(value, subject)?;
            }
            b'u' => {
                let _ = canonical_toml_u64(value, subject)?;
            }
            b'i' => {
                let _ = canonical_toml_i64(value, subject)?;
            }
            b'b' => {
                if !matches!(value, "true" | "false") {
                    return Err(TrustError::new("E_ATTESTATION_VALUE", subject));
                }
            }
            b'a' => {
                for (index, item) in canonical_toml_array_items(value, subject)?
                    .into_iter()
                    .enumerate()
                {
                    let _ = canonical_toml_string(
                        item,
                        &format!("{subject}[{index}]"),
                    )?;
                }
            }
            b'e' => {
                for (index, item) in canonical_toml_array_items(value, subject)?
                    .into_iter()
                    .enumerate()
                {
                    let pair =
                        canonical_toml_array_items(item, &format!("{subject}[{index}]"))?;
                    if pair.len() != 2 {
                        return Err(TrustError::new(
                            "E_ATTESTATION_VALUE",
                            subject,
                        ));
                    }
                    for (part, value) in pair.into_iter().enumerate() {
                        let _ = canonical_toml_string(
                            value,
                            &format!("{subject}[{index}][{part}]"),
                        )?;
                    }
                }
            }
            b'S' => {
                let items = canonical_toml_array_items(value, subject)?;
                if items.len() > 1 {
                    return Err(TrustError::new("E_ATTESTATION_VALUE", subject));
                }
                if let Some(item) = items.first() {
                    let _ = canonical_toml_string(item, subject)?;
                }
            }
            b'q' => {
                if value != "[]" {
                    return Err(TrustError::new("E_ATTESTATION_VALUE", subject));
                }
            }
            _ => {
                return Err(TrustError::new(
                    "E_ATTESTATION_VALUE",
                    format!("{subject}: unknown direct type"),
                ));
            }
        }
        Ok(())
    }

