        #[test]
        fn ordinary_handoff_argv_authority_rejects_every_mutated_position() {
            let run_id = "0123456789abcdef0123456789abcdef";
            assert!(matches!(ordinary_decode_run_id("0"), Err(OrdinaryHandoffArgumentFailure::RunIdLength(_))));
            assert!(matches!(ordinary_decode_run_id(&"g".repeat(32)), Err(OrdinaryHandoffArgumentFailure::RunIdFormat(_))));
            assert!(matches!(ordinary_decode_run_id(&"0".repeat(32)), Err(OrdinaryHandoffArgumentFailure::RunIdNonzero(_))));
            assert!(std::panic::catch_unwind(|| ordinary_read_exact_environment(&["A", "A"])).is_err());
            let executable = "/repo/target/control-harness";
            let produce = expected_ordinary_handoff_argv(
                BootstrapMode::Produce,
                executable,
                run_id,
            )
            .expect("produce handoff authority");
            validate_ordinary_handoff_argv(
                &produce,
                BootstrapMode::Produce,
                executable,
                run_id,
                &produce[4],
            )
            .expect("exact produce handoff");
            for index in 0..produce.len() {
                let mut changed = produce.clone();
                changed[index].push('x');
                assert!(
                    validate_ordinary_handoff_argv(
                        &changed,
                        BootstrapMode::Produce,
                        executable,
                        run_id,
                        &produce[4],
                    )
                    .is_err(),
                    "argv position {index} must be bound",
                );
            }
            assert!(validate_ordinary_handoff_argv(
                &produce[..4],
                BootstrapMode::Produce,
                executable,
                run_id,
                &produce[4],
            )
            .is_err());
            let mut longer = produce.clone();
            longer.push("extra".to_owned());
            assert!(validate_ordinary_handoff_argv(
                &longer,
                BootstrapMode::Produce,
                executable,
                run_id,
                &produce[4],
            )
            .is_err());

            let attest = expected_ordinary_handoff_argv(
                BootstrapMode::Attest,
                executable,
                run_id,
            )
            .expect("attest handoff authority");
            validate_ordinary_handoff_argv(
                &attest,
                BootstrapMode::Attest,
                executable,
                run_id,
                &attest[4],
            )
            .expect("exact attest handoff");
            assert!(validate_ordinary_handoff_argv(
                &attest,
                BootstrapMode::Produce,
                executable,
                run_id,
                &attest[4],
            )
            .is_err());
            assert!(validate_ordinary_handoff_argv(
                &produce,
                BootstrapMode::Produce,
                executable,
                run_id,
                ".fnd01-run/other/control-ledger.bin",
            )
            .is_err());
        }

        #[test]
        fn ordinary_supply_path_authority_is_role_derived_and_lexically_exact() {
            let root = Path::new("/repo");
            let run_id = "0123456789abcdef0123456789abcdef";
            let produce =
                "/repo/.fnd01-run/integration-producer/0123456789abcdef0123456789abcdef/supply-bundle.bin";
            assert_eq!(
                validate_ordinary_supply_path(
                    produce,
                    root,
                    BootstrapMode::Produce,
                    run_id,
                )
                .expect("exact producer supply path"),
                ".fnd01-run/integration-producer/0123456789abcdef0123456789abcdef/supply-bundle.bin",
            );
            let attest = "/repo/evidence/fnd-01/integration/supply-bundle.bin";
            assert_eq!(
                validate_ordinary_supply_path(
                    attest,
                    root,
                    BootstrapMode::Attest,
                    run_id,
                )
                .expect("exact attester supply path"),
                "evidence/fnd-01/integration/supply-bundle.bin",
            );
            for invalid in [
                ".fnd01-run/integration-producer/0123456789abcdef0123456789abcdef/supply-bundle.bin",
                "/repo/.fnd01-run/independent-attester/0123456789abcdef0123456789abcdef/supply-bundle.bin",
                "/repo/.fnd01-run/integration-producer/1123456789abcdef0123456789abcdef/supply-bundle.bin",
                "/repo/./.fnd01-run/integration-producer/0123456789abcdef0123456789abcdef/supply-bundle.bin",
                "/repo//.fnd01-run/integration-producer/0123456789abcdef0123456789abcdef/supply-bundle.bin",
                attest,
            ] {
                assert!(
                    validate_ordinary_supply_path(
                        invalid,
                        root,
                        BootstrapMode::Produce,
                        run_id,
                    )
                    .is_err(),
                    "{invalid} must not satisfy the producer path authority",
                );
            }
            assert!(validate_ordinary_supply_path(
                attest,
                root,
                BootstrapMode::Gate,
                run_id,
            )
            .is_err());
        }

        #[test]
        fn bootstrap_lock_lexical_profile_rejects_noncanonical_mutations() {
            let checksum = "a".repeat(64);
            let valid = format!(
                concat!(
                    "# This file is automatically @generated by Cargo.\n",
                    "# It is not intended for manual editing.\n",
                    "version = 4\n\n",
                    "[[package]]\n",
                    "name = \"fastmcp-fnd01-bootstrap-control\"\n",
                    "version = \"0.0.0\"\n",
                    "dependencies = [\n",
                    " \"alpha\",\n",
                    " \"zeta\",\n",
                    "]\n\n",
                    "[[package]]\n",
                    "name = \"sample\"\n",
                    "version = \"1.2.3\"\n",
                    "source = \"registry+https://github.com/rust-lang/crates.io-index\"\n",
                    "checksum = \"{}\"\n",
                ),
                checksum,
            );
            let limits = BootstrapLockLexicalLimits {
                max_bytes: u64::try_from(valid.len()).expect("fixture length"),
                max_packages: 2,
                max_dependencies_per_package: 2,
                max_string_bytes: 128,
            };
            validate_bootstrap_cargo_lock_v4_lexical_with_limits(
                valid.as_bytes(),
                limits,
            )
            .expect("canonical Cargo v4 lexical fixture");

            let mutations = [
                valid.replace(
                    "name = \"sample\"\nversion = \"1.2.3\"",
                    "version = \"1.2.3\"\nname = \"sample\"",
                ),
                valid.replace("]\n\n[[package]]", "]\n[[package]]"),
                valid.replace("]\n\n[[package]]", "]\n\n\n[[package]]"),
                valid.replace(
                    "dependencies = [\n \"alpha\",\n \"zeta\",\n]",
                    "dependencies = [\n]",
                ),
                valid.replace(
                    " \"alpha\",\n \"zeta\",",
                    " \"zeta\",\n \"alpha\",",
                ),
                valid.replace(
                    "source = \"registry+https://github.com/rust-lang/crates.io-index\"\nchecksum",
                    "checksum = \"missing\"\nsource",
                ),
                format!("{valid}\n"),
                valid.replace('\n', "\r\n"),
            ];
            for (ordinal, mutation) in mutations.iter().enumerate() {
                assert!(
                    validate_bootstrap_cargo_lock_v4_lexical_with_limits(
                        mutation.as_bytes(),
                        BootstrapLockLexicalLimits {
                            max_bytes: u64::try_from(mutation.len())
                                .expect("mutation length"),
                            ..limits
                        },
                    )
                    .is_err(),
                    "mutation {ordinal} must fail",
                );
            }
            let mut bom = vec![0xef, 0xbb, 0xbf];
            bom.extend_from_slice(valid.as_bytes());
            assert!(
                validate_bootstrap_cargo_lock_v4_lexical_with_limits(
                    &bom,
                    BootstrapLockLexicalLimits {
                        max_bytes: u64::try_from(bom.len()).expect("BOM length"),
                        ..limits
                    },
                )
                .is_err()
            );
            assert!(
                validate_bootstrap_cargo_lock_v4_lexical_with_limits(
                    valid.as_bytes(),
                    BootstrapLockLexicalLimits {
                        max_packages: 1,
                        ..limits
                    },
                )
                .is_err()
            );
            assert!(
                validate_bootstrap_cargo_lock_v4_lexical_with_limits(
                    valid.as_bytes(),
                    BootstrapLockLexicalLimits {
                        max_dependencies_per_package: 1,
                        ..limits
                    },
                )
                .is_err()
            );
            assert!(
                validate_bootstrap_cargo_lock_v4_lexical_with_limits(
                    valid.as_bytes(),
                    BootstrapLockLexicalLimits {
                        max_string_bytes: 5,
                        ..limits
                    },
                )
                .is_err()
            );
        }

        fn append_tagged_string(output: &mut Vec<u8>, value: &str) {
            output.push(0x01);
            output.extend_from_slice(
                &u32::try_from(value.len())
                    .expect("test string length")
                    .to_be_bytes(),
            );
            output.extend_from_slice(value.as_bytes());
        }

        fn append_tagged_unsigned(output: &mut Vec<u8>, value: u64) {
            output.push(0x02);
            output.extend_from_slice(&value.to_be_bytes());
        }

        fn append_tagged_signed(output: &mut Vec<u8>, value: i64) {
            output.push(0x0a);
            output.extend_from_slice(&value.to_be_bytes());
        }

        fn append_tagged_boolean(output: &mut Vec<u8>, value: bool) {
            output.extend_from_slice(&[0x03, u8::from(value)]);
        }

        fn append_tagged_string_array(output: &mut Vec<u8>, values: &[&str]) {
            output.push(0x05);
            output.extend_from_slice(
                &u32::try_from(values.len())
                    .expect("test array length")
                    .to_be_bytes(),
            );
            for value in values {
                append_tagged_string(output, value);
            }
        }

        fn append_tagged_environment(
            output: &mut Vec<u8>,
            values: &[(&str, &str)],
        ) {
            output.push(0x05);
            output.extend_from_slice(
                &u32::try_from(values.len())
                    .expect("test environment length")
                    .to_be_bytes(),
            );
            for (key, value) in values {
                output.push(0x05);
                output.extend_from_slice(&2u32.to_be_bytes());
                append_tagged_string(output, key);
                append_tagged_string(output, value);
            }
        }

        fn append_record_header(output: &mut Vec<u8>, schema: &str) {
            output.push(0x06);
            output.extend_from_slice(
                &u32::try_from(schema.len())
                    .expect("test schema length")
                    .to_be_bytes(),
            );
            output.extend_from_slice(schema.as_bytes());
        }

        fn append_file_binding(output: &mut Vec<u8>, schema: &str, path: &str) {
            append_record_header(output, schema);
            append_tagged_string(output, path);
            append_tagged_unsigned(output, 1);
            append_tagged_string(
                output,
                "1111111111111111111111111111111111111111111111111111111111111111",
            );
        }

        fn append_raw_stream_fixture(output: &mut Vec<u8>, bytes: &[u8]) {
            append_record_header(output, "raw-stream-blob");
            append_tagged_unsigned(
                output,
                u64::try_from(bytes.len()).expect("raw fixture length"),
            );
            append_tagged_string(
                output,
                &encode_lower_hex(&sha256(bytes).expect("raw fixture digest")),
            );
            output.push(0x04);
            output.extend_from_slice(
                &u64::try_from(bytes.len())
                    .expect("raw fixture length")
                    .to_be_bytes(),
            );
            output.extend_from_slice(bytes);
        }

