        fn append_plain_u32_bytes(output: &mut Vec<u8>, bytes: &[u8]) {
            output.extend_from_slice(
                &u32::try_from(bytes.len())
                    .expect("manual preimage u32 byte length")
                    .to_be_bytes(),
            );
            output.extend_from_slice(bytes);
        }

        fn append_plain_stream(output: &mut Vec<u8>, bytes: &[u8]) {
            output.extend_from_slice(
                &u64::try_from(bytes.len())
                    .expect("manual preimage u64 stream length")
                    .to_be_bytes(),
            );
            output.extend_from_slice(
                &sha256(bytes).expect("manual preimage stream digest"),
            );
            output.extend_from_slice(bytes);
        }

        fn manual_acquisition_command_preimage(
            command: &ValidatedAcquisitionCommand,
        ) -> Vec<u8> {
            let mut output = b"FND01BOOTSTRAPCOMMANDv1\0".to_vec();
            output.extend_from_slice(
                &u32::try_from(command.ordinal)
                    .expect("manual preimage command ordinal")
                    .to_be_bytes(),
            );
            append_plain_u32_bytes(&mut output, command.id.as_bytes());
            output.extend_from_slice(
                &u32::try_from(command.argv.len())
                    .expect("manual preimage argv count")
                    .to_be_bytes(),
            );
            for argument in &command.argv {
                append_plain_u32_bytes(&mut output, argument.as_bytes());
            }
            output.extend_from_slice(
                &u32::try_from(command.environment.len())
                    .expect("manual preimage environment count")
                    .to_be_bytes(),
            );
            for (key, value) in &command.environment {
                append_plain_u32_bytes(&mut output, key.as_bytes());
                append_plain_u32_bytes(&mut output, value.as_bytes());
            }
            append_plain_u32_bytes(
                &mut output,
                command.working_directory.as_bytes(),
            );
            output.extend_from_slice(&command.exit_code.to_be_bytes());
            append_plain_stream(&mut output, &command.stdout.bytes);
            append_plain_stream(&mut output, &command.stderr.bytes);
            append_plain_u32_bytes(
                &mut output,
                command.typed_result_kind.as_bytes(),
            );
            output.extend_from_slice(&command.typed_result_sha256);
            append_plain_u32_bytes(
                &mut output,
                command.evidence_verdict.as_bytes(),
            );
            output
        }

        fn validated_acquisition_command_preimage(
            command: &ValidatedAcquisitionCommand,
        ) -> TrustResult<Vec<u8>> {
            acquisition_command_preimage(&AcquisitionCommandPreimageInput {
                ordinal: command.ordinal,
                id: &command.id,
                argv: &command.argv,
                environment: &command.environment,
                working_directory: &command.working_directory,
                exit_code: command.exit_code,
                stdout: AcquisitionCommandStreamPreimage {
                    binding: command.stdout.binding,
                    bytes: &command.stdout.bytes,
                },
                stderr: AcquisitionCommandStreamPreimage {
                    binding: command.stderr.binding,
                    bytes: &command.stderr.bytes,
                },
                typed_result_kind: &command.typed_result_kind,
                typed_result_sha256: command.typed_result_sha256,
                evidence_verdict: &command.evidence_verdict,
            })
        }

        fn rebind_raw_stream(stream: &mut ValidatedRawStreamBlob) {
            stream.binding = FileBinding {
                byte_length: u64::try_from(stream.bytes.len())
                    .expect("mutated stream length"),
                sha256: sha256(&stream.bytes).expect("mutated stream digest"),
            };
        }

        #[test]
        fn acquisition_spool_semantics_reject_prefix_tag_digest_role_order_and_supply_drift() {
            let expected = acquisition_spool_expectation();
            let valid =
                acquisition_spool_fixture("integration-producer", false);
            let parsed = validate_acquisition_spool_bytes(&valid, &expected)
                .expect("valid acquisition spool");
            assert_eq!(parsed.commands[0].id, "bootstrap.resolve");
            assert_eq!(parsed.commands[1].id, "bootstrap.fetch");

            let mut bad_prefix = valid.clone();
            bad_prefix[0] = b'X';
            assert_eq!(
                validate_acquisition_spool_bytes(&bad_prefix, &expected)
                    .expect_err("prefix drift")
                    .code(),
                "E_RECORD_FORMAT"
            );

            let mut bad_tag = valid.clone();
            bad_tag[ACQUISITION_SPOOL_PREFIX.len()] = 0x01;
            assert_eq!(
                validate_acquisition_spool_bytes(&bad_tag, &expected)
                    .expect_err("record tag drift")
                    .code(),
                "E_RECORD_DEPTH_OR_TAG"
            );

            let mut stale_digest = valid.clone();
            let role_offset = stale_digest
                .windows("integration-producer".len())
                .position(|window| window == b"integration-producer")
                .expect("fixture role offset");
            stale_digest[role_offset] = b'X';
            assert_eq!(
                validate_acquisition_spool_bytes(&stale_digest, &expected)
                    .expect_err("stale spool digest")
                    .code(),
                "E_RECORD_DIGEST"
            );

            let wrong_role = acquisition_spool_fixture(
                "independent-attester",
                false,
            );
            assert_eq!(
                validate_acquisition_spool_bytes(&wrong_role, &expected)
                    .expect_err("spool role drift")
                    .code(),
                "E_ACQUISITION_SPOOL"
            );

            let wrong_order =
                acquisition_spool_fixture("integration-producer", true);
            assert_eq!(
                validate_acquisition_spool_bytes(&wrong_order, &expected)
                    .expect_err("spool command order drift")
                    .code(),
                "E_ACQUISITION_COMMAND"
            );

            let mut wrong_supply = expected.clone();
            wrong_supply.supply_bundle.binding.sha256 = [0x44; 32];
            assert_eq!(
                validate_acquisition_spool_bytes(&valid, &wrong_supply)
                    .expect_err("spool supply drift")
                    .code(),
                "E_ACQUISITION_SUPPLY"
            );
        }

        #[test]
        fn acquisition_spool_claims_require_independent_typed_finalization() {
            let expected = acquisition_spool_expectation();
            let plan = acquisition_plan(
                Path::new("/repo"),
                ACQUISITION_FIXTURE_RUN_ID,
                &acquisition_tool_paths_fixture(),
                &ACQUISITION_PLAN_AUTHORITY,
            )
            .expect("compiled acquisition fixture plan");
            let bytes =
                acquisition_spool_fixture("integration-producer", false);
            let structural = parse_acquisition_spool_structure(
                &bytes,
                ACQUISITION_FIXTURE_RUN_ID,
                &plan.commands,
                &expected.supply_bundle,
            )
            .expect("structurally valid acquisition spool");
            assert_eq!(
                structural.commands[0].claimed_typed_result_sha256,
                [0x22; 32],
            );
            let error = finalize_acquisition_spool(
                structural.clone(),
                &[
                    TypedAcquisitionResult {
                        kind: "strict-cargo-metadata-json-plus-union-lock".to_owned(),
                        sha256: [0x44; 32],
                    },
                    TypedAcquisitionResult {
                        kind: "exit-and-cache-closure".to_owned(),
                        sha256: [0x33; 32],
                    },
                ],
            )
            .expect_err("a self-consistent spool claim is not independent authority");
            assert_eq!(error.code(), "E_ACQUISITION_TYPED_RESULT");

            finalize_acquisition_spool(
                structural,
                &[
                    TypedAcquisitionResult {
                        kind: "strict-cargo-metadata-json-plus-union-lock".to_owned(),
                        sha256: [0x22; 32],
                    },
                    TypedAcquisitionResult {
                        kind: "exit-and-cache-closure".to_owned(),
                        sha256: [0x33; 32],
                    },
                ],
            )
            .expect("independently matching typed results");
        }

        fn assert_acquisition_command_preimage_binds_every_field(
            command: &ValidatedAcquisitionCommand,
        ) {
            let baseline =
                validated_acquisition_command_preimage(command)
                    .expect("baseline command preimage");
            assert_eq!(baseline, command.preimage);
            assert_eq!(
                baseline,
                manual_acquisition_command_preimage(command),
                "the production encoder must match an independently assembled byte oracle",
            );

            let mut ordinal = command.clone();
            ordinal.ordinal = u64::from(command.ordinal == 0);
            assert_ne!(
                validated_acquisition_command_preimage(&ordinal)
                    .expect("mutated ordinal preimage"),
                baseline,
            );

            let mut id = command.clone();
            id.id.push_str(".alternate");
            assert_ne!(
                validated_acquisition_command_preimage(&id)
                    .expect("mutated id preimage"),
                baseline,
            );

            for index in 0..command.argv.len() {
                let mut argument = command.clone();
                argument.argv[index].push('x');
                assert_ne!(
                    validated_acquisition_command_preimage(&argument)
                        .expect("mutated argv item preimage"),
                    baseline,
                    "argv item {index} was not bound",
                );
            }
            let mut reordered_argv = command.clone();
            reordered_argv.argv.swap(1, 2);
            assert_ne!(
                validated_acquisition_command_preimage(&reordered_argv)
                    .expect("reordered argv preimage"),
                baseline,
            );
            let mut shorter_argv = command.clone();
            shorter_argv.argv.pop();
            assert_ne!(
                validated_acquisition_command_preimage(&shorter_argv)
                    .expect("shorter argv preimage"),
                baseline,
            );

            for index in 0..command.environment.len() {
                let mut key = command.clone();
                key.environment[index].0.push_str("_ALT");
                assert_ne!(
                    validated_acquisition_command_preimage(&key)
                        .expect("mutated environment key preimage"),
                    baseline,
                    "environment key {index} was not bound",
                );

                let mut value = command.clone();
                value.environment[index].1.push('x');
                assert_ne!(
                    validated_acquisition_command_preimage(&value)
                        .expect("mutated environment value preimage"),
                    baseline,
                    "environment value {index} was not bound",
                );
            }
            let mut reordered_environment = command.clone();
            reordered_environment.environment.swap(0, 1);
            assert_ne!(
                validated_acquisition_command_preimage(
                    &reordered_environment,
                )
                .expect("reordered environment preimage"),
                baseline,
            );

            let mut working_directory = command.clone();
            working_directory.working_directory.push_str("-alternate");
            assert_ne!(
                validated_acquisition_command_preimage(&working_directory)
                    .expect("mutated working-directory preimage"),
                baseline,
            );

            let mut stdout_bytes = command.clone();
            stdout_bytes.stdout.bytes.push(b'!');
            rebind_raw_stream(&mut stdout_bytes.stdout);
            assert_ne!(
                validated_acquisition_command_preimage(&stdout_bytes)
                    .expect("mutated stdout bytes preimage"),
                baseline,
            );
            let mut stdout_length = command.clone();
            stdout_length.stdout.binding.byte_length += 1;
            assert_eq!(
                validated_acquisition_command_preimage(&stdout_length)
                    .expect_err("stale stdout length")
                    .code(),
                "E_ACQUISITION_COMMAND_PREIMAGE",
            );
            let mut stdout_digest = command.clone();
            stdout_digest.stdout.binding.sha256[0] ^= 1;
            assert_eq!(
                validated_acquisition_command_preimage(&stdout_digest)
                    .expect_err("stale stdout digest")
                    .code(),
                "E_ACQUISITION_COMMAND_PREIMAGE",
            );

            let mut stderr_bytes = command.clone();
            stderr_bytes.stderr.bytes.push(b'!');
            rebind_raw_stream(&mut stderr_bytes.stderr);
            assert_ne!(
                validated_acquisition_command_preimage(&stderr_bytes)
                    .expect("mutated stderr bytes preimage"),
                baseline,
            );
            let mut stderr_length = command.clone();
            stderr_length.stderr.binding.byte_length += 1;
            assert_eq!(
                validated_acquisition_command_preimage(&stderr_length)
                    .expect_err("stale stderr length")
                    .code(),
                "E_ACQUISITION_COMMAND_PREIMAGE",
            );
            let mut stderr_digest = command.clone();
            stderr_digest.stderr.binding.sha256[0] ^= 1;
            assert_eq!(
                validated_acquisition_command_preimage(&stderr_digest)
                    .expect_err("stale stderr digest")
                    .code(),
                "E_ACQUISITION_COMMAND_PREIMAGE",
            );

            let mut typed_kind = command.clone();
            typed_kind.typed_result_kind.push_str("-alternate");
            assert_ne!(
                validated_acquisition_command_preimage(&typed_kind)
                    .expect("mutated typed-result kind preimage"),
                baseline,
            );
            let mut typed_digest = command.clone();
            typed_digest.typed_result_sha256[0] ^= 1;
            assert_ne!(
                validated_acquisition_command_preimage(&typed_digest)
                    .expect("mutated typed-result digest preimage"),
                baseline,
            );

            let mut nonzero_exit = command.clone();
            nonzero_exit.exit_code = 1;
            assert_eq!(
                validated_acquisition_command_preimage(&nonzero_exit)
                    .expect_err("nonzero acquisition exit")
                    .code(),
                "E_ACQUISITION_COMMAND_PREIMAGE",
            );
            let mut alternate_verdict = command.clone();
            alternate_verdict.evidence_verdict = "Fail".to_owned();
            assert_eq!(
                validated_acquisition_command_preimage(&alternate_verdict)
                    .expect_err("alternate evidence verdict")
                    .code(),
                "E_ACQUISITION_COMMAND_PREIMAGE",
            );
        }

        #[test]
        fn acquisition_command_preimage_is_exact_and_binds_every_field() {
            let expected = acquisition_spool_expectation();
            let bytes =
                acquisition_spool_fixture("integration-producer", false);
            let parsed = validate_acquisition_spool_bytes(&bytes, &expected)
                .expect("valid acquisition spool");
            assert_eq!(parsed.commands.len(), 2);
            for command in &parsed.commands {
                assert_acquisition_command_preimage_binds_every_field(
                    command,
                );
            }
        }

        fn outer_lifecycle_fixture(
            mode: BootstrapMode,
            run_id: &str,
            phase: &str,
            authoring_marker: &str,
            integration_marker: Option<&str>,
            outer_argv: &[Vec<u8>],
        ) -> CanonicalRecord {
            let phase_code = match phase {
                "producer" => "p",
                "attester" => "a",
                "gate" => "g",
                _ => panic!("fixture lifecycle phase"),
            };
            let socket_path = format!(
                "{}/fnd01/{run_id}/s/{phase_code}/rch.sock",
                controller_temp_root_fixture(),
            );
            let invocation_argv = outer_argv
                .iter()
                .map(|value| {
                    std::str::from_utf8(value).expect("outer fixture argv UTF-8")
                })
                .collect::<Vec<_>>();
            let producer_outer_path =
                format!(".fnd01-run/controller/{run_id}/producer-outer.bin");
            let mut output = Vec::new();
            append_record_header(&mut output, "outer-lifecycle");
            append_tagged_string(&mut output, phase);
            append_record_header(&mut output, "controller-rch-binding");
            append_unix_file_identity(
                &mut output,
                "/controller/bin/rch",
                1,
                0o100_755,
                1_000,
                "2222222222222222222222222222222222222222222222222222222222222222",
            );
            append_tagged_string(&mut output, "1.0.49");
            append_tagged_string(&mut output, "40beb520c1f3");
            append_tagged_boolean(&mut output, true);
            append_tagged_boolean(&mut output, true);
            append_tagged_boolean(&mut output, true);
            append_record_header(&mut output, "controller-invocation-plan");
            append_unix_file_identity(
                &mut output,
                "/controller/bin/rch",
                1,
                0o100_755,
                1_000,
                "2222222222222222222222222222222222222222222222222222222222222222",
            );
            append_tagged_environment(
                &mut output,
                &[
                    ("RCH_NO_SELF_HEALING", "1"),
                    ("RCH_QUIET", "1"),
                    ("RCH_REQUIRE_REMOTE", "1"),
                    ("RCH_SOCKET_PATH", &socket_path),
                ],
            );
            append_tagged_string_array(&mut output, &invocation_argv);
            match mode {
                BootstrapMode::Produce => append_tagged_environment(
                    &mut output,
                    &[
                        (AUTHORING_MARKER_ENV, authoring_marker),
                        (RUN_ID_ENV, run_id),
                        ("LANG", "C"),
                        ("LC_ALL", "C"),
                        ("PATH", "$fnd01_tool_bin:/usr/bin:/bin"),
                        ("TZ", "UTC"),
                    ],
                ),
                BootstrapMode::Attest => append_tagged_environment(
                    &mut output,
                    &[
                        (AUTHORING_MARKER_ENV, authoring_marker),
                        (
                            INTEGRATION_SEAL_ENV,
                            integration_marker
                                .expect("attester integration marker"),
                        ),
                        (
                            PRODUCER_OUTER_RECORD_PATH_ENV,
                            producer_outer_path.as_str(),
                        ),
                        (RUN_ID_ENV, run_id),
                        ("LANG", "C"),
                        ("LC_ALL", "C"),
                        ("PATH", "$fnd01_tool_bin:/usr/bin:/bin"),
                        ("TZ", "UTC"),
                    ],
                ),
                BootstrapMode::Gate => panic!("outer role fixture excludes gate"),
            }
            append_tagged_string(
                &mut output,
                "/controller/work/fastmcp-rust",
            );
            append_tagged_string(&mut output, ".");
            append_tagged_unsigned(&mut output, 86_400);
            output.extend_from_slice(&[0x08, 0]);
            append_rch_daemon_pre_fixture(
                &mut output,
                phase,
                run_id,
                &socket_path,
            );
            append_rch_daemon_post_fixture(&mut output, phase, run_id);
            let mut cursor =
                BinaryCursor::new(&output, "outer lifecycle fixture");
            let record = parse_tagged_record(
                &mut cursor,
                "outer-lifecycle",
                0,
            )
            .expect("outer lifecycle fixture parse");
            cursor.finish().expect("outer lifecycle fixture EOF");
            record
        }

        fn set_outer_requested_worker(
            record: &mut OuterTransportRecord,
            worker: &str,
        ) {
            record.assignments.push((
                b"RCH_WORKER".to_vec(),
                worker.as_bytes().to_vec(),
            ));
            let CanonicalValue::Record(invocation) =
                &mut record.lifecycle.fields[2]
            else {
                panic!("outer invocation fixture");
            };
            let CanonicalValue::EnvironmentPairs(environment) =
                &mut invocation.fields[1]
            else {
                panic!("outer controller environment fixture");
            };
            environment.push(("RCH_WORKER".to_owned(), worker.to_owned()));
            invocation.fields[7] =
                CanonicalValue::OptionalString(Some(worker.to_owned()));
        }

        fn set_outer_socket_path(
            record: &mut OuterTransportRecord,
            socket_path: &str,
        ) {
            record.assignments[3].1 = socket_path.as_bytes().to_vec();
            let CanonicalValue::Record(invocation) =
                &mut record.lifecycle.fields[2]
            else {
                panic!("outer invocation fixture");
            };
            let CanonicalValue::EnvironmentPairs(environment) =
                &mut invocation.fields[1]
            else {
                panic!("outer controller environment fixture");
            };
            environment[3].1 = socket_path.to_owned();
        }

        pub(super) fn build_outer_role_fixture(
            mode: BootstrapMode,
            run_id: &str,
            phase: &str,
            authoring_marker: &str,
            integration_marker: Option<&str>,
        ) -> OuterTransportRecord {
            let shell = expected_outer_shell(
                mode,
                run_id,
                authoring_marker,
                integration_marker,
            )
            .expect("outer shell fixture");
            let phase_code = match phase {
                "producer" => "p",
                "attester" => "a",
                "gate" => "g",
                other => other, // already a phase-code in some call sites
            };
            let socket_path = format!(
                "{}/fnd01/{run_id}/s/{phase_code}/rch.sock",
                controller_temp_root_fixture(),
            );
            let argv = [
                b"/controller/bin/rch".to_vec(),
                b"exec".to_vec(),
                b"--".to_vec(),
                b"sh".to_vec(),
                b"-c".to_vec(),
                shell.into_bytes(),
            ]
            .to_vec();
            let lifecycle = outer_lifecycle_fixture(
                mode,
                run_id,
                phase,
                authoring_marker,
                integration_marker,
                &argv,
            );
            OuterTransportRecord {
                argv,
                assignments: vec![
                    (b"RCH_NO_SELF_HEALING".to_vec(), b"1".to_vec()),
                    (b"RCH_QUIET".to_vec(), b"1".to_vec()),
                    (b"RCH_REQUIRE_REMOTE".to_vec(), b"1".to_vec()),
                    (b"RCH_SOCKET_PATH".to_vec(), socket_path.into_bytes()),
                ],
                exit_code: 0,
                stdout: b"target_arch=\"x86_64\"\ntarget_os=\"linux\"\n".to_vec(),
                stderr: Vec::new(),
                final_argv: vec![
                    b"rustc".to_vec(),
                    b"--print".to_vec(),
                    b"cfg".to_vec(),
                ],
                rustc_cfg: vec![
                    (b"target_arch".to_vec(), Some(b"x86_64".to_vec())),
                    (b"target_os".to_vec(), Some(b"linux".to_vec())),
                ],
                lifecycle,
            }
        }

        fn append_unix_file_identity(
            output: &mut Vec<u8>,
            path: &str,
            inode: u64,
            mode: u64,
            byte_length: u64,
            digest: &str,
        ) {
            append_record_header(output, "unix-file-identity");
            append_tagged_string(output, path);
            append_tagged_unsigned(output, 1);
            append_tagged_unsigned(output, inode);
            append_tagged_unsigned(output, mode);
            append_tagged_unsigned(output, 1);
            append_tagged_unsigned(output, byte_length);
            append_tagged_unsigned(output, 10);
            append_tagged_unsigned(output, 20);
            append_tagged_unsigned(output, 30);
            append_tagged_unsigned(output, 40);
            append_tagged_string(output, digest);
        }

        fn append_unix_node_identity(
            output: &mut Vec<u8>,
            schema: &str,
            path: &str,
            inode: u64,
            mode: u64,
            nlink: u64,
        ) {
            append_record_header(output, schema);
            append_tagged_string(output, path);
            append_tagged_unsigned(output, 1);
            append_tagged_unsigned(output, inode);
            append_tagged_unsigned(output, mode);
            append_tagged_unsigned(output, nlink);
            append_tagged_unsigned(output, 10);
            append_tagged_unsigned(output, 20);
            append_tagged_unsigned(output, 30);
            append_tagged_unsigned(output, 40);
        }

