        fn append_fixture_section(
            output: &mut String,
            path: &str,
            phase: Option<&str>,
        ) {
            let (fields, mask, array) =
                final_direct_schema(path).expect("frozen direct schema");
            if !path.is_empty() {
                if array {
                    output.push_str("[[");
                    output.push_str(path);
                    output.push_str("]]\n");
                } else {
                    output.push('[');
                    output.push_str(path);
                    output.push_str("]\n");
                }
            }
            for (field, kind) in fields.iter().zip(mask.bytes()) {
                let value = match (path, *field) {
                    ("attester_staging_snapshot", "phase") => {
                        format!("\"{}\"", phase.expect("staging phase"))
                    }
                    ("attester_staging_snapshot", "file_count") => {
                        "163".to_owned()
                    }
                    ("attester_staging_snapshot", "vcs_probe_count") => {
                        "0".to_owned()
                    }
                    _ => match kind {
                        b's' => "\"x\"".to_owned(),
                        b'u' => "1".to_owned(),
                        b'i' => "0".to_owned(),
                        b'b' => "false".to_owned(),
                        b'a' | b'e' | b'S' | b'q' => "[]".to_owned(),
                        _ => panic!("unexpected fixture kind {kind:#x}"),
                    },
                };
                output.push_str(field);
                output.push_str(" = ");
                output.push_str(&value);
                output.push('\n');
            }
        }

