        #[test]
        fn outer_role_socket_assignment_is_required_and_phase_scoped() {
            let run_id = "0123456789abcdef0123456789abcdef";
            let authoring_marker = "authoring-marker";
            let integration_marker = "integration-marker";
            let producer =
                outer_role_fixture(
                    BootstrapMode::Produce,
                    run_id,
                    "producer",
                    "authoring-marker",
                    None,
                );
            validate_outer_role_record(
                &producer,
                BootstrapMode::Produce,
                run_id,
                authoring_marker,
                None,
            )
            .expect("producer socket assignment");

            let mut attester =
                outer_role_fixture(
                    BootstrapMode::Attest,
                    run_id,
                    "attester",
                    "authoring-marker",
                    Some("integration-marker"),
                );
            set_outer_requested_worker(&mut attester, "preferred-worker");
            validate_outer_role_record(
                &attester,
                BootstrapMode::Attest,
                run_id,
                authoring_marker,
                Some(integration_marker),
            )
            .expect("attester socket assignment with optional worker");

            let mut wrong_phase =
                outer_role_fixture(
                    BootstrapMode::Produce,
                    run_id,
                    "producer",
                    "authoring-marker",
                    None,
                );
            set_outer_socket_path(
                &mut wrong_phase,
                &format!(
                    "{}/fnd01/{run_id}/s/a/rch.sock",
                    controller_temp_root_fixture(),
                ),
            );
            let error = validate_outer_role_record(
                &wrong_phase,
                BootstrapMode::Produce,
                run_id,
                authoring_marker,
                None,
            )
            .expect_err("cross-phase socket must fail");
            assert_eq!(error.code(), "E_OUTER_ASSIGNMENT");

            let mut missing_socket = producer;
            missing_socket.assignments.remove(3);
            let error = validate_outer_role_record(
                &missing_socket,
                BootstrapMode::Produce,
                run_id,
                authoring_marker,
                None,
            )
            .expect_err("missing socket assignment must fail");
            assert_eq!(error.code(), "E_OUTER_LIFECYCLE");
        }

