        #[test]
        fn lock_union_requires_pinned_package_order_and_checksum_binding() {
            let first = concat!(
                "# This file is automatically @generated by Cargo.\n",
                "# It is not intended for manual editing.\n",
                "version = 4\n\n",
                "[[package]]\n",
                "name = \"fastmcp-fnd01-bootstrap-control\"\n",
                "version = \"0.0.0\"\n",
                "dependencies = [\n",
                " \"sample\",\n",
                "]\n\n",
                "[[package]]\n",
                "name = \"sample\"\n",
                "version = \"1.2.3\"\n",
                "source = \"registry+https://github.com/rust-lang/crates.io-index\"\n",
                "checksum = \"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"\n",
            );
            let second = concat!(
                "# This file is automatically @generated by Cargo.\n",
                "# It is not intended for manual editing.\n",
                "version = 4\n\n",
                "[[package]]\n",
                "name = \"sample\"\n",
                "version = \"1.2.3\"\n",
                "source = \"registry+https://github.com/rust-lang/crates.io-index\"\n",
                "checksum = \"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"\n\n",
                "[[package]]\n",
                "name = \"fastmcp-fnd01-bootstrap-control\"\n",
                "version = \"0.0.0\"\n",
                "dependencies = [\n",
                " \"sample\",\n",
                "]\n",
            );
            let first = bootstrap_lock_union(first.as_bytes()).expect("first lock union");
            assert_eq!(
                bootstrap_lock_union(second.as_bytes())
                    .expect_err("out-of-order package blocks must fail")
                    .code(),
                "E_PHASE_B_LOCK_SCHEMA",
            );
            let changed = first
                .packages
                .iter()
                .cloned()
                .map(|mut package| {
                    package.checksum.replace_range(..1, "b");
                    package
                })
                .collect::<Vec<_>>();
            assert_ne!(changed, first.packages);
        }

