    fn supply_package_triples(
        packages: &BTreeMap<RegistryPackageTriple, ParsedSupplyPackage>,
    ) -> BTreeSet<RegistryPackageTriple> {
        packages.keys().cloned().collect()
    }

    fn validate_supply_package_closure(
        receipt: &ParsedSupplyReceiptSummary,
        bootstrap_packages: &BTreeSet<RegistryPackageTriple>,
        downstream_packages: &BTreeSet<RegistryPackageTriple>,
    ) -> VResult<()> {
        validate_supply_package_maps_closure(
            &receipt.bootstrap_packages,
            &receipt.downstream_packages,
            &receipt.control_only_packages,
            bootstrap_packages,
            downstream_packages,
        )
    }

    fn validate_supply_package_maps_closure(
        receipt_bootstrap_packages: &BTreeMap<RegistryPackageTriple, ParsedSupplyPackage>,
        receipt_downstream_packages: &BTreeMap<RegistryPackageTriple, ParsedSupplyPackage>,
        receipt_control_only_packages: &BTreeMap<RegistryPackageTriple, ParsedSupplyPackage>,
        bootstrap_packages: &BTreeSet<RegistryPackageTriple>,
        downstream_packages: &BTreeSet<RegistryPackageTriple>,
    ) -> VResult<()> {
        let receipt_bootstrap = supply_package_triples(receipt_bootstrap_packages);
        let receipt_downstream = supply_package_triples(receipt_downstream_packages);
        let receipt_control_only = supply_package_triples(receipt_control_only_packages);
        if &receipt_bootstrap != bootstrap_packages {
            return Err(Diagnostic::error("E_SUPPLY_PACKAGE_JOIN", "supply-receipt")
                .at("bootstrap_package"));
        }
        if &receipt_downstream != downstream_packages {
            return Err(Diagnostic::error("E_SUPPLY_PACKAGE_JOIN", "supply-receipt")
                .at("downstream_union_package"));
        }
        if !downstream_packages.is_subset(bootstrap_packages) {
            return Err(Diagnostic::error("E_SUPPLY_PACKAGE_JOIN", "supply-receipt")
                .at("downstream-not-subset-of-bootstrap"));
        }
        let expected_control_only = bootstrap_packages
            .difference(downstream_packages)
            .cloned()
            .collect::<BTreeSet<_>>();
        if receipt_control_only != expected_control_only {
            return Err(Diagnostic::error("E_SUPPLY_PACKAGE_JOIN", "supply-receipt")
                .at("control_only_package"));
        }
        Ok(())
    }

    fn validate_supply_acquisition_anchor_bijection(
        receipt: &ParsedSupplyReceiptSummary,
        bundle: &SupplyBundleSummary,
    ) -> VResult<()> {
        let subject = "supply-receipt/acquisition_anchor";
        let mut matched_sparse_entries = BTreeSet::new();
        let mut matched_crate_entries = BTreeSet::new();
        let mut sparse_config_count = 0usize;
        for (anchor_index, anchor) in receipt.acquisition_anchors.iter().enumerate() {
            let logical = format!("{subject}[{anchor_index}]");
            match &anchor.detail {
                ParsedSupplyAcquisitionAnchorDetail::SparseConfig => {
                    sparse_config_count = sparse_config_count.checked_add(1).ok_or_else(|| {
                        Diagnostic::error("E_SUPPLY_ACQUISITION_ANCHOR_COUNT", &logical)
                    })?;
                    if anchor.binding.path != bundle.sparse_config_path
                        || anchor.binding.byte_length != bundle.sparse_config_byte_length
                        || anchor.binding.sha256 != lower_hex(&bundle.sparse_config_sha256)
                        || anchor.binding.sha256.bytes().all(|byte| byte == b'0')
                    {
                        return Err(Diagnostic::error(
                            "E_SUPPLY_ACQUISITION_CONFIG_JOIN",
                            &logical,
                        )
                        .at("supply-header sparse config"));
                    }
                }
                ParsedSupplyAcquisitionAnchorDetail::SparseCache(detail) => {
                    let expected_entry_path = format!("sparse-cache/{}", anchor.binding.path);
                    let matching = receipt
                        .entries
                        .iter()
                        .enumerate()
                        .filter_map(|(entry_index, entry)| {
                            let ParsedSupplyEntryDetail::SparseCache(entry_detail) = &entry.detail
                            else {
                                return None;
                            };
                            (entry.binding.relative_path == expected_entry_path).then_some((
                                entry_index,
                                entry,
                                entry_detail,
                            ))
                        })
                        .collect::<Vec<_>>();
                    if matching.len() != 1 {
                        return Err(Diagnostic::error(
                            "E_SUPPLY_ACQUISITION_ANCHOR_BINDING",
                            &logical,
                        )
                        .at("sparse-cache peer"));
                    }
                    let (entry_index, entry, entry_detail) = matching[0];
                    let matching_derived = receipt
                        .entries
                        .iter()
                        .filter_map(|candidate| {
                            let ParsedSupplyEntryDetail::DerivedIndex(derived) = &candidate.detail
                            else {
                                return None;
                            };
                            (derived.package_name == detail.package_name).then_some(derived)
                        })
                        .collect::<Vec<_>>();
                    let package_versions_match = detail.selected_versions.iter().all(|version| {
                        receipt
                            .bootstrap_packages
                            .keys()
                            .filter(|package| {
                                package.name == detail.package_name && &package.version == version
                            })
                            .count()
                            == 1
                    });
                    let dependency_path = crates_io_index_path(&detail.package_name, &logical)?
                        .strip_prefix("index/")
                        .ok_or_else(|| {
                            Diagnostic::error("E_SUPPLY_ACQUISITION_ANCHOR_PATH", &logical)
                        })?
                        .to_owned();
                    if !matched_sparse_entries.insert(entry_index)
                        || entry.binding.byte_length != anchor.binding.byte_length
                        || entry.binding.sha256 != anchor.binding.sha256
                        || entry_detail.cache_relative_path != anchor.binding.path
                        || anchor.binding.path
                            != format!("{ACQUISITION_SPARSE_CACHE_PREFIX}{dependency_path}")
                        || entry_detail.validator != detail.validator
                        || entry_detail.selected_versions != detail.selected_versions
                        || entry_detail.selected_ordinals != detail.selected_ordinals
                        || entry_detail.selected_sha256 != detail.selected_sha256
                        || matching_derived.len() != 1
                        || matching_derived[0].selected_versions != detail.selected_versions
                        || !package_versions_match
                    {
                        return Err(Diagnostic::error(
                            "E_SUPPLY_ACQUISITION_ANCHOR_SELECTION",
                            &logical,
                        )
                        .at("sparse-cache tuple"));
                    }
                }
                ParsedSupplyAcquisitionAnchorDetail::CrateCache(detail) => {
                    let basename = format!("{}-{}.crate", detail.package_name, detail.version);
                    let matching = receipt
                        .entries
                        .iter()
                        .enumerate()
                        .filter_map(|(entry_index, entry)| {
                            let ParsedSupplyEntryDetail::CrateArchive(entry_detail) = &entry.detail
                            else {
                                return None;
                            };
                            (entry.binding.relative_path == basename).then_some((
                                entry_index,
                                entry,
                                entry_detail,
                            ))
                        })
                        .collect::<Vec<_>>();
                    if matching.len() != 1 {
                        return Err(Diagnostic::error(
                            "E_SUPPLY_ACQUISITION_ANCHOR_BINDING",
                            &logical,
                        )
                        .at("crate-cache peer"));
                    }
                    let (entry_index, entry, entry_detail) = matching[0];
                    let triple = RegistryPackageTriple {
                        name: detail.package_name.clone(),
                        version: detail.version.clone(),
                        checksum: anchor.binding.sha256.clone(),
                    };
                    let package = receipt.bootstrap_packages.get(&triple).ok_or_else(|| {
                        Diagnostic::error("E_SUPPLY_ACQUISITION_ANCHOR_BINDING", &logical)
                            .at("bootstrap package peer")
                    })?;
                    if !matched_crate_entries.insert(entry_index)
                        || anchor.binding.path
                            != format!("{ACQUISITION_CRATE_CACHE_PREFIX}{basename}")
                        || entry.binding.byte_length != anchor.binding.byte_length
                        || entry.binding.sha256 != anchor.binding.sha256
                        || entry_detail.package_id != package.package_id
                        || entry_detail.version != detail.version
                        || entry_detail.checksum_sha256 != anchor.binding.sha256
                        || entry_detail.yanked
                    {
                        return Err(Diagnostic::error(
                            "E_SUPPLY_ACQUISITION_ANCHOR_BINDING",
                            &logical,
                        )
                        .at("crate-cache fields"));
                    }
                }
            }
        }
        let expected_sparse_entries = receipt
            .entries
            .iter()
            .filter(|entry| matches!(&entry.detail, ParsedSupplyEntryDetail::SparseCache(_)))
            .count();
        let expected_crate_entries = receipt
            .entries
            .iter()
            .filter(|entry| matches!(&entry.detail, ParsedSupplyEntryDetail::CrateArchive(_)))
            .count();
        if sparse_config_count != 1
            || matched_sparse_entries.len() != expected_sparse_entries
            || matched_crate_entries.len() != expected_crate_entries
        {
            return Err(
                Diagnostic::error("E_SUPPLY_ACQUISITION_ANCHOR_COUNT", subject)
                    .at("entry bijection"),
            );
        }
        if receipt.acquisition_root_set_sha256 != lower_hex(&bundle.acquisition_root_set_sha256) {
            return Err(Diagnostic::error("E_SUPPLY_ACQUISITION_ROOT_JOIN", subject)
                .at("supply-header root digest"));
        }
        Ok(())
    }

    fn validate_supply_receipt_bootstrap_and_copy_joins(
        receipt: &ParsedSupplyReceiptSummary,
        published_bundle: &ReceiptOutputBinding,
        producer_build: &ParsedBootstrapControlBuild,
        producer_exec: &ParsedBootstrapExecEntry,
        run_id: &str,
    ) -> VResult<()> {
        let subject = "supply-receipt";
        let expected_pre_handoff =
            format!(".fnd01-run/integration-producer/{run_id}/supply-bundle.bin");
        let expected_returned = format!("target/debug/fnd-01/{run_id}/return/supply-bundle.bin");
        let expected_manifest = format!(
            ".fnd01-run/integration-producer/{run_id}/bootstrap-control-package/Cargo.toml"
        );
        let expected_lock = format!(
            ".fnd01-run/integration-producer/{run_id}/bootstrap-control-package/Cargo.lock"
        );
        if &receipt.bundle != published_bundle
            || receipt.producer_pre_handoff_bundle.path != expected_pre_handoff
            || receipt.returned_bundle.path != expected_returned
            || receipt.bundle.path != "evidence/fnd-01/integration/supply-bundle.bin"
            || receipt.producer_pre_handoff_bundle.path == receipt.returned_bundle.path
            || receipt.producer_pre_handoff_bundle.path == receipt.bundle.path
            || receipt.returned_bundle.path == receipt.bundle.path
            || receipt.producer_pre_handoff_bundle.byte_length != published_bundle.byte_length
            || receipt.producer_pre_handoff_bundle.sha256 != published_bundle.sha256
            || receipt.returned_bundle.byte_length != published_bundle.byte_length
            || receipt.returned_bundle.sha256 != published_bundle.sha256
            || producer_exec.supply_bundle_sha256 != published_bundle.sha256
        {
            return Err(Diagnostic::error("E_SUPPLY_BUNDLE_COPY_JOIN", subject)
                .at("published/pre-handoff/returned"));
        }
        if receipt.bootstrap_manifest.path != expected_manifest
            || receipt.bootstrap_manifest.byte_length != BOOTSTRAP_MANIFEST_BYTES
            || receipt.bootstrap_manifest.sha256 != BOOTSTRAP_MANIFEST_SHA256
            || receipt.bootstrap_lock.path != expected_lock
            || !same_bound_bytes(&receipt.bootstrap_manifest, &producer_build.manifest)
            || !same_bound_bytes(&receipt.bootstrap_lock, &producer_build.lock)
        {
            return Err(Diagnostic::error("E_SUPPLY_BOOTSTRAP_JOIN", subject).at("manifest/lock"));
        }
        Ok(())
    }

    fn validate_supply_entry_bijection(
        receipt: &ParsedSupplyReceiptSummary,
        bundle: &SupplyBundleSummary,
        bundle_bytes: &[u8],
    ) -> VResult<()> {
        let subject = "supply-receipt/entry";
        if receipt.bootstrap_lock.byte_length != bundle.bootstrap_lock_byte_length
            || receipt.bootstrap_lock.sha256 != lower_hex(&bundle.bootstrap_lock_sha256)
            || receipt.embedded_bootstrap_lock_byte_length != bundle.bootstrap_lock_byte_length
            || receipt.embedded_bootstrap_lock_sha256 != lower_hex(&bundle.bootstrap_lock_sha256)
            || receipt.entry_count != bundle.entry_count
            || receipt.entries.len() != bundle.entries.len()
            || receipt.total_payload_bytes != bundle.total_payload_bytes
            || receipt.inner_entry_set_sha256 != lower_hex(&bundle.inner_entry_set_sha256)
            || receipt.closure_bijection_sha256 != lower_hex(&bundle.closure_bijection_sha256)
        {
            return Err(
                Diagnostic::error("E_SUPPLY_ENTRY_HEADER_JOIN", subject).at("bundle header")
            );
        }
        let binary_crate_count = bundle
            .entries
            .iter()
            .filter(|entry| entry.kind == 0x01)
            .count();
        let binary_derived_count = bundle
            .entries
            .iter()
            .filter(|entry| entry.kind == 0x02)
            .count();
        let binary_sparse_count = bundle
            .entries
            .iter()
            .filter(|entry| entry.kind == 0x03)
            .count();
        if receipt.crate_archive_count != binary_crate_count
            || receipt.derived_index_file_count != binary_derived_count
            || receipt.sparse_cache_input_count != binary_sparse_count
        {
            return Err(
                Diagnostic::error("E_SUPPLY_ENTRY_COUNT_JOIN", subject).at("binary kind partition")
            );
        }
        let mut lock_by_identity = BTreeMap::new();
        for package in &bundle.lock_triples {
            if lock_by_identity
                .insert(
                    (package.name.clone(), package.version.clone()),
                    package.clone(),
                )
                .is_some()
            {
                return Err(Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", subject)
                    .at("duplicate lock identity"));
            }
        }
        let mut consumed = vec![[false; 3]; bundle.closure_rows.len()];
        for (entry_index, (receipt_entry, binary_entry)) in
            receipt.entries.iter().zip(&bundle.entries).enumerate()
        {
            let logical = format!("{subject}[{entry_index}]");
            if receipt_entry.binding.kind != binary_entry.kind
                || receipt_entry.binding.relative_path != binary_entry.path
                || receipt_entry.binding.byte_length != binary_entry.byte_length
                || receipt_entry.binding.sha256 != lower_hex(&binary_entry.sha256)
            {
                return Err(Diagnostic::error("E_SUPPLY_ENTRY_BINARY_JOIN", &logical)
                    .at(&binary_entry.path));
            }
            match &receipt_entry.detail {
                ParsedSupplyEntryDetail::CrateArchive(detail) => {
                    if binary_entry.kind != 0x01 {
                        return Err(Diagnostic::error("E_SUPPLY_ENTRY_VARIANT_JOIN", &logical)
                            .at("crate archive kind"));
                    }
                    let matching = bundle
                        .closure_rows
                        .iter()
                        .enumerate()
                        .filter(|(_, row)| row.archive_path == binary_entry.path)
                        .collect::<Vec<_>>();
                    if matching.len() != 1 {
                        return Err(Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", &logical)
                            .at("crate archive peer"));
                    }
                    let (closure_index, row) = matching[0];
                    let triple = RegistryPackageTriple {
                        name: row.package.name.clone(),
                        version: row.package.version.clone(),
                        checksum: row.package.checksum.clone(),
                    };
                    let package = receipt.bootstrap_packages.get(&triple).ok_or_else(|| {
                        Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", &logical)
                            .at("crate package row")
                    })?;
                    if consumed[closure_index][0]
                        || row.archive_byte_length != binary_entry.byte_length
                        || row.archive_sha256 != binary_entry.sha256
                        || detail.package_id != package.package_id
                        || detail.version != row.package.version
                        || detail.checksum_sha256 != row.package.checksum
                        || detail.selected_index_line_sha256 != lower_hex(&row.selected_json_sha256)
                        || detail.yanked
                    {
                        return Err(Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", &logical)
                            .at("crate archive fields"));
                    }
                    consumed[closure_index][0] = true;
                }
                ParsedSupplyEntryDetail::DerivedIndex(detail) => {
                    if binary_entry.kind != 0x02 {
                        return Err(Diagnostic::error("E_SUPPLY_ENTRY_VARIANT_JOIN", &logical)
                            .at("derived index kind"));
                    }
                    let mut matching = bundle
                        .closure_rows
                        .iter()
                        .enumerate()
                        .filter(|(_, row)| row.derived_index_path == binary_entry.path)
                        .collect::<Vec<_>>();
                    matching.sort_by(|(_, left), (_, right)| {
                        left.sparse_path
                            .as_bytes()
                            .cmp(right.sparse_path.as_bytes())
                            .then(left.selected_ordinal.cmp(&right.selected_ordinal))
                    });
                    if matching.is_empty()
                        || matching.iter().any(|(_, row)| {
                            row.package.name != detail.package_name
                                || row.derived_index_byte_length != binary_entry.byte_length
                                || row.derived_index_sha256 != binary_entry.sha256
                        })
                        || detail.derived_index_sha256 != lower_hex(&binary_entry.sha256)
                        || detail.selected_versions
                            != matching
                                .iter()
                                .map(|(_, row)| row.package.version.clone())
                                .collect::<Vec<_>>()
                    {
                        return Err(Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", &logical)
                            .at("derived index fields"));
                    }
                    for (closure_index, _) in matching {
                        if consumed[closure_index][1] {
                            return Err(Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", &logical)
                                .at("duplicate derived peer"));
                        }
                        consumed[closure_index][1] = true;
                    }
                }
                ParsedSupplyEntryDetail::SparseCache(detail) => {
                    if binary_entry.kind != 0x03 {
                        return Err(Diagnostic::error("E_SUPPLY_ENTRY_VARIANT_JOIN", &logical)
                            .at("sparse cache kind"));
                    }
                    let payload =
                        ordinary_supply_entry_payload(bundle_bytes, binary_entry, &logical)?;
                    let parsed = parse_ordinary_summaries_cache_summary(
                        payload,
                        binary_entry,
                        &lock_by_identity,
                        &logical,
                    )?;
                    let cache_relative_path = binary_entry
                        .path
                        .strip_prefix("sparse-cache/")
                        .ok_or_else(|| {
                            Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", &logical)
                                .at("sparse cache path")
                        })?;
                    let selected_versions = parsed
                        .selected
                        .iter()
                        .map(|row| row.package.version.clone())
                        .collect::<Vec<_>>();
                    let selected_ordinals = parsed
                        .selected
                        .iter()
                        .map(|row| row.ordinal)
                        .collect::<Vec<_>>();
                    let selected_sha256 = parsed
                        .selected
                        .iter()
                        .map(|row| lower_hex(&sha256(row.json)))
                        .collect::<Vec<_>>();
                    if detail.cache_relative_path != cache_relative_path
                        || detail.validator != parsed.validator
                        || detail.selected_versions != selected_versions
                        || detail.selected_ordinals != selected_ordinals
                        || detail.selected_sha256 != selected_sha256
                    {
                        return Err(Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", &logical)
                            .at("sparse cache fields"));
                    }
                    for selected in parsed.selected {
                        let selected_json_byte_length = u64::try_from(selected.json.len())
                            .map_err(|_| {
                                Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", &logical)
                                    .at("selected JSON length")
                            })?;
                        let selected_json_sha256 = sha256(selected.json);
                        let matching = bundle
                            .closure_rows
                            .iter()
                            .enumerate()
                            .filter(|(_, row)| {
                                row.package == selected.package
                                    && row.sparse_path == binary_entry.path
                                    && row.sparse_byte_length == binary_entry.byte_length
                                    && row.sparse_sha256 == binary_entry.sha256
                                    && row.selected_ordinal == selected.ordinal
                                    && row.selected_json_byte_length == selected_json_byte_length
                                    && row.selected_json_sha256 == selected_json_sha256
                            })
                            .collect::<Vec<_>>();
                        if matching.len() != 1 || consumed[matching[0].0][2] {
                            return Err(Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", &logical)
                                .at("sparse selected peer"));
                        }
                        consumed[matching[0].0][2] = true;
                    }
                }
            }
        }
        if consumed.is_empty() || consumed.iter().any(|row| row != &[true, true, true]) {
            return Err(Diagnostic::error("E_SUPPLY_ENTRY_CLOSURE_JOIN", subject)
                .at("each closure row must be consumed by all three variants"));
        }
        validate_supply_acquisition_anchor_bijection(receipt, bundle)?;
        Ok(())
    }

