                || parsed.package_id.len() > policy.bounds.max_record_string_bytes
                || parsed.build_script_id.is_empty()
                || parsed.build_script_id.len() > policy.bounds.max_record_string_bytes
                || parsed.program.is_empty()
                || parsed.program.len() > policy.bounds.max_record_string_bytes
                || parsed.program.as_bytes().contains(&0)
