    fn core_conformance_authority_field(
        document: &toml::Value,
        section: &str,
        field: &str,
        expected: &str,
    ) -> VResult<()> {
        if document
            .as_table()
            .and_then(|root| root.get(section))
            .and_then(toml::Value::as_table)
            .and_then(|table| table.get(field))
            .and_then(toml::Value::as_str)
            != Some(expected)
        {
            return Err(Diagnostic::error("E_CORE_CONFORMANCE_AUTHORITY", section).at(field));
        }
        Ok(())
    }

    fn core_conformance_artifact<'a>(
        document: &'a toml::Value,
        id: &str,
    ) -> VResult<&'a toml::map::Map<String, toml::Value>> {
        document
            .as_table()
            .and_then(|root| root.get("artifacts"))
            .and_then(toml::Value::as_array)
            .and_then(|artifacts| {
                artifacts
                    .iter()
                    .filter_map(toml::Value::as_table)
                    .find(|artifact| artifact.get("id").and_then(toml::Value::as_str) == Some(id))
            })
            .ok_or_else(|| Diagnostic::error("E_CORE_CONFORMANCE_ARTIFACT", id))
    }

    fn git_blob_sha1(bytes: &[u8]) -> String {
        let mut canonical = format!("blob {}\0", bytes.len()).into_bytes();
        canonical.extend_from_slice(bytes);
        lower_hex(ring_digest(&SHA1_FOR_LEGACY_USE_ONLY, &canonical).as_ref())
    }

    #[derive(Clone, Debug, PartialEq)]
    struct CoreConformanceRecord {
        label: &'static str,
        fields: toml::map::Map<String, toml::Value>,
    }

    #[derive(Clone, Debug, PartialEq)]
    struct CoreConformanceTreeEdge {
        fields: toml::map::Map<String, toml::Value>,
        parent_edge: Option<usize>,
    }

    #[derive(Clone, Debug, PartialEq)]
    struct CoreConformanceAdmittedArtifact {
        manifest: CoreConformanceRecord,
        path: String,
        bytes: Vec<u8>,
        digest: [u8; 32],
    }

    #[derive(Clone, Debug, PartialEq)]
    struct CoreConformanceAcceptedBinding {
        authority: Vec<CoreConformanceRecord>,
        artifacts: Vec<CoreConformanceAdmittedArtifact>,
        tree_chain: Vec<CoreConformanceTreeEdge>,
        licenses: Vec<CoreConformanceRecord>,
        no_claim: CoreConformanceRecord,
        registries: Vec<CoreConformanceRecord>,
        group_digests: [(&'static str, [u8; 32]); 6],
    }

    fn core_conformance_root(
        document: &toml::Value,
    ) -> VResult<&toml::map::Map<String, toml::Value>> {
        document
            .as_table()
            .ok_or_else(|| Diagnostic::error("E_CORE_CONFORMANCE_MANIFEST", "core-conformance"))
    }

    fn validate_core_conformance_manifest_binding(
        document: &toml::Value,
        admitted_files: &[LoadedFile],
    ) -> VResult<()> {
        let source = source_lookup(admitted_files, "evidence/fnd-01/core-conformance.toml")?;
        if source.bytes.len() != 54_154
            || source.digest != sha256(&source.bytes)
            || lower_hex(&source.digest)
                != "76403615758b3c6ee6eafebf4755d9eadbb7713e240421eceb4f1776c0083750"
        {
            return Err(Diagnostic::error(
                "E_CORE_CONFORMANCE_MANIFEST_BINDING",
                "core-conformance",
            ));
        }
        let admitted = parse_source_toml(admitted_files, "evidence/fnd-01/core-conformance.toml")?;
        if document != &admitted {
            return Err(Diagnostic::error(
                "E_CORE_CONFORMANCE_MANIFEST_BINDING",
                "core-conformance",
            ));
        }
        Ok(())
    }

