    #[test]
    fn fnd_01_toolchain_and_workflow_action_identities_are_closed() {
        assert_eq!(EXACT_RUST_TOOLCHAIN_TOML.len(), 239);
        assert_eq!(
            lower_hex(&sha256(EXACT_RUST_TOOLCHAIN_TOML.as_bytes())),
            "58ab2dcb0e12130199f0f404141dc333734cbc28c1f163f9f0c7ccd1f2a2a37f",
        );
        assert!(is_exact_rust_toolchain_document(
            EXACT_RUST_TOOLCHAIN_TOML.as_bytes(),
        ));
        let toolchain_mutations = [
            EXACT_RUST_TOOLCHAIN_TOML.replace('\n', "\r\n"),
            EXACT_RUST_TOOLCHAIN_TOML
                .strip_suffix('\n')
                .expect("exact toolchain has final LF")
                .to_owned(),
            format!("{EXACT_RUST_TOOLCHAIN_TOML}\n"),
            format!("# comment\n{EXACT_RUST_TOOLCHAIN_TOML}"),
            format!("\u{feff}{EXACT_RUST_TOOLCHAIN_TOML}"),
            EXACT_RUST_TOOLCHAIN_TOML.replacen(
                "channel = \"nightly-2026-07-11\"\nprofile = \"minimal\"",
                "profile = \"minimal\"\nchannel = \"nightly-2026-07-11\"",
                1,
            ),
            EXACT_RUST_TOOLCHAIN_TOML.replacen(
                "profile = \"minimal\"",
                "profile  = \"minimal\"",
                1,
            ),
            EXACT_RUST_TOOLCHAIN_TOML.replacen(
                "\"aarch64-apple-darwin\", \"aarch64-unknown-linux-gnu\"",
                "\"aarch64-unknown-linux-gnu\", \"aarch64-apple-darwin\"",
                1,
            ),
        ];
        for mutation in toolchain_mutations {
            assert!(
                !is_exact_rust_toolchain_document(mutation.as_bytes()),
                "mutated toolchain bytes must fail exact comparison",
            );
        }

        for (reference, _, _) in WORKFLOW_ACTION_IDENTITIES {
            validate_workflow_action_reference(reference, "valid action")
                .verified();
        }
        let invalid_actions = [
            "actions/checkout@v4",
            "actions/checkout@main",
            "actions/checkout@3D3C42E5AAC5BA805825DA76410C181273BA90B1",
            "actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b",
            "actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b10",
            "actions/checkout@0000000000000000000000000000000000000000",
            "./.github/actions/local",
            "docker://alpine:3.20",
            "${{ matrix.action }}",
            "actions/checkout/path@3d3c42e5aac5ba805825da76410c181273ba90b1",
            "actions/checkout@@3d3c42e5aac5ba805825da76410c181273ba90b1",
            "actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 ",
        ];
        for reference in invalid_actions {
            assert_eq!(
                validate_workflow_action_reference(reference, "invalid action")
                    .expect_err("unapproved workflow action identity must fail")
                    .code,
                "E_WORKFLOW_ACTION_IDENTITY",
            );
        }

        let quoted = parse_restricted_workflow_yaml(
            &format!("jobs:\n  build:\n    steps:\n      - \"uses\": {ACTION_CHECKOUT}\n"),
            "quoted uses workflow",
        )
        .verified();
        let mut references = Vec::new();
        collect_workflow_action_references(&quoted, "quoted uses workflow", &mut references)
            .verified();
        assert_eq!(references, [ACTION_CHECKOUT]);

        assert_eq!(
            parse_restricted_workflow_yaml(
                "jobs:\n  build:\n    steps:\n      - uses: [nested]\n",
                "nonscalar uses workflow",
            )
            .expect_err("a uses sequence must fail")
            .code,
            "E_WORKFLOW_YAML_TYPE",
        );
    }

    #[test]
    fn fnd_01_dependency_evidence_is_strict_offline_and_fail_closed() {
        match run_verifier() {
            Ok(report) => {
                assert!(
                    !report.has_errors(),
                    "FND-01 verifier errors:\n{}",
                    report.sorted_stable().join("\n")
                );
                for diagnostic in &report.diagnostics {
                    assert_eq!(
                        diagnostic.severity,
                        Severity::Pending,
                        "only explicit pending gates are admissible before final attestation"
                    );
                    assert!(
                        diagnostic.code.starts_with("E_PENDING_GATE:FND01:"),
                        "pending diagnostics must carry the exact phase gate: {}",
                        diagnostic.code
                    );
                }
                validate_case_unique(
                    report
                        .diagnostics
                        .iter()
                        .map(|diagnostic| diagnostic.code.clone()),
                    "pending gates",
                )
                .verified();
            }
            Err(diagnostic) => {
                panic!("FND-01 verifier failed: {}", diagnostic.stable());
            }
        }
    }

    #[test]
    fn fnd_01_static_oracles_have_exact_cardinality_and_no_case_collisions() {
        let specs = negative_specs();
        assert_eq!(specs.len(), EXPECTED_NEGATIVES);
        validate_case_unique(
            specs
                .iter()
                .map(|spec| format!("{}/{}", spec.family, spec.id)),
            "static negative registry",
        )
        .verified();

        let outputs = expected_receipt_paths().verified();
        assert_eq!(outputs.len(), EXPECTED_RECEIPTS);
        assert_eq!(TOML_OUTPUT_IDS.len(), EXPECTED_RECEIPT_TOMLS);
        assert_eq!(BINARY_OUTPUT_IDS.len(), EXPECTED_RECEIPT_BINARIES);
        validate_case_unique(outputs, "static receipt matrix")
            .verified();

        let matrix = expected_derived_outputs().verified();
        assert_eq!(matrix.len(), EXPECTED_RECEIPTS);
        assert_eq!(
            matrix
                .values()
                .map(|output| output.required_parent_ids.len())
                .sum::<usize>(),
            EXPECTED_DIRECT_PARENT_EDGES
        );
        let matrix_paths = matrix
            .values()
            .map(|output| {
                output
                    .path
                    .strip_prefix("evidence/fnd-01/integration/")
                    .expect("static oracle path has integration prefix")
                    .to_owned()
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(
            matrix_paths,
            expected_receipt_paths().verified()
        );
    }

    #[test]
    fn fnd_01_strict_json_preserves_arbitrary_precision_and_rejects_duplicates() {
        for number_text in [
            "18446744073709551616",
            "-9223372036854775809",
            "340282366920938463463374607431768211455",
            "-170141183460469231731687303715884105728",
            "1234567890123456789012345678901234567890",
        ] {
            let parsed = parse_strict_json(
                number_text.as_bytes(),
                "arbitrary-precision integer self-test",
            )
            .verified();
            let StrictJson::Number(number) = parsed else {
                panic!("large JSON integer was not classified as a number");
            };
            assert_eq!(
                number.to_string(),
                number_text,
                "serde_json arbitrary_precision must preserve every tested integer"
            );
        }

        let negative_zero = parse_strict_json(b"-0", "negative-zero self-test").verified();
        let StrictJson::Number(negative_zero) = negative_zero else {
            panic!("negative zero was not classified as a number");
        };
        assert_eq!(
            negative_zero.to_string(),
            "0",
            "FND01OBS uses serde_json::Number::to_string canonical form, not the source lexeme"
        );

        let duplicate = parse_strict_json(br#"{"same":1,"same":2}"#, "duplicate-key self-test")
            .expect_err("duplicate JSON object members must fail closed");
        assert_eq!(duplicate.code, "E_JSON_SCHEMA");

        for reserved_object in [
            br#"{"$serde_json::private::Number":"123"}"#.as_slice(),
            br#"{"nested":{"$serde_json::private::\u004eumber":"123"}}"#.as_slice(),
        ] {
            let reserved = parse_strict_json(reserved_object, "reserved-key self-test")
                .expect_err("decoded private number carrier member must fail closed");
            assert_eq!(reserved.code, "E_JSON_SCHEMA");
        }
        parse_strict_json(
            br#"{"ordinary":"$serde_json::private::Number"}"#,
            "reserved-name string-value self-test",
        )
        .expect("reserved carrier text is forbidden only as a decoded object member name");
    }

    #[test]
    fn fnd_01_archive_parser_rejects_boundary_and_namespace_ambiguity() {
        let valid_tar = test_tar(&[("demo-1.0.0/src/lib.rs", b"x", 0)]);
        let valid_gzip = test_gzip(&valid_tar);
        let summary = validate_gzip_tar(
            &valid_gzip,
            &archive_test_bounds(),
            "in-memory archive",
            Some("demo-1.0.0"),
        )
        .expect("frozen in-memory archive must be valid");
        assert_eq!(summary.member_count, 1);
        assert_eq!(summary.regular_file_count, 1);
        assert_eq!(summary.expanded_bytes, 1);

        let missing_terminal = test_gzip(&valid_tar[..valid_tar.len() - 1_024]);
        assert_archive_error(&missing_terminal, "demo-1.0.0", "E_TAR_TERMINATOR");

        let single_terminal = test_gzip(&valid_tar[..valid_tar.len() - 512]);
        assert_archive_error(&single_terminal, "demo-1.0.0", "E_TAR_TERMINATOR");

        let mut third_terminal = valid_tar.clone();
        third_terminal.resize(third_terminal.len() + 512, 0);
        assert_archive_error(&test_gzip(&third_terminal), "demo-1.0.0", "E_TAR_TRAILING");

        let mut appended_bytes = valid_gzip.clone();
        appended_bytes.push(0);
        assert_archive_error(&appended_bytes, "demo-1.0.0", "E_GZIP_TRAILING");

        let mut concatenated = valid_gzip.clone();
        concatenated.extend_from_slice(&valid_gzip);
        assert_archive_error(&concatenated, "demo-1.0.0", "E_GZIP_TRAILING");

        assert_archive_error(&valid_gzip, "other-1.0.0", "E_TAR_ROOT");
        let bare_root = test_gzip(&test_tar(&[("demo-1.0.0", b"x", 0)]));
        assert_archive_error(&bare_root, "demo-1.0.0", "E_TAR_ROOT");

        let special = test_gzip(&test_tar(&[("demo-1.0.0/link", b"", b'5')]));
        assert_archive_error(&special, "demo-1.0.0", "E_TAR_ENTRY_TYPE");

        let duplicate = test_gzip(&test_tar(&[
            ("demo-1.0.0/a", b"a", 0),
            ("demo-1.0.0/a", b"b", 0),
        ]));
        assert_archive_error(&duplicate, "demo-1.0.0", "E_INVENTORY_DUPLICATE");

        let case_collision = test_gzip(&test_tar(&[
            ("demo-1.0.0/A", b"a", 0),
            ("demo-1.0.0/a", b"b", 0),
        ]));
        assert_archive_error(&case_collision, "demo-1.0.0", "E_CASE_COLLISION");

        let mut bad_padding_tar = valid_tar.clone();
        bad_padding_tar[513] = 1;
        assert_archive_error(&test_gzip(&bad_padding_tar), "demo-1.0.0", "E_TAR_PADDING");
    }

    #[test]
    fn fnd_01_ordinary_supply_parses_before_validating_every_archive() {
        let alpha = test_gzip(&test_tar(&[("alpha-1.2.3/src/lib.rs", b"alpha", 0)]));
        let beta = test_gzip(&test_tar(&[("beta-2.0.0/src/lib.rs", b"beta", 0)]));
        let valid = test_ordinary_supply_bundle(&[
            ("alpha-1.2.3.crate", &alpha),
            ("beta-2.0.0.crate", &beta),
        ]);
        let framing = parse_ordinary_supply_framing(&valid, "ordinary supply self-test")
            .verified();
        assert_eq!(
            framing
                .archives
                .iter()
                .map(|archive| archive.expected_root.as_str())
                .collect::<Vec<_>>(),
            ["alpha-1.2.3", "beta-2.0.0"],
        );
        validate_ordinary_supply_archives(&valid, &framing)
            .verified();

        let lock_length_offset = b"FND01SUPPLYv4\0".len();
        let lock_length = usize::try_from(u64::from_be_bytes(
            valid[lock_length_offset..lock_length_offset + 8]
                .try_into()
                .expect("synthetic lock length"),
        ))
        .expect("synthetic lock length fits usize");
        let lock_start = lock_length_offset + 8 + 32;
        let lock_text = std::str::from_utf8(&valid[lock_start..lock_start + lock_length])
            .expect("synthetic lock is UTF-8");
        let unreachable_lock = lock_text.replace(" \"beta\",\n", "");
        assert_ne!(
            unreachable_lock, lock_text,
            "synthetic lock mutation must remove one controlled-root edge",
        );
        let mut unreachable_and_corrupt_tail =
            test_replace_supply_bootstrap_lock(&valid, unreachable_lock.as_bytes());
        *unreachable_and_corrupt_tail
            .last_mut()
            .expect("synthetic supply has a tail") ^= 1;
        assert_eq!(
            parse_ordinary_supply_framing(
                &unreachable_and_corrupt_tail,
                "unreachable ordinary supply lock",
            )
            .expect_err("unreachable lock must fail before the corrupt entry tail")
            .code,
            "E_SUPPLY_LOCK_UNREACHABLE",
        );

        let sample_v1 = test_gzip(&test_tar(&[("sample-1.0.0/src/lib.rs", b"sample-v1", 0)]));
        let sample_v2 = test_gzip(&test_tar(&[("sample-2.0.0/src/lib.rs", b"sample-v2", 0)]));
        let multi_version = test_ordinary_supply_bundle(&[
            ("sample-1.0.0.crate", &sample_v1),
            ("sample-2.0.0.crate", &sample_v2),
        ]);
        let multi_version_framing =
            parse_ordinary_supply_framing(&multi_version, "multi-version ordinary supply")
                .verified();
        assert_eq!(
            multi_version_framing
                .entries
                .iter()
                .map(|entry| entry.kind)
                .collect::<Vec<_>>(),
            [0x01, 0x01, 0x02, 0x03],
            "two versions of one package share one derived index and sparse cache",
        );
        assert_eq!(
            multi_version_framing
                .closure_rows
                .iter()
                .map(|row| row.selected_ordinal)
                .collect::<Vec<_>>(),
            [0, 1],
        );
        assert_eq!(
            multi_version_framing.closure_rows[0].sparse_path,
            multi_version_framing.closure_rows[1].sparse_path,
        );
        assert_eq!(
            multi_version_framing.closure_rows[0].sparse_sha256,
            multi_version_framing.closure_rows[1].sparse_sha256,
        );
        assert_eq!(
            multi_version_framing.closure_rows[0].derived_index_sha256,
            multi_version_framing.closure_rows[1].derived_index_sha256,
        );
        validate_ordinary_supply_archives(&multi_version, &multi_version_framing)
            .verified();

        let reversed = test_ordinary_supply_bundle(&[
            ("beta-2.0.0.crate", &beta),
            ("alpha-1.2.3.crate", &alpha),
        ]);
        assert_eq!(
            parse_ordinary_supply_framing(&reversed, "reversed ordinary supply")
                .expect_err("out-of-order archive entries must fail before decompression")
                .code,
            "E_ORDINARY_SUPPLY_ORDER",
        );

        let mut changed_payload = valid.clone();
        let final_byte = changed_payload
            .last_mut()
            .expect("synthetic supply has an archive payload");
        *final_byte ^= 1;
        assert_eq!(
            parse_ordinary_supply_framing(&changed_payload, "changed ordinary supply")
                .expect_err("payload digest drift must fail before decompression")
                .code,
            "E_ORDINARY_SUPPLY_DIGEST",
        );

        let wrong_root_payload = test_gzip(&test_tar(&[("wrong-9.9.9/src/lib.rs", b"wrong", 0)]));
        let wrong_root = test_ordinary_supply_bundle(&[("right-9.9.9.crate", &wrong_root_payload)]);
        let wrong_root_framing =
            parse_ordinary_supply_framing(&wrong_root, "wrong-root ordinary supply")
                .expect("container framing is independent of tar validation");
        assert_eq!(
            validate_ordinary_supply_archives(&wrong_root, &wrong_root_framing)
                .expect_err("tar root must equal the exact .crate basename")
                .code,
            "E_TAR_ROOT",
        );
    }

    #[test]
    fn fnd_01_supply_v4_header_is_exact_and_config_is_evidence_only() {
        let archive = test_gzip(&test_tar(&[("sample-1.2.3/src/lib.rs", b"sample", 0)]));
        let valid = test_ordinary_supply_bundle(&[("sample-1.2.3.crate", &archive)]);
        let framing = parse_ordinary_supply_framing(&valid, "supply-v4 header")
            .verified();
        assert_eq!(framing.sparse_config_path, ACQUISITION_SPARSE_CONFIG_PATH,);
        assert!(framing.acquisition_root_entry_count > 0);
        assert!(framing.acquisition_root_total_regular_file_bytes > 0);
        assert!(framing
            .entries
            .iter()
            .all(|entry| entry.path != ACQUISITION_SPARSE_CONFIG_PATH));

        let offsets = test_supply_v4_header_offsets(&valid);
        assert_eq!(
            &valid[offsets.config_payload..offsets.config_payload + offsets.config_length],
            &valid[framing.sparse_config_payload_offset
                ..framing.sparse_config_payload_offset
                    + usize::try_from(framing.sparse_config_byte_length)
                        .expect("framing config length fits usize")],
        );

        let mut v3 = valid.clone();
        let version_offset = b"FND01SUPPLYv".len();
        v3[version_offset] = b'3';
        assert_eq!(
            parse_ordinary_supply_framing(&v3, "rejected supply-v3")
                .expect_err("v3 must not be treated as v4")
                .code,
            "E_ORDINARY_SUPPLY_HEADER",
        );

        let mut zero_root = valid.clone();
        zero_root[offsets.root_digest..offsets.root_digest + 32].fill(0);
        assert_eq!(
            parse_ordinary_supply_framing(&zero_root, "zero acquisition root")
                .expect_err("zero root digest sentinel must fail")
                .code,
            "E_ORDINARY_SUPPLY_ACQUISITION",
        );

        let mut wrong_path = valid.clone();
        wrong_path[offsets.config_path] ^= 1;
        assert_eq!(
            parse_ordinary_supply_framing(&wrong_path, "wrong config path")
                .expect_err("the fixed config path must join exactly")
                .code,
            "E_ORDINARY_SUPPLY_ACQUISITION",
        );

        let mut stale_config = valid.clone();
        stale_config[offsets.config_payload] ^= 1;
        assert_eq!(
            parse_ordinary_supply_framing(&stale_config, "stale config digest",)
                .expect_err("config bytes with a stale digest must fail")
                .code,
            "E_ORDINARY_SUPPLY_ACQUISITION",
        );

        let mut rebound_config = stale_config;
        let config_digest = sha256(
            &rebound_config[offsets.config_payload..offsets.config_payload + offsets.config_length],
        );
        rebound_config[offsets.config_digest..offsets.config_digest + 32]
            .copy_from_slice(&config_digest);
        parse_ordinary_supply_framing(&rebound_config, "rebound config digest")
            .expect("a self-consistent v4 header remains parseable");
        assert_ne!(
            sha256(&rebound_config),
            sha256(&valid),
            "a config rewrite changes the full supply binding",
        );

        let truncated = &valid[..valid.len() - 1];
        assert!(parse_ordinary_supply_framing(truncated, "truncated supply-v4").is_err(),);
    }

