    #[test]
    fn fnd_01_final_attestation_joins_exact_producer_aggregate_digests() {
        let streams_sha256 = "11".repeat(32);
        let lock_set_sha256 = "22".repeat(32);
        let streams = ReceiptOutputBinding {
            id: "command-streams".to_owned(),
            path: "evidence/fnd-01/integration/command-streams.bin.gz".to_owned(),
            kind: "command_streams".to_owned(),
            byte_length: 17,
            sha256: streams_sha256.clone(),
        };
        validate_final_producer_digest_joins(
            &streams_sha256,
            &lock_set_sha256,
            &streams,
            Some(lock_set_sha256.as_str()),
            "synthetic final attestation",
        )
        .expect("exact producer commitments join");

        let error = validate_final_producer_digest_joins(
            &"33".repeat(32),
            &lock_set_sha256,
            &streams,
            Some(lock_set_sha256.as_str()),
            "synthetic final attestation",
        )
        .expect_err("a different compressed stream digest must fail");
        assert_eq!(error.code, "E_FINAL_PRODUCER_DIGEST_JOIN");
        let changed_lock_set_sha256 = "44".repeat(32);
        let error = validate_final_producer_digest_joins(
            &streams_sha256,
            &lock_set_sha256,
            &streams,
            Some(changed_lock_set_sha256.as_str()),
            "synthetic final attestation",
        )
        .expect_err("a different post-command lock row-set digest must fail");
        assert_eq!(error.code, "E_FINAL_PRODUCER_DIGEST_JOIN");
    }

    #[test]
    fn fnd_01_final_attestation_command_population_is_exact() {
        let producer_ids = vec![
            "bootstrap.resolve".to_owned(),
            "bootstrap.fetch".to_owned(),
            "workspace.gate".to_owned(),
        ];
        let excluded = producer_ids[..2].to_vec();
        validate_final_command_population(
            3,
            1,
            &excluded,
            3,
            1,
            &excluded,
            &producer_ids,
            3,
            "synthetic final attestation",
        )
        .expect("exact producer/attester population");

        let reversed = vec![excluded[1].clone(), excluded[0].clone()];
        assert!(validate_final_command_population(
            3,
            1,
            &reversed,
            3,
            1,
            &excluded,
            &producer_ids,
            3,
            "synthetic final attestation",
        )
        .is_err());
        let missing_excluded_id = vec!["bootstrap.resolve".to_owned(), "workspace.gate".to_owned()];
        assert!(validate_final_command_population(
            2,
            0,
            &excluded,
            2,
            0,
            &excluded,
            &missing_excluded_id,
            2,
            "synthetic final attestation",
        )
        .is_err());
    }

    #[test]
    fn fnd_01_final_attestation_bootstrap_reconstruction_is_byte_exact() {
        let binding = |path: &str, digest_byte: &str| ParsedFileBinding {
            path: path.to_owned(),
            byte_length: 7,
            sha256: digest_byte.repeat(64),
        };
        let producer_build = ParsedBootstrapControlBuild {
            manifest: binding("/producer/Cargo.toml", "1"),
            lock: binding("/producer/Cargo.lock", "2"),
            cargo_config: binding("/producer/cargo-config.toml", "3"),
            harness_copy: binding("/producer/src/main.rs", "4"),
            verifier_copy: binding("/producer/tests/verifier.rs", "5"),
        };
        let attester_build = ParsedBootstrapControlBuild {
            manifest: binding("/attester/Cargo.toml", "1"),
            lock: binding("/attester/Cargo.lock", "2"),
            cargo_config: binding("/attester/cargo-config.toml", "3"),
            harness_copy: binding("/attester/src/main.rs", "4"),
            verifier_copy: binding("/attester/tests/verifier.rs", "5"),
        };
        let supply_sha256 = "66".repeat(32);
        let exec = |role: &str| ParsedBootstrapExecEntry {
            id: "bootstrap-control.exec".to_owned(),
            ledger: binding(&format!(".fnd01-run/{role}/ledger.bin"), "7"),
            executable: binding(&format!("/{role}/harness"), "8"),
            repository_root: format!("/{role}"),
            supply_bundle_sha256: supply_sha256.clone(),
            integration_seal: None,
        };
        let producer_exec = exec("producer");
        let attester_exec = exec("attester");
        let supply_bundle = ReceiptOutputBinding {
            id: "supply-bundle".to_owned(),
            path: "evidence/fnd-01/integration/supply-bundle.bin".to_owned(),
            kind: "supply_bundle".to_owned(),
            byte_length: 23,
            sha256: supply_sha256,
        };
        validate_bootstrap_reconstruction_join(
            &producer_build,
            &producer_exec,
            &attester_build,
            &attester_exec,
            &supply_bundle,
            "synthetic final attestation",
        )
        .expect("paths may differ while reconstructed bytes remain exact");

        let mut changed = attester_build;
        changed.lock.sha256 = "99".repeat(32);
        let error = validate_bootstrap_reconstruction_join(
            &producer_build,
            &producer_exec,
            &changed,
            &attester_exec,
            &supply_bundle,
            "synthetic final attestation",
        )
        .expect_err("changed reconstructed lock bytes must fail");
        assert_eq!(error.code, "E_FINAL_BOOTSTRAP_RECONSTRUCTION");
    }

    #[test]
    fn fnd_01_final_attestation_integration_seal_joins_every_bound_object() {
        let make_output = |id: &str, byte: &str| ReceiptOutputBinding {
            id: id.to_owned(),
            path: format!("evidence/fnd-01/integration/{id}"),
            kind: id.to_owned(),
            byte_length: 9,
            sha256: byte.repeat(64),
        };
        let mut outputs = BTreeMap::new();
        for (id, byte) in [
            ("source-snapshot", "1"),
            ("supply-bundle", "2"),
            ("workspace-receipt", "3"),
            ("integration-index", "4"),
        ] {
            outputs.insert(id, make_output(id, byte));
        }
        let workspace = ParsedFileBinding {
            path: "Cargo.lock".to_owned(),
            byte_length: 11,
            sha256: "55".repeat(32),
        };
        let producer_outer = ParsedFileBinding {
            path: ".fnd01-run/controller/run/producer-outer.bin".to_owned(),
            byte_length: 13,
            sha256: "66".repeat(32),
        };
        let authoring = ActualAuthoringBindings {
            policy: ActualFileBinding {
                path: "policy".to_owned(),
                byte_length: 1,
                sha256: "77".repeat(32),
            },
            verifier: ActualFileBinding {
                path: "verifier".to_owned(),
                byte_length: 1,
                sha256: "88".repeat(32),
            },
            harness: ActualFileBinding {
                path: "harness".to_owned(),
                byte_length: 1,
                sha256: "99".repeat(32),
            },
            closure_sha256: "aa".repeat(32),
        };
        let run_id = [0x0b; 16];
        let mut seal = super::trust_std::IntegrationSeal {
            run_id,
            records: [
                parsed_trust_file_binding(&workspace, "synthetic seal").expect("workspace binding"),
                output_trust_file_binding(&outputs["source-snapshot"], "synthetic seal")
                    .expect("source binding"),
                output_trust_file_binding(&outputs["supply-bundle"], "synthetic seal")
                    .expect("supply binding"),
                output_trust_file_binding(&outputs["workspace-receipt"], "synthetic seal")
                    .expect("workspace receipt binding"),
                output_trust_file_binding(&outputs["integration-index"], "synthetic seal")
                    .expect("index binding"),
            ],
            outer_transport: parsed_trust_file_binding(&producer_outer, "synthetic seal")
                .expect("outer binding"),
            authoring_closure_sha256: [0xaa; 32],
            seal_sha256: [0; 32],
        };
        seal.seal_sha256 = sha256(
            &super::trust_std::integration_seal_preimage(&seal)
                .expect("bounded integration preimage"),
        );
        let seal_sha256 = lower_hex(&seal.seal_sha256);
        validate_integration_seal_join(
            &seal,
            &run_id,
            &authoring,
            &seal_sha256,
            &producer_outer,
            &workspace,
            &outputs,
            "synthetic final attestation",
        )
        .expect("all six sealed byte objects join");

        let mut changed = seal;
        changed.records[3].byte_length += 1;
        assert!(validate_integration_seal_join(
            &changed,
            &run_id,
            &authoring,
            &seal_sha256,
            &producer_outer,
            &workspace,
            &outputs,
            "synthetic final attestation",
        )
        .is_err());
    }

    #[test]
    fn fnd_01_binary_cursor_rejects_truncation_bounds_utf8_and_trailing_bytes() {
        let mut truncated = BinaryCursor::new(&[0, 1, 2], "truncated");
        assert_eq!(
            truncated.read_u64().expect_err("short u64 must fail").code,
            "E_BINARY_TRUNCATED"
        );

        let mut oversized = BinaryCursor::new(&[0, 0, 0, 4, b'a', b'b', b'c', b'd'], "oversized");
        assert_eq!(
            oversized
                .read_string(3)
                .expect_err("declared string above the field bound must fail")
                .code,
            "E_BINARY_BOUND"
        );

        let mut invalid_utf8 = BinaryCursor::new(&[0, 0, 0, 2, 0xff, 0xfe], "invalid UTF-8");
        assert_eq!(
            invalid_utf8
                .read_string(8)
                .expect_err("invalid UTF-8 must fail")
                .code,
            "E_BINARY_UTF8"
        );

        let mut nul = BinaryCursor::new(&[0, 0, 0, 1, 0], "NUL string");
        assert_eq!(
            nul.read_string(8)
                .expect_err("NUL-bearing string must fail")
                .code,
            "E_BINARY_UTF8"
        );

        assert_eq!(
            BinaryCursor::new(b"\0", "trailing")
                .finish()
                .expect_err("unread suffix must fail")
                .code,
            "E_BINARY_TRAILING"
        );
    }

    #[test]
    fn fnd_01_command_id_expansion_is_exact_and_canonical() {
        let root = repository_root();
        let (policy, _) =
            read_policy(&root).verified();
        let ids = expected_command_ids(&policy).verified();
        assert_eq!(ids.len(), 206);
        assert_eq!(ids.first().map(String::as_str), Some("bootstrap.resolve"));
        assert_eq!(ids.get(1).map(String::as_str), Some("bootstrap.fetch"));
        assert_eq!(
            ids.get(191).map(String::as_str),
            Some("package.list.fastmcp-cli")
        );
        assert_eq!(
            ids.get(206),
            None,
            "the command matrix must remain the exact 206-row expansion"
        );
        assert_eq!(ids.last().map(String::as_str), Some("consumer.test.all"));
        assert_eq!(
            ids.iter().collect::<BTreeSet<_>>().len(),
            ids.len(),
            "the expanded command matrix must not contain duplicate IDs"
        );
    }

