    fn ordinary_supply_entry_payload<'a>(
        bytes: &'a [u8],
        entry: &OrdinarySupplyEntryBinding,
        subject: &str,
    ) -> VResult<&'a [u8]> {
        let payload_length = usize::try_from(entry.byte_length)
            .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject).at(&entry.path))?;
        let payload_end = entry
            .payload_offset
            .checked_add(payload_length)
            .ok_or_else(|| Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject).at(&entry.path))?;
        let payload = bytes
            .get(entry.payload_offset..payload_end)
            .ok_or_else(|| Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject).at(&entry.path))?;
        if sha256(payload) != entry.sha256 {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_DIGEST", subject).at(&entry.path));
        }
        Ok(payload)
    }

    fn ordinary_index_error(subject: &str, detail: impl Into<String>) -> Diagnostic {
        Diagnostic::error("E_ORDINARY_SUPPLY_INDEX_JSON", subject).at(detail.into())
    }

    fn ordinary_index_exact_fields(
        object: &BTreeMap<String, StrictJson>,
        required: &[&str],
        optional: &[&str],
        subject: &str,
    ) -> VResult<()> {
        if sparse_fields_exact(
            |field| object.contains_key(field),
            object.keys().map(String::as_str),
            object.len(),
            required,
            optional,
        ) {
            return Ok(());
        }
        Err(ordinary_index_error(
            subject,
            "missing required or unknown JSON field",
        ))
    }

    fn ordinary_index_text<'a>(value: &'a StrictJson, subject: &str) -> VResult<&'a str> {
        match value {
            StrictJson::String(text) if sparse_text_valid(text) => Ok(text),
            _ => Err(ordinary_index_error(
                subject,
                "nonempty bounded control-free string required",
            )),
        }
    }

    fn ordinary_index_string_array(value: &StrictJson, subject: &str) -> VResult<Vec<String>> {
        let StrictJson::Array(values) = value else {
            return Err(ordinary_index_error(subject, "string array required"));
        };
        let mut parsed = Vec::new();
        for value in values {
            parsed.push(ordinary_index_text(value, subject)?.to_owned());
        }
        Ok(parsed)
    }

    fn ordinary_index_dependency_string_array(value: &StrictJson, subject: &str) -> VResult<()> {
        let StrictJson::Array(values) = value else {
            return Err(ordinary_index_error(subject, "string array required"));
        };
        if values
            .iter()
            .any(|value| !matches!(value, StrictJson::String(_)))
        {
            return Err(ordinary_index_error(subject, "string array required"));
        }
        Ok(())
    }

    fn ordinary_index_feature_map(
        value: &StrictJson,
        subject: &str,
    ) -> VResult<BTreeMap<String, Vec<String>>> {
        let object = strict_json_object(value, subject)?;
        let mut features = BTreeMap::new();
        for (feature, members) in object {
            if !sparse_text_valid(feature) {
                return Err(ordinary_index_error(subject, "invalid feature-map key"));
            }
            let values = ordinary_index_string_array(members, &format!("{subject}.{feature}"))?;
            features.insert(feature.clone(), values);
        }
        Ok(features)
    }

    fn ordinary_index_dependency(
        value: &StrictJson,
        subject: &str,
    ) -> VResult<SparseDependencySemantic> {
        let object = strict_json_object(value, subject)?;
        ordinary_index_exact_fields(object, SDF_REQ, SDF_OPT, subject)?;
        let name = object
            .get("name")
            .ok_or_else(|| ordinary_index_error(subject, "name"))?;
        validate_crates_io_package_name(ordinary_index_text(name, subject)?, subject)?;
        let requirement = object
            .get("req")
            .ok_or_else(|| ordinary_index_error(subject, "req"))?;
        let requirement = ordinary_index_text(requirement, subject)?;
        SemverVersionReq::parse(requirement)
            .map_err(|_| ordinary_index_error(subject, "invalid version requirement"))?;
        if let Some(features) = object.get("features") {
            ordinary_index_dependency_string_array(features, &format!("{subject}.features"))?;
        }
        let optional = match object.get("optional") {
            None => false,
            Some(StrictJson::Bool(value)) => *value,
            Some(_) => {
                return Err(ordinary_index_error(subject, "optional: boolean"));
            }
        };
        if object
            .get("default_features")
            .is_some_and(|value| !matches!(value, StrictJson::Bool(_)))
        {
            return Err(ordinary_index_error(subject, "default_features: boolean"));
        }
        let target = match object.get("target") {
            None | Some(StrictJson::Null) => None,
            Some(value) => {
                Some(ordinary_index_text(value, &format!("{subject}.target"))?.to_owned())
            }
        };
        let registry = match object.get("registry") {
            None | Some(StrictJson::Null) => None,
            Some(value) => {
                Some(ordinary_index_text(value, &format!("{subject}.registry"))?.to_owned())
            }
        };
        let kind = if let Some(value) = object.get("kind") {
            match value {
                StrictJson::Null => SparseDependencyKind::Normal,
                _ if ordinary_index_text(value, &format!("{subject}.kind"))? == "normal" => {
                    SparseDependencyKind::Normal
                }
                _ if ordinary_index_text(value, &format!("{subject}.kind"))? == "dev" => {
                    SparseDependencyKind::Dev
                }
                _ if ordinary_index_text(value, &format!("{subject}.kind"))? == "build" => {
                    SparseDependencyKind::Build
                }
                _ => {
                    return Err(ordinary_index_error(
                        subject,
                        "kind must be normal, dev, build, or null",
                    ));
                }
            }
        } else {
            SparseDependencyKind::Normal
        };
        if let Some(value) = object.get("package") {
            match value {
                StrictJson::Null => {}
                _ => validate_crates_io_package_name(
                    ordinary_index_text(value, &format!("{subject}.package"))?,
                    subject,
                )?,
            }
        }
        let public = match object.get("public") {
            None | Some(StrictJson::Null) => false,
            Some(StrictJson::Bool(value)) => *value,
            Some(_) => {
                return Err(ordinary_index_error(subject, "public: boolean or null"));
            }
        };
        for field in ["artifact", "bindep_target"] {
            if object
                .get(field)
                .is_some_and(|value| !matches!(value, StrictJson::Null))
            {
                return Err(ordinary_index_error(
                    subject,
                    format!("{field}: unsupported schema v3 field"),
                ));
            }
        }
        if let Some(value) = object.get("lib") {
            match value {
                StrictJson::Bool(false) => {}
                StrictJson::Bool(true) => {
                    return Err(ordinary_index_error(
                        subject,
                        "lib=true requires unsupported schema v3",
                    ));
                }
                _ => {
                    return Err(ordinary_index_error(
                        subject,
                        "lib must be boolean when present",
                    ));
                }
            }
        }
        Ok(SparseDependencySemantic {
            name: ordinary_index_text(name, subject)?.to_owned(),
            optional,
            kind,
            public,
            target,
            registry,
        })
    }

    fn ordinary_index_rust_version(value: &str, subject: &str) -> VResult<()> {
        let components = value.split('.').collect::<Vec<_>>();
        if !(1..=3).contains(&components.len())
            || components.iter().any(|component| {
                component.is_empty()
                    || (component.len() > 1 && component.starts_with('0'))
                    || !component.bytes().all(|byte| byte.is_ascii_digit())
                    || component.parse::<u64>().is_err()
            })
        {
            return Err(ordinary_index_error(
                subject,
                "rust_version must have one to three canonical numeric components",
            ));
        }
        Ok(())
    }

    fn ordinary_index_pubtime(value: &str, subject: &str) -> VResult<()> {
        match sparse_pubtime_valid(value) {
            Ok(()) => Ok(()),
            Err(SparsePubtimeFailure::Shape) => Err(ordinary_index_error(
                subject,
                "pubtime must use YYYY-MM-DDThh:mm:ssZ",
            )),
            Err(SparsePubtimeFailure::Calendar) => Err(ordinary_index_error(
                subject,
                "invalid pubtime calendar value",
            )),
        }
    }

    fn ordinary_supply_json_identity(
        json_bytes: &[u8],
        cache_version: Option<&str>,
        subject: &str,
    ) -> VResult<(OrdinarySupplyLockTriple, Option<bool>)> {
        let json = parse_strict_json(json_bytes, subject)?;
        let object = strict_json_object(&json, subject)?;
        ordinary_index_exact_fields(object, SIF_REQ, SIF_OPT, subject)?;
        let name = strict_json_string(object, "name", subject)?;
        let version = strict_json_string(object, "vers", subject)?;
        let checksum = match object.get("cksum") {
            Some(StrictJson::String(value)) => value.as_str(),
            _ => return Err(ordinary_index_error(subject, "cksum: string required")),
        };
        validate_crates_io_package_name(name, subject)?;
        if version.len() > ORDINARY_MAX_SPARSE_VERSION_BYTES
            || SemverVersion::parse(version).is_err()
        {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_VERSION", subject).at(version));
        }
        if cache_version.is_some_and(|outer| outer != version) {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_VERSION", subject)
                .at("selected outer cache version differs from vers"));
        }
        if cache_version.is_some() {
            validate_sha256(checksum, subject)?;
        }
        let dependency_values = match object.get("deps") {
            Some(StrictJson::Array(values)) => values,
            _ => return Err(ordinary_index_error(subject, "deps: array required")),
        };
        let mut dependencies = Vec::new();
        for (ordinal, dependency) in dependency_values.iter().enumerate() {
            dependencies.push(ordinary_index_dependency(
                dependency,
                &format!("{subject}.deps[{ordinal}]"),
            )?);
        }
        let features = match object.get("features") {
            None => BTreeMap::new(),
            Some(features) => ordinary_index_feature_map(features, &format!("{subject}.features"))?,
        };
        let effective_version = match object.get("v") {
            None | Some(StrictJson::Null) => 1,
            Some(StrictJson::Number(value)) if value.as_u64() == Some(1) => 1,
            Some(StrictJson::Number(value)) if value.as_u64() == Some(2) => 2,
            _ => {
                return Err(ordinary_index_error(
                    subject,
                    "only effective index schema versions one and two are admitted",
                ));
            }
        };
        let features2 = if let Some(features2) = object.get("features2") {
            match (effective_version, features2) {
                (_, StrictJson::Null) => None,
                (2, value) => Some(ordinary_index_feature_map(
                    value,
                    &format!("{subject}.features2"),
                )?),
                _ => {
                    return Err(ordinary_index_error(
                        subject,
                        "features2 requires index schema version two",
                    ));
                }
            }
        } else {
            None
        };
        validate_sparse_index_semantics(&dependencies, &features, features2.as_ref(), subject)
            .map_err(|error| ordinary_index_error(subject, error.detail()))?;
        let yanked = match object.get("yanked") {
            None | Some(StrictJson::Null) => None,
            Some(StrictJson::Bool(value)) => Some(*value),
            _ => return Err(ordinary_index_error(subject, "yanked: boolean or null")),
        };
        if let Some(links) = object.get("links") {
            if !matches!(links, StrictJson::Null | StrictJson::String(_)) {
                return Err(ordinary_index_error(subject, "links: string or null"));
            }
        }
        if let Some(rust_version) = object.get("rust_version") {
            match rust_version {
                StrictJson::Null => {}
                value => ordinary_index_rust_version(
                    ordinary_index_text(value, &format!("{subject}.rust_version"))?,
                    &format!("{subject}.rust_version"),
                )?,
            }
        }
        if let Some(pubtime) = object.get("pubtime") {
            match pubtime {
                StrictJson::Null => {}
                value => ordinary_index_pubtime(
                    ordinary_index_text(value, &format!("{subject}.pubtime"))?,
                    &format!("{subject}.pubtime"),
                )?,
            }
        }
        Ok((
            OrdinarySupplyLockTriple {
                name: name.to_owned(),
                version: version.to_owned(),
                checksum: checksum.to_owned(),
            },
            yanked,
        ))
    }

    #[cfg(test)]
    mod ordinary_supply_index_tests {
        use super::*;

        const CHECKSUM: &str = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";

        #[test]
        fn ordinary_sparse_index_json_matches_the_registered_v1_v2_surface() {
            let corpus = sparse_index_fixture_corpus();
            assert_eq!(corpus.checksum, CHECKSUM);
            let (identity, yanked) =
                ordinary_supply_json_identity(corpus.valid_v1.as_bytes(), Some("1.2.3"), "valid v1")
                    .expect("registered v1 fields and duplicate array members must pass");
            assert_eq!(identity.name, "sample");
            assert_eq!(identity.version, "1.2.3");
            assert_eq!(identity.checksum, CHECKSUM);
            assert_eq!(yanked, Some(false));
            let leap_second = corpus
                .valid_v1
                .replace("0000-02-29T00:00:00Z", "2026-07-07T15:52:60Z");
            ordinary_supply_json_identity(
                leap_second.as_bytes(),
                Some("1.2.3"),
                "Cargo-compatible leap second",
            )
            .expect("pinned Cargo maps second 60 to 59");

            assert_eq!(
                ordinary_supply_json_identity(corpus.valid_v2.as_bytes(), Some("2.0.0"), "valid v2")
                    .expect("registered v2 fields must pass")
                    .1,
                None,
            );

            assert_eq!(corpus.invalid.len(), 21);
            for (case_id, invalid) in &corpus.invalid {
                let error = ordinary_supply_json_identity(
                    invalid.as_bytes(),
                    Some("1.2.3"),
                    "invalid index",
                )
                .expect_err("invalid registered index JSON must fail");
                assert!(!error.code.is_empty(), "{case_id}: {invalid}");
            }

            assert_eq!(
            ordinary_supply_json_identity(
                corpus.duplicate_key.as_bytes(),
                Some("1.2.3"),
                "duplicate index key",
            )
            .expect_err("duplicate object keys must fail")
            .code,
            "E_JSON_SCHEMA",
        );
            assert_eq!(
                ordinary_supply_json_identity(corpus.valid_v1.as_bytes(), Some("1.2.4"), "cache mismatch")
                    .expect_err("outer cache version must equal vers")
                    .code,
                "E_ORDINARY_SUPPLY_VERSION",
            );

            ordinary_supply_json_identity(
                corpus.renamed_dependency.as_bytes(),
                Some("1.2.3"),
                "renamed dependency alias",
            )
            .expect("feature references use the dependency alias");
            let wrong_renamed_feature = corpus
                .renamed_dependency
                .replace("dep:alias", "dep:actual");
            assert_eq!(
                ordinary_supply_json_identity(
                    wrong_renamed_feature.as_bytes(),
                    Some("1.2.3"),
                    "renamed dependency package",
                )
                .expect_err("the actual package name cannot replace its alias")
                .code,
                "E_ORDINARY_SUPPLY_INDEX_JSON",
            );
        }

        fn ordinary_summaries_cache_with_validator(
            validator: &[u8],
            rows: &[(&str, &[u8])],
        ) -> Vec<u8> {
            let mut output = vec![3];
            output.extend_from_slice(&2u32.to_le_bytes());
            output.extend_from_slice(validator);
            output.push(0);
            for (version, json) in rows {
                output.extend_from_slice(version.as_bytes());
                output.push(0);
                output.extend_from_slice(json);
                output.push(0);
            }
            output
        }

        fn ordinary_summaries_cache(rows: &[(&str, &[u8])]) -> Vec<u8> {
            ordinary_summaries_cache_with_validator(b"synthetic-validator", rows)
        }

        #[test]
        fn ordinary_sparse_cache_binds_only_selected_identity_and_exact_path() {
            let historical =
            br#"{"name":"historical_other","vers":"1.0.1","deps":[],"cksum":"","yanked":true,"links":""}"#;
            let selected = format!(
                r#"{{"name":"sample","vers":"1.2.3","deps":[],"cksum":"{CHECKSUM}","yanked":false}}"#
            );
            let cache =
                ordinary_summaries_cache(&[("1.0.0", historical), ("1.2.3", selected.as_bytes())]);
            let exact_path = format!("{ORDINARY_SPARSE_CACHE_PATH_PREFIX}sa/mp/sample");
            let entry = OrdinarySupplyEntryBinding {
                kind: 0x03,
                path: exact_path,
                payload_offset: 0,
                byte_length: u64::try_from(cache.len()).expect("cache length fits u64"),
                sha256: sha256(&cache),
            };
            let locked = OrdinarySupplyLockTriple {
                name: "sample".to_owned(),
                version: "1.2.3".to_owned(),
                checksum: CHECKSUM.to_owned(),
            };
            let lock_by_identity = [(("sample".to_owned(), "1.2.3".to_owned()), locked)]
                .into_iter()
                .collect::<BTreeMap<_, _>>();
            let selected_rows = parse_ordinary_summaries_cache(
                &cache,
                &entry,
                &lock_by_identity,
                "ordinary selected cache",
            )
            .expect("unselected outer-version/checksum/yanked drift remains typed data");
            assert_eq!(selected_rows.len(), 1);
            assert_eq!(selected_rows[0].ordinal, 1);

            let oversized_version = format!("1.0.0+{}", "a".repeat(4_091));
            assert_eq!(oversized_version.len(), 4_097);
            let oversized_json = format!(
                r#"{{"name":"sample","vers":"{oversized_version}","deps":[],"cksum":"{CHECKSUM}","yanked":false}}"#
            );
            let oversized_cache = ordinary_summaries_cache(&[(
                oversized_version.as_str(),
                oversized_json.as_bytes(),
            )]);
            let oversized_entry = OrdinarySupplyEntryBinding {
                byte_length: u64::try_from(oversized_cache.len()).expect("cache length fits u64"),
                sha256: sha256(&oversized_cache),
                ..entry.clone()
            };
            assert_eq!(
                parse_ordinary_summaries_cache(
                    &oversized_cache,
                    &oversized_entry,
                    &lock_by_identity,
                    "ordinary oversized valid SemVer cache",
                )
                .expect_err("SemVer validity cannot bypass the ordinary 4096-byte bound",)
                .code,
                "E_ORDINARY_SUPPLY_VERSION",
            );

            let invalid_historical =
            br#"{"name":"historical_other","vers":"1.0.1","deps":[{"name":"dep","req":"*","optional":true,"kind":"dev"}],"cksum":"","yanked":true}"#;
            let invalid_historical_cache = ordinary_summaries_cache(&[
                ("1.0.0", invalid_historical),
                ("1.2.3", selected.as_bytes()),
            ]);
            let invalid_historical_entry = OrdinarySupplyEntryBinding {
                byte_length: u64::try_from(invalid_historical_cache.len())
                    .expect("cache length fits u64"),
                sha256: sha256(&invalid_historical_cache),
                ..entry.clone()
            };
            assert_eq!(
                parse_ordinary_summaries_cache(
                    &invalid_historical_cache,
                    &invalid_historical_entry,
                    &lock_by_identity,
                    "ordinary invalid historical cache row",
                )
                .expect_err("Cargo-invalid historical summaries must fail before row selection",)
                .code,
                "E_ORDINARY_SUPPLY_INDEX_JSON",
            );
            let empty_validator_cache = ordinary_summaries_cache_with_validator(
                b"",
                &[("1.0.0", historical), ("1.2.3", selected.as_bytes())],
            );
            let empty_validator_entry = OrdinarySupplyEntryBinding {
                byte_length: u64::try_from(empty_validator_cache.len())
                    .expect("cache length fits u64"),
                sha256: sha256(&empty_validator_cache),
                ..entry.clone()
            };
            parse_ordinary_summaries_cache(
                &empty_validator_cache,
                &empty_validator_entry,
                &lock_by_identity,
                "ordinary empty validator",
            )
            .expect("pinned Cargo admits an empty UTF-8 cache validator");

            let wrong_inner = br#"{"name":"historical_other","vers":"9.9.9","deps":[],"cksum":""}"#;
            let demotion_cache =
                ordinary_summaries_cache(&[("1.2.3", wrong_inner), ("1.2.3", selected.as_bytes())]);
            let demotion_entry = OrdinarySupplyEntryBinding {
                byte_length: u64::try_from(demotion_cache.len()).expect("cache length fits u64"),
                sha256: sha256(&demotion_cache),
                ..entry.clone()
            };
            assert_eq!(
                parse_ordinary_summaries_cache(
                    &demotion_cache,
                    &demotion_entry,
                    &lock_by_identity,
                    "ordinary selected-row demotion",
                )
                .expect_err("a selected outer version cannot be demoted by wrong inner identity",)
                .code,
                "E_ORDINARY_SUPPLY_VERSION",
            );

            let mixed_selected = format!(
                r#"{{"name":"Sample_Crate","vers":"1.2.3","deps":[],"cksum":"{CHECKSUM}","yanked":false}}"#
            );
            let mixed_cache = ordinary_summaries_cache(&[("1.2.3", mixed_selected.as_bytes())]);
            let mixed_entry = OrdinarySupplyEntryBinding {
                kind: 0x03,
                path: format!("{ORDINARY_SPARSE_CACHE_PATH_PREFIX}sa/mp/sample_crate"),
                payload_offset: 0,
                byte_length: u64::try_from(mixed_cache.len()).expect("cache length fits u64"),
                sha256: sha256(&mixed_cache),
            };
            let mixed_lock = [(
                ("Sample_Crate".to_owned(), "1.2.3".to_owned()),
                OrdinarySupplyLockTriple {
                    name: "Sample_Crate".to_owned(),
                    version: "1.2.3".to_owned(),
                    checksum: CHECKSUM.to_owned(),
                },
            )]
            .into_iter()
            .collect::<BTreeMap<_, _>>();
            parse_ordinary_summaries_cache(
                &mixed_cache,
                &mixed_entry,
                &mixed_lock,
                "ordinary mixed-case cache",
            )
            .expect("lock identity preserves case while crates.io sparse paths lowercase");

            let mut wrong_path = entry.clone();
            wrong_path.path = format!("{ORDINARY_SPARSE_CACHE_PATH_PREFIX}wrong/sample");
            assert_eq!(
                parse_ordinary_summaries_cache(
                    &cache,
                    &wrong_path,
                    &lock_by_identity,
                    "ordinary wrong sparse path",
                )
                .expect_err("the sparse cache path must be reconstructed from its package name")
                .code,
                "E_ORDINARY_SUPPLY_SPARSE_PATH",
            );

            let mut extra_terminal_nul = cache.clone();
            extra_terminal_nul.push(0);
            let extra_entry = OrdinarySupplyEntryBinding {
                byte_length: u64::try_from(extra_terminal_nul.len())
                    .expect("cache length fits u64"),
                sha256: sha256(&extra_terminal_nul),
                ..entry
            };
            assert_eq!(
                parse_ordinary_summaries_cache(
                    &extra_terminal_nul,
                    &extra_entry,
                    &lock_by_identity,
                    "ordinary extra terminal NUL",
                )
                .expect_err("an extra terminal NUL must create an empty version and fail")
                .code,
                "E_ORDINARY_SUPPLY_SPARSE_CACHE",
            );
        }
    }

    fn parse_ordinary_summaries_cache_summary<'a>(
        payload: &'a [u8],
        entry: &'a OrdinarySupplyEntryBinding,
        lock_by_identity: &BTreeMap<(String, String), OrdinarySupplyLockTriple>,
        subject: &str,
    ) -> VResult<OrdinaryParsedSummariesCache<'a>> {
        if payload.len() < 6 || payload[0] != 3 {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                .at(format!("{}: SummariesCache version", entry.path)));
        }
        if u32::from_le_bytes([payload[1], payload[2], payload[3], payload[4]]) != 2 {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                .at(format!("{}: INDEX_V_MAX", entry.path)));
        }
        let validator_start = 5usize;
        let validator_end = payload[validator_start..]
            .iter()
            .position(|byte| *byte == 0)
            .and_then(|relative| validator_start.checked_add(relative))
            .ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                    .at(format!("{}: validator terminator", entry.path))
            })?;
        let validator =
            std::str::from_utf8(&payload[validator_start..validator_end]).map_err(|_| {
                Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                    .at(format!("{}: validator UTF-8", entry.path))
            })?;
        if validator.len() > usize::try_from(ORDINARY_MAX_SOURCE_FILE_BYTES).unwrap_or(usize::MAX) {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                .at(format!("{}: validator bound", entry.path)));
        }
        let mut offset = validator_end.checked_add(1).ok_or_else(|| {
            Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                .at(format!("{}: validator offset", entry.path))
        })?;
        let mut enclosing_package_names = BTreeSet::new();
        for package in lock_by_identity.values() {
            let index_path = crates_io_index_path(&package.name, subject)?;
            let dependency_path = index_path.strip_prefix("index/").ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_INDEX_BINDING", subject)
                    .at(format!("{}: invalid compiled index path", entry.path))
            })?;
            let expected_path = format!("{ORDINARY_SPARSE_CACHE_PATH_PREFIX}{dependency_path}");
            if entry.path == expected_path {
                enclosing_package_names.insert(package.name.clone());
            }
        }
        if enclosing_package_names.len() != 1 {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_PATH", subject)
                .at(format!("{}: no unique enclosing lock package", entry.path)));
        }
        let enclosing_package_name =
            enclosing_package_names.into_iter().next().ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_INDEX_BINDING", subject)
                    .at("missing enclosing package name")
            })?;
        let mut pair_count = 0usize;
        let mut selected = Vec::new();
        while offset < payload.len() {
            let version_end = payload[offset..]
                .iter()
                .position(|byte| *byte == 0)
                .and_then(|relative| offset.checked_add(relative))
                .ok_or_else(|| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                        .at(format!("{}: version terminator", entry.path))
                })?;
            if version_end == offset {
                return Err(
                    Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject).at(format!(
                        "{}: empty version or extra terminal NUL",
                        entry.path
                    )),
                );
            }
            let version = std::str::from_utf8(&payload[offset..version_end]).map_err(|_| {
                Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                    .at(format!("{}: version UTF-8", entry.path))
            })?;
            if version.len() > ORDINARY_MAX_SPARSE_VERSION_BYTES
                || SemverVersion::parse(version).is_err()
            {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_VERSION", subject)
                    .at(format!("{}: {version}", entry.path)));
            }
            let json_start = version_end.checked_add(1).ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                    .at(format!("{}: JSON offset", entry.path))
            })?;
            if json_start >= payload.len() {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                    .at(format!("{}: missing JSON partner", entry.path)));
            }
            let json_end = payload[json_start..]
                .iter()
                .position(|byte| *byte == 0)
                .and_then(|relative| json_start.checked_add(relative))
                .ok_or_else(|| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                        .at(format!("{}: JSON terminator", entry.path))
                })?;
            if json_end == json_start {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject)
                    .at(format!("{}: empty JSON", entry.path)));
            }
            let json = &payload[json_start..json_end];
            let row_subject = format!("{subject}/{}#pair[{pair_count}]", entry.path);
            let (_, yanked) = ordinary_supply_json_identity(json, None, &row_subject)?;
            if let Some(locked) =
                lock_by_identity.get(&(enclosing_package_name.clone(), version.to_owned()))
            {
                let (selected_package, selected_yanked) =
                    ordinary_supply_json_identity(json, Some(version), &row_subject)?;
                if locked != &selected_package
                    || selected_yanked != Some(false)
                    || yanked != selected_yanked
                {
                    return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", &row_subject)
                        .at("selected sparse row checksum/yanked mismatch"));
                }
                let ordinal = u32::try_from(pair_count).map_err(|_| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_COUNT", &row_subject)
                        .at("selected ordinal")
                })?;
                selected.try_reserve(1).map_err(|_| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_ALLOCATION", &row_subject)
                        .at("selected sparse rows")
                })?;
                selected.push(OrdinarySupplySelectedSparseRow {
                    entry,
                    ordinal,
                    json,
                    package: selected_package,
                });
            }
            pair_count = pair_count.checked_add(1).ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_COUNT", &row_subject)
                    .at("SummariesCache pairs")
            })?;
            offset = json_end.checked_add(1).ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", &row_subject).at("pair offset")
            })?;
        }
        if pair_count == 0 || payload.last() != Some(&0) {
            return Err(
                Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_CACHE", subject).at(format!(
                    "{}: nonempty complete pairs and final NUL",
                    entry.path
                )),
            );
        }
        if selected.is_empty() {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                .at(format!("{}: unused extra 0x03 entry", entry.path)));
        }
        Ok(OrdinaryParsedSummariesCache {
            validator,
            selected,
        })
    }

    fn parse_ordinary_summaries_cache<'a>(
        payload: &'a [u8],
        entry: &'a OrdinarySupplyEntryBinding,
        lock_by_identity: &BTreeMap<(String, String), OrdinarySupplyLockTriple>,
        subject: &str,
    ) -> VResult<Vec<OrdinarySupplySelectedSparseRow<'a>>> {
        Ok(
            parse_ordinary_summaries_cache_summary(payload, entry, lock_by_identity, subject)?
                .selected,
        )
    }

    fn ordinary_supply_append_preimage_bytes(
        output: &mut Vec<u8>,
        bytes: &[u8],
        subject: &str,
    ) -> VResult<()> {
        let next_length = output
            .len()
            .checked_add(bytes.len())
            .ok_or_else(|| Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject))?;
        if u64::try_from(next_length).unwrap_or(u64::MAX) > ORDINARY_MAX_SUPPLY_BUNDLE_BYTES {
            return Err(
                Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject).at("closure preimage")
            );
        }
        output.try_reserve(bytes.len()).map_err(|_| {
            Diagnostic::error("E_ORDINARY_SUPPLY_ALLOCATION", subject).at("closure preimage")
        })?;
        output.extend_from_slice(bytes);
        Ok(())
    }

    fn ordinary_supply_append_preimage_string(
        output: &mut Vec<u8>,
        value: &str,
        subject: &str,
    ) -> VResult<()> {
        let length = u32::try_from(value.len())
            .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject))?;
        ordinary_supply_append_preimage_bytes(output, &length.to_be_bytes(), subject)?;
        ordinary_supply_append_preimage_bytes(output, value.as_bytes(), subject)
    }

    fn validate_ordinary_supply_closure(
        bytes: &[u8],
        entries: &[OrdinarySupplyEntryBinding],
        lock_triples: &[OrdinarySupplyLockTriple],
        declared_closure_sha256: [u8; 32],
        subject: &str,
    ) -> VResult<Vec<OrdinarySupplyClosureRow>> {
        if lock_triples.is_empty() {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                .at("empty crates.io lock set"));
        }
        let lock_set = lock_triples.iter().cloned().collect::<BTreeSet<_>>();
        if lock_set.len() != lock_triples.len() {
            return Err(
                Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject).at("duplicate lock triple")
            );
        }
        let mut lock_by_identity = BTreeMap::<(String, String), OrdinarySupplyLockTriple>::new();
        for package in lock_triples {
            if lock_by_identity
                .insert(
                    (package.name.clone(), package.version.clone()),
                    package.clone(),
                )
                .is_some()
            {
                return Err(
                    Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject).at(format!(
                        "{} {}: duplicate lock identity",
                        package.name, package.version
                    )),
                );
            }
        }

        let mut archives = BTreeMap::<String, &OrdinarySupplyEntryBinding>::new();
        let mut sparse_selected =
            BTreeMap::<OrdinarySupplyLockTriple, OrdinarySupplySelectedSparseRow<'_>>::new();
        for entry in entries {
            match entry.kind {
                0x01 => {
                    if archives.insert(entry.path.clone(), entry).is_some() {
                        return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                            .at(format!("{}: duplicate 0x01 peer", entry.path)));
                    }
                }
                0x03 => {
                    let payload = ordinary_supply_entry_payload(bytes, entry, subject)?;
                    for selected in
                        parse_ordinary_summaries_cache(payload, entry, &lock_by_identity, subject)?
                    {
                        let package = selected.package.clone();
                        if sparse_selected.insert(package.clone(), selected).is_some() {
                            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                                .at(format!(
                                    "{} {}: duplicate selected 0x03 row",
                                    package.name, package.version
                                )));
                        }
                    }
                }
                0x02 => {}
                _ => {
                    return Err(Diagnostic::error("E_ORDINARY_SUPPLY_KIND", subject)
                        .at(format!("{:#04x}", entry.kind)));
                }
            }
        }
        if sparse_selected.len() != lock_set.len()
            || sparse_selected
                .keys()
                .any(|package| !lock_set.contains(package))
            || lock_set
                .iter()
                .any(|package| !sparse_selected.contains_key(package))
        {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                .at("lock and selected 0x03 row sets differ"));
        }

        let mut indexes = BTreeMap::<String, &OrdinarySupplyEntryBinding>::new();
        let mut derived_rows = BTreeMap::<String, Vec<(OrdinarySupplyLockTriple, &[u8])>>::new();
        let mut derived_triples = BTreeSet::<OrdinarySupplyLockTriple>::new();
        for entry in entries.iter().filter(|entry| entry.kind == 0x02) {
            let payload = ordinary_supply_entry_payload(bytes, entry, subject)?;
            let body = payload.strip_suffix(b"\n").ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_INDEX_JSON", subject)
                    .at(format!("{}: missing terminal LF", entry.path))
            })?;
            if body.is_empty() {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_INDEX_JSON", subject)
                    .at(format!("{}: empty derived index", entry.path)));
            }
            let mut package_name = None::<String>;
            let mut versions_without_build = BTreeSet::<String>::new();
            let mut rows = Vec::new();
            for (ordinal, json_bytes) in body.split(|byte| *byte == b'\n').enumerate() {
                if json_bytes.is_empty() {
                    return Err(Diagnostic::error("E_ORDINARY_SUPPLY_INDEX_JSON", subject)
                        .at(format!("{}: empty row {ordinal}", entry.path)));
                }
                let row_subject = format!("{subject}/{}#row[{ordinal}]", entry.path);
                let (package, yanked) =
                    ordinary_supply_json_identity(json_bytes, None, &row_subject)?;
                if yanked != Some(false)
                    || crates_io_index_path(&package.name, &row_subject)? != entry.path
                    || package_name
                        .as_ref()
                        .is_some_and(|name| name != &package.name)
                    || !versions_without_build
                        .insert(semver_without_build_metadata(&package.version).to_owned())
                {
                    return Err(
                        Diagnostic::error("E_ORDINARY_SUPPLY_INDEX_BINDING", &row_subject)
                            .at("path/name/version/yanked"),
                    );
                }
                if !lock_set.contains(&package) || !derived_triples.insert(package.clone()) {
                    return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", &row_subject)
                        .at("unused, duplicate, or non-lock 0x02 row"));
                }
                let selected = sparse_selected.get(&package).ok_or_else(|| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", &row_subject)
                        .at("missing selected 0x03 peer")
                })?;
                if selected.json != json_bytes {
                    return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", &row_subject)
                        .at("0x02 row differs from exact selected 0x03 JSON bytes"));
                }
                package_name.get_or_insert_with(|| package.name.clone());
                rows.try_reserve(1).map_err(|_| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_ALLOCATION", &row_subject)
                        .at("derived index rows")
                })?;
                rows.push((package, json_bytes));
            }
            let package_name = package_name.ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_INDEX_JSON", subject).at(&entry.path)
            })?;
            if indexes.insert(package_name.clone(), entry).is_some()
                || derived_rows.insert(package_name.clone(), rows).is_some()
            {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                    .at(format!("{package_name}: duplicate 0x02 peer")));
            }
        }

        let expected_index_names = lock_set
            .iter()
            .map(|package| package.name.clone())
            .collect::<BTreeSet<_>>();
        if indexes.len() != expected_index_names.len()
            || indexes
                .keys()
                .any(|name| !expected_index_names.contains(name))
            || expected_index_names
                .iter()
                .any(|name| !indexes.contains_key(name))
            || derived_triples != lock_set
        {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                .at("lock and 0x02 derived-index sets differ"));
        }
        for name in &expected_index_names {
            let mut expected = sparse_selected
                .values()
                .filter(|selected| &selected.package.name == name)
                .collect::<Vec<_>>();
            expected.sort_by(|left, right| {
                left.entry
                    .path
                    .as_bytes()
                    .cmp(right.entry.path.as_bytes())
                    .then(left.ordinal.cmp(&right.ordinal))
            });
            let actual = derived_rows.get(name).ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                    .at(format!("{name}: missing derived rows"))
            })?;
            if actual.len() != expected.len()
                || actual
                    .iter()
                    .zip(&expected)
                    .any(|((package, json), selected)| {
                        package != &selected.package || *json != selected.json
                    })
            {
                return Err(
                    Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject).at(format!(
                        "{name}: derived rows not in sparse path/ordinal order"
                    )),
                );
            }
        }

        if archives.len() != lock_set.len() {
            return Err(
                Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject).at("archive peer count")
            );
        }
        let mut preimage = Vec::new();
        ordinary_supply_append_preimage_bytes(&mut preimage, b"FND01SUPPLYCLOSUREv1\0", subject)?;
        let triple_count = u32::try_from(lock_triples.len())
            .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_COUNT", subject))?;
        ordinary_supply_append_preimage_bytes(&mut preimage, &triple_count.to_be_bytes(), subject)?;
        let mut closure_rows = Vec::new();
        closure_rows
            .try_reserve_exact(lock_triples.len())
            .map_err(|_| {
                Diagnostic::error("E_ORDINARY_SUPPLY_ALLOCATION", subject).at("closure rows")
            })?;
        for package in lock_triples {
            let sparse = sparse_selected.get(package).ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                    .at(format!("{} {}: sparse peer", package.name, package.version))
            })?;
            let index = indexes.get(&package.name).copied().ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                    .at(format!("{}: index peer", package.name))
            })?;
            let archive_path = format!("{}-{}.crate", package.name, package.version);
            let archive = archives.get(&archive_path).copied().ok_or_else(|| {
                Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                    .at(format!("{archive_path}: archive peer"))
            })?;
            if lower_hex(&archive.sha256) != package.checksum {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                    .at(format!("{archive_path}: archive/lock/index checksum")));
            }
            ordinary_supply_append_preimage_string(&mut preimage, &package.name, subject)?;
            ordinary_supply_append_preimage_string(&mut preimage, &package.version, subject)?;
            ordinary_supply_append_preimage_string(&mut preimage, &package.checksum, subject)?;
            ordinary_supply_append_preimage_string(&mut preimage, &sparse.entry.path, subject)?;
            ordinary_supply_append_preimage_bytes(
                &mut preimage,
                &sparse.entry.byte_length.to_be_bytes(),
                subject,
            )?;
            ordinary_supply_append_preimage_bytes(&mut preimage, &sparse.entry.sha256, subject)?;
            ordinary_supply_append_preimage_bytes(
                &mut preimage,
                &sparse.ordinal.to_be_bytes(),
                subject,
            )?;
            let selected_json_byte_length = u64::try_from(sparse.json.len())
                .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject))?;
            let selected_json_sha256 = sha256(sparse.json);
            ordinary_supply_append_preimage_bytes(
                &mut preimage,
                &selected_json_byte_length.to_be_bytes(),
                subject,
            )?;
            ordinary_supply_append_preimage_bytes(&mut preimage, &selected_json_sha256, subject)?;
            ordinary_supply_append_preimage_string(&mut preimage, &index.path, subject)?;
            ordinary_supply_append_preimage_bytes(
                &mut preimage,
                &index.byte_length.to_be_bytes(),
                subject,
            )?;
            ordinary_supply_append_preimage_bytes(&mut preimage, &index.sha256, subject)?;
            ordinary_supply_append_preimage_string(&mut preimage, &archive.path, subject)?;
            ordinary_supply_append_preimage_bytes(
                &mut preimage,
                &archive.byte_length.to_be_bytes(),
                subject,
            )?;
            ordinary_supply_append_preimage_bytes(&mut preimage, &archive.sha256, subject)?;
            ordinary_supply_append_preimage_bytes(&mut preimage, &[0x00], subject)?;
            closure_rows.push(OrdinarySupplyClosureRow {
                package: package.clone(),
                sparse_path: sparse.entry.path.clone(),
                sparse_byte_length: sparse.entry.byte_length,
                sparse_sha256: sparse.entry.sha256,
                selected_ordinal: sparse.ordinal,
                selected_json_byte_length,
                selected_json_sha256,
                derived_index_path: index.path.clone(),
                derived_index_byte_length: index.byte_length,
                derived_index_sha256: index.sha256,
                archive_path: archive.path.clone(),
                archive_byte_length: archive.byte_length,
                archive_sha256: archive.sha256,
            });
        }
        if sha256(&preimage) != declared_closure_sha256 {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_CLOSURE", subject)
                .at("closure_bijection_sha256 recomputation"));
        }
        Ok(closure_rows)
    }

    fn parse_ordinary_supply_framing(
        bytes: &[u8],
        subject: &str,
    ) -> VResult<OrdinarySupplyFraming> {
        let container_length = u64::try_from(bytes.len()).unwrap_or(u64::MAX);
        if bytes.is_empty() || container_length > ORDINARY_MAX_SUPPLY_BUNDLE_BYTES {
            return Err(
                Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject).at("complete container")
            );
        }
        let mut cursor = BinaryCursor::new(bytes, subject);
        if cursor.read_exact(b"FND01SUPPLYv4\0".len())? != b"FND01SUPPLYv4\0" {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_HEADER", subject));
        }
        let bootstrap_lock_byte_length = cursor.read_u64()?;
        let bootstrap_lock_length = checked_payload_length(
            bootstrap_lock_byte_length,
            ORDINARY_MAX_SOURCE_FILE_BYTES,
            subject,
        )?;
        let bootstrap_lock_sha256: [u8; 32] = cursor
            .read_exact(32)?
            .try_into()
            .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_LOCK", subject))?;
        let bootstrap_lock_payload_offset = cursor.position();
        let bootstrap_lock = cursor.read_exact(bootstrap_lock_length)?;
        if sha256(bootstrap_lock) != bootstrap_lock_sha256 {
            return Err(
                Diagnostic::error("E_ORDINARY_SUPPLY_LOCK", subject).at("bootstrap lock digest")
            );
        }
        let bootstrap_lock_toml = parse_bootstrap_cargo_lock_strict(
            bootstrap_lock,
            &ORDINARY_CARGO_LOCK_BOUNDS,
            "ordinary supply bootstrap Cargo.lock",
        )?;
        let registry_packages = registry_packages_from_lock(
            &bootstrap_lock_toml,
            &ORDINARY_CARGO_LOCK_BOUNDS,
            &singleton_lock_local_package("fastmcp-fnd01-bootstrap-control", "0.0.0"),
            "ordinary supply bootstrap Cargo.lock",
        )?;
        let mut expected_archives = BTreeMap::<String, [u8; 32]>::new();
        let mut folded_archive_paths = BTreeSet::<String>::new();
        let mut lock_triples = BTreeSet::<OrdinarySupplyLockTriple>::new();
        for (ordinal, package) in registry_packages.into_iter().enumerate() {
            let logical = format!("ordinary supply bootstrap Cargo.lock/package[{ordinal}]");
            let archive_path_length = package
                .name
                .len()
                .checked_add(1)
                .and_then(|length| length.checked_add(package.version.len()))
                .and_then(|length| length.checked_add(".crate".len()))
                .ok_or_else(|| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_PATH", &logical)
                        .at("archive basename length overflow")
                })?;
            if archive_path_length > 240 {
                return Err(
                    Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_PATH", &logical)
                        .at("archive basename exceeds path bound"),
                );
            }
            let archive_path = format!("{}-{}.crate", package.name, package.version);
            validate_ascii_posix_path(&archive_path, &logical)?;
            if !folded_archive_paths.insert(archive_path.to_ascii_lowercase()) {
                return Err(
                    Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_PATH", &logical)
                        .at("ASCII-case-folded archive basename collision"),
                );
            }
            let checksum_bytes: [u8; 32] = decode_lower_hex(&package.checksum, &logical)?
                .try_into()
                .map_err(|_| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_LOCK", &logical).at("checksum width")
                })?;
            let ordinary_package = OrdinarySupplyLockTriple {
                name: package.name,
                version: package.version,
                checksum: package.checksum,
            };
            if expected_archives
                .insert(archive_path.clone(), checksum_bytes)
                .is_some()
                || !lock_triples.insert(ordinary_package)
            {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_LOCK", &logical)
                    .at(format!("duplicate package/archive identity {archive_path}")));
            }
        }

        let acquisition_root_entry_count = cursor.read_u64()?;
        let acquisition_root_total_regular_file_bytes = cursor.read_u64()?;
        let acquisition_root_set_sha256: [u8; 32] =
            cursor.read_exact(32)?.try_into().map_err(|_| {
                Diagnostic::error("E_ORDINARY_SUPPLY_ACQUISITION", subject).at("root digest width")
            })?;
        if acquisition_root_entry_count == 0
            || acquisition_root_entry_count
                > u64::try_from(ORDINARY_MAX_SUPPLY_ENTRY_COUNT).unwrap_or(u64::MAX)
            || acquisition_root_total_regular_file_bytes == 0
            || acquisition_root_total_regular_file_bytes > ORDINARY_MAX_ACQUISITION_TREE_BYTES
            || acquisition_root_set_sha256.iter().all(|byte| *byte == 0)
        {
            return Err(
                Diagnostic::error("E_ORDINARY_SUPPLY_ACQUISITION", subject).at("root observation")
            );
        }
        let sparse_config_path = cursor.read_string(240)?;
        if sparse_config_path != ACQUISITION_SPARSE_CONFIG_PATH {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_ACQUISITION", subject)
                .at("sparse config path"));
        }
        let sparse_config_byte_length = cursor.read_u64()?;
        let sparse_config_length = checked_payload_length(
            sparse_config_byte_length,
            ORDINARY_MAX_SOURCE_FILE_BYTES,
            subject,
        )?;
        let sparse_config_sha256: [u8; 32] = cursor.read_exact(32)?.try_into().map_err(|_| {
            Diagnostic::error("E_ORDINARY_SUPPLY_ACQUISITION", subject)
                .at("sparse config digest width")
        })?;
        let sparse_config_payload_offset = cursor.position();
        let sparse_config_payload = cursor.read_exact(sparse_config_length)?;
        if sha256(sparse_config_payload) != sparse_config_sha256 {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_ACQUISITION", subject)
                .at("sparse config digest"));
        }

        let entry_count = usize::try_from(cursor.read_u32()?)
            .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_COUNT", subject))?;
        if entry_count == 0 || entry_count > ORDINARY_MAX_SUPPLY_ENTRY_COUNT {
            return Err(
                Diagnostic::error("E_ORDINARY_SUPPLY_COUNT", subject).at(entry_count.to_string())
            );
        }
        let declared_payload_bytes = cursor.read_u64()?;
        if declared_payload_bytes == 0 || declared_payload_bytes > ORDINARY_MAX_SUPPLY_BUNDLE_BYTES
        {
            return Err(
                Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject).at("declared payload bytes")
            );
        }
        let declared_inner_sha256: [u8; 32] = cursor
            .read_exact(32)?
            .try_into()
            .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_DIGEST", subject))?;
        let closure_bijection_sha256: [u8; 32] = cursor
            .read_exact(32)?
            .try_into()
            .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_DIGEST", subject))?;
        let mut inner = Sha256::new();
        inner.update(b"FND01SUPPLY-ENTRIESv1\0");
        inner.update(
            u32::try_from(entry_count)
                .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_COUNT", subject))?
                .to_be_bytes(),
        );
        let mut paths = Vec::new();
        paths.try_reserve_exact(entry_count).map_err(|_| {
            Diagnostic::error("E_ORDINARY_SUPPLY_ALLOCATION", subject).at("entry paths")
        })?;
        let mut archives = Vec::new();
        let mut entries = Vec::new();
        entries.try_reserve_exact(entry_count).map_err(|_| {
            Diagnostic::error("E_ORDINARY_SUPPLY_ALLOCATION", subject).at("entry bindings")
        })?;
        let mut seen_archives = BTreeSet::new();
        let mut prior_key = None::<(u8, Vec<u8>)>;
        let mut total_payload_bytes = 0u64;
        for ordinal in 0..entry_count {
            let logical = format!("{subject}/entry[{ordinal}]");
            let kind = cursor.read_u8()?;
            if !matches!(kind, 0x01..=0x03) {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_KIND", &logical)
                    .at(format!("{kind:#04x}")));
            }
            let path = cursor.read_string(240)?;
            validate_ascii_posix_path(&path, &logical)?;
            match kind {
                0x01 => {
                    let basename = path.strip_suffix(".crate").ok_or_else(|| {
                        Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_PATH", &logical).at(&path)
                    })?;
                    if path.contains('/') || basename.is_empty() {
                        return Err(
                            Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_PATH", &logical).at(&path),
                        );
                    }
                }
                0x02 => {
                    let package_name = path.rsplit('/').next().unwrap_or_default();
                    if crates_io_index_path(package_name, &logical)? != path {
                        return Err(
                            Diagnostic::error("E_ORDINARY_SUPPLY_INDEX_PATH", &logical).at(&path)
                        );
                    }
                }
                0x03 => {
                    if path.strip_prefix("sparse-cache/").is_none_or(str::is_empty) {
                        return Err(
                            Diagnostic::error("E_ORDINARY_SUPPLY_SPARSE_PATH", &logical).at(&path)
                        );
                    }
                }
                _ => unreachable!("kind domain checked above"),
            }
            let key = (kind, path.as_bytes().to_vec());
            if prior_key.as_ref().is_some_and(|prior| prior >= &key) {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_ORDER", &logical).at(&path));
            }
            prior_key = Some(key);
            paths.push(path.clone());

            let payload_byte_length = cursor.read_u64()?;
            let payload_limit = match kind {
                0x01 => ORDINARY_ARCHIVE_BOUNDS.max_archive_compressed_bytes,
                0x02 => ORDINARY_MAX_SOURCE_FILE_BYTES,
                0x03 => MAX_SPARSE_CACHE_INPUT_BYTES,
                _ => unreachable!("kind domain checked above"),
            };
            let payload_length =
                checked_payload_length(payload_byte_length, payload_limit, &logical)?;
            let payload_sha256: [u8; 32] = cursor
                .read_exact(32)?
                .try_into()
                .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_DIGEST", &logical))?;
            let payload_offset = cursor.position();
            let payload = cursor.read_exact(payload_length)?;
            if sha256(payload) != payload_sha256 {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_DIGEST", &logical).at(&path));
            }
            if kind == 0x01 {
                let expected_sha256 = expected_archives.get(&path).ok_or_else(|| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_BINDING", &logical)
                        .at(format!("{path}: absent from bootstrap lock"))
                })?;
                if expected_sha256 != &payload_sha256 || !seen_archives.insert(path.clone()) {
                    return Err(
                        Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_BINDING", &logical)
                            .at(format!("{path}: lock checksum or uniqueness")),
                    );
                }
            }
            total_payload_bytes = total_payload_bytes
                .checked_add(payload_byte_length)
                .ok_or_else(|| Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject))?;
            if total_payload_bytes > declared_payload_bytes
                || total_payload_bytes > ORDINARY_MAX_SUPPLY_BUNDLE_BYTES
            {
                return Err(Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject)
                    .at("aggregate entry payloads"));
            }
            inner.update([kind]);
            inner.update(
                u32::try_from(path.len())
                    .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", &logical))?
                    .to_be_bytes(),
            );
            inner.update(path.as_bytes());
            inner.update(payload_byte_length.to_be_bytes());
            inner.update(payload_sha256);
            inner.update(payload);
            entries.push(OrdinarySupplyEntryBinding {
                kind,
                path: path.clone(),
                payload_offset,
                byte_length: payload_byte_length,
                sha256: payload_sha256,
            });
            if kind == 0x01 {
                let expected_root = path
                    .strip_suffix(".crate")
                    .ok_or_else(|| Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_PATH", &logical))?
                    .to_owned();
                archives.try_reserve(1).map_err(|_| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_ALLOCATION", subject)
                        .at("archive bindings")
                })?;
                archives.push(OrdinarySupplyArchiveBinding {
                    path,
                    expected_root,
                    payload_offset,
                    byte_length: payload_byte_length,
                    sha256: payload_sha256,
                });
            }
        }
        cursor.finish()?;
        validate_case_unique(paths, "ordinary supply entry paths")?;
        if total_payload_bytes != declared_payload_bytes {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_BOUND", subject)
                .at("declared/actual payload total"));
        }
        let actual_inner_sha256: [u8; 32] = inner.finalize().into();
        if actual_inner_sha256 != declared_inner_sha256 {
            return Err(
                Diagnostic::error("E_ORDINARY_SUPPLY_DIGEST", subject).at("inner entry-set digest")
            );
        }
        if archives.is_empty()
            || seen_archives.len() != expected_archives.len()
            || expected_archives
                .keys()
                .any(|path| !seen_archives.contains(path))
        {
            return Err(Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_SET", subject)
                .at("0x01 archive set differs from bootstrap lock"));
        }
        let lock_triples = lock_triples.into_iter().collect::<Vec<_>>();
        let closure_rows = validate_ordinary_supply_closure(
            bytes,
            &entries,
            &lock_triples,
            closure_bijection_sha256,
            subject,
        )?;
        Ok(OrdinarySupplyFraming {
            bootstrap_lock_payload_offset,
            bootstrap_lock_byte_length,
            bootstrap_lock_sha256,
            acquisition_root_entry_count,
            acquisition_root_total_regular_file_bytes,
            acquisition_root_set_sha256,
            sparse_config_path,
            sparse_config_payload_offset,
            sparse_config_byte_length,
            sparse_config_sha256,
            lock_triples,
            entry_count,
            total_payload_bytes,
            inner_entry_set_sha256: declared_inner_sha256,
            closure_bijection_sha256,
            entries,
            closure_rows,
            archives,
        })
    }

    fn validate_ordinary_supply_archives(
        bytes: &[u8],
        framing: &OrdinarySupplyFraming,
    ) -> VResult<()> {
        for archive in &framing.archives {
            let payload_length = usize::try_from(archive.byte_length)
                .map_err(|_| Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_BOUND", &archive.path))?;
            let payload_end = archive
                .payload_offset
                .checked_add(payload_length)
                .ok_or_else(|| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_BOUND", &archive.path)
                })?;
            let payload = bytes
                .get(archive.payload_offset..payload_end)
                .ok_or_else(|| {
                    Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_BOUND", &archive.path)
                })?;
            if sha256(payload) != archive.sha256 {
                return Err(
                    Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_BINDING", &archive.path)
                        .at("pre-validation digest"),
                );
            }
            let summary = validate_gzip_tar(
                payload,
                &ORDINARY_ARCHIVE_BOUNDS,
                &archive.path,
                Some(&archive.expected_root),
            )?;
            if summary.root != archive.expected_root
                || u64::try_from(payload.len()).unwrap_or(u64::MAX) != archive.byte_length
                || sha256(payload) != archive.sha256
            {
                return Err(
                    Diagnostic::error("E_ORDINARY_SUPPLY_ARCHIVE_BINDING", &archive.path)
                        .at("post-validation binding"),
                );
            }
        }
        Ok(())
    }

    fn parse_ordinary_acquisition_spool(
        bytes: &[u8],
        run_id: &str,
        supply_path: &str,
        supply_byte_length: u64,
        supply_sha256: [u8; 32],
    ) -> Result<CanonicalRecord, String> {
        let record = parse_canonical_record_file_with_final_self_digest(
            bytes,
            ACQUISITION_SPOOL_PREFIX,
            "acquisition-spool",
            "spool_set_sha256",
            ORDINARY_MAX_ACQUISITION_SPOOL_BYTES,
            "ordinary acquisition spool",
        )
        .map_err(|error| error.detail().to_owned())?;
        let commands = record
            .records("command")
            .map_err(|error| error.detail().to_owned())?;
        if record
            .string("format")
            .map_err(|error| error.detail().to_owned())?
            != "FND01ACQSPOOLv1"
            || record
                .unsigned("schema_version")
                .map_err(|error| error.detail().to_owned())?
                != 1
            || record
                .string("role")
                .map_err(|error| error.detail().to_owned())?
                != "integration-producer"
            || record
                .string("run_id")
                .map_err(|error| error.detail().to_owned())?
                != run_id
            || record
                .unsigned("command_count")
                .map_err(|error| error.detail().to_owned())?
                != 2
            || commands.len() != 2
        {
            return Err("format/schema/role/run/count mismatch".to_owned());
        }
        for (ordinal, (command, expected_id)) in commands
            .iter()
            .zip(["bootstrap.resolve", "bootstrap.fetch"])
            .enumerate()
        {
            if command
                .string("id")
                .map_err(|error| error.detail().to_owned())?
                != expected_id
                || command
                    .unsigned("ordinal")
                    .map_err(|error| error.detail().to_owned())?
                    != u64::try_from(ordinal)
                        .map_err(|_| "command ordinal conversion".to_owned())?
                || command
                    .signed("exit_code")
                    .map_err(|error| error.detail().to_owned())?
                    != 0
                || command
                    .string("evidence_verdict")
                    .map_err(|error| error.detail().to_owned())?
                    != "Pass"
            {
                return Err(format!("command ordinal {ordinal} mismatch"));
            }
        }
        let spool_supply = record
            .record("supply_bundle")
            .map_err(|error| error.detail().to_owned())?;
        let spool_supply_sha256 = super::trust_std::decode_lower_hex::<32>(
            spool_supply
                .string("sha256")
                .map_err(|error| error.detail().to_owned())?,
            "ordinary spool supply SHA-256",
        )
        .map_err(|error| error.detail().to_owned())?;
        if spool_supply
            .string("path")
            .map_err(|error| error.detail().to_owned())?
            != supply_path
            || spool_supply
                .unsigned("byte_length")
                .map_err(|error| error.detail().to_owned())?
                != supply_byte_length
            || spool_supply_sha256 != supply_sha256
        {
            return Err("supply binding mismatch".to_owned());
        }
        Ok(record)
    }

    #[derive(Debug)]
    struct ControlLedgerExpectationAuthority {
        role: &'static str,
        run_id: String,
        process_id: u64,
        control_ledger_relative: String,
        environment_set_sha256: [u8; 32],
        handoff_argv_arity: usize,
        native_tool_count: usize,
    }

    struct OrdinaryAttestAuthority {
        seal: IntegrationSeal,
        retained: RetainedSnapshotSet<6>,
    }

    struct OrdinaryPreLedgerAuthority {
        marker: super::trust_std::AuthoringMarker,
        integration: Option<OrdinaryAttestAuthority>,
        repository_root: PathBuf,
        mode: BootstrapMode,
        control: ControlLedgerExpectationAuthority,
        closed_path: String,
    }

    impl fmt::Debug for OrdinaryPreLedgerAuthority {
        fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
            formatter
                .debug_struct("OrdinaryPreLedgerAuthority")
                .field("repository_root", &self.repository_root)
                .field("mode", &self.mode)
                .field("control", &self.control)
                .field("closed_path", &self.closed_path)
                .field("has_integration_authority", &self.integration.is_some())
                .finish_non_exhaustive()
        }
    }

    struct OrdinaryNonToolExpectation {
        scratch_bindings: [ValidatedFileBinding; 5],
        local_registry: ValidatedDirectoryTreeBinding,
        supply_bundle: ValidatedFileBinding,
        supply_relative: String,
        supply_snapshot: CheckedSnapshot,
        supply_bytes: Vec<u8>,
        target_snapshot: ValidatedTargetSnapshot,
        selected_executable: ValidatedFileBinding,
        selected_snapshot: CheckedSnapshot,
        control_build_environment: OrdinaryControlBuildEnvironmentAuthority,
        handoff_argv: Vec<String>,
        handoff_environment: Vec<(String, String)>,
        spool_relative: Option<String>,
        spool_snapshot: Option<CheckedSnapshot>,
        acquisition_spool_binding: Option<FileBinding>,
    }

    struct OrdinaryProbePermit {
        authority: OrdinaryPreLedgerAuthority,
        non_tool: OrdinaryNonToolExpectation,
        ledger_snapshot: CheckedSnapshot,
        ledger_bytes: Vec<u8>,
        qualified_platform: OrdinaryQualifiedPlatform,
    }

    struct OrdinaryQualifiedPlatform;

    struct OrdinaryProbedAuthority {
        authority: OrdinaryPreLedgerAuthority,
        non_tool: OrdinaryNonToolExpectation,
        ledger_snapshot: CheckedSnapshot,
        ledger_bytes: Vec<u8>,
        tool_reprobe: OrdinaryToolReprobe,
    }

    impl OrdinaryProbePermit {
        fn consume(self) -> Result<OrdinaryProbedAuthority, OrdinaryEntryFailure> {
            let tool_reprobe = ordinary_reprobe_tool_set_qualified(
                &self.authority.repository_root,
                self.authority.mode,
                &self.authority.control.run_id,
                &self.authority.closed_path,
                self.qualified_platform,
            )?;
            Ok(OrdinaryProbedAuthority {
                authority: self.authority,
                non_tool: self.non_tool,
                ledger_snapshot: self.ledger_snapshot,
                ledger_bytes: self.ledger_bytes,
                tool_reprobe,
            })
        }
    }

    struct OrdinaryArchivePermit {
        expectation: ControlLedgerExpectation,
        ledger_snapshot: CheckedSnapshot,
        ledger_bytes: Vec<u8>,
        ledger: ValidatedControlLedger,
        non_tool: OrdinaryNonToolExpectation,
        tool_reprobe: OrdinaryToolReprobe,
        integration: Option<OrdinaryAttestAuthority>,
    }

    const ORDINARY_NATIVE_TOOL_COUNT: usize = 20;
    const ORDINARY_NATIVE_TOOL_REGISTRY_BYTES: usize = 3911;
    const ORDINARY_NATIVE_TOOL_REGISTRY_SHA256: &str =
        "f699966ccfc01221f2dd81d6e801825c0f9fc56583ce6d474cdb03baaa47dc9b";
    const ORDINARY_HANDOFF_ARGV_ARITY: usize = 5;

    fn validate_ordinary_native_tool_descriptor_authority(
        expected_count: usize,
        expected_byte_length: usize,
        expected_sha256_text: &str,
    ) -> Result<(), OrdinaryEntryFailure> {
        let (count, byte_length, sha256) =
            super::trust_std::compiled_native_tool_registry_identity()
                .map_err(|error| OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::ProbeToolSet,
                    error.detail(),
                ))?;
        let expected_sha256 = super::trust_std::decode_lower_hex::<32>(
            expected_sha256_text,
            "ordinary native-tool registry SHA-256",
        )
        .map_err(|error| OrdinaryEntryFailure::from_site(
            OrdinaryFailureSite::ProbeToolSet,
            error.detail(),
        ))?;
        if count != expected_count
            || byte_length != expected_byte_length
            || sha256 != expected_sha256
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::ProbeToolSet,
                "pure twenty-tool descriptor registry drift",
            ));
        }
        Ok(())
    }

    fn ordinary_native_tool_descriptor_authority() -> Result<(), OrdinaryEntryFailure> {
        validate_ordinary_native_tool_descriptor_authority(
            ORDINARY_NATIVE_TOOL_COUNT,
            ORDINARY_NATIVE_TOOL_REGISTRY_BYTES,
            ORDINARY_NATIVE_TOOL_REGISTRY_SHA256,
        )
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    struct OrdinaryDualPathPureAuthority {
        native_tool_count: usize,
        registry_byte_length: usize,
        registry_sha256: [u8; 32],
    }

    fn ordinary_reprobe_dual_path_pure_authority()
        -> Result<OrdinaryDualPathPureAuthority, OrdinaryEntryFailure>
    {
        ordinary_native_tool_descriptor_authority()?;
        let descriptors = super::trust_std::NATIVE_TOOL_DESCRIPTORS;
        if descriptors.len() != ORDINARY_NATIVE_TOOL_COUNT {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::ProbeToolSet,
                format!(
                    "pure table cardinality {} != ORDINARY_NATIVE_TOOL_COUNT {ORDINARY_NATIVE_TOOL_COUNT}",
                    descriptors.len(),
                ),
            ));
        }
        let mut seen_ids = std::collections::BTreeSet::new();
        for (ordinal, row) in descriptors.iter().enumerate() {
            if row.id.is_empty() {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::ProbeToolSet,
                    format!("pure table row {ordinal} has empty id"),
                ));
            }
            if !seen_ids.insert(row.id) {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::ProbeToolSet,
                    format!("pure table duplicate tool id {}", row.id),
                ));
            }
            if row.candidates.is_empty() || row.version_argv.is_empty() {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::ProbeToolSet,
                    format!("pure table row {} missing candidates or version argv", row.id),
                ));
            }
        }
        if seen_ids.len() != ORDINARY_NATIVE_TOOL_COUNT {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::ProbeToolSet,
                format!(
                    "pure table unique-id cardinality {} != {ORDINARY_NATIVE_TOOL_COUNT}",
                    seen_ids.len(),
                ),
            ));
        }
        let (count, byte_length, sha256) =
            super::trust_std::compiled_native_tool_registry_identity()
                .map_err(|error| OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::ProbeToolSet,
                    error.detail(),
                ))?;
        if count != ORDINARY_NATIVE_TOOL_COUNT
            || byte_length != ORDINARY_NATIVE_TOOL_REGISTRY_BYTES
            || lower_hex(&sha256) != ORDINARY_NATIVE_TOOL_REGISTRY_SHA256
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::ProbeToolSet,
                "pure dual-path registry identity drift",
            ));
        }
        Ok(OrdinaryDualPathPureAuthority {
            native_tool_count: count,
            registry_byte_length: byte_length,
            registry_sha256: sha256,
        })
    }

    fn ordinary_closed_path_toolchain_authority(
        closed_path: &str,
    ) -> Result<String, OrdinaryEntryFailure> {
        let tool_bin = closed_path
            .strip_suffix(":/usr/bin:/bin")
            .ok_or_else(|| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::PreLedgerAuthority,
                    "independent twenty-tool closed PATH must end with :/usr/bin:/bin",
                )
            })?;
        if tool_bin.is_empty()
            || tool_bin.contains(':')
            || !tool_bin.starts_with('/')
            || !tool_bin.ends_with("/bin")
            || tool_bin.contains("//")
            || tool_bin.contains("/./")
            || tool_bin.contains("/../")
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreLedgerAuthority,
                "independent twenty-tool toolchain bin is not a single absolute /bin path",
            ));
        }
        Ok(tool_bin.to_owned())
    }

    fn ordinary_control_ledger_expectation_authority(
        mode: BootstrapMode,
        run_id: &str,
        environment_set_sha256: [u8; 32],
    ) -> Result<ControlLedgerExpectationAuthority, String> {
        let role = super::trust_std::bootstrap_role_name(mode).map_err(|error| {
            format!(
                "ControlLedgerExpectation mode/role authority incomplete ({})",
                error.detail()
            )
        })?;
        let run_id_bytes = super::trust_std::decode_lower_hex::<16>(run_id, "ordinary run ID")
            .map_err(|error| {
                format!(
                    "ControlLedgerExpectation run_id authority incomplete ({})",
                    error.detail()
                )
            })?;
        if run_id_bytes.iter().all(|byte| *byte == 0) {
            return Err("ControlLedgerExpectation rejects all-zero run_id".to_owned());
        }
        let process_id = u64::from(std::process::id());
        if process_id == 0 {
            return Err("ControlLedgerExpectation process_id must be nonzero".to_owned());
        }
        if environment_set_sha256 == [0; 32] {
            return Err(
                "ControlLedgerExpectation environment_set digest must be nonzero".to_owned(),
            );
        }
        let control_ledger_relative = format!(".fnd01-run/{role}/{run_id}/control-ledger.bin");
        if control_ledger_relative.contains("//")
            || control_ledger_relative.contains("/./")
            || control_ledger_relative.contains("/../")
            || !control_ledger_relative.ends_with("/control-ledger.bin")
        {
            return Err(
                "ControlLedgerExpectation control-ledger path grammar failed".to_owned(),
            );
        }
        Ok(ControlLedgerExpectationAuthority {
            role,
            run_id: run_id.to_owned(),
            process_id,
            control_ledger_relative,
            environment_set_sha256,
            handoff_argv_arity: ORDINARY_HANDOFF_ARGV_ARITY,
            native_tool_count: ORDINARY_NATIVE_TOOL_COUNT,
        })
    }

    fn ordinary_sealed_nonzero_digest(tag: u8) -> [u8; 32] {
        let mut digest = [tag; 32];
        digest[0] = tag.wrapping_add(1);
        digest[31] = tag.wrapping_add(0x5a);
        digest
    }

    fn ordinary_sealed_file_binding(path: String, tag: u8) -> ValidatedFileBinding {
        ValidatedFileBinding {
            path,
            binding: FileBinding {
                byte_length: 64 + u64::from(tag),
                sha256: ordinary_sealed_nonzero_digest(tag),
            },
        }
    }

    macro_rules! pending {
        ($($arg:tt)*) => { format!("E_ORDINARY_HANDOFF_PENDING: {}", format_args!($($arg)*)) };
    }

    fn ordinary_role_absolute_path(
        repository_root: &Path,
        role: &str,
        run_id: &str,
        suffix: &str,
    ) -> Result<String, String> {
        let root = ordinary_utf8_path(repository_root, "repository root")?;
        if !root.starts_with('/') {
            return Err(pending!(
                "sealed ControlLedgerExpectation repository root must be absolute"
            ));
        }
        let relative = if suffix.is_empty() {
            format!(".fnd01-run/{role}/{run_id}")
        } else {
            format!(".fnd01-run/{role}/{run_id}/{suffix}")
        };
        if relative.contains("//") || relative.contains("/./") || relative.contains("/../") {
            return Err(pending!(
                "sealed ControlLedgerExpectation role path grammar failed"
            ));
        }
        ordinary_utf8_path(&repository_root.join(relative), "role path")
    }

    fn ordinary_sealed_control_ledger_expectation_join(
        mode: BootstrapMode,
        repository_root: &Path,
        control: &ControlLedgerExpectationAuthority,
        authoring_closure_sha256: [u8; 32],
        integration_seal_sha256: [u8; 32],
        tool_set_sha256: [u8; 32],
        cargo_executable: &str,
        bootstrap_environment: BootstrapEnvironment,
    ) -> Result<ControlLedgerExpectation, String> {
        if control.run_id.is_empty()
            || control.process_id == 0
            || control.environment_set_sha256 == [0; 32]
            || control.native_tool_count != ORDINARY_NATIVE_TOOL_COUNT
            || control.handoff_argv_arity != ORDINARY_HANDOFF_ARGV_ARITY
        {
            return Err(pending!(
                "sealed ControlLedgerExpectation pure authority incomplete"
            ));
        }
        let role = bootstrap_role_name(mode).map_err(|error| {
            pending!("sealed ControlLedgerExpectation mode/role incomplete ({error})")
        })?;
        if control.role != role {
            return Err(pending!(
                "sealed ControlLedgerExpectation role desync (expected {role}, observed {})",
                control.role
            ));
        }
        if control.control_ledger_relative
            != format!(".fnd01-run/{role}/{}/control-ledger.bin", control.run_id)
        {
            return Err(pending!(
                "sealed ControlLedgerExpectation control-ledger relative desync"
            ));
        }
        if authoring_closure_sha256 == [0; 32] {
            return Err(pending!("sealed authoring_closure_sha256 must be nonzero"));
        }
        if tool_set_sha256 == [0; 32] {
            return Err(pending!("sealed tool_set_sha256 must be nonzero"));
        }
        if cargo_executable.is_empty() || !cargo_executable.starts_with('/') {
            return Err(pending!(
                "sealed cargo_executable must be absolute and nonempty"
            ));
        }
        if bootstrap_environment.authoring_marker.is_empty()
            || bootstrap_environment.closed_path.is_empty()
        {
            return Err(pending!("sealed bootstrap environment incomplete"));
        }

        match mode {
            BootstrapMode::Produce => {
                if integration_seal_sha256 != [0; 32]
                    || bootstrap_environment.integration_seal.is_some()
                    || bootstrap_environment.producer_outer_record_path.is_some()
                {
                    return Err(pending!(
                        "Produce sealed expectation rejects Attest seal/spool authority"
                    ));
                }
            }
            BootstrapMode::Attest => {
                if integration_seal_sha256 == [0; 32]
                    || bootstrap_environment.integration_seal.is_none()
                {
                    return Err(pending!(
                        "Attest sealed expectation requires nonzero integration seal"
                    ));
                }
            }
            BootstrapMode::Gate => {
                return Err(pending!(
                    "Gate cannot carry a sealed ControlLedgerExpectation"
                ));
            }
        }

        let package_root = ordinary_role_absolute_path(
            repository_root,
            role,
            &control.run_id,
            "bootstrap-control-package",
        )?;
        let target_root = ordinary_role_absolute_path(
            repository_root,
            role,
            &control.run_id,
            "bootstrap-control-target",
        )?;
        let local_registry_path =
            ordinary_role_absolute_path(repository_root, role, &control.run_id, "local-registry")?;
        let supply_path = ordinary_role_absolute_path(
            repository_root,
            role,
            &control.run_id,
            "supply-bundle.bin",
        )?;

        let scratch_suffixes = [
            "Cargo.toml",
            "Cargo.lock",
            "cargo-config.toml",
            "src/main.rs",
            "tests/fnd_01_dependency_evidence.rs",
        ];
        let mut scratch_bindings = [
            ordinary_sealed_file_binding(String::new(), 1),
            ordinary_sealed_file_binding(String::new(), 2),
            ordinary_sealed_file_binding(String::new(), 3),
            ordinary_sealed_file_binding(String::new(), 4),
            ordinary_sealed_file_binding(String::new(), 5),
        ];
        for (index, suffix) in scratch_suffixes.iter().enumerate() {
            scratch_bindings[index] = ordinary_sealed_file_binding(
                format!("{package_root}/{suffix}"),
                (index as u8).wrapping_add(0x10),
            );
        }

        let local_registry = ValidatedDirectoryTreeBinding {
            id: "sealed-local-registry".to_owned(),
            path: local_registry_path,
            device: 1,
            inode: 2,
            mode: 0o40755,
            nlink: 2,
            entry_count: 1,
            total_regular_file_bytes: 128,
            tree_sha256: ordinary_sealed_nonzero_digest(0x20),
        };
        let supply_bundle = ordinary_sealed_file_binding(supply_path, 0x30);
        let selected_executable = ordinary_sealed_file_binding(
            format!("{target_root}/debug/fnd_01_evidence_harness"),
            0x40,
        );
        let target_snapshot = ValidatedTargetSnapshot {
            path: target_root,
            entry_count: 3,
            total_regular_file_bytes: selected_executable.binding.byte_length,
            tree_sha256: ordinary_sealed_nonzero_digest(0x41),
        };
        let build_environment = vec![
            (
                "CARGO_HOME".to_owned(),
                format!(
                    "{}/.fnd01-run/{role}/{}/cargo-home/offline",
                    ordinary_utf8_path(repository_root, "repository root")?,
                    control.run_id
                ),
            ),
            ("PATH".to_owned(), bootstrap_environment.closed_path.clone()),
            ("TZ".to_owned(), "UTC".to_owned()),
        ];
        let acquisition_spool_binding = match mode {
            BootstrapMode::Produce => Some(FileBinding {
                byte_length: 256,
                sha256: ordinary_sealed_nonzero_digest(0x50),
            }),
            BootstrapMode::Attest => None,
            BootstrapMode::Gate => unreachable!("Gate rejected above"),
        };

        if scratch_bindings
            .iter()
            .map(|binding| binding.path.as_str())
            .ne([
                format!("{package_root}/Cargo.toml"),
                format!("{package_root}/Cargo.lock"),
                format!("{package_root}/cargo-config.toml"),
                format!("{package_root}/src/main.rs"),
                format!("{package_root}/tests/fnd_01_dependency_evidence.rs"),
            ]
            .iter()
            .map(String::as_str))
            || local_registry.id != "sealed-local-registry"
            || selected_executable.binding.byte_length == 0
            || target_snapshot.path.is_empty()
            || supply_bundle.binding.byte_length == 0
        {
            return Err(pending!(
                "sealed ControlLedgerExpectation layout-derived field mismatch"
            ));
        }
        match mode {
            BootstrapMode::Produce => {
                if integration_seal_sha256 != [0; 32] || acquisition_spool_binding.is_none() {
                    return Err(pending!(
                        "Produce sealed integration/spool expectation mismatch"
                    ));
                }
            }
            BootstrapMode::Attest => {
                if integration_seal_sha256 == [0; 32] || acquisition_spool_binding.is_some() {
                    return Err(pending!(
                        "Attest sealed integration/spool expectation mismatch"
                    ));
                }
            }
            BootstrapMode::Gate => unreachable!("Gate rejected above"),
        }

        Ok(ControlLedgerExpectation {
            mode,
            repository_root: repository_root.to_path_buf(),
            run_id: control.run_id.clone(),
            process_id: control.process_id,
            authoring_closure_sha256,
            integration_seal_sha256,
            scratch_bindings,
            local_registry,
            supply_bundle,
            tool_set_sha256,
            environment_set_sha256: control.environment_set_sha256,
            cargo_executable: cargo_executable.to_owned(),
            build_environment,
            target_snapshot,
            selected_executable,
            bootstrap_environment,
            acquisition_spool_binding,
        })
    }

    fn ordinary_sealed_control_build_stdout(
        package_root: &str,
        target_root: &str,
        selected_executable: &str,
    ) -> String {
        let package_id =
            format!("path+file://{package_root}#fastmcp-fnd01-bootstrap-control@0.0.0");
        let artifact = format!(
            concat!(
                r#"{{"reason":"compiler-artifact","package_id":"{package_id}","manifest_path":"{package_root}/Cargo.toml","target":{{"kind":["bin"],"crate_types":["bin"],"name":"fnd_01_evidence_harness","src_path":"{package_root}/src/main.rs","edition":"2024","doc":false,"doctest":false,"test":false}},"profile":{{"opt_level":"0","debuginfo":2,"debug_assertions":true,"overflow_checks":true,"test":false}},"features":[],"filenames":["{selected_executable}"],"executable":"{selected_executable}","fresh":false}}"#,
                "\n",
                r#"{{"reason":"build-finished","success":true}}"#,
                "\n",
            ),
            package_id = package_id,
            package_root = package_root,
            selected_executable = selected_executable,
        );
        let _ = target_root;
        artifact
    }

    fn ordinary_sealed_file_binding_record(binding: &ValidatedFileBinding) -> CanonicalRecord {
        CanonicalRecord {
            schema_id: "file-binding",
            fields: vec![
                CanonicalValue::String(binding.path.clone()),
                CanonicalValue::Unsigned(binding.binding.byte_length),
                CanonicalValue::String(encode_lower_hex(&binding.binding.sha256)),
            ],
            field_offsets: Vec::new(),
        }
    }

    fn ordinary_sealed_raw_stream_record(bytes: &[u8]) -> Result<CanonicalRecord, String> {
        let digest =
            trust_sha256(bytes).map_err(|error| format!("E_CONTROL_RAW_DIGEST: {error}"))?;
        let length = u64::try_from(bytes.len())
            .map_err(|_| "E_CONTROL_RAW_LENGTH: stream length".to_owned())?;
        Ok(CanonicalRecord {
            schema_id: "raw-stream-blob",
            fields: vec![
                CanonicalValue::Unsigned(length),
                CanonicalValue::String(encode_lower_hex(&digest)),
                CanonicalValue::RawBytes(bytes.to_vec()),
            ],
            field_offsets: Vec::new(),
        })
    }

    fn ordinary_sealed_encode_control_ledger_bytes(
        expected: &ControlLedgerExpectation,
        build_stdout: &[u8],
    ) -> Result<Vec<u8>, String> {
        let role = bootstrap_role_name(expected.mode)
            .map_err(|error| format!("E_CONTROL_MODE: {error}"))?;
        let package_root = ordinary_role_absolute_path(
            &expected.repository_root,
            role,
            &expected.run_id,
            "bootstrap-control-package",
        )?;
        let target_root = ordinary_role_absolute_path(
            &expected.repository_root,
            role,
            &expected.run_id,
            "bootstrap-control-target",
        )?;
        let selected = expected.selected_executable.path.as_str();
        let joined = join_control_build_stream(build_stdout, &package_root, &target_root, selected)
            .map_err(|error| format!("E_CONTROL_BUILD_STREAM_JOIN: {error}"))?;
        let build_argv = vec![
            expected.cargo_executable.clone(),
            "build".to_owned(),
            "--manifest-path".to_owned(),
            format!("{package_root}/Cargo.toml"),
            "--bin".to_owned(),
            "fnd_01_evidence_harness".to_owned(),
            "--locked".to_owned(),
            "--offline".to_owned(),
            "--message-format=json".to_owned(),
            "--target-dir".to_owned(),
            target_root.clone(),
            "--config".to_owned(),
            format!("{package_root}/cargo-config.toml"),
        ];
        let handoff_argv =
            expected_ordinary_handoff_argv(expected.mode, selected, &expected.run_id)
                .map_err(|error| format!("E_CONTROL_HANDOFF: {error}"))?;
        let handoff_environment = expected_ordinary_handoff_environment(
            expected.mode,
            &expected.run_id,
            &expected.bootstrap_environment,
        )
        .map_err(|error| format!("E_CONTROL_HANDOFF_ENVIRONMENT: {error}"))?;
        let stderr_record = ordinary_sealed_raw_stream_record(b"")?;
        let stdout_record = ordinary_sealed_raw_stream_record(build_stdout)?;
        let local_registry = CanonicalRecord {
            schema_id: "directory-tree-binding",
            fields: vec![
                CanonicalValue::String(expected.local_registry.id.clone()),
                CanonicalValue::String(expected.local_registry.path.clone()),
                CanonicalValue::Unsigned(expected.local_registry.device),
                CanonicalValue::Unsigned(expected.local_registry.inode),
                CanonicalValue::Unsigned(u64::from(expected.local_registry.mode)),
                CanonicalValue::Unsigned(expected.local_registry.nlink),
                CanonicalValue::Unsigned(expected.local_registry.entry_count),
                CanonicalValue::Unsigned(expected.local_registry.total_regular_file_bytes),
                CanonicalValue::String(encode_lower_hex(&expected.local_registry.tree_sha256)),
            ],
            field_offsets: Vec::new(),
        };
        let supply_bundle = ordinary_sealed_file_binding_record(&expected.supply_bundle);
        let compiler_artifact = CanonicalRecord {
            schema_id: "cargo-compiler-artifact",
            fields: vec![
                CanonicalValue::String(joined.artifact.reason.clone()),
                CanonicalValue::String(joined.artifact.package_id.clone()),
                CanonicalValue::String(joined.artifact.manifest_path.clone()),
                CanonicalValue::String(joined.artifact.target_name.clone()),
                CanonicalValue::StringArray(joined.artifact.target_kind.clone()),
                CanonicalValue::StringArray(joined.artifact.crate_types.clone()),
                CanonicalValue::String(joined.artifact.src_path.clone()),
                CanonicalValue::String(joined.artifact.edition.clone()),
                CanonicalValue::StringArray(joined.artifact.features.clone()),
                CanonicalValue::Boolean(joined.artifact.profile_test),
                CanonicalValue::Boolean(joined.artifact.fresh),
                CanonicalValue::StringArray(joined.artifact.filenames.clone()),
                CanonicalValue::String(joined.artifact.executable.clone()),
            ],
            field_offsets: Vec::new(),
        };
        let build_finished = CanonicalRecord {
            schema_id: "cargo-build-finished",
            fields: vec![
                CanonicalValue::String(joined.finished.reason.clone()),
                CanonicalValue::Boolean(joined.finished.success),
                CanonicalValue::Unsigned(joined.finished.line_ordinal),
            ],
            field_offsets: Vec::new(),
        };
        let target_snapshot = CanonicalRecord {
            schema_id: "target-snapshot",
            fields: vec![
                CanonicalValue::String(expected.target_snapshot.path.clone()),
                CanonicalValue::Unsigned(expected.target_snapshot.entry_count),
                CanonicalValue::Unsigned(expected.target_snapshot.total_regular_file_bytes),
                CanonicalValue::String(encode_lower_hex(&expected.target_snapshot.tree_sha256)),
            ],
            field_offsets: Vec::new(),
        };
        let selected_executable =
            ordinary_sealed_file_binding_record(&expected.selected_executable);
        let acquisition_spool = match expected.acquisition_spool_binding {
            Some(binding) => {
                let spool_path = expected
                    .repository_root
                    .join(".fnd01-run")
                    .join("integration-producer")
                    .join(&expected.run_id)
                    .join("acquisition-spool.bin");
                let spool_path = ordinary_utf8_path(&spool_path, "acquisition spool")?;
                CanonicalRecord {
                    schema_id: "optional-file-binding",
                    fields: vec![
                        CanonicalValue::Boolean(true),
                        CanonicalValue::OptionalString(Some(spool_path)),
                        CanonicalValue::OptionalUnsigned(Some(binding.byte_length)),
                        CanonicalValue::OptionalString(Some(encode_lower_hex(&binding.sha256))),
                    ],
                    field_offsets: Vec::new(),
                }
            }
            None => CanonicalRecord {
                schema_id: "optional-file-binding",
                fields: vec![
                    CanonicalValue::Boolean(false),
                    CanonicalValue::OptionalString(None),
                    CanonicalValue::OptionalUnsigned(None),
                    CanonicalValue::OptionalString(None),
                ],
                field_offsets: Vec::new(),
            },
        };
        let scratch_records = expected
            .scratch_bindings
            .iter()
            .map(ordinary_sealed_file_binding_record)
            .collect::<Vec<_>>();
        let build_control_ledger_record = |ledger_set_sha256: &str| CanonicalRecord {
            schema_id: "control-ledger",
            fields: vec![
                CanonicalValue::String("FND01CONTROLv2".to_owned()),
                CanonicalValue::Unsigned(2),
                CanonicalValue::String(role.to_owned()),
                CanonicalValue::String(expected.run_id.clone()),
                CanonicalValue::Unsigned(expected.process_id),
                CanonicalValue::String(encode_lower_hex(&expected.authoring_closure_sha256)),
                CanonicalValue::String(encode_lower_hex(&expected.integration_seal_sha256)),
                CanonicalValue::Unsigned(5),
                CanonicalValue::RecordArray(scratch_records.clone()),
                CanonicalValue::Record(Box::new(local_registry.clone())),
                CanonicalValue::Record(Box::new(supply_bundle.clone())),
                CanonicalValue::String(encode_lower_hex(&expected.tool_set_sha256)),
                CanonicalValue::String(encode_lower_hex(&expected.environment_set_sha256)),
                CanonicalValue::StringArray(build_argv.clone()),
                CanonicalValue::EnvironmentPairs(expected.build_environment.clone()),
                CanonicalValue::String(package_root.clone()),
                CanonicalValue::Signed(0),
                CanonicalValue::Record(Box::new(stdout_record.clone())),
                CanonicalValue::Record(Box::new(stderr_record.clone())),
                CanonicalValue::Unsigned(joined.message_count),
                CanonicalValue::String(encode_lower_hex(&joined.message_set_sha256)),
                CanonicalValue::Record(Box::new(compiler_artifact.clone())),
                CanonicalValue::Record(Box::new(build_finished.clone())),
                CanonicalValue::Record(Box::new(target_snapshot.clone())),
                CanonicalValue::Record(Box::new(selected_executable.clone())),
                CanonicalValue::StringArray(handoff_argv.clone()),
                CanonicalValue::EnvironmentPairs(handoff_environment.clone()),
                CanonicalValue::Record(Box::new(acquisition_spool.clone())),
                CanonicalValue::String(ledger_set_sha256.to_owned()),
            ],
            field_offsets: Vec::new(),
        };
        let placeholder = "0".repeat(64);
        let provisional = build_control_ledger_record(&placeholder);
        let body = encode_canonical_record(&provisional, "sealed control ledger")
            .map_err(|error| format!("E_CONTROL_LEDGER: encode failed ({error})"))?;
        let mut bytes = CONTROL_LEDGER_PREFIX.to_vec();
        bytes.extend_from_slice(&body);
        let parsed = parse_canonical_record_file(
            &bytes,
            CONTROL_LEDGER_PREFIX,
            "control-ledger",
            MAX_CONTROL_LEDGER_BYTES,
            "sealed control ledger provisional",
        )
        .map_err(|error| format!("E_CONTROL_LEDGER: provisional parse failed ({error})"))?;
        let digest_index = parsed
            .fields
            .len()
            .checked_sub(1)
            .ok_or_else(|| "E_CONTROL_LEDGER: empty control ledger fields".to_owned())?;
        let preimage_end = *parsed
            .field_offsets
            .get(digest_index)
            .ok_or_else(|| "E_CONTROL_LEDGER: missing ledger_set_sha256 offset".to_owned())?;
        let digest = trust_sha256(
            bytes
                .get(..preimage_end)
                .ok_or_else(|| "E_CONTROL_LEDGER: digest preimage bounds".to_owned())?,
        )
        .map_err(|error| format!("E_CONTROL_LEDGER: self-digest failed ({error})"))?;
        let sealed = build_control_ledger_record(&encode_lower_hex(&digest));
        let sealed_body = encode_canonical_record(&sealed, "sealed control ledger final")
            .map_err(|error| format!("E_CONTROL_LEDGER: final encode failed ({error})"))?;
        let mut sealed_bytes = CONTROL_LEDGER_PREFIX.to_vec();
        sealed_bytes.extend_from_slice(&sealed_body);
        parse_canonical_record_file_with_final_self_digest(
            &sealed_bytes,
            CONTROL_LEDGER_PREFIX,
            "control-ledger",
            "ledger_set_sha256",
            MAX_CONTROL_LEDGER_BYTES,
            "sealed control ledger self-digest",
        )
        .map_err(|error| format!("E_CONTROL_LEDGER: self-digest join failed ({error})"))?;
        Ok(sealed_bytes)
    }

    fn ordinary_sealed_produce_control_fixture(
    ) -> Result<(ControlLedgerExpectation, Vec<u8>, String, String), String> {
        let run_id = "0123456789abcdef0123456789abcdef";
        let env_digest = ordinary_environment_set_digest();
        let control = ordinary_control_ledger_expectation_authority(
            BootstrapMode::Produce,
            run_id,
            env_digest,
        )?;
        let repository_root = PathBuf::from("/repo/fastmcp_rust");
        let bootstrap_environment = BootstrapEnvironment {
            authoring_marker: "FND01AUTHORv2:fixture".to_owned(),
            closed_path: "/toolchains/nightly-2026-07-11/bin:/usr/bin:/bin".to_owned(),
            integration_seal: None,
            producer_outer_record_path: None,
            attester_outer_record_path: None,
            final_gate_seal: None,
        };
        let expectation = ordinary_sealed_control_ledger_expectation_join(
            BootstrapMode::Produce,
            &repository_root,
            &control,
            ordinary_sealed_nonzero_digest(0x61),
            [0; 32],
            ordinary_sealed_nonzero_digest(0x62),
            "/toolchains/nightly-2026-07-11/bin/cargo",
            bootstrap_environment,
        )?;
        let package_root = ordinary_role_absolute_path(
            &repository_root,
            "integration-producer",
            run_id,
            "bootstrap-control-package",
        )?;
        let target_root = ordinary_role_absolute_path(
            &repository_root,
            "integration-producer",
            run_id,
            "bootstrap-control-target",
        )?;
        let selected = expectation.selected_executable.path.clone();
        let stdout = ordinary_sealed_control_build_stdout(&package_root, &target_root, &selected);
        let ledger_bytes =
            ordinary_sealed_encode_control_ledger_bytes(&expectation, stdout.as_bytes())?;
        Ok((expectation, ledger_bytes, package_root, target_root))
    }

