    #[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
    fn ordinary_fixture_write_new(root: &Path, relative: &str, bytes: &[u8]) -> Result<(), String> {
        let path = root.join(relative);
        let parent = path
            .parent()
            .ok_or_else(|| pending!("fixture parent missing for {relative}"))?;
        fs::create_dir_all(parent)
            .map_err(|error| pending!("create {relative}: {error}"))?;
        let mut file = fs::OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(&path)
            .map_err(|error| pending!("create {relative}: {error}"))?;
        file.write_all(bytes)
            .map_err(|error| pending!("write {relative}: {error}"))?;
        file.sync_all()
            .map_err(|error| pending!("sync {relative}: {error}"))
    }

    #[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
    fn ordinary_fixture_copy_bounded_executable(
        source: &Path,
        destination: &Path,
    ) -> Result<u64, String> {
        let source_metadata = fs::symlink_metadata(source)
            .map_err(|error| pending!("source executable metadata: {error}"))?;
        let debug_input_maximum = MAX_GATE_EXECUTABLE_BYTES
            .checked_mul(2)
            .ok_or_else(|| pending!("debug executable input cap overflow"))?;
        if source_metadata.file_type().is_symlink()
            || !source_metadata.is_file()
            || source_metadata.len() == 0
            || source_metadata.len() > debug_input_maximum
        {
            return Err(pending!(
                "debug executable length {} outside 1..={debug_input_maximum}",
                source_metadata.len(),
            ));
        }
        if source_metadata.len() <= MAX_GATE_EXECUTABLE_BYTES {
            fs::copy(source, destination)
                .map_err(|error| pending!("copy selected executable: {error}"))?;
        } else {
            let strip = Path::new("/usr/bin/strip");
            let strip_metadata = fs::metadata(strip)
                .map_err(|error| pending!("strip fixture tool metadata: {error}"))?;
            if !strip_metadata.is_file() || strip_metadata.mode() & 0o111 == 0 {
                return Err(pending!("strip fixture tool is not executable"));
            }
            let status = Command::new(strip)
                .arg("--strip-debug")
                .arg("-o")
                .arg(destination)
                .arg(source)
                .env_clear()
                .env("LANG", "C")
                .env("LC_ALL", "C")
                .env("TZ", "UTC")
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .status()
                .map_err(|error| pending!("strip debug executable: {error}"))?;
            if !status.success() {
                return Err(pending!(
                    "strip debug executable exit {:?}",
                    status.code(),
                ));
            }
        }
        let output_metadata = fs::symlink_metadata(destination)
            .map_err(|error| pending!("selected executable metadata: {error}"))?;
        if output_metadata.file_type().is_symlink()
            || !output_metadata.is_file()
            || output_metadata.len() == 0
            || output_metadata.len() > MAX_GATE_EXECUTABLE_BYTES
        {
            return Err(pending!(
                "selected executable length {} outside 1..={MAX_GATE_EXECUTABLE_BYTES}",
                output_metadata.len(),
            ));
        }
        Ok(output_metadata.len())
    }

    #[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
    fn ordinary_fixture_install_executable(source: &Path, destination: &Path) -> Result<(), String> {
        let parent = destination
            .parent()
            .ok_or_else(|| pending!("selected executable parent missing"))?;
        fs::create_dir_all(parent)
            .map_err(|error| pending!("create selected executable parent: {error}"))?;
        if destination.exists() {
            return Err(pending!("selected executable already exists"));
        }
        let copied = ordinary_fixture_copy_bounded_executable(source, destination)?;
        if copied == 0 {
            return Err(pending!("copied executable is empty"));
        }
        let mut permissions = fs::metadata(destination)
            .map_err(|error| pending!("selected metadata: {error}"))?
            .permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(destination, permissions)
            .map_err(|error| pending!("selected executable chmod: {error}"))?;
        File::open(destination)
            .and_then(|file| file.sync_all())
            .map_err(|error| pending!("selected executable sync: {error}"))?;
        File::open(parent)
            .and_then(|directory| directory.sync_all())
            .map_err(|error| pending!("selected executable parent sync: {error}"))?;
        let metadata = fs::symlink_metadata(destination)
            .map_err(|error| pending!("selected executable recheck: {error}"))?;
        if !metadata.is_file()
            || metadata.nlink() != 1
            || metadata.mode() & 0o100 == 0
            || metadata.len() != copied
            || metadata.len() > MAX_GATE_EXECUTABLE_BYTES
        {
            return Err(pending!("selected executable identity is not sealed"));
        }
        Ok(())
    }

    #[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
    type OrdinaryFixtureNode = (u8, String, (u64, u64, u32, u32, u32, u64, u64), Vec<u8>);

    #[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
    fn ordinary_fixture_tree_state(root: &Path) -> Result<Vec<OrdinaryFixtureNode>, String> {
        use std::os::unix::ffi::OsStrExt;
        use std::os::unix::fs::MetadataExt;
        fn relative_path(root: &Path, path: &Path) -> Result<String, String> {
            path.strip_prefix(root).map_err(|_| "E_HANDOFF_LEDGER: accepted fixture escapes root".to_owned())?
                .to_str().ok_or_else(|| "E_HANDOFF_LEDGER: accepted fixture path is not UTF-8".to_owned()).map(str::to_owned)
        }
        fn node_metadata(metadata: &fs::Metadata) -> (u64, u64, u32, u32, u32, u64, u64) {
            (metadata.dev(), metadata.ino(), metadata.mode(), metadata.uid(), metadata.gid(), metadata.nlink(), metadata.len())
        }
        fn visit(root: &Path, current: &Path, state: &mut Vec<OrdinaryFixtureNode>) -> Result<(), String> {
            let mut paths = fs::read_dir(current)
                .map_err(|error| format!("E_HANDOFF_LEDGER: enumerate accepted fixture: {error}"))?
                .map(|entry| entry.map(|entry| entry.path()))
                .collect::<Result<Vec<_>, _>>()
                .map_err(|error| format!("E_HANDOFF_LEDGER: enumerate accepted entry: {error}"))?;
            paths.sort();
            for path in paths {
                let metadata = fs::symlink_metadata(&path).map_err(|error| format!("E_HANDOFF_LEDGER: stat accepted fixture: {error}"))?;
                if metadata.file_type().is_symlink() {
                    let relative = relative_path(root, &path)?;
                    let target = fs::read_link(&path).map_err(|error| format!("E_HANDOFF_LEDGER: read accepted symlink {relative}: {error}"))?;
                    state.push((3, relative, node_metadata(&metadata), target.as_os_str().as_bytes().to_vec()));
                } else if metadata.is_dir() {
                    state.push((1, relative_path(root, &path)?, node_metadata(&metadata), Vec::new()));
                    visit(root, &path, state)?;
                } else if metadata.is_file() {
                    let relative = relative_path(root, &path)?;
                    let bytes = fs::read(&path).map_err(|error| format!("E_HANDOFF_LEDGER: read accepted {relative}: {error}"))?;
                    state.push((2, relative, node_metadata(&metadata), bytes));
                } else {
                    return Err("E_HANDOFF_LEDGER: accepted fixture contains non-file node".to_owned());
                }
            }
            Ok(())
        }
        let root_metadata = fs::symlink_metadata(root).map_err(|error| format!("E_HANDOFF_LEDGER: stat accepted fixture root: {error}"))?;
        if root_metadata.file_type().is_symlink() || !root_metadata.is_dir() {
            return Err("E_HANDOFF_LEDGER: accepted fixture root is not a real directory".to_owned());
        }
        let mut state = vec![(0, String::new(), node_metadata(&root_metadata), Vec::new())];
        visit(root, root, &mut state)?;
        Ok(state)
    }

    #[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
    fn ordinary_attest_self_reexec_subject() -> Result<OrdinaryAttestSelfReexecSubject, String> {
        use super::trust_std::{AUTHORING_PATHS, INTEGRATION_SEAL_PATHS};
        use std::sync::atomic::{AtomicU64, Ordering};
        use std::time::{SystemTime, UNIX_EPOCH};

        static NEXT_SUBJECT: AtomicU64 = AtomicU64::new(1);

        let sequence = NEXT_SUBJECT.fetch_add(1, Ordering::Relaxed);
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_err(|error| pending!("fixture clock: {error}"))?
            .as_nanos();
        let mut fresh = None;
        for retry in 0..64u64 {
            let run_id = format!(
                "{:032x}",
                now ^ (u128::from(std::process::id()) << 64) ^ u128::from(sequence + retry),
            );
            if run_id == "00000000000000000000000000000000" {
                continue;
            }
            let root = Path::new("/tmp").join(format!("fastmcp-fnd01-attest-{run_id}"));
            match fs::create_dir(&root) {
                Ok(()) => {
                    fresh = Some((run_id, root));
                    break;
                }
                Err(error) if error.kind() == io::ErrorKind::AlreadyExists => continue,
                Err(error) => {
                    return Err(pending!("create fresh root: {error}"));
                }
            }
        }
        let (run_id, root) =
            fresh.ok_or_else(|| pending!("collision-safe fresh root allocation exhausted"))?;

        let source_root = repository_root();
        for path in AUTHORING_PATHS {
            let bytes = fs::read(source_root.join(path))
                .map_err(|error| pending!("read source authoring {path}: {error}"))?;
            ordinary_fixture_write_new(&root, path, &bytes)?;
        }
        let (policy, _) = read_policy(&source_root).map_err(|error| error.stable())?;
        let sources = load_sources(&source_root, &policy).map_err(|error| error.stable())?;
        for source in &sources { ordinary_fixture_write_new(&root, &source.contract.path, &source.bytes)?; }
        for path in ["Cargo.toml", "rust-toolchain.toml"] {
            let bytes = fs::read(source_root.join(path)).map_err(|error| error.to_string())?;
            ordinary_fixture_write_new(&root, path, &bytes)?;
        }
        let authoring_marker = live_authoring_marker_text(&root);

        let sysroot_output = Command::new("rustup")
            .args(["run", "nightly-2026-07-11", "rustc", "--print", "sysroot"])
            .output()
            .map_err(|error| pending!("query rust sysroot: {error}"))?;
        if !sysroot_output.status.success() {
            return Err(pending!(
                "query rust sysroot exit {:?}",
                sysroot_output.status.code(),
            ));
        }
        let sysroot = std::str::from_utf8(&sysroot_output.stdout)
            .map_err(|_| pending!("rust sysroot is not UTF-8"))?
            .strip_suffix('\n')
            .ok_or_else(|| pending!("rust sysroot newline missing"))?;
        let toolchain_bin = Path::new(sysroot).join("bin");
        let closed_path = format!(
            "{}:/usr/bin:/bin",
            toolchain_bin
                .to_str()
                .ok_or_else(|| pending!("rust toolchain bin is not UTF-8"))?,
        );

        let archive = test_gzip(&test_tar(&[(
            "attest-fixture-1.0.0/src/lib.rs",
            b"pub fn attest_fixture() {}\n",
            0,
        )]));
        let supply_bytes = test_ordinary_supply_bundle(&[("attest-fixture-1.0.0.crate", &archive)]);
        let cargo_lock = fs::read(source_root.join(INTEGRATION_SEAL_PATHS[0]))
            .map_err(|error| error.to_string())?;
        let integration_rows: [(&str, &[u8]); 5] = [
            (
                INTEGRATION_SEAL_PATHS[0],
                cargo_lock.as_slice(),
            ),
            (
                INTEGRATION_SEAL_PATHS[1],
                b"fixture source snapshot\n".as_slice(),
            ),
            (INTEGRATION_SEAL_PATHS[2], supply_bytes.as_slice()),
            (
                INTEGRATION_SEAL_PATHS[3],
                b"fixture workspace receipt\n".as_slice(),
            ),
            (
                INTEGRATION_SEAL_PATHS[4],
                b"fixture integration index\n".as_slice(),
            ),
        ];
        for &(path, bytes) in &integration_rows { ordinary_fixture_write_new(&root, path, bytes)?; }
        let integration=super::trust_std::attest_fixture_outer_and_integration(&run_id,&authoring_marker,integration_rows).map_err(|error|pending!("Attest fixture integration: {error}"))?;
        ordinary_fixture_write_new(&root,&format!(".fnd01-run/controller/{run_id}/producer-outer.bin"),&integration.producer_outer_bytes)?;
        super::phase_b_std::materialize_attest_fixture_supply(&root,&run_id,&supply_bytes).map_err(|error|pending!("materialize Attest supply: {error}"))?;

        let package_root=format!(".fnd01-run/independent-attester/{run_id}/bootstrap-control-package");
        for (relative, bytes) in [
            (
                "Cargo.toml",
                b"[package]\nname = \"fixture\"\nversion = \"0.1.0\"\nedition = \"2024\"\n"
                    .as_slice(),
            ),
            ("Cargo.lock", b"version = 4\n".as_slice()),
            ("cargo-config.toml", b"[net]\noffline = true\n".as_slice()),
            ("src/main.rs", b"fn main() {}\n".as_slice()),
            (
                "tests/fnd_01_dependency_evidence.rs",
                b"#[test]\nfn fixture() {}\n".as_slice(),
            ),
        ] {
            ordinary_fixture_write_new(&root, &format!("{package_root}/{relative}"), bytes)?;
        }

        let selected_relative=format!(".fnd01-run/independent-attester/{run_id}/bootstrap-control-target/debug/fnd_01_evidence_harness");
        let selected_executable = root.join(&selected_relative);
        let public_harness=std::env::var_os("FASTMCP_FND01_PUBLIC_HARNESS_BIN").map(PathBuf::from).ok_or_else(||pending!("FASTMCP_FND01_PUBLIC_HARNESS_BIN is required"))?;
        if !public_harness.is_absolute(){return Err(pending!("public harness path must be absolute"));}
        let target=std::env::var_os("CARGO_TARGET_DIR").map(PathBuf::from).unwrap_or_else(||source_root.join("target"));
        if !target.is_absolute(){return Err(pending!("CARGO_TARGET_DIR must be absolute"));}
        let expected=target.join("debug/examples/fnd_01_evidence_harness");
        if public_harness!=expected{return Err(pending!("public harness must be the Cargo example artifact"));}
        let (_,public_binding)=ordinary_checked_file_binding(&target,"debug/examples/fnd_01_evidence_harness",MAX_GATE_EXECUTABLE_BYTES,None,"Cargo-built public harness")?;
        ordinary_fixture_install_executable(&public_harness, &selected_executable)?;
        let (_,installed_binding)=ordinary_checked_file_binding(&root,&selected_relative,MAX_GATE_EXECUTABLE_BYTES,None,"installed public harness")?;
        if public_binding.binding!=installed_binding.binding{return Err(pending!("installed public harness bytes differ"));}
        let fixture_driver = selected_executable.with_file_name("fnd_01_evidence_fixture_driver");
        ordinary_fixture_install_executable(&std::env::current_exe().map_err(|error|pending!("current test executable: {error}"))?,&fixture_driver)?;

        Ok(OrdinaryAttestSelfReexecSubject {
            root,
            run_id,
            authoring_marker,
            integration_marker: integration.integration_marker,
            closed_path,
            fixture_driver,
        })
    }

    #[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
    fn ordinary_attest_self_reexec_child() -> Result<Option<OrdinaryAttestSelfReexecChild>, String>
    {
        use super::trust_std::{
            AUTHORING_MARKER_ENV, INTEGRATION_SEAL_ENV, PRODUCER_OUTER_RECORD_PATH_ENV, RUN_ID_ENV,
        };

        let environment = std::env::vars().collect::<BTreeMap<_, _>>();
        let role_keys = [
            AUTHORING_MARKER_ENV,
            INTEGRATION_SEAL_ENV,
            PRODUCER_OUTER_RECORD_PATH_ENV,
            RUN_ID_ENV,
        ];
        let required = [
            AUTHORING_MARKER_ENV,
            INTEGRATION_SEAL_ENV,
            PRODUCER_OUTER_RECORD_PATH_ENV,
            RUN_ID_ENV,
            "LANG",
            "LC_ALL",
            "PATH",
            "TZ",
        ];
        let role_key_count = role_keys
            .iter()
            .filter(|name| environment.contains_key(**name))
            .count();
        if role_key_count == 0 {
            return Ok(None);
        }
        if environment.len() != required.len()
            || required.iter().any(|name| !environment.contains_key(*name))
        {
            return Err(
                "E_HANDOFF_ENVIRONMENT: partial Attest self-reexec role environment".to_owned(),
            );
        }
        let run_id = environment
            .get(RUN_ID_ENV)
            .expect("required Attest self-reexec run ID is present")
            .clone();
        if run_id.len() != 32
            || run_id == "00000000000000000000000000000000"
            || !run_id
                .bytes()
                .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
        {
            return Err("E_HANDOFF_ARGUMENTS: invalid Attest self-reexec run ID".to_owned());
        }
        let current_executable = std::env::current_exe()
            .map_err(|error| format!("E_HANDOFF_EXECUTABLE: child current_exe: {error}"))?;
        let executable = current_executable
            .to_str()
            .ok_or_else(|| "E_HANDOFF_EXECUTABLE: child current_exe must be UTF-8".to_owned())?;
        let suffix = format!(
        "/.fnd01-run/independent-attester/{run_id}/bootstrap-control-target/debug/fnd_01_evidence_fixture_driver"
    );
        let root = executable.strip_suffix(&suffix).ok_or_else(|| {
            "E_HANDOFF_EXECUTABLE: child executable does not match rigid Attest formula".to_owned()
        })?;
        if root.is_empty() || !Path::new(root).is_absolute() {
            return Err("E_HANDOFF_EXECUTABLE: child formula root is not absolute".to_owned());
        }
        let repository_root = PathBuf::from(root);
        let expected_executable = repository_root.join(suffix.trim_start_matches('/'));
        if current_executable != expected_executable {
            return Err("E_HANDOFF_EXECUTABLE: child formula reassembly differs".to_owned());
        }
        Ok(Some(OrdinaryAttestSelfReexecChild {
            repository_root,
            run_id,
        }))
    }

    #[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
    fn run_ordinary_attest_self_reexec_child(
        child: OrdinaryAttestSelfReexecChild,
        plant: OrdinaryPlant,
    ) -> Result<(), String> {
        let OrdinaryAttestSelfReexecChild {
            repository_root,
            run_id,
        } = child;
        let current_root = super::trust_std::ordinary_checked_current_repository_root()
            .map_err(|error| format!("E_HANDOFF_ARGUMENTS: child root: {error}"))?;
        if current_root != repository_root {
            return Err("E_HANDOFF_ARGUMENTS: child root differs from executable formula".to_owned());
        }
        let public_harness = repository_root.join(format!(
            ".fnd01-run/independent-attester/{run_id}/bootstrap-control-target/debug/fnd_01_evidence_harness"
        ));
        let run_id_bytes = super::trust_std::decode_lower_hex::<16>(&run_id, "fixture run ID")
            .map_err(|error| format!("E_HANDOFF_ARGUMENTS: {error}"))?;
        if run_id_bytes == [0; 16] {
            return Err("E_HANDOFF_ARGUMENTS: all-zero fixture run ID".to_owned());
        }
        let invocation = OrdinaryHandoffArguments {
            mode: BootstrapMode::Attest,
            executable_path: public_harness.clone(),
            repository_root: repository_root.clone(),
            run_root: repository_root.join(format!(
                ".fnd01-run/independent-attester/{run_id}"
            )),
            run_id: run_id.clone(),
            run_id_bytes,
            control_ledger_path: format!(
                ".fnd01-run/independent-attester/{run_id}/control-ledger.bin"
            ),
        };
        ordinary_fixture_write_new(
            &invocation.repository_root,
            &format!(
                ".fnd01-run/independent-attester/{}/self-reexec-child-ran",
                invocation.run_id,
            ),
            format!("child-ran={}\n", invocation.run_id).as_bytes(),
        )?;
        let environment = read_ordinary_handoff_environment(&invocation)
            .map_err(|error| format!("E_HANDOFF_ENVIRONMENT: child environment: {error}"))?;

        // The fixture driver alone seals the PID-bound ledger before same-PID exec replacement.
        let mut authority = require_ordinary_execution_authority(
            &invocation.repository_root,
            invocation.mode,
            &invocation.run_id,
            &environment,
        )
        .map_err(|error| error.to_string())?;
        let non_tool = derive_ordinary_non_tool_expectation(
            &mut authority,
            &invocation,
            &environment,
            &public_harness,
        )
        .map_err(|error| error.to_string())?;
        let fresh_inventory = super::phase_b_std::inventory_fresh_native_tools(
            &invocation.repository_root,
            invocation.mode,
            &invocation.run_id,
            &environment.closed_path,
        )
        .map_err(|error| format!("E_HANDOFF_TOOL_SET: fresh runtime inventory: {error}"))?;
        if fresh_inventory.native_tool_count() != ORDINARY_NATIVE_TOOL_COUNT
            || fresh_inventory.tool_set_sha256() == [0; 32]
            || fresh_inventory.execution_bin_sha256() == [0; 32]
        {
            return Err("E_HANDOFF_TOOL_SET: fresh runtime inventory is incomplete".to_owned());
        }
        let fresh_reprobe = OrdinaryToolReprobe {
            tool_set_sha256: fresh_inventory.tool_set_sha256(),
            execution_bin_sha256: fresh_inventory.execution_bin_sha256(),
            acquisition_tools: fresh_inventory.acquisition_tools().clone(),
            inventory: fresh_inventory,
        };
        let expectation = assemble_complete_ordinary_control_ledger_expectation(
            &authority,
            &non_tool,
            &fresh_reprobe,
            &invocation,
            &environment,
        );
        let expected_tool_set_sha256 = expectation.tool_set_sha256;
        let role = bootstrap_role_name(invocation.mode)
            .map_err(|error| format!("E_HANDOFF_MODE: child role: {error}"))?;
        let package_root = ordinary_role_absolute_path(
            &invocation.repository_root,
            role,
            &invocation.run_id,
            "bootstrap-control-package",
        )?;
        let target_root = ordinary_role_absolute_path(
            &invocation.repository_root,
            role,
            &invocation.run_id,
            "bootstrap-control-target",
        )?;
        let build_stdout = ordinary_sealed_control_build_stdout(
            &package_root,
            &target_root,
            &expectation.selected_executable.path,
        );
        let mut ledger_expectation = expectation.clone();
        if plant == OrdinaryPlant::ToolSet {
            ledger_expectation.tool_set_sha256[0] ^= 0x80;
        }
        let observed_tool_set_sha256 = ledger_expectation.tool_set_sha256;
        let ledger_bytes = ordinary_sealed_encode_control_ledger_bytes(
            &ledger_expectation,
            build_stdout.as_bytes(),
        )?;
        ordinary_fixture_write_new(
            &invocation.repository_root,
            &invocation.control_ledger_path,
            &ledger_bytes,
        )?;
        drop(fresh_reprobe);
        drop(non_tool);
        drop(authority);
        let binding_digests = if plant == OrdinaryPlant::SourceBinding {
            let path = invocation.repository_root.join(ORDINARY_CORE_SOURCE);
            let mut bytes = fs::read(&path).map_err(|error| error.to_string())?;
            let expected = trust_sha256(&bytes).map_err(|error| error.to_string())?;
            let first = bytes.first_mut()
                .ok_or_else(|| "E_SHA256_MISMATCH: empty source plant".to_owned())?;
            *first ^= 1;
            fs::write(&path, &bytes).map_err(|error| error.to_string())?;
            let observed = trust_sha256(&bytes).map_err(|error| error.to_string())?;
            Some((expected, observed))
        } else if plant == OrdinaryPlant::ToolSet {
            Some((expected_tool_set_sha256, observed_tool_set_sha256))
        } else {
            None
        };
        if let Some((expected, observed)) = binding_digests {
            let state = ordinary_fixture_tree_state(&invocation.repository_root)?;
            let state_sha256 = trust_sha256(format!("{state:?}").as_bytes())
                .map_err(|error| format!("E_HANDOFF_LEDGER: baseline state digest: {error}"))?;
            let mut stdout = io::stdout().lock();
            writeln!(
                stdout,
                "FND01NEGSTATEv1|{}|{}|{}",
                encode_lower_hex(&state_sha256),
                encode_lower_hex(&expected),
                encode_lower_hex(&observed),
            )
            .and_then(|()| stdout.flush())
            .map_err(|error| format!("E_HANDOFF_LEDGER: baseline state output: {error}"))?;
        }
        use std::os::unix::process::CommandExt;
        let error = Command::new(&public_harness)
            .arg("attest")
            .arg(".")
            .arg(&run_id)
            .arg(&invocation.control_ledger_path)
            .exec();
        Err(format!(
            "E_HANDOFF_EXECUTABLE: same-PID public harness exec failed: {error}"
        ))
    }

    #[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
    fn spawn_ordinary_attest_self_reexec(
        subject: &OrdinaryAttestSelfReexecSubject,
        test_id: &str,
        plant: OrdinaryPlant,
    ) {
        let output = Command::new(&subject.fixture_driver)
            .args(["--exact", test_id, "--nocapture"])
            .env_clear()
            .env("FASTMCP_FND01_AUTHORING_CLOSURE", &subject.authoring_marker)
            .env(
                "FASTMCP_FND01_INTEGRATION_SEAL",
                &subject.integration_marker,
            )
            .env(
                "FASTMCP_FND01_PRODUCER_OUTER_RECORD_PATH",
                format!(
                    ".fnd01-run/controller/{}/producer-outer.bin",
                    subject.run_id
                ),
            )
            .env("FASTMCP_FND01_RUN_ID", &subject.run_id)
            .env("LANG", "C")
            .env("LC_ALL", "C")
            .env("PATH", &subject.closed_path)
            .env("TZ", "UTC")
            .current_dir(&subject.root)
            .output()
            .unwrap_or_else(|error| panic!("Attest self-reexec spawn: {error}"));
        let stdout = String::from_utf8(output.stdout).expect("public harness stdout UTF-8");
        let stderr = String::from_utf8(output.stderr).expect("public harness stderr UTF-8");
        let stdout = stdout
            .strip_prefix("\nrunning 1 test\n")
            .expect("exact fixture-driver stdout prelude");
        let child_ran = subject.root.join(format!(
            ".fnd01-run/independent-attester/{}/self-reexec-child-ran", subject.run_id));
        assert_eq!(
            fs::read(&child_ran)
                .unwrap_or_else(|error| panic!("Attest self-reexec child marker: {error}")),
            format!("child-ran={}\n", subject.run_id).as_bytes(),
            "Attest self-reexec exact child body did not run",
        );
        if plant == OrdinaryPlant::None {
            assert_eq!(output.status.code(), Some(0));
            assert!(stdout.is_empty() && stderr.is_empty());
        } else {
            let stderr = stderr
                .strip_suffix('\n')
                .expect("public harness failure-frame terminal LF");
            assert!(!stderr.contains('\n'), "one public harness failure frame");
            assert_eq!(output.status.code(), Some(3));
            let fields = stdout
                .strip_suffix('\n')
                .expect("negative state receipt terminal LF")
                .split('|')
                .collect::<Vec<_>>();
            assert_eq!(fields.len(), 4, "negative state receipt field count");
            assert_eq!(fields[0], "FND01NEGSTATEv1");
            for field in &fields[1..] {
                assert_eq!(field.len(), 64, "negative receipt digest width");
                assert!(field.bytes().all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase()));
            }
            assert_ne!(fields[2], fields[3], "planted binding digest must differ");
            let state = ordinary_fixture_tree_state(&subject.root).expect("public rejection fixture-state recheck");
            let state_sha256 = trust_sha256(format!("{state:?}").as_bytes())
                .expect("public rejection fixture-state digest");
            assert_eq!(encode_lower_hex(&state_sha256), fields[1],
                "public rejection leaves complete fixture state unchanged");
            if plant == OrdinaryPlant::ToolSet {
                assert_eq!(stderr, format!(
                    "FND01ENTRYv1|ledger|attest|E_HANDOFF_LEDGER|role=attest @ run_id={} @ expected=complete ControlLedgerExpectation @ observed=complete validator failed (E_CONTROL_AUTHORITY\\x7Ctool_set_sha256 expected={} observed={})",
                    subject.run_id, fields[2], fields[3]));
            } else {
                assert_eq!(stderr, format!(
                    "FND01ENTRYv1|evidence|attest|E_ORDINARY_EVIDENCE|role=attest @ run_id={} @ expected=accepted evidence report @ observed=FND01\\x7CError\\x7CE_SHA256_MISMATCH\\x7C{}\\x7C",
                    subject.run_id, ORDINARY_CORE_SOURCE));
                let path = subject.root.join(ORDINARY_CORE_SOURCE);
                let pristine = fs::read(repository_root().join(ORDINARY_CORE_SOURCE)).expect("pristine source");
                assert_eq!(fs::metadata(&path).expect("planted source").len(),
                    u64::try_from(pristine.len()).expect("source length"));
                fs::write(&path, pristine).expect("restore source");
                let report = run_verifier_at(&subject.root).expect("restored source accepted");
                assert!(!report.has_errors());
            }
        }
    }

    #[cfg(all(test, target_os = "linux", target_arch = "x86_64"))]
    fn assert_ordinary_attest_self_reexec(test_id: &str, plant: OrdinaryPlant) {
        match ordinary_attest_self_reexec_child() {
            Ok(Some(child)) => {
                run_ordinary_attest_self_reexec_child(child, plant)
                    .unwrap_or_else(|error| panic!("Attest self-reexec child: {error}"));
            }
            Ok(None) => {
                let subject = ordinary_attest_self_reexec_subject()
                    .unwrap_or_else(|error| panic!("Attest self-reexec subject: {error}"));
                spawn_ordinary_attest_self_reexec(&subject, test_id, plant);
            }
            Err(error) => panic!("Attest self-reexec child admission: {error}"),
        }
    }

    #[cfg(not(all(test, target_os = "linux", target_arch = "x86_64")))]
    fn assert_ordinary_attest_self_reexec(_test_id: &str, _plant: OrdinaryPlant) {
        panic!("ordinary Attest self-reexec fixture requires Linux x86_64");
    }

    fn ordinary_utf8_path(path: &Path, subject: &str) -> Result<String, String> {
        path.to_str()
            .map(str::to_owned)
            .ok_or_else(|| format!("{subject} must be UTF-8"))
    }

    fn ordinary_checked_file_binding(
        repository_root: &Path,
        relative: &str,
        maximum: u64,
        expected: Option<FileBinding>,
        subject: &str,
    ) -> Result<(CheckedSnapshot, ValidatedFileBinding), String> {
        let snapshot = checked_snapshot(repository_root, relative, maximum, expected)
            .map_err(|error| format!("{subject}: {}", error.detail()))?;
        if snapshot.byte_length == 0 {
            return Err(format!("{subject} must be nonempty"));
        }
        let path = ordinary_utf8_path(&repository_root.join(relative), subject)?;
        let binding = ValidatedFileBinding {
            path,
            binding: FileBinding {
                byte_length: snapshot.byte_length,
                sha256: snapshot.sha256,
            },
        };
        Ok((snapshot, binding))
    }

    struct OrdinaryControlBuildEnvironmentAuthority {
        cargo_home: String,
        target: String,
        execution_bin: String,
    }

    fn derive_ordinary_control_build_environment(
        invocation: &OrdinaryHandoffArguments,
    ) -> Result<OrdinaryControlBuildEnvironmentAuthority, String> {
        let cargo_home = ordinary_utf8_path(
            &invocation.run_root.join("cargo-home/offline"),
            "ordinary control CARGO_HOME",
        )?;
        let target = ordinary_utf8_path(
            &invocation.run_root.join("bootstrap-control-target"),
            "ordinary control target",
        )?;
        let execution_bin = ordinary_utf8_path(
            &invocation.run_root.join("execution-bin"),
            "ordinary execution-bin",
        )?;
        Ok(OrdinaryControlBuildEnvironmentAuthority {
            cargo_home,
            target,
            execution_bin,
        })
    }

    fn complete_ordinary_control_build_environment(
        authority: &OrdinaryControlBuildEnvironmentAuthority,
        tools: &AcquisitionToolPaths,
    ) -> Vec<(String, String)> {
        vec![
            ("AR".to_owned(), tools.host_ar.clone()),
            ("CARGO_HOME".to_owned(), authority.cargo_home.clone()),
            ("CARGO_NET_OFFLINE".to_owned(), "true".to_owned()),
            ("CARGO_TARGET_DIR".to_owned(), authority.target.clone()),
            ("CC".to_owned(), tools.host_cc.clone()),
            ("CLIPPY_DRIVER".to_owned(), tools.clippy_driver.clone()),
            ("LANG".to_owned(), "C".to_owned()),
            ("LC_ALL".to_owned(), "C".to_owned()),
            ("PATH".to_owned(), authority.execution_bin.clone()),
            ("RANLIB".to_owned(), tools.host_ranlib.clone()),
            ("RUSTC".to_owned(), tools.rustc.clone()),
            ("RUSTDOC".to_owned(), tools.rustdoc.clone()),
            ("RUSTFMT".to_owned(), tools.rustfmt.clone()),
            (
                "RUSTUP_TOOLCHAIN".to_owned(),
                "nightly-2026-07-11".to_owned(),
            ),
            ("SOURCE_DATE_EPOCH".to_owned(), "0".to_owned()),
            ("TZ".to_owned(), "UTC".to_owned()),
        ]
    }

    fn derive_ordinary_non_tool_expectation(
        authority: &mut OrdinaryPreLedgerAuthority,
        invocation: &OrdinaryHandoffArguments,
        environment: &BootstrapEnvironment,
        current_executable: &Path,
    ) -> Result<OrdinaryNonToolExpectation, OrdinaryEntryFailure> {
        if authority.repository_root != invocation.repository_root
            || authority.mode != invocation.mode
            || authority.control.run_id != invocation.run_id
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreLedgerAuthority,
                "pre-ledger authority identity drift",
            ));
        }
        let role = authority.control.role;
        let package_root = format!(
            ".fnd01-run/{role}/{}/bootstrap-control-package",
            invocation.run_id
        );
        let scratch_paths = [
            format!("{package_root}/Cargo.toml"),
            format!("{package_root}/Cargo.lock"),
            format!("{package_root}/cargo-config.toml"),
            format!("{package_root}/src/main.rs"),
            format!("{package_root}/tests/fnd_01_dependency_evidence.rs"),
        ];
        let scratch_bindings = scratch_paths
            .iter()
            .zip(CONTROL_SCRATCH_MAXIMA)
            .enumerate()
            .map(|(ordinal, (relative, maximum))| {
                ordinary_checked_file_binding(
                    &invocation.repository_root,
                    relative,
                    maximum,
                    None,
                    &format!("ordinary scratch binding {ordinal}"),
                )
                .map(|(_, binding)| binding)
            })
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreLedgerAuthority,
                error,
            ))?
            .try_into()
            .map_err(|values: Vec<ValidatedFileBinding>| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::PreLedgerAuthority,
                    format!("expected five scratch bindings, observed {}", values.len()),
                )
            })?;

        let selected_relative = format!(
            ".fnd01-run/{role}/{}/bootstrap-control-target/debug/fnd_01_evidence_harness",
            invocation.run_id
        );
        let selected_path = invocation.repository_root.join(&selected_relative);
        if selected_path != invocation.executable_path || selected_path != current_executable {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreflightExecutable,
                "argv[0]/current executable differs from the exact role/run target formula",
            ));
        }
        let (selected_snapshot, selected_executable) = ordinary_checked_file_binding(
            &invocation.repository_root,
            &selected_relative,
            MAX_GATE_EXECUTABLE_BYTES,
            None,
            "ordinary selected executable",
        )
        .map_err(|error| OrdinaryEntryFailure::from_site(
            OrdinaryFailureSite::PreflightExecutable,
            error,
        ))?;
        if selected_snapshot.identity.file_type != 0o100_000
            || selected_snapshot.identity.link_count != 1
            || selected_snapshot.identity.mode & 0o100 == 0
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreflightExecutable,
                "selected executable must be regular, nlink-one, and owner-executable",
            ));
        }
        let control_build_environment = derive_ordinary_control_build_environment(invocation)
            .map_err(|error| OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreLedgerAuthority,
                error,
            ))?;
        let handoff_argv = expected_ordinary_handoff_argv(
            invocation.mode,
            &selected_executable.path,
            &invocation.run_id,
        )
        .map_err(|error| OrdinaryEntryFailure::from_site(
            OrdinaryFailureSite::PreLedgerAuthority,
            format!("exact handoff argv: {error}"),
        ))?;
        if handoff_argv.len() != ORDINARY_HANDOFF_ARGV_ARITY
            || handoff_argv.first().map(String::as_str) != Some(selected_executable.path.as_str())
            || handoff_argv.get(4).map(String::as_str)
                != Some(invocation.control_ledger_path.as_str())
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreLedgerAuthority,
                "independently derived handoff argv differs from the live invocation",
            ));
        }
        let handoff_environment =
            expected_ordinary_handoff_environment(invocation.mode, &invocation.run_id, environment)
                .map_err(|error| OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::PreLedgerAuthority,
                    format!("exact handoff environment: {error}"),
                ))?;

        let supply_relative =
            expected_ordinary_supply_relative_path(invocation.mode, &invocation.run_id).map_err(
                |error| OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::PreLedgerAuthority,
                    format!("exact supply path: {error}"),
                ),
            )?;
        let (supply_snapshot, supply_bytes) = match invocation.mode {
            BootstrapMode::Produce => checked_read(
                &invocation.repository_root,
                &supply_relative,
                MAX_SUPPLY_BUNDLE_BYTES,
                None,
            )
            .map_err(|error| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::PreLedgerAuthority,
                    format!("producer supply binding: {error}"),
                )
            })?,
            BootstrapMode::Attest => {
                let integration = authority.integration.as_mut().ok_or_else(|| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        "Attest retained seal authority is missing",
                    )
                })?;
                let retained_bytes = integration.retained.consume().map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        format!("retained integration set consumption failed ({error})"),
                    )
                })?;
                let expected_bindings = [
                    integration.seal.records[0],
                    integration.seal.records[1],
                    integration.seal.records[2],
                    integration.seal.records[3],
                    integration.seal.records[4],
                    integration.seal.outer_transport,
                ];
                for (ordinal, (bytes, binding)) in
                    retained_bytes.iter().zip(expected_bindings).enumerate()
                {
                    if u64::try_from(bytes.len()).unwrap_or(u64::MAX) != binding.byte_length
                        || sha256(bytes) != binding.sha256
                    {
                        return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                            OrdinaryFailureSite::PreLedgerAuthority,
                            format!("retained integration member {ordinal} binding drift"),
                        ));
                    }
                }
                let [_, _, supply_bytes, _, _, outer_bytes] = retained_bytes;
                let outer = parse_outer_transport_record(
                    &outer_bytes,
                    "ordinary retained producer outer record",
                )
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        format!("producer outer-record parse failed ({error})"),
                    )
                })?;
                validate_outer_role_record(
                    &outer,
                    BootstrapMode::Produce,
                    &invocation.run_id,
                    &environment.authoring_marker,
                    None,
                )
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        format!("producer outer-record semantics failed ({error})"),
                    )
                })?;
                integration
                    .retained
                    .revalidate_after_consumption()
                    .map_err(|error| {
                        OrdinaryEntryFailure::from_site(
                            OrdinaryFailureSite::PreLedgerAuthority,
                            format!("retained integration set changed ({error})"),
                        )
                    })?;
                let snapshot = checked_snapshot(
                    &invocation.repository_root,
                    &supply_relative,
                    MAX_SUPPLY_BUNDLE_BYTES,
                    Some(integration.seal.records[2]),
                )
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        format!("attested supply path rebind failed ({error})"),
                    )
                })?;
                (snapshot, supply_bytes)
            }
            BootstrapMode::Gate => {
                unreachable!("ordinary argv parsing rejects Gate before non-tool derivation")
            }
        };
        if supply_snapshot.byte_length == 0 || supply_bytes.is_empty() {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreLedgerAuthority,
                "independently bound supply is empty",
            ));
        }
        let supply_bundle = ValidatedFileBinding {
            path: ordinary_utf8_path(
                &invocation.repository_root.join(&supply_relative),
                "ordinary supply path",
            )
            .map_err(|error| OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreLedgerAuthority,
                error,
            ))?,
            binding: FileBinding {
                byte_length: supply_snapshot.byte_length,
                sha256: supply_snapshot.sha256,
            },
        };

        let (local_registry, target_snapshot): (
            ValidatedDirectoryTreeBinding,
            ValidatedTargetSnapshot,
        ) = {
            #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
            {
                super::phase_b_std::observe_ordinary_control_trees(
                &invocation.repository_root,
                invocation.mode,
                &invocation.run_id,
                &supply_bytes,
            )
            .map_err(|error| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::PreLedgerAuthority,
                    format!("independent control-tree observation failed ({error})"),
                )
            })?
            }
            #[cfg(not(all(target_os = "linux", target_arch = "x86_64")))]
            {
                unreachable!("ordinary entry rejects an unqualified platform before control-tree observation")
            }
        };

        let (spool_relative, spool_snapshot, acquisition_spool_binding) = match invocation.mode {
            BootstrapMode::Produce => {
                let relative = format!(
                    ".fnd01-run/integration-producer/{}/acquisition-spool.bin",
                    invocation.run_id
                );
                let snapshot = checked_snapshot(
                    &invocation.repository_root,
                    &relative,
                    MAX_ACQUISITION_SPOOL_BYTES,
                    None,
                )
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        format!("producer acquisition-spool binding failed ({error})"),
                    )
                })?;
                if snapshot.byte_length == 0 {
                    return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        "producer acquisition spool is empty",
                    ));
                }
                let binding = FileBinding {
                    byte_length: snapshot.byte_length,
                    sha256: snapshot.sha256,
                };
                (Some(relative), Some(snapshot), Some(binding))
            }
            BootstrapMode::Attest => (None, None, None),
            BootstrapMode::Gate => unreachable!("Gate rejected before non-tool derivation"),
        };

        Ok(OrdinaryNonToolExpectation {
            scratch_bindings,
            local_registry,
            supply_bundle,
            supply_relative,
            supply_snapshot,
            supply_bytes,
            target_snapshot,
            selected_executable,
            selected_snapshot,
            control_build_environment,
            handoff_argv,
            handoff_environment,
            spool_relative,
            spool_snapshot,
            acquisition_spool_binding,
        })
    }

    fn assemble_complete_ordinary_control_ledger_expectation(
        authority: &OrdinaryPreLedgerAuthority,
        non_tool: &OrdinaryNonToolExpectation,
        tool_reprobe: &OrdinaryToolReprobe,
        invocation: &OrdinaryHandoffArguments,
        environment: &BootstrapEnvironment,
    ) -> ControlLedgerExpectation {
        let integration_seal_sha256 = authority
            .integration
            .as_ref()
            .map_or([0; 32], |integration| integration.seal.seal_sha256);
        let build_environment = complete_ordinary_control_build_environment(
            &non_tool.control_build_environment,
            &tool_reprobe.acquisition_tools,
        );
        ControlLedgerExpectation {
            mode: invocation.mode,
            repository_root: invocation.repository_root.clone(),
            run_id: invocation.run_id.clone(),
            process_id: authority.control.process_id,
            authoring_closure_sha256: authority.marker.closure_sha256,
            integration_seal_sha256,
            scratch_bindings: non_tool.scratch_bindings.clone(),
            local_registry: non_tool.local_registry.clone(),
            supply_bundle: non_tool.supply_bundle.clone(),
            tool_set_sha256: tool_reprobe.tool_set_sha256,
            environment_set_sha256: authority.control.environment_set_sha256,
            cargo_executable: tool_reprobe.acquisition_tools.cargo.clone(),
            build_environment,
            target_snapshot: non_tool.target_snapshot.clone(),
            selected_executable: non_tool.selected_executable.clone(),
            bootstrap_environment: environment.clone(),
            acquisition_spool_binding: non_tool.acquisition_spool_binding,
        }
    }

    fn validate_probed_ordinary_ledger(
        mut probed: OrdinaryProbedAuthority,
        invocation: &OrdinaryHandoffArguments,
        environment: &BootstrapEnvironment,
    ) -> Result<OrdinaryArchivePermit, OrdinaryEntryFailure> {
        let ledger_binding = FileBinding {
            byte_length: probed.ledger_snapshot.byte_length,
            sha256: probed.ledger_snapshot.sha256,
        };
        let ledger_recheck = checked_snapshot(
            &invocation.repository_root,
            &invocation.control_ledger_path,
            MAX_CONTROL_LEDGER_BYTES,
            Some(ledger_binding),
        )
        .map_err(|error| OrdinaryEntryFailure::from_site(
            OrdinaryFailureSite::LedgerDirectRecheck,
            format!("opaque post-probe binding failed ({error})"),
        ))?;
        if ledger_recheck != probed.ledger_snapshot {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRecheck,
                "opaque ledger identity changed during the tool reprobe",
            ));
        }

        let expectation = assemble_complete_ordinary_control_ledger_expectation(
            &probed.authority,
            &probed.non_tool,
            &probed.tool_reprobe,
            invocation,
            environment,
        );
        let ledger = validate_control_ledger_bytes(&probed.ledger_bytes, &expectation).map_err(
            |error| OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerJoin,
                format!("complete validator failed ({error})"),
            ),
        )?;
        if ledger.handoff_argv != probed.non_tool.handoff_argv
            || ledger.handoff_environment != probed.non_tool.handoff_environment
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerJoin,
                "validated handoff argv/environment differ from independent pre-probe authority",
            ));
        }
        rebind_control_ledger_regular_files(&invocation.repository_root, &ledger).map_err(
            |error| OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerRebind,
                format!("regular-file rebind failed ({error})"),
            ),
        )?;
        let (registry_recheck, target_recheck): (
            ValidatedDirectoryTreeBinding,
            ValidatedTargetSnapshot,
        ) = {
            #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
            {
                super::phase_b_std::observe_ordinary_control_trees(
                    &invocation.repository_root,
                    invocation.mode,
                    &invocation.run_id,
                    &probed.non_tool.supply_bytes,
                )
                .map_err(|error| OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerRebind,
                    format!("control-tree reobservation failed ({error})"),
                ))?
            }
            #[cfg(not(all(target_os = "linux", target_arch = "x86_64")))]
            {
                unreachable!("ordinary entry rejects an unqualified platform before ledger rebind")
            }
        };
        if registry_recheck != ledger.local_registry || target_recheck != ledger.target_snapshot {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerRebind,
                "local-registry or target tree changed after ledger validation",
            ));
        }
        if let Some(integration) = probed.authority.integration.as_mut() {
            integration
                .retained
                .revalidate_after_consumption()
                .map_err(|error| OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerRebind,
                    format!(
                        "retained integration authority changed ({error})"
                    ),
                ))?;
        }
        Ok(OrdinaryArchivePermit {
            expectation,
            ledger_snapshot: probed.ledger_snapshot,
            ledger_bytes: probed.ledger_bytes,
            ledger,
            non_tool: probed.non_tool,
            tool_reprobe: probed.tool_reprobe,
            integration: probed.authority.integration,
        })
    }

    fn require_ordinary_execution_authority(
        repository_root: &Path,
        mode: BootstrapMode,
        run_id: &str,
        environment: &BootstrapEnvironment,
    ) -> Result<OrdinaryPreLedgerAuthority, OrdinaryEntryFailure> {
        let marker = match super::trust_std::parse_authoring_marker(&environment.authoring_marker) {
            Ok(marker) => marker,
            Err(error) => {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::PreLedgerAuthority,
                    format!(
                        "external authoring/seal authority and the complete ControlLedgerExpectation join are not yet frozen; no ordinary child may execute ({error})"
                    ),
                ));
            }
        };
        let limits = [
            super::trust_std::MAX_POLICY_BYTES,
            super::trust_std::MAX_VERIFIER_BYTES,
            super::trust_std::MAX_HARNESS_BYTES,
        ];
        let expected = [marker.policy, marker.verifier, marker.harness];
        for ((path, limit), binding) in super::trust_std::AUTHORING_PATHS
            .iter()
            .copied()
            .zip(limits)
            .zip(expected)
        {
            super::trust_std::checked_snapshot(repository_root, path, limit, Some(binding))
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        format!("authoring path rebind failed for {path}: {error}"),
                    )
                })?;
        }

        let _toolchain_bin = ordinary_closed_path_toolchain_authority(&environment.closed_path)?;

        let pure_tools = ordinary_reprobe_dual_path_pure_authority()?;
        debug_assert_eq!(pure_tools.native_tool_count, ORDINARY_NATIVE_TOOL_COUNT);

        let environment_set_sha256 = ordinary_environment_set_digest();
        if environment_set_sha256 == [0; 32] {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreLedgerAuthority,
                "compiled ordinary environment-set digest is zero",
            ));
        }

        let control = ordinary_control_ledger_expectation_authority(mode, run_id, environment_set_sha256)
            .map_err(|error| {
                OrdinaryEntryFailure::from_site(OrdinaryFailureSite::PreLedgerAuthority, error)
            })?;
        debug_assert_eq!(control.native_tool_count, ORDINARY_NATIVE_TOOL_COUNT);
        debug_assert_eq!(control.handoff_argv_arity, ORDINARY_HANDOFF_ARGV_ARITY);
        debug_assert_eq!(control.environment_set_sha256, environment_set_sha256);

        let integration = match mode {
            BootstrapMode::Produce => {
                if environment.integration_seal.is_some()
                    || environment.producer_outer_record_path.is_some()
                {
                    return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        "Produce received Attest-only seal authority",
                    ));
                }
                None
            }
            BootstrapMode::Attest => {
                let seal_text = environment.integration_seal.as_deref().ok_or_else(|| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        "Attest integration seal is missing",
                    )
                })?;
                let seal =
                    parse_integration_seal(seal_text, &marker.closure_sha256).map_err(|error| {
                        OrdinaryEntryFailure::from_site(
                            OrdinaryFailureSite::PreLedgerAuthority,
                            format!("Attest integration seal authority failed ({error})"),
                        )
                    })?;
                let expected_run_id =
                    super::trust_std::decode_lower_hex::<16>(run_id, "ordinary Attest run ID")
                        .map_err(|error| {
                            OrdinaryEntryFailure::from_site(
                                OrdinaryFailureSite::PreLedgerAuthority,
                                format!("Attest run ID authority failed ({error})"),
                            )
                        })?;
                if seal.run_id != expected_run_id {
                    return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        "integration seal run ID differs from the ordinary handoff",
                    ));
                }
                let expected_outer = format!(".fnd01-run/controller/{run_id}/producer-outer.bin");
                let outer_path = environment
                .producer_outer_record_path
                .as_deref()
                .filter(|path| *path == expected_outer)
                .ok_or_else(|| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::PreLedgerAuthority,
                        "producer outer-record path differs from the exact role/run formula",
                    )
                })?;
                let retained =
                    retain_integration_and_outer_files(repository_root, &seal, outer_path)
                        .map_err(|error| {
                            OrdinaryEntryFailure::from_site(
                                OrdinaryFailureSite::PreLedgerAuthority,
                                format!("integration seal file rebind failed ({error})"),
                            )
                        })?;
                Some(OrdinaryAttestAuthority { seal, retained })
            }
            BootstrapMode::Gate => {
                unreachable!("ordinary argv parsing rejects Gate before authority")
            }
        };

        Ok(OrdinaryPreLedgerAuthority {
            marker,
            integration,
            repository_root: repository_root.to_path_buf(),
            mode,
            control,
            closed_path: environment.closed_path.clone(),
        })
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum OrdinaryProductStage {
        Authority,
        Reprobe,
        Ledger,
        Archive,
        Bookend,
        Evidence,
    }

    impl OrdinaryProductStage {
        const fn as_str(self) -> &'static str {
            match self {
                Self::Authority => "authority",
                Self::Reprobe => "reprobe",
                Self::Ledger => "ledger",
                Self::Archive => "archive",
                Self::Bookend => "bookend",
                Self::Evidence => "evidence",
            }
        }
    }

    macro_rules! ordinary_failure_routes {
    ($( $(#[$route_cfg:meta])* $route:ident => ($id:literal, $code:literal, $stage:ident, $expected:literal) ),+ $(,)?) => {
        #[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
        enum OrdinaryFailureRoute { $( $(#[$route_cfg])* $route ),+ }
        impl OrdinaryFailureRoute {
            #[cfg(test)]
            const ALL: &'static [Self] = &[$($(#[$route_cfg])* Self::$route),+];
            const fn id(self) -> &'static str {
                match self { $($(#[$route_cfg])* Self::$route => $id),+ }
            }
            const fn code(self) -> &'static str {
                match self { $($(#[$route_cfg])* Self::$route => $code),+ }
            }
            const fn stage(self) -> OrdinaryProductStage {
                match self { $($(#[$route_cfg])* Self::$route => OrdinaryProductStage::$stage),+ }
            }
            const fn expected(self) -> &'static str {
                match self { $($(#[$route_cfg])* Self::$route => $expected),+ }
            }
        }
    };
}

