    #[derive(Debug)]
    struct OrdinaryEntryFailure {
        site: OrdinaryFailureSite,
        observed: String,
    }

    impl OrdinaryEntryFailure {
        fn from_site(site: OrdinaryFailureSite, observed: impl std::fmt::Display) -> Self {
            let observed = observed.to_string();
            Self { site, observed }
        }

        const fn route(&self) -> OrdinaryFailureRoute {
            self.site.route()
        }

        const fn code(&self) -> &'static str {
            self.route().code()
        }

        const fn expected(&self) -> &'static str {
            self.route().expected()
        }
    }

    impl std::fmt::Display for OrdinaryEntryFailure {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(formatter, "{}: {}", self.code(), self.observed)
        }
    }

    #[cfg(test)]
    struct OrdinaryRouteFixture {
        route: OrdinaryFailureRoute,
        observed: String,
    }

    #[cfg(test)]
    impl OrdinaryRouteFixture {
        fn new(route: OrdinaryFailureRoute, observed: impl Into<String>) -> Self {
            Self {
                route,
                observed: observed.into(),
            }
        }

        fn frame(&self, mode: &str, run_id: &str) -> OrdinaryEntryFailureFrame {
            OrdinaryEntryFailureFrame {
                stage: self.route.stage().as_str(),
                parts: ordinary_entry_failure_fields(
                    mode,
                    run_id,
                    self.route.expected(),
                    &self.observed,
                ),
            }
        }
    }

