    #[allow(dead_code)] // Invoked by the path-including ordinary handoff example.
    fn run_ordinary_handoff_entry(arguments: Vec<std::ffi::OsString>) -> i32 {
        let mode = match arguments.get(1).and_then(|value| value.to_str()) {
            Some("produce") => "produce",
            Some("attest") => "attest",
            _ => "unknown",
        };
        let known_run_id = ordinary_known_handoff_run_id(&arguments);
        let invocation = match parse_ordinary_handoff_arguments(arguments) {
            Ok(invocation) => invocation,
            Err(error) => {
                emit_ordinary_entry_failure_route(
                    mode,
                    known_run_id.as_deref().unwrap_or("unavailable"),
                    OrdinaryEntryFailure::from_handoff_argument_failure(error),
                );
                return 3;
            }
        };
        let environment = match read_ordinary_handoff_environment(&invocation) {
            Ok(environment) => environment,
            Err(error) => {
                emit_ordinary_entry_failure_route(
                    mode,
                    &invocation.run_id,
                    OrdinaryEntryFailure::from_handoff_environment_failure(error),
                );
                return 3;
            }
        };
        match validate_ordinary_handoff_entry(&invocation, &environment) {
            Ok(()) => 0,
            Err(error) => {
                emit_ordinary_entry_failure_route(mode, &invocation.run_id, error);
                3
            }
        }
    }

    fn validate_ordinary_handoff_entry(
        invocation: &OrdinaryHandoffArguments,
        environment: &BootstrapEnvironment,
    ) -> Result<(), OrdinaryEntryFailure> {
        validate_ordinary_handoff_entry_with_effects(
            invocation,
            environment,
            ordinary_platform_is_qualified(),
            &mut (),
        )
    }

    fn validate_ordinary_handoff_entry_with_effects(
        invocation: &OrdinaryHandoffArguments,
        environment: &BootstrapEnvironment,
        platform_qualified: bool,
        effects: &mut impl OrdinaryEntryEffects,
    ) -> Result<(), OrdinaryEntryFailure> {
        use std::io::Read;

        if environment.authoring_marker.is_empty() {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreflightAuthoring,
                "empty authoring marker",
            ));
        }
        let current_executable = std::env::current_exe().map_err(|error| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreflightExecutable,
                format!("current_exe: {error}"),
            )
        })?;
        if current_executable != invocation.executable_path {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreflightExecutable,
                "current executable differs from argv[0]",
            ));
        }
        if !platform_qualified {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::HandoffRepositoryPlatform,
                "ordinary handoff requires Linux x86_64",
            ));
        }
        let qualified_platform = OrdinaryQualifiedPlatform;
        // Independent authoring, closed-PATH, and field joins precede every artifact open.
        let mut authority = require_ordinary_execution_authority(
            &invocation.repository_root,
            invocation.mode,
            &invocation.run_id,
            environment,
        )?;
        // Join the expectation to live argv before the untrusted ledger opens.
        let expected_role = match invocation.mode {
            BootstrapMode::Produce => "integration-producer",
            BootstrapMode::Attest => "independent-attester",
            BootstrapMode::Gate => unreachable!("ordinary argv parsing rejects Gate before entry"),
        };
        if authority.mode != invocation.mode
            || authority.control.role != expected_role
            || authority.control.run_id != invocation.run_id
            || authority.control.control_ledger_relative != invocation.control_ledger_path
            || authority.closed_path != environment.closed_path
            || authority.control.native_tool_count != ORDINARY_NATIVE_TOOL_COUNT
            || authority.control.handoff_argv_arity != ORDINARY_HANDOFF_ARGV_ARITY
            || authority.control.environment_set_sha256 == [0; 32]
            || authority.control.process_id != u64::from(std::process::id())
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::PreLedgerAuthority,
                "pre-ledger authority desync from live handoff identity",
            ));
        }
        // Retain non-tool expectations first; ledger bytes stay opaque until permit use.
        let non_tool = derive_ordinary_non_tool_expectation(
            &mut authority,
            invocation,
            environment,
            &current_executable,
        )?;
        effects.before_ledger_open();
        let (opaque_ledger_snapshot, opaque_ledger_bytes) = checked_read(
            &invocation.repository_root,
            &invocation.control_ledger_path,
            MAX_CONTROL_LEDGER_BYTES,
            None,
        )
        .map_err(|error| OrdinaryEntryFailure::from_site(
            OrdinaryFailureSite::OpaqueLedger,
            format!("opaque checked-read failed ({error})"),
        ))?;
        if opaque_ledger_snapshot.byte_length == 0 || opaque_ledger_bytes.is_empty() {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::OpaqueLedger,
                "opaque control ledger is empty",
            ));
        }
        let probed = OrdinaryProbePermit {
            authority,
            non_tool,
            ledger_snapshot: opaque_ledger_snapshot,
            ledger_bytes: opaque_ledger_bytes,
            qualified_platform,
        }
        .consume()?;
        let archive_permit = validate_probed_ordinary_ledger(probed, invocation, environment)?;
        let OrdinaryArchivePermit {
            expectation,
            ledger_snapshot,
            ledger_bytes: admitted_ledger_bytes,
            ledger: validated_ledger,
            non_tool,
            tool_reprobe,
            mut integration,
        } = archive_permit;

        // The retained reread must exactly match the admitted opaque ledger.
        let ledger_path = invocation
            .repository_root
            .join(&invocation.control_ledger_path);
        let metadata = std::fs::symlink_metadata(&ledger_path).map_err(|error| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                format!(
                    "missing control ledger {}: {error}",
                    invocation.control_ledger_path
                ),
            )
        })?;
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                "control ledger must be a regular non-symlink file",
            ));
        }
        let declared_len = metadata.len();
        if declared_len == 0 || declared_len > MAX_CONTROL_LEDGER_BYTES {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                format!("control ledger length {declared_len} outside (0, max_control_ledger_bytes]"),
            ));
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            if metadata.nlink() != 1 {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerDirectRead,
                    "control ledger must have nlink=1",
                ));
            }
        }
        let mut file = std::fs::File::open(&ledger_path).map_err(|error| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                format!("open: {error}"),
            )
        })?;
        // Identity recheck after open before any allocation/consumption.
        let open_meta = file
            .metadata()
            .map_err(|error| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerDirectRead,
                    format!("open metadata: {error}"),
                )
            })?;
        if open_meta.file_type().is_symlink()
            || !open_meta.is_file()
            || open_meta.len() != declared_len
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                "open identity desync",
            ));
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            if open_meta.nlink() != 1
                || open_meta.dev() != metadata.dev()
                || open_meta.ino() != metadata.ino()
            {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerDirectRead,
                    "open inode/nlink desync",
                ));
            }
        }
        // Cap allocation to declared length and detect one extra byte.
        let capacity = usize::try_from(declared_len).map_err(|_| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                "control ledger length conversion",
            )
        })?;
        let mut bytes = Vec::new();
        bytes.try_reserve_exact(capacity).map_err(|_| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                "allocation refused",
            )
        })?;
        bytes.resize(capacity, 0);
        file.read_exact(&mut bytes).map_err(|error| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                format!("read: {error}"),
            )
        })?;
        let mut extra = [0u8; 1];
        match file.read(&mut extra) {
            Ok(0) => {}
            Ok(_) => {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerDirectRead,
                    "control ledger grew past declared length",
                ));
            }
            Err(error) => {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerDirectRead,
                    format!("trailing probe: {error}"),
                ));
            }
        }
        // Post-read identity recheck.
        let after_path = std::fs::symlink_metadata(&ledger_path).map_err(|error| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                format!("post-read metadata: {error}"),
            )
        })?;
        if after_path.file_type().is_symlink()
            || !after_path.is_file()
            || after_path.len() != declared_len
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                "post-read identity desync",
            ));
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            if after_path.nlink() != 1
                || after_path.dev() != metadata.dev()
                || after_path.ino() != metadata.ino()
            {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerDirectRead,
                    "post-read inode/nlink desync",
                ));
            }
        }
        drop(file);
        if declared_len != ledger_snapshot.byte_length
            || sha256(&bytes) != ledger_snapshot.sha256
            || bytes != admitted_ledger_bytes
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRecheck,
                "direct ledger read differs from the admitted opaque binding",
            ));
        }
        if !bytes.starts_with(CONTROL_LEDGER_PREFIX) {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerDirectRead,
                "control ledger missing exact FND01CONTROLv2 prefix",
            ));
        }
        let ledger_first_sha256 = sha256(&bytes);
        // After retained-byte equality, reuse the already parsed typed ledger.
        let selected = &validated_ledger.selected_executable;
        let selected_path_text = selected.path.as_str();
        let selected_path = Path::new(selected_path_text);
        let current_executable_text = current_executable.to_str().ok_or_else(|| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerExecutable,
                "current executable path must be UTF-8",
            )
        })?;
        if selected_path != invocation.executable_path.as_path()
            || selected_path != current_executable.as_path()
            || selected_path_text != current_executable_text
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerExecutable,
                "selected_executable raw path desync from argv[0]/current_exe",
            ));
        }
        let selected_len = selected.binding.byte_length;
        let selected_sha256 = selected.binding.sha256;
        if selected_len == 0 {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerExecutable,
                "selected_executable empty",
            ));
        }
        if selected_path_text != non_tool.selected_executable.path
            || selected_len != non_tool.selected_executable.binding.byte_length
            || selected_sha256 != non_tool.selected_executable.binding.sha256
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerExecutable,
                "validated ledger differs from the independent executable binding",
            ));
        }
        let exe_meta = std::fs::symlink_metadata(&current_executable)
            .map_err(|error| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerExecutable,
                    format!("metadata: {error}"),
                )
            })?;
        if exe_meta.file_type().is_symlink()
            || !exe_meta.is_file()
            || exe_meta.len() != selected_len
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerExecutable,
                "current executable length/type desync from ledger",
            ));
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::{MetadataExt, PermissionsExt};
            if exe_meta.nlink() != 1 || exe_meta.permissions().mode() & 0o111 == 0 {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerExecutable,
                    "current executable must be nlink-one and executable",
                ));
            }
        }
        let executable_relative = current_executable
            .strip_prefix(&invocation.repository_root)
            .map_err(|_| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerExecutable,
                    "current executable escapes the physical repository",
                )
            })?
            .to_str()
            .ok_or_else(|| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::LedgerExecutable,
                    "repository-relative executable path must be UTF-8",
                )
            })?;
        let selected_recheck = super::trust_std::checked_snapshot(
            &invocation.repository_root,
            executable_relative,
            selected_len,
            Some(super::trust_std::FileBinding {
                byte_length: selected_len,
                sha256: selected_sha256,
            }),
        )
        .map_err(|error| {
            OrdinaryEntryFailure::from_site(OrdinaryFailureSite::LedgerExecutable, error)
        })?;
        if selected_recheck != non_tool.selected_snapshot {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerExecutable,
                "executable identity changed after independent binding",
            ));
        }
        let supply_path = validated_ledger.supply_bundle.path.as_str();
        let supply_relative = non_tool.supply_relative.clone();
        let supply_len = validated_ledger.supply_bundle.binding.byte_length;
        let expected_supply_sha256 = validated_ledger.supply_bundle.binding.sha256;
        if supply_len == 0 || supply_len > ORDINARY_MAX_SUPPLY_BUNDLE_BYTES {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerSupply,
                "supply bundle length out of bounds",
            ));
        }
        if validated_ledger.supply_bundle != non_tool.supply_bundle {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerSupply,
                "validated ledger differs from the independent supply binding",
            ));
        }
        let (supply_read_snapshot, supply_bytes) = super::trust_std::checked_read(
            &invocation.repository_root,
            &supply_relative,
            ORDINARY_MAX_SUPPLY_BUNDLE_BYTES,
            Some(super::trust_std::FileBinding {
                byte_length: supply_len,
                sha256: expected_supply_sha256,
            }),
        )
        .map_err(|error| {
            OrdinaryEntryFailure::from_site(OrdinaryFailureSite::LedgerSupply, error)
        })?;
        let supply_first_sha256 = sha256(&supply_bytes);
        if supply_read_snapshot != non_tool.supply_snapshot
            || supply_bytes != non_tool.supply_bytes
            || supply_first_sha256 != expected_supply_sha256
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerSupply,
                "supply bytes or complete identity changed after independent binding",
            ));
        }
        if !supply_bytes.starts_with(b"FND01SUPPLYv4\0") {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerSupply,
                "missing FND01SUPPLYv4 prefix",
            ));
        }

        // Bind the role-specific spool before archive contents.
        let spool_present = validated_ledger.acquisition_spool.present;
        let spool_path = validated_ledger.acquisition_spool.path.as_deref();
        let spool_binding = validated_ledger.acquisition_spool.binding;
        let first_spool = match invocation.mode {
            BootstrapMode::Produce => {
                let (spool_path, spool_binding) = match (spool_path, spool_binding) {
                    (Some(path), Some(binding)) if spool_present => (path, binding),
                    _ => {
                        return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                            OrdinaryFailureSite::LedgerSpool,
                            "Produce requires one complete present binding",
                        ));
                    }
                };
                let expected_spool_relative = format!(
                    ".fnd01-run/integration-producer/{}/acquisition-spool.bin",
                    invocation.run_id
                );
                let expected_spool_path = invocation.repository_root.join(&expected_spool_relative);
                let expected_spool_path_text = expected_spool_path
                    .to_str()
                    .ok_or_else(|| {
                        OrdinaryEntryFailure::from_site(
                            OrdinaryFailureSite::LedgerSpool,
                            "exact spool path must be UTF-8",
                        )
                    })?;
                if spool_path != expected_spool_path_text {
                    return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::LedgerSpool,
                        "producer spool path differs from exact run formula",
                    ));
                }
                let independent_relative = non_tool.spool_relative.as_deref().ok_or_else(|| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::LedgerSpool,
                        "independent Produce spool path is absent",
                    )
                })?;
                let independent_snapshot = non_tool.spool_snapshot.as_ref().ok_or_else(|| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::LedgerSpool,
                        "independent Produce spool snapshot is absent",
                    )
                })?;
                let independent_binding = non_tool.acquisition_spool_binding.ok_or_else(|| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::LedgerSpool,
                        "independent Produce spool binding is absent",
                    )
                })?;
                if expected_spool_relative != independent_relative
                    || spool_binding != independent_binding
                {
                    return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::LedgerSpool,
                        "validated ledger differs from the independent spool binding",
                    ));
                }
                let (spool_snapshot, spool_bytes) = checked_read(
                    &invocation.repository_root,
                    &expected_spool_relative,
                    ORDINARY_MAX_ACQUISITION_SPOOL_BYTES,
                    Some(independent_binding),
                )
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::LedgerSpool,
                        format!("independent spool read failed ({error})"),
                    )
                })?;
                if &spool_snapshot != independent_snapshot {
                    return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::LedgerSpool,
                        "spool identity changed after independent binding",
                    ));
                }
                let spool_record = parse_ordinary_acquisition_spool(
                    &spool_bytes,
                    &invocation.run_id,
                    supply_path,
                    supply_len,
                    supply_first_sha256,
                )
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(OrdinaryFailureSite::LedgerSpool, error)
                })?;
                Some(OrdinarySpoolBinding {
                    relative_path: expected_spool_relative,
                    snapshot: spool_snapshot,
                    byte_length: spool_binding.byte_length,
                    sha256: spool_binding.sha256,
                    bytes: spool_bytes,
                    record: spool_record,
                })
            }
            BootstrapMode::Attest => {
                if spool_present
                    || spool_path.is_some()
                    || spool_binding.is_some()
                {
                    return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::LedgerSpool,
                        "Attest requires the exact absent option",
                    ));
                }
                if non_tool.spool_relative.is_some()
                    || non_tool.spool_snapshot.is_some()
                    || non_tool.acquisition_spool_binding.is_some()
                {
                    return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::LedgerSpool,
                        "independent Attest expectation must omit the spool",
                    ));
                }
                None
            }
            BootstrapMode::Gate => {
                unreachable!("ordinary argv parsing rejects Gate before ledger decoding")
            }
        };
        // Decompression follows complete framing, ordering, bounds, and digest validation.
        let first_supply_framing =
            parse_ordinary_supply_framing(&supply_bytes, "ordinary handoff supply bundle")
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::ArchiveFraming,
                        error.stable(),
                    )
                })?;
        validate_ordinary_supply_archives(&supply_bytes, &first_supply_framing)
            .map_err(|error| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::ArchiveValidation,
                    error.stable(),
                )
            })?;
        drop(bytes);
        drop(supply_bytes);

        // Reopen, strict-reparse, and rehash every first-bound handoff object.
        let (ledger_recheck_snapshot, ledger_recheck_bytes) = checked_read(
            &invocation.repository_root,
            &invocation.control_ledger_path,
            MAX_CONTROL_LEDGER_BYTES,
            Some(FileBinding {
                byte_length: declared_len,
                sha256: ledger_first_sha256,
            }),
        )
        .map_err(|error| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendLedger,
                format!("post-archive checked-read failed ({error})"),
            )
        })?;
        if ledger_recheck_snapshot != ledger_snapshot
            || ledger_recheck_bytes != admitted_ledger_bytes
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendLedger,
                "post-archive bytes or complete identity differ from admission",
            ));
        }
        let ledger_recheck = validate_control_ledger_bytes(&ledger_recheck_bytes, &expectation)
            .map_err(|error| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::BookendLedger,
                    format!("complete validator failed ({error})"),
                )
            })?;
        if ledger_recheck != validated_ledger {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendLedger,
                "complete validated ledger differs from admission",
            ));
        }
        rebind_control_ledger_regular_files(&invocation.repository_root, &ledger_recheck).map_err(
            |error| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::BookendLedger,
                    format!("regular-file rebind failed ({error})"),
                )
            },
        )?;

        let (supply_recheck_snapshot, supply_recheck_bytes) = checked_read(
            &invocation.repository_root,
            &supply_relative,
            ORDINARY_MAX_SUPPLY_BUNDLE_BYTES,
            Some(non_tool.supply_bundle.binding),
        )
        .map_err(|error| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendSupply,
                format!("post-archive checked-read failed ({error})"),
            )
        })?;
        if supply_recheck_snapshot != non_tool.supply_snapshot
            || supply_recheck_bytes != non_tool.supply_bytes
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendSupply,
                "post-archive bytes or complete identity differ from admission",
            ));
        }
        let supply_recheck_framing = parse_ordinary_supply_framing(
            &supply_recheck_bytes,
            "ordinary supply bundle post-archive recheck",
        )
        .map_err(|error| {
            OrdinaryEntryFailure::from_site(OrdinaryFailureSite::BookendSupply, error.stable())
        })?;
        if supply_recheck_framing != first_supply_framing {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendSupply,
                "framing differs from first binding",
            ));
        }

        let (registry_recheck, target_recheck): (
            ValidatedDirectoryTreeBinding,
            ValidatedTargetSnapshot,
        ) = {
            #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
            {
                super::phase_b_std::observe_ordinary_control_trees(
                    &invocation.repository_root,
                    invocation.mode,
                    &invocation.run_id,
                    &supply_recheck_bytes,
                )
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::BookendLedger,
                        format!("post-archive tree observation failed ({error})"),
                    )
                })?
            }
            #[cfg(not(all(target_os = "linux", target_arch = "x86_64")))]
            {
                unreachable!("ordinary entry rejects an unqualified platform before archive rebind")
            }
        };
        if registry_recheck != non_tool.local_registry
            || registry_recheck != ledger_recheck.local_registry
            || target_recheck != non_tool.target_snapshot
            || target_recheck != ledger_recheck.target_snapshot
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendLedger,
                "post-archive local-registry or target tree changed",
            ));
        }

        if let Some(first_spool) = &first_spool {
            let (spool_recheck_snapshot, spool_recheck_bytes) = checked_read(
                &invocation.repository_root,
                &first_spool.relative_path,
                ORDINARY_MAX_ACQUISITION_SPOOL_BYTES,
                Some(FileBinding {
                    byte_length: first_spool.byte_length,
                    sha256: first_spool.sha256,
                }),
            )
            .map_err(|error| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::BookendSpool,
                    format!("post-archive checked-read failed ({error})"),
                )
            })?;
            let spool_recheck = parse_ordinary_acquisition_spool(
                &spool_recheck_bytes,
                &invocation.run_id,
                supply_path,
                supply_len,
                supply_first_sha256,
            )
            .map_err(|error| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::BookendSpool,
                    format!("post-archive canonical spool parse failed ({error})"),
                )
            })?;
            if spool_recheck_snapshot != first_spool.snapshot
                || spool_recheck_bytes != first_spool.bytes
                || spool_recheck != first_spool.record
            {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::BookendSpool,
                    "spool bytes or canonical record differ from first binding",
                ));
            }
            // phase_b_std producer acquisition revalidation is Linux x86_64 only
            // (same gate as the dual-path inventory / control-tree observers).
            #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
            {
                super::phase_b_std::revalidate_ordinary_producer_acquisition(
                    &invocation.repository_root,
                    &invocation.run_id,
                    &supply_recheck_bytes,
                    &spool_recheck_bytes,
                    &tool_reprobe.acquisition_tools,
                    &ledger_recheck.scratch_bindings[0],
                    &ledger_recheck.scratch_bindings[1],
                    &non_tool.supply_bundle,
                )
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::BookendSpool,
                        format!("producer acquisition typed-result revalidation failed ({error})"),
                    )
                })?;
            }
            #[cfg(not(all(target_os = "linux", target_arch = "x86_64")))]
            {
                let _ = (
                    &supply_recheck_bytes,
                    &spool_recheck_bytes,
                    &tool_reprobe,
                    &ledger_recheck,
                );
                unreachable!(
                    "ordinary entry rejects an unqualified platform before acquisition revalidation"
                )
            }
        }
        if let Some(authority) = integration.as_mut() {
            authority
                .retained
                .revalidate_after_consumption()
                .map_err(|error| {
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::BookendLedger,
                        format!("retained integration authority changed ({error})"),
                    )
                })?;
        }

        // Join pre-parse tool observations to ledger digests and revalidate after archive.
        let tool_set = validated_ledger.tool_set_sha256;
        let environment_set = validated_ledger.environment_set_sha256;
        if tool_set == [0; 32] || environment_set == [0; 32] {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerJoin,
                "tool/environment set digests must be nonzero",
            ));
        }
        let expected_env = ordinary_environment_set_digest();
        if environment_set != expected_env {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerJoin,
                "environment template digest desync from compiled authority",
            ));
        }
        if tool_set != tool_reprobe.tool_set_sha256 {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::LedgerJoin,
                "live 20-tool reprobe digest desync from ledger",
            ));
        }
        tool_reprobe.require_unchanged()?;
        let final_current_executable = std::env::current_exe().map_err(|error| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendExecutable,
                format!("current_exe: {error}"),
            )
        })?;
        let expected_executable = Path::new(&expectation.selected_executable.path);
        if final_current_executable != invocation.executable_path
            || final_current_executable != expected_executable
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendExecutable,
                "current executable differs from the exact admitted role/run target",
            ));
        }
        let final_executable_relative = final_current_executable
            .strip_prefix(&invocation.repository_root)
            .map_err(|_| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::BookendExecutable,
                    "current executable escapes the physical repository",
                )
            })?
            .to_str()
            .ok_or_else(|| {
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::BookendExecutable,
                    "repository-relative executable path must be UTF-8",
                )
            })?;
        let final_executable_snapshot = checked_snapshot(
            &invocation.repository_root,
            final_executable_relative,
            MAX_GATE_EXECUTABLE_BYTES,
            Some(expectation.selected_executable.binding),
        )
        .map_err(|error| {
            OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendExecutable,
                format!("final binding failed ({error})"),
            )
        })?;
        if final_executable_snapshot != non_tool.selected_snapshot
            || final_executable_snapshot.identity.file_type != 0o100_000
            || final_executable_snapshot.identity.link_count != 1
            || final_executable_snapshot.identity.mode & 0o100 == 0
        {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::BookendExecutable,
                "executable identity or owner-executable mode changed",
            ));
        }
        // Pending receipts stay pending; only errors fail the evidence dispatch.
        effects.before_evidence_dispatch();
        complete_ordinary_post_consume_continuation(|| run_verifier_at(&invocation.repository_root))
    }

    #[test]
    fn ordinary_authority_sentinel_precedes_untrusted_artifact_reads() {
        let repository_root = repository_root();
        let current_executable = std::env::current_exe().expect("current test executable");
        let invocation = OrdinaryHandoffArguments {
            mode: BootstrapMode::Produce,
            executable_path: current_executable,
            repository_root: repository_root.clone(),
            run_root: repository_root
                .join(".fnd01-run/integration-producer/0123456789abcdef0123456789abcdef"),
            run_id: "0123456789abcdef0123456789abcdef".to_owned(),
            run_id_bytes: [
                0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef, 0x01, 0x23, 0x45, 0x67, 0x89, 0xab,
                0xcd, 0xef,
            ],
            control_ledger_path: ".fnd01-run/does-not-exist/control-ledger.bin".to_owned(),
        };
        let environment = BootstrapEnvironment {
            authoring_marker: "externally-required-authority".to_owned(),
            closed_path: "/externally-required-tool-bin".to_owned(),
            integration_seal: None,
            producer_outer_record_path: None,
            attester_outer_record_path: None,
            final_gate_seal: None,
        };
        let error = validate_ordinary_handoff_entry(&invocation, &environment)
            .expect_err("unfrozen external authority must stop ordinary entry");
        assert_eq!(error.code(), "E_ORDINARY_HANDOFF_PENDING");
        assert_eq!(error.site, OrdinaryFailureSite::PreLedgerAuthority);
        assert_eq!(error.route(), OrdinaryFailureRoute::Pending);
        assert_eq!(error.route().stage().as_str(), "authority");
        assert!(
            !error.observed.contains("does-not-exist"),
            "the ledger path must not be opened before external authority"
        );
    }

    pub(super) fn ordinary_function_body(source: &str, name: &str) -> String {
        fn find(tokens: TokenStream, name: &str) -> Option<TokenStream> {
            let tokens = tokens.into_iter().collect::<Vec<_>>();
            for (index, token) in tokens.iter().enumerate() {
                if let TokenTree::Ident(keyword) = token {
                    if keyword == "fn"
                        && matches!(tokens.get(index + 1), Some(TokenTree::Ident(candidate)) if candidate == name)
                    {
                        for token in &tokens[index + 2..] {
                            if let TokenTree::Group(group) = token {
                                if group.delimiter() == Delimiter::Brace {
                                    return Some(group.stream());
                                }
                            }
                        }
                    }
                }
                if let TokenTree::Group(group) = token {
                    if let Some(body) = find(group.stream(), name) {
                        return Some(body);
                    }
                }
            }
            None
        }

        let tokens = TokenStream::from_str(source).expect("ordinary source tokenizes");
        find(tokens, name)
            .unwrap_or_else(|| panic!("missing ordinary function body: {name}"))
            .to_string()
    }

    fn compact_ordinary_token_text(text: &str) -> String {
        text.chars()
            .filter(|character| !character.is_whitespace())
            .collect::<String>()
    }

    fn validate_ordinary_harness_wrapper_binding(body: &str) -> Result<(), &'static str> {
        let compact = compact_ordinary_token_text(body);
        const REQUIRED_BINDING: &str = "ordinary_handoff_harness_core(arguments,run_ordinary_handoff_entry,|mode,run_id,failure|{emit_ordinary_entry_failure_route(mode,run_id,failure);}";
        if compact.matches(REQUIRED_BINDING).count() == 2 {
            Ok(())
        } else {
            Err("ordinary harness must bind the real handoff callback and emitter")
        }
    }

    fn validate_ordinary_handoff_marker_order(body: &str) -> Result<(), String> {
        let first_ledger_binding = body
            .find("opaque_ledger_snapshot")
            .ok_or_else(|| "missing initial ledger binding".to_owned())?;
        let post_archive_ledger_binding = body
            .find("let (ledger_recheck_snapshot , ledger_recheck_bytes) = checked_read (")
            .ok_or_else(|| "missing post-archive ledger reread binding".to_owned())?;
        let ordered_markers = [
            "require_ordinary_execution_authority (",
            "derive_ordinary_non_tool_expectation (",
            "OrdinaryProbePermit",
            ". consume () ?",
            "validate_probed_ordinary_ledger (",
            "validate_ordinary_supply_archives (",
            "validate_control_ledger_bytes (",
            "revalidate_ordinary_producer_acquisition (",
            "tool_reprobe . require_unchanged () ?",
            "complete_ordinary_post_consume_continuation (",
            "run_verifier_at (",
        ];
        let mut cursor = 0usize;
        for marker in ordered_markers {
            let relative = body[cursor..]
                .find(marker)
                .ok_or_else(|| format!("missing or reordered ordinary marker: {marker}"))?;
            cursor += relative + marker.len();
            if marker == "derive_ordinary_non_tool_expectation (" {
                if cursor > first_ledger_binding {
                    return Err("authority follows ledger read".to_owned());
                }
            }
            if marker == "validate_ordinary_supply_archives (" {
                if cursor > post_archive_ledger_binding {
                    return Err("archive validation follows ledger reread".to_owned());
                }
            }
        }
        Ok(())
    }

    #[test]
    fn ordinary_b_r4_handoff_source_order_keeps_probe_archive_and_bookend_authority() {
        let body = ordinary_function_body(
            include_str!("fnd_01_dependency_evidence.rs"),
            "validate_ordinary_handoff_entry_with_effects",
        );
        validate_ordinary_handoff_marker_order(&body)
            .expect("production source markers remain ordered");
        let archive_marker = "validate_ordinary_supply_archives (";
        let post_archive_marker =
            "let (ledger_recheck_snapshot , ledger_recheck_bytes) = checked_read (";
        let archive_offset = body.find(archive_marker).expect("archive marker");
        let post_archive_offset = body
            .find(post_archive_marker)
            .expect("post-archive ledger marker");
        assert!(archive_offset < post_archive_offset, "baseline marker order");
        let planted = format!(
            "{}{}{}{}{}",
            &body[..archive_offset],
            post_archive_marker,
            &body[archive_offset + archive_marker.len()..post_archive_offset],
            archive_marker,
            &body[post_archive_offset + post_archive_marker.len()..],
        );
        assert_eq!(
            validate_ordinary_handoff_marker_order(&planted),
            Err("archive validation follows ledger reread".to_owned()),
            "one swapped archive/recheck ordering must reject the source-order oracle",
        );
    }

    fn live_authoring_marker_text(repository_root: &Path) -> String {
        use super::trust_std::{
            authoring_closure_preimage, AuthoringMarker, FileBinding, AUTHORING_PATHS,
            MAX_HARNESS_BYTES, MAX_POLICY_BYTES, MAX_VERIFIER_BYTES,
        };
        let limits = [MAX_POLICY_BYTES, MAX_VERIFIER_BYTES, MAX_HARNESS_BYTES];
        let mut bindings = [FileBinding {
            byte_length: 0,
            sha256: [0; 32],
        }; 3];
        for ((path, limit), binding) in AUTHORING_PATHS
            .iter()
            .copied()
            .zip(limits)
            .zip(bindings.iter_mut())
        {
            let abs = repository_root.join(path);
            let bytes = std::fs::read(&abs).unwrap_or_else(|error| panic!("read {path}: {error}"));
            let byte_length = u64::try_from(bytes.len()).expect("authoring length");
            assert!(
                byte_length > 0 && byte_length <= limit,
                "{path}: length {byte_length} outside (0, {limit}]"
            );
            *binding = FileBinding {
                byte_length,
                sha256: sha256(&bytes),
            };
        }
        let marker = AuthoringMarker {
            policy: bindings[0],
            verifier: bindings[1],
            harness: bindings[2],
            closure_sha256: [0; 32],
        };
        let closure = sha256(
            &authoring_closure_preimage(&marker).expect("authoring closure preimage"),
        );
        format!(
            "FND01AUTHORv2:{}:{}:{}:{}:{}:{}:{}",
            marker.policy.byte_length,
            lower_hex(&marker.policy.sha256),
            marker.verifier.byte_length,
            lower_hex(&marker.verifier.sha256),
            marker.harness.byte_length,
            lower_hex(&marker.harness.sha256),
            lower_hex(&closure),
        )
    }

    #[test]
    fn ordinary_live_authoring_marker_rebind_remains_pending_before_ledger_open() {
        let repository_root = repository_root();
        let marker = live_authoring_marker_text(&repository_root);
        let environment = BootstrapEnvironment {
            authoring_marker: marker,
            closed_path: "/usr/bin".to_owned(),
            integration_seal: None,
            producer_outer_record_path: None,
            attester_outer_record_path: None,
            final_gate_seal: None,
        };
        let error = require_ordinary_execution_authority(
            &repository_root,
            BootstrapMode::Produce,
            "0123456789abcdef0123456789abcdef",
            &environment,
        )
        .expect_err("a matching authoring marker alone must not authorize ledger access");
        assert_eq!(error.code(), "E_ORDINARY_HANDOFF_PENDING");
        assert_eq!(error.site, OrdinaryFailureSite::PreLedgerAuthority);
        assert_eq!(error.route(), OrdinaryFailureRoute::Pending);
        assert!(
            error.observed.contains("twenty-tool")
                || error.observed.contains("closed PATH")
                || error.observed.contains("authoring path rebind")
                || error.observed.contains("UNQUALIFIED_PLATFORM"),
            "early authority boundary must fail closed without ledger open: {error}"
        );
    }

