    #[test]
    fn ordinary_b_r4_product_stages_are_first_class_entry_tokens() {
        let mut route_ids = BTreeSet::new();
        for route in OrdinaryFailureRoute::SHIPPED {
            assert!(
                route_ids.insert(route.id()),
                "duplicate ordinary route id: {}",
                route.id()
            );
            let frame = OrdinaryRouteFixture::new(*route, "fixture observed")
                .frame("attest", "0123456789abcdef0123456789abcdef");
            assert_eq!(frame.stage, route.stage().as_str());
            assert_eq!(
                frame.parts[2],
                format!("expected={}", route.expected()),
                "route {} must preserve its registry invariant",
                route.id(),
            );
        }
        for stage in [
            "authority",
            "reprobe",
            "ledger",
            "archive",
            "bookend",
            "evidence",
        ] {
            assert_ne!(stage, "ordinary");
            assert_ne!(stage, "bootstrap");
            assert_ne!(stage, "controller");
        }
        assert_eq!(OrdinaryFailureRoute::Evidence.stage().as_str(), "evidence");
        assert_eq!(OrdinaryFailureRoute::ToolSet.stage().as_str(), "reprobe");
        assert_eq!(OrdinaryFailureRoute::ArchiveValidate.stage().as_str(), "archive");
        assert_eq!(OrdinaryFailureRoute::Pending.stage().as_str(), "authority");
        assert_eq!(OrdinaryFailureRoute::Arguments.stage().as_str(), "authority");
        assert_eq!(OrdinaryFailureRoute::Panic.stage().as_str(), "authority");
    }

    #[test]
    fn ordinary_b_r4_registry_selectors_and_frames_are_exact() {
        let run_id = "0123456789abcdef0123456789abcdef";
        let mut selectors = BTreeSet::new();
        for &(route, id, code, stage, expected) in ORDINARY_FAILURE_ROUTE_ORACLE {
            assert!(
                selectors.insert(route.id()),
                "duplicate selector: {}",
                route.id()
            );
            assert_eq!(route.id(), id, "literal route ID: {id}");
            assert_eq!(route.code(), code, "literal route code: {id}");
            assert_eq!(
                route.stage().as_str(),
                stage,
                "literal route stage: {id}",
            );
            assert_eq!(
                route.expected(),
                expected,
                "literal route expectation: {id}",
            );
            let frame = OrdinaryRouteFixture::new(route, "route frame observation")
                .frame("attest", run_id);
            assert_eq!(frame.stage, route.stage().as_str());
            assert_eq!(
                frame.parts,
                [
                    "role=attest".to_owned(),
                    format!("run_id={run_id}"),
                    format!("expected={expected}"),
                    "observed=route frame observation".to_owned(),
                ],
                "route {} frame must retain the exact role/run/expected/observed contract",
                route.id(),
            );
            let site = if route == OrdinaryFailureRoute::Panic {
                OrdinaryFailureSite::HandoffPanic
            } else {
                ORDINARY_PUBLIC_FAILURE_SITE_ORACLE
                    .iter()
                    .find_map(|(site, mapped)| (*mapped == route).then_some(*site))
                    .expect("each non-panic literal route has a public site")
            };
            let mut emitted = Vec::new();
            write_ordinary_emitted_failure_frame(
                &mut emitted,
                "attest",
                run_id,
                OrdinaryEntryFailure::from_site(site, "route frame observation"),
            )
            .expect("production writer emits literal route frame");
            assert_eq!(
                String::from_utf8(emitted).expect("entry frame UTF-8"),
                format!(
                    "FND01ENTRYv1|{}|attest|{}|role=attest @ run_id={run_id} @ expected={} @ observed=route frame observation\n",
                    stage, code, expected,
                ),
                "route {} writer must retain literal frame fields",
                id,
            );
        }
    }

    #[test]
    fn ordinary_b_r4_emitted_frames_keep_real_code_expected_run_and_one_variable_negative() {
        let run_id = "0123456789abcdef0123456789abcdef";
        let positive = OrdinaryFrameCandidate {
            site: OrdinaryFailureSite::BookendSpool,
            route: OrdinaryFailureRoute::BookendSpool,
            observed: "post-archive canonical spool parse failed (invalid frame)",
        };
        let mut committed = OrdinaryFrameCommit::default();
        stage_validate_and_commit_ordinary_frame(positive, "attest", run_id, &mut committed)
            .expect("literal positive reaches the production frame commit");
        assert_eq!(
            String::from_utf8(committed.accepted_frames[0].clone()).expect("entry frame is UTF-8"),
            format!(
                "FND01ENTRYv1|bookend|attest|E_HANDOFF_SPOOL_RECHECK|role=attest @ run_id={run_id} @ expected=unchanged post-archive spool @ observed=post-archive canonical spool parse failed (invalid frame)\n"
            ),
        );

        let before_negative = committed.clone();
        let negative = OrdinaryFrameCandidate {
            site: OrdinaryFailureSite::BookendLedger,
            ..positive
        };
        assert_eq!(
            stage_validate_and_commit_ordinary_frame(negative, "attest", run_id, &mut committed),
            Err("candidate site-to-route mismatch"),
            "only the typed site differs from the accepted spool candidate",
        );
        assert_eq!(
            committed, before_negative,
            "the rejected one-field substitution leaves accepted frame and effect state unchanged",
        );
    }

    #[test]
    fn ordinary_b_r4_harness_main_product_failures_emit_authority_stage() {
        #[derive(Clone, Default, Debug, PartialEq, Eq)]
        struct MalformedHandoffState {
            callback_attempts: usize,
            acceptance_effects: usize,
            diagnostics: Vec<String>,
        }

        let source = include_str!("fnd_01_dependency_evidence.rs");
        let ordinary_start = source.find("mod ordinary {").expect("ordinary module");
        let ordinary_end = source.rfind("} // mod ordinary").expect("ordinary module end");
        let ordinary_source = &source[ordinary_start..=ordinary_end];
        let body = compact_ordinary_token_text(&ordinary_function_body(
            ordinary_source,
            "harness_main",
        ));
        let handoff_core = compact_ordinary_token_text(&ordinary_function_body(
            ordinary_source,
            "ordinary_handoff_harness_core",
        ));
        validate_ordinary_harness_wrapper_binding(&body)
            .expect("shipped harness must bind its real callback and emitter");
        let planted = body.replacen("run_ordinary_handoff_entry", "|_|3", 1);
        assert_eq!(
            validate_ordinary_harness_wrapper_binding(&planted),
            Err("ordinary harness must bind the real handoff callback and emitter"),
            "one callback binding replacement must reject the wrapper evaluator",
        );
        let planted_emitter = body.replacen("emit_ordinary_entry_failure_route", "drop", 1);
        assert_eq!(
            validate_ordinary_harness_wrapper_binding(&planted_emitter),
            Err("ordinary harness must bind the real handoff callback and emitter"),
            "one emitter binding replacement must reject the wrapper evaluator",
        );
        assert!(
            handoff_core.contains("arguments.len()!=ORDINARY_HANDOFF_ARGV_ARITY"),
            "the typed core must reject malformed arity before callback dispatch",
        );
        assert!(
            handoff_core.contains("OrdinaryFailureSite::EntryArity"),
            "malformed arity must select the EntryArity site",
        );
        assert!(
            handoff_core.contains("OrdinaryFailureSite::HandoffPanic"),
            "panic path must select the HandoffPanic site",
        );
        assert!(
            !body.contains("emit_entry_diagnostic(\"ordinary\","),
            "harness_main must not hard-code stage=ordinary for ordinary product failures",
        );

        let state = std::rc::Rc::new(RefCell::new(MalformedHandoffState::default()));
        let callback_state = std::rc::Rc::clone(&state);
        let emitter_state = std::rc::Rc::clone(&state);
        let code = ordinary_handoff_harness_core(
            vec![
                std::ffi::OsString::from("/tmp/fnd01-harness"),
                std::ffi::OsString::from("produce"),
            ],
            move |_| {
                let mut state = callback_state.borrow_mut();
                state.callback_attempts += 1;
                state.acceptance_effects += 1;
                0
            },
            |mode, run_id, failure| {
                let mut emitted = Vec::new();
                write_ordinary_emitted_failure_frame(&mut emitted, mode, run_id, failure)
                    .expect("malformed-arity frame write");
                emitter_state
                    .borrow_mut()
                    .diagnostics
                    .push(String::from_utf8(emitted).expect("malformed-arity frame UTF-8"));
            },
        );
        assert_eq!(code, 3, "malformed arity must fail closed");
        let state = state.borrow();
        assert_eq!(state.callback_attempts, 0, "callback must remain unstarted");
        assert_eq!(state.acceptance_effects, 0, "accepted/effect state must remain empty");
        assert_eq!(state.diagnostics.len(), 1, "exactly one typed frame is emitted");
        assert_eq!(
            state.diagnostics[0],
            "FND01ENTRYv1|authority|unknown|E_ENTRY_ARGUMENTS|role=unknown @ run_id=unavailable @ expected=valid ordinary handoff argv @ observed=invalid argument count\n",
            "the captured production writer preserves the typed authority-stage route",
        );
    }

    #[test]
    fn ordinary_b_r4_injected_panic_emits_once_with_callback_and_emitter_state() {
        #[derive(Clone, Default, Debug, PartialEq, Eq)]
        struct HandoffState {
            callback_attempts: usize,
            diagnostics: Vec<String>,
        }

        let state = std::rc::Rc::new(RefCell::new(HandoffState::default()));
        let before = state.borrow().clone();
        let callback_state = std::rc::Rc::clone(&state);
        let emitter_state = std::rc::Rc::clone(&state);
        let code = ordinary_handoff_harness_core(
            vec![
                std::ffi::OsString::from("/tmp/fnd01-harness"),
                std::ffi::OsString::from("attest"),
                std::ffi::OsString::from("."),
                std::ffi::OsString::from("0123456789abcdef0123456789abcdef"),
                std::ffi::OsString::from("handoff"),
            ],
            move |_| -> i32 {
                callback_state.borrow_mut().callback_attempts += 1;
                std::panic::resume_unwind(Box::new("deterministic injected panic"))
            },
            |mode, run_id, failure| {
                let mut emitted = Vec::new();
                write_ordinary_emitted_failure_frame(&mut emitted, mode, run_id, failure)
                    .expect("panic frame write");
                emitter_state
                    .borrow_mut()
                    .diagnostics
                    .push(String::from_utf8(emitted).expect("panic frame UTF-8"));
            },
        );
        assert_eq!(code, 3, "panic must fail closed");
        let after = state.borrow();
        assert_eq!(after.callback_attempts, before.callback_attempts + 1);
        assert_eq!(after.diagnostics.len(), 1, "one panic diagnostic is committed");
        assert_eq!(
            after.diagnostics[0],
            "FND01ENTRYv1|authority|attest|E_ENTRY_PANIC|role=attest @ run_id=0123456789abcdef0123456789abcdef @ expected=ordinary handoff must not panic @ observed=panic payload suppressed\n",
            "exactly one typed panic frame is emitted",
        );

        let mut catch_only = OrdinaryCatchOnlyCommit::default();
        classify_and_commit_catch_only_claim(
            OrdinaryCatchOnlyClaim {
                site: OrdinaryFailureSite::HandoffPanic,
                requests_public_reachability_credit: false,
            },
            &mut catch_only,
        )
        .expect("HandoffPanic is the one defensive catch-only site");
        assert_eq!(
            catch_only,
            OrdinaryCatchOnlyCommit {
                accepted_catch_sites: vec![OrdinaryFailureSite::HandoffPanic],
                classification_effects: 1,
            },
        );
        let before_public_credit_request = catch_only.clone();
        assert_eq!(
            classify_and_commit_catch_only_claim(
                OrdinaryCatchOnlyClaim {
                    site: OrdinaryFailureSite::HandoffPanic,
                    requests_public_reachability_credit: true,
                },
                &mut catch_only,
            ),
            Err("catch-only site cannot receive public reachability credit"),
            "one forbidden public-credit field must reject",
        );
        assert_eq!(
            catch_only, before_public_credit_request,
            "rejected public-credit request leaves catch classification commit/effect state unchanged",
        );
    }

