    #[derive(Debug)]
    struct OrdinaryToolReprobe {
        tool_set_sha256: [u8; 32],
        #[allow(dead_code)]
        execution_bin_sha256: [u8; 32],
        acquisition_tools: AcquisitionToolPaths,
        #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
        inventory: super::phase_b_std::OrdinaryNativeToolInventory,
    }

    impl OrdinaryToolReprobe {
        fn require_unchanged(&self) -> Result<(), OrdinaryEntryFailure> {
            #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
            {
                self.inventory
                    .require_unchanged()
                    .map_err(|error| OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::BookendToolSet,
                        error.detail(),
                    ))?;
                if self.inventory.tool_set_sha256() != self.tool_set_sha256
                    || self.inventory.execution_bin_sha256() != self.execution_bin_sha256
                    || self.inventory.acquisition_tools() != &self.acquisition_tools
                {
                    return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::BookendToolSet,
                        "opaque inventory binding drifted",
                    ));
                }
                Ok(())
            }
            #[cfg(not(all(target_os = "linux", target_arch = "x86_64")))]
            {
                unreachable!("ordinary entry rejects an unqualified platform before reprobe recheck")
            }
        }
    }

    fn ordinary_reprobe_tool_set_qualified(
        repository_root: &Path,
        mode: BootstrapMode,
        run_id: &str,
        closed_path: &str,
        _qualified_platform: OrdinaryQualifiedPlatform,
    ) -> Result<OrdinaryToolReprobe, OrdinaryEntryFailure> {
        let pure = ordinary_reprobe_dual_path_pure_authority()?;
        debug_assert_eq!(pure.native_tool_count, ORDINARY_NATIVE_TOOL_COUNT);
        #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
        {
            let inventory = super::phase_b_std::inventory_existing_native_tools(
                repository_root,
                mode,
                run_id,
                closed_path,
            )
            .map_err(|error| OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::ProbeToolSet,
                error.detail(),
            ))?;
            if inventory.native_tool_count() != pure.native_tool_count
                || inventory.native_tool_count() != ORDINARY_NATIVE_TOOL_COUNT
            {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::ProbeToolSet,
                    format!(
                        "live inventory cardinality {} != pure dual-path count {}",
                        inventory.native_tool_count(),
                        pure.native_tool_count,
                    ),
                ));
            }
            let reprobe = OrdinaryToolReprobe {
                tool_set_sha256: inventory.tool_set_sha256(),
                execution_bin_sha256: inventory.execution_bin_sha256(),
                acquisition_tools: inventory.acquisition_tools().clone(),
                inventory,
            };
            if reprobe.execution_bin_sha256 == [0; 32] || reprobe.tool_set_sha256 == [0; 32] {
                return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::ProbeToolSet,
                    "execution-bin and tool-set digests must both be nonzero",
                ));
            }
            Ok(reprobe)
        }
        #[cfg(not(all(target_os = "linux", target_arch = "x86_64")))]
        {
            let _ = (repository_root, mode, run_id, closed_path, pure);
            unreachable!("the shared platform gate returns before this branch")
        }
    }

    #[cfg(test)]
    fn ordinary_reprobe_tool_set_shared(
        repository_root: &Path,
        mode: BootstrapMode,
        run_id: &str,
        closed_path: &str,
    ) -> Result<OrdinaryToolReprobe, OrdinaryEntryFailure> {
        if !ordinary_platform_is_qualified() {
            return std::result::Result::Err(OrdinaryEntryFailure::from_site(
                OrdinaryFailureSite::ProbeToolPlatform,
                "ordinary native-tool probes require Linux x86_64",
            ));
        }
        ordinary_reprobe_tool_set_qualified(
            repository_root,
            mode,
            run_id,
            closed_path,
            OrdinaryQualifiedPlatform,
        )
    }

