    fn ordinary_handoff_harness_core<F, E>(
        arguments: Vec<std::ffi::OsString>,
        handoff: F,
        mut emit: E,
    ) -> i32
    where
        F: FnOnce(Vec<std::ffi::OsString>) -> i32,
        E: FnMut(&str, &str, OrdinaryEntryFailure),
    {
        if arguments.len() != ORDINARY_HANDOFF_ARGV_ARITY {
            emit(
                "unknown",
                "unavailable",
                OrdinaryEntryFailure::from_site(
                    OrdinaryFailureSite::EntryArity,
                    "invalid argument count",
                ),
            );
            return 3;
        }
        let mode = match arguments.get(1).and_then(|value| value.to_str()) {
            Some("produce") => "produce",
            Some("attest") => "attest",
            _ => "unknown",
        };
        let run_id = ordinary_known_handoff_run_id(&arguments)
            .unwrap_or_else(|| "unavailable".to_owned());
        match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| handoff(arguments))) {
            Ok(code) => code,
            Err(_) => {
                emit(
                    mode,
                    &run_id,
                    OrdinaryEntryFailure::from_site(
                        OrdinaryFailureSite::HandoffPanic,
                        "panic payload suppressed",
                    ),
                );
                3
            }
        }
    }

    #[allow(dead_code)] // Invoked by the path-including ordinary handoff example.
    pub fn harness_main<I>(arguments: I) -> i32
    where
        I: IntoIterator<Item = std::ffi::OsString>,
    {
        let prior_hook = std::panic::take_hook();
        std::panic::set_hook(Box::new(|_| {}));
        let branch = Cell::new(0u8);
        let mode = Cell::new("unknown");
        let ordinary_run_id = RefCell::new("unavailable".to_owned());
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let arguments = arguments.into_iter().collect::<Vec<_>>();
            if has_exact_gate_intent(&arguments) {
                branch.set(5);
                return match super::bootstrap::run_gate(arguments) {
                    Ok(()) => 0,
                    Err(_) => 3,
                };
            }
            if arguments.len() == 2
                && arguments.get(1).and_then(|value| value.to_str())
                    == Some("sdk-batch-verify-json")
            {
                branch.set(1);
                return run_sdk_batch_verify_json_from_stdin();
            }
            match arguments.len() {
                1 => {
                    branch.set(1);
                    match run_verifier() {
                        Ok(report) => {
                            let failed = report.has_errors();
                            for diagnostic in report.sorted_stable() {
                                eprintln!("{diagnostic}");
                            }
                            i32::from(failed)
                        }
                        Err(diagnostic) => {
                            eprintln!("{}", diagnostic.stable());
                            1
                        }
                    }
                }
                4 => {
                    branch.set(2);
                    mode.set("controller");
                    run_ordinary_controller_entry(arguments)
                }
                5 => {
                    branch.set(3);
                    mode.set(match arguments.get(1).and_then(|value| value.to_str()) {
                        Some("produce") => "produce",
                        Some("attest") => "attest",
                        _ => "unknown",
                    });
                    if let Some(run_id) = ordinary_known_handoff_run_id(&arguments) {
                        *ordinary_run_id.borrow_mut() = run_id;
                    }
                    ordinary_handoff_harness_core(
                        arguments,
                        run_ordinary_handoff_entry,
                        |mode, run_id, failure| {
                            emit_ordinary_entry_failure_route(mode, run_id, failure);
                        },
                    )
                }
                _ => {
                    branch.set(4);
                    ordinary_handoff_harness_core(
                        arguments,
                        run_ordinary_handoff_entry,
                        |mode, run_id, failure| {
                            emit_ordinary_entry_failure_route(mode, run_id, failure);
                        },
                    )
                }
            }
        }));
        std::panic::set_hook(prior_hook);
        match result {
            Ok(code) => code,
            Err(_) => {
                match branch.get() {
                    2 => emit_entry_diagnostic(
                        "controller",
                        "controller",
                        "E_ENTRY_PANIC",
                        "panic payload suppressed",
                    ),
                    3 => {
                        let run_id = ordinary_run_id.borrow();
                        emit_ordinary_entry_failure_route(
                            mode.get(),
                            &run_id,
                            OrdinaryEntryFailure::from_site(
                                OrdinaryFailureSite::HandoffPanic,
                                "panic payload suppressed",
                            ),
                        );
                    }
                    4 => {
                        emit_ordinary_entry_failure_route(
                            "unknown",
                            "unavailable",
                            OrdinaryEntryFailure::from_site(
                                OrdinaryFailureSite::HandoffPanic,
                                "panic payload suppressed",
                            ),
                        );
                    }
                    _ => {}
                }
                3
            }
        }
    }

