        ta_require!(ta_str(apps, "stable_spec_date", "apps")? == "2026-01-26", "E_TASKS_APPS_LEGACY_2025_AUTHORITY", "apps", "stable_spec_date"); ta_require!(ta_str(apps, "maturity_at_pin", "apps")? == "stable", TA_AUTH, "apps", "maturity_at_pin");
